B.bzc=new A.a("gen_std_intro_5","economic_law","\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00\uc758 \uc758\uc758\xb7\uc81c\uc815 \uc808\ucc28","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ud45c\uc900\uc57d\uad00\uc744 \ub9c8\ub828\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uad00\uacc4 \ubd80\ucc98\uc640\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a71,0,"\ud45c\uc900\uc57d\uad00\uc740 \uc5c5\uc885\uc5d0 \ub530\ub77c \ud2b9\uc218\ud55c \uac70\ub798 \uad00\ud589\uc774\ub098 \uaddc\uc81c\uac00 \uad00\ub828\ub420 \uc218 \uc788\uc73c\ubbc0\ub85c, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ud45c\uc900\uc57d\uad00\uc744 \ub9c8\ub828\xb7\uc2ec\uc0ac\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ud574\ub2f9 \uc5c5\uc885\uc744 \uc18c\uad00\ud558\ub294 \uad00\uacc4 \ud589\uc815\uae30\uad00\uc758 \uc7a5\uacfc \ud611\uc758\ud558\ub294 \uc808\ucc28\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4.",B.aEU,B.aQ_,null)
