B.bqu=new A.a("gen_iv_start_1","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc704\ubc18\ud589\uc704 \uc870\uc0ac \uac1c\uc2dc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.agV,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ubc95 \uc704\ubc18 \ud610\uc758\uac00 \uc788\ub2e4\uace0 \uc778\uc9c0\ud558\uba74 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud560 \uc218 \uc788\uace0, \uc774\ud574\uad00\uacc4\uc778\xb7\uc18c\ube44\uc790\ub2e8\uccb4 \ub4f1\uc758 \uc2e0\uace0\ub97c \uacc4\uae30\ub85c\ub3c4 \uc870\uc0ac\uc5d0 \ucc29\uc218\ud560 \uc218 \uc788\ub2e4. \uc870\uc0ac \uac1c\uc2dc\uc5d0 \ud53c\uc870\uc0ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758\ub098 \uad6d\ud68c \uc2b9\uc778, \uac80\ucc30\uc758 \uc694\uccad\uc774 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4.",B.ahK,B.aWt,null)
B.atE=s(["\ub204\uad6c\ub4e0\uc9c0 \ubc95 \uc704\ubc18\uc0ac\uc2e4\uc744 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\ub2e4","\uc2e0\uace0\ub294 \ubc18\ub4dc\uc2dc \ud53c\ud574 \ub2f9\uc0ac\uc790 \ubcf8\uc778\ub9cc \ud560 \uc218 \uc788\ub2e4","\uc2e0\uace0\ub294 \ubc18\ub4dc\uc2dc \ubcc0\ud638\uc0ac\ub97c \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc2e0\uace0\uac00 \uc788\uc73c\uba74 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ubc18\ub4dc\uc2dc \uadf8 \uc2e0\uace0 \ub0b4\uc6a9\ub300\ub85c\ub9cc \ucc98\ubd84\ud574\uc57c \ud55c\ub2e4","\uc2e0\uace0\uc790\ub294 \uc2e0\uace0 \uc774\ud6c4 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc775\uba85\uc744 \uc720\uc9c0\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a1t=s(["\ub204\uad6c\ub4e0\uc9c0 \ubc95 \uc704\ubc18\uc0ac\uc2e4\uc744 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.asY=s(["\uc2e0\uace0 \uc81c\ub3c4"],t.s)
B.bqa=new A.a("gen_iv_start_2","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c \uc790\uc758 \uc2e0\uace0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.atE,0,"\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c \uc790\ub294 \ub204\uad6c\ub4e0\uc9c0 \uadf8 \uc0ac\uc2e4\uc744 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\ub2e4. \uc2e0\uace0\uc790\uac00 \ubc18\ub4dc\uc2dc \ud53c\ud574 \ub2f9\uc0ac\uc790 \ubcf8\uc778\uc77c \ud544\uc694\ub294 \uc5c6\uc73c\uba70, \uc2e0\uace0\uac00 \uc788\ub2e4\uace0 \ud558\uc5ec \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc2e0\uace0 \ub0b4\uc6a9 \uadf8\ub300\ub85c \uad6c\uc18d\ub418\uc5b4 \ucc98\ubd84\ud574\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\uace0 \uc870\uc0ac \uacb0\uacfc\uc5d0 \ub530\ub77c \ubcc4\ub3c4\ub85c \ud310\ub2e8\ud55c\ub2e4.",B.a1t,B.asY,null)
B.alY=s([u.j4,"\uc2e0\uace0\uc790\uc758 \uc7ac\uc0b0 \uaddc\ubaa8","\ud53c\uc2e0\uace0\uc778\uc758 \uc815\uce58\uc801 \uc131\ud5a5","\uc2e0\uace0\uc790\uc758 \uad6d\uc801","\ud53c\uc2e0\uace0\uc778\uc758 \uc784\uc9c1\uc6d0 \uc218\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.aaB=s([u.j4],t.s)
B.aF3=s(["\uc870\uc0ac \uac1c\uc2dc \ud310\ub2e8\uae30\uc900"],t.s)
B.bPn=new A.a("gen_iv_start_3","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc870\uc0ac \uac1c\uc2dc \uc5ec\ubd80\ub97c \uacb0\uc815\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc0ac\ud56d\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.alY,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc2e0\uace0\ub418\uac70\ub098 \uc778\uc9c0\ub41c \uc0ac\uc2e4\uc774 \ubc95 \uc704\ubc18 \ud610\uc758\ub85c \ubcfc \ub9cc\ud55c \uc0c1\ub2f9\ud55c \uadfc\uac70\ub97c \uac16\ucd94\uace0 \uc788\ub294\uc9c0\ub97c \uc911\uc2ec\uc73c\ub85c \uc870\uc0ac \uac1c\uc2dc \uc5ec\ubd80\ub97c \ud310\ub2e8\ud55c\ub2e4. \uc2e0\uace0\uc790\uc758 \uc7ac\uc0b0\xb7\uad6d\uc801, \ud53c\uc2e0\uace0\uc778\uc758 \uc815\uce58\uc801 \uc131\ud5a5\uc774\ub098 \ub2e8\uc21c \uc784\uc9c1\uc6d0 \uc218\ub294 \uc870\uc0ac \uac1c\uc2dc \uc5ec\ubd80 \ud310\ub2e8\uacfc \ubb34\uad00\ud55c \uc694\uc18c\uc774\ub2e4.",B.aaB,B.aF3,null)
B.bhO=s([u.zr,"\uc2e0\uace0\uc778\uc774 \uc870\uc0ac\uc758 \ubaa8\ub4e0 \uc9c4\ud589\uc744 \uc9c1\uc811 \uc9c0\ud718\ud55c\ub2e4","\uc2e0\uace0\uc778\uc740 \uc870\uc0ac \uac1c\uc2dc \uc774\ud6c4 \uc544\ubb34\ub7f0 \uc808\ucc28\uc801 \uc9c0\uc704\ub3c4 \uac16\uc9c0 \uc54a\ub294\ub2e4","\uc2e0\uace0\uc778\uc740 \ud53c\uc2e0\uace0\uc778\uc5d0 \ub300\ud55c \ucc98\ubd84 \ub0b4\uc6a9\uc744 \uc2a4\uc2a4\ub85c \uacb0\uc815\ud560 \uc218 \uc788\ub2e4","\uc2e0\uace0\uc778\uc740 \uc870\uc0ac \uac1c\uc2dc\uc640 \ub3d9\uc2dc\uc5d0 \uc790\ub3d9\uc73c\ub85c \uc18c\uc1a1\ub2f9\uc0ac\uc790\uac00 \ub41c\ub2e4"],t.s)
B.ayJ=s([u.zr],t.s)
B.aO0=s(["\uc2e0\uace0\uc778\uc758 \uc808\ucc28\uc801 \uc9c0\uc704"],t.s)
B.bAN=new A.a("gen_iv_start_4","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac\uac00 \uac1c\uc2dc\ub41c \uc774\ud6c4 \uc2e0\uace0\uc778\uc758 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.bhO,0,"\uc2e0\uace0\uc778\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc870\uc0ac\uc758 \ub2e8\ucd08\ub97c \uc81c\uacf5\ud558\ub294 \uc9c0\uc704\uc5d0 \uc788\uc73c\ub098, \uc870\uc0ac\uc640 \ucc98\ubd84\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ub3c5\uc790\uc801\uc73c\ub85c \uc218\ud589\ud558\ub294 \uac83\uc774\uba70 \uc2e0\uace0\uc778\uc774 \uc774\ub97c \uc9c1\uc811 \uc9c0\ud718\ud558\uac70\ub098 \ucc98\ubd84 \ub0b4\uc6a9\uc744 \uacb0\uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc808\ucc28 \uc9c4\ud589\uc0c1\ud669\uc5d0 \uad00\ud55c \ud1b5\uc9c0 \ub4f1 \uc77c\uc815\ud55c \uc808\ucc28\uc801 \uc9c0\uc704\ub294 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.ayJ,B.aO0,null)
B.bdy=s([u.yw,"\uc624\uc9c1 \ub300\ud1b5\ub839\uc758 \uac1c\ubcc4 \uc9c0\uc2dc\uac00 \uc788\uc744 \ub54c\ub9cc \uc9c1\uad8c\uc870\uc0ac\uac00 \uac00\ub2a5\ud558\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \ubc95\ub960\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294 \uac1c\ub150\uc774\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \uc2e0\uace0\uac00 \uc804\ud600 \uc5c6\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc808\ub300 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc9c1\uad8c\uc870\uc0ac\ub294 \ub9e4\ub144 \uc815\ud574\uc9c4 \ud2b9\uc815 \ub0a0\uc9dc\uc5d0\ub9cc \uac1c\uc2dc\ub420 \uc218 \uc788\ub2e4"],t.s)
B.bez=s([u.yw],t.s)
B.a8D=s(["\uc9c1\uad8c\uc778\uc9c0\uc758 \uacc4\uae30"],t.s)
B.bJP=new A.a("gen_iv_start_5","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\uc758 \uac1c\uc2dc(\uc9c1\uad8c\xb7\uc2e0\uace0)","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc9c1\uad8c\uc73c\ub85c \uc778\uc9c0\ud558\uc5ec \uc870\uc0ac\ub97c \uac1c\uc2dc\ud558\ub294 \ub300\ud45c\uc801\uc778 \uacc4\uae30\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bdy,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc5b8\ub860\ubcf4\ub3c4, \ub2e4\ub978 \uc0ac\uac74\uc744 \uc870\uc0ac\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ubc1c\uacac\ub41c \ub2e8\uc11c, \uc2dc\uc7a5\ub3d9\ud5a5 \ubaa8\ub2c8\ud130\ub9c1 \uacb0\uacfc \ub4f1 \ub2e4\uc591\ud55c \uacbd\ub85c\ub85c \ubc95 \uc704\ubc18 \ud610\uc758\ub97c \uc778\uc9c0\ud558\uc5ec \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc2e0\uace0\uac00 \uc5c6\ub354\ub77c\ub3c4 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \ubc95 \uc9d1\ud589\uc5d0 \ub098\uc124 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uae30\ub2a5\uc744 \ud55c\ub2e4.",B.bez,B.a8D,null)
B.abk=s([u.wB,"\uc5b4\ub5a0\ud55c \uc2e0\uace0\ub4e0 \uc811\uc218\ub418\uba74 \uc608\uc678 \uc5c6\uc774 \uc989\uc2dc \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c4\ub2e4","\ubb34\uae30\uba85 \uc2e0\uace0\ub294 \ubc95\ub960\uc0c1 \uc804\ud600 \uc811\uc218\ub420 \uc218 \uc5c6\ub2e4","\ud5c8\uc704\uc2e0\uace0\ub85c \ubc1d\ud600\uc9c0\uba74 \ud53c\uc2e0\uace0\uc778\uc5d0\uac8c \uc790\ub3d9\uc73c\ub85c \uc2b9\uc18c \ud310\uacb0\uc774 \ub0b4\ub824\uc9c4\ub2e4","\uc2e0\uace0\uc758 \uc9c4\uc704\uc640 \ubb34\uad00\ud558\uac8c \uc2e0\uace0\uc790\uc5d0\uac8c \ud56d\uc0c1 \ubcf4\uc0c1\uae08\uc774 \uc9c0\uae09\ub41c\ub2e4"],t.s)
