B.bDc=new A.a("gen_iv_obstruct_2","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc790\ub8cc\ub97c \uc740\ub2c9\ud558\uac70\ub098 \uc704\uc870\xb7\ubcc0\uc870\ud558\uc5ec \uc81c\ucd9c\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aMa,0,"\ub2e8\uc21c\ud788 \uc790\ub8cc\uc81c\ucd9c\uc744 \uc9c0\uc5f0\ud558\uac70\ub098 \uc18c\uadf9\uc801\uc73c\ub85c \ud611\uc870\ud558\uc9c0 \uc54a\ub294 \uac83\uc744 \ub118\uc5b4, \uc790\ub8cc\ub97c \uc740\ub2c9\ud558\uac70\ub098 \uc704\uc870\xb7\ubcc0\uc870\ud558\uc5ec \uc81c\ucd9c\ud558\ub294 \ud589\uc704\ub294 \uc870\uc0ac\uc758 \uc2e4\ud6a8\uc131\uc744 \uadfc\ubcf8\uc801\uc73c\ub85c \ud6fc\uc190\ud558\ub294 \uac83\uc73c\ub85c\uc11c \ud1b5\uc0c1\uc758 \ud611\uc870 \uc704\ubc18\ubcf4\ub2e4 \ub354 \ubb34\uac81\uac8c \ud3c9\uac00\ub418\uc5b4 \uc81c\uc7ac\ub098 \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4.",B.a9D,B.a5N,null)
B.aBR=s(["\uc870\uc0ac \ubc29\ud574\ub098 \ube44\ud611\uc870 \uc0ac\uc2e4\uc740 \uacfc\uc9d5\uae08 \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4","\uc870\uc0ac\ubc29\ud574 \uc5ec\ubd80\ub294 \uacfc\uc9d5\uae08 \uc0b0\uc815\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc870\uc0ac\ubc29\ud574\ub97c \ud558\uba74 \uc624\ud788\ub824 \uacfc\uc9d5\uae08\uc774 \uc790\ub3d9\uc73c\ub85c \uac10\uacbd\ub41c\ub2e4","\uc870\uc0ac\ubc29\ud574 \uc5ec\ubd80\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\uc5d0\uc11c\ub9cc \uace0\ub824\ub418\uace0 \uacfc\uc9d5\uae08\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uc870\uc0ac\ubc29\ud574\ub294 \ud56d\uc0c1 \uacfc\uc9d5\uae08 \ubd80\uacfc \uc790\uccb4\ub97c \ubb34\ud6a8\ub85c \ub9cc\ub4e0\ub2e4"],t.s)
