B.bnB=new A.a("gen_refuse_def_2","economic_law","\uac70\ub798\uac70\uc808","\uac70\ub798\uac70\uc808\uc758 \uc758\ubbf8\xb7\uc720\ud615",'\uac70\ub798\uac70\uc808\uc758 \ud558\uc704 \uc720\ud615\uc778 "\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.beL,0,'"\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808"\uc740 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ubcf5\uc218\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc73c\ub85c \ud2b9\uc815 \uc0ac\uc5c5\uc790\uc640\uc758 \uac70\ub798\uac1c\uc2dc\ub97c \uac70\uc808\ud558\uac70\ub098 \uac70\ub798\ub97c \uc911\ub2e8\ud558\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud558\uba70, \ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\ubcf4\ub2e4 \uc2dc\uc7a5 \uc804\uccb4\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uac00 \ud074 \uc218 \uc788\uc5b4 \ubcc4\ub3c4\ub85c \uc720\ud615\ud654\ub418\uc5b4 \uc788\ub2e4.',B.bfB,B.Zo,null)
B.aDp=s([u.jU,"\ubcf5\uc218\uc758 \uc0ac\uc5c5\uc790\uac00 \uacf5\ub3d9\uc73c\ub85c \uac70\ub798\ub97c \uac70\uc808\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud68c\uc6d0 \uc790\uaca9\uc744 \uc815\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc774 \uacc4\uc57d\uc744 \uc704\ubc18\ud558\uc5ec \uc0ac\uc5c5\uc790\uac00 \uc815\ub2f9\ud558\uac8c \uacc4\uc57d\uc744 \ud574\uc9c0\ud558\ub294 \ud589\uc704","\uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc0ac\uc5c5\uc790\ub9cc\uc774 \ud560 \uc218 \uc788\ub294 \ud589\uc704"],t.s)
