B.brX=new A.a("gen_refuse_exam_5","economic_law","\uac70\ub798\uac70\uc808","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uac70\ub798\uac70\uc808\uacfc \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b8a,0,"\uac70\ub798\uac70\uc808\uc740 \uac70\ub798\uad00\uacc4 \uc790\uccb4\ub97c \uac1c\uc2dc\ud558\uc9c0 \uc54a\uac70\ub098 \uc911\ub2e8\ud558\ub294 \uac83\uc774 \ubb38\uc81c\ub418\ub294 \uc720\ud615\uc778 \ubc18\uba74, \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \uac70\ub798\uad00\uacc4\ub97c \uc720\uc9c0\ud558\uba74\uc11c \uadf8 \uac70\ub798\uc870\uac74\uc774\ub098 \ub0b4\uc6a9(\uad6c\uc785\uac15\uc81c, \uc774\uc775\uc81c\uacf5\uac15\uc694 \ub4f1)\uc758 \ubd88\uacf5\uc815\uc131\uc774 \ubb38\uc81c\ub418\ub294 \uc720\ud615\uc774\ub77c\ub294 \uc810\uc5d0\uc11c, \ub450 \uaddc\uc81c\ub294 \ucd08\uc810\uc744 \ub2ec\ub9ac\ud558\ub294 \ubcc4\uac1c\uc758 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uc720\ud615\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.U0,B.b0j,null)
B.aEw=s([u.xg,"\uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \uac70\ub798\ub97c \uac70\uc808\ub2f9\ud55c \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc18c\ube44\uc790\ub2e8\uccb4\uc5d0\uac8c \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec \ubd80\ub2f4\ud55c\ub2e4","\uc99d\uba85\ucc45\uc784 \uac1c\ub150\uc740 \uac70\ub798\uac70\uc808 \uc0ac\uac74\uc5d0 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
