B.bQw=new A.a("gen_leniency_process_5","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uac10\uba74 \uc808\ucc28\xb7\ud615\uc0ac\uace0\ubc1c\uacfc\uc758 \uad00\uacc4","\uac00\ub9f9\ubcf8\ubd80\uac00 \ub2e4\ub978 \uac00\ub9f9\ubcf8\ubd80\ub4e4\uacfc \uacf5\uae09\uac00\uaca9 \ub2f4\ud569\uc744 \ud55c \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c \uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uc790\ubb38 \uc2dc \uc548\ub0b4\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aAN,0,"\uac00\ub9f9\uac70\ub798\uc0ac\ub294 \ub2f4\ud569\uc5d0 \uac00\ub2f4\ud55c \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c \uc758\ub8b0\uc778\uc5d0\uac8c \uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\uc758 \uc694\uac74\uacfc \uc21c\uc704\ubcc4 \ud61c\ud0dd\uc758 \ucc28\uc774(1\uc21c\uc704 \uc804\ubd80 \uba74\uc81c, 2\uc21c\uc704 \uc774\ud558 \uac10\uacbd \ub4f1)\ub97c \uc124\uba85\ud558\uace0, \uba3c\uc800 \uc2e0\uace0\ud560\uc218\ub85d \uc720\ub9ac\ud55c \ud61c\ud0dd\uc744 \ubc1b\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c \uc870\uc18d\ud55c \ud310\ub2e8\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc74c\uc744 \uc548\ub0b4\ud558\ub294 \uac83\uc774 \uc801\uc808\ud55c \uc790\ubb38 \ubc29\ud5a5\uc774\ub2e4.",B.a4X,B.aeI,null)
B.aLw=s([u.k2,"\uacf5\ub3d9 \uc790\uc9c4\uc2e0\uace0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc808\ub300 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud655\ub9bd\ub41c \ubc95\ub9ac\uc774\ub2e4","\uacf5\ub3d9 \uc790\uc9c4\uc2e0\uace0\ub97c \ud558\uba74 \ucc38\uc5ec\uc790 \uc804\uc6d0\uc774 \uc790\ub3d9\uc73c\ub85c \ud615\uc0ac\ucc98\ubc8c\uc744 \uba74\uc81c\ubc1b\ub294\ub2e4","\uacf5\ub3d9 \uc790\uc9c4\uc2e0\uace0\ub294 \uac1c\ubcc4 \uc790\uc9c4\uc2e0\uace0\ubcf4\ub2e4 \ud56d\uc0c1 \ubd88\ub9ac\ud558\uac8c\ub9cc \ucde8\uae09\ub41c\ub2e4","\uacf5\ub3d9 \uc790\uc9c4\uc2e0\uace0\ub294 \uac10\uba74 \uc21c\uc704 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
