B.bBD=new A.a("gen_ca_permit_process_1","economic_law","\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc81c\ub3c4","\uc778\uac00 \uc694\uac74\xb7\uc808\ucc28","\uacf5\ub3d9\ud589\uc704 \uc778\uac00\ub97c \ubc1b\uae30 \uc704\ud574 \uc0ac\uc5c5\uc790\uac00 \uac16\ucd94\uc5b4\uc57c \ud558\ub294 \uc694\uac74\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.awK,0,"\uacf5\ub3d9\ud589\uc704 \uc778\uac00\ub97c \ubc1b\uae30 \uc704\ud574\uc11c\ub294 \ubc95\uc5d0\uc11c \uc815\ud55c \uc778\uac00\uc0ac\uc720(\uc0b0\uc5c5\uad6c\uc870\uc870\uc815, \uc5f0\uad6c\uac1c\ubc1c \ub4f1)\uc5d0 \ud574\ub2f9\ud558\uace0, \ub300\ud1b5\ub839\ub839\uc774 \uc815\ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc138\ubd80 \uc694\uac74(\uacbd\uc7c1\uc81c\ud55c\uc758 \uc815\ub3c4, \ubaa9\uc801 \ub2ec\uc131\uc5d0 \ud544\uc694\ud55c \ucd5c\uc18c\ud55c\uc758 \ubc94\uc704 \ub4f1)\uc744 \ucda9\uc871\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.a9b,B.aDV,null)
B.aSx=s(["\uacf5\ub3d9\ud589\uc704\ub97c \ud558\ub824\ub294 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4","\uc624\uc9c1 \uc18c\ube44\uc790\ub2e8\uccb4\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc7a5\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \uad6d\ud68c\uc758\uc6d0\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\uc6d0\ub9cc \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Sw=s(["\uacf5\ub3d9\ud589\uc704\ub97c \ud558\ub824\ub294 \uc0ac\uc5c5\uc790 \ub610\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4"],t.s)
