B.bId=new A.a("gen_collusion_type_limit_1","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uc0c1\ud488\uc758 \uc0dd\uc0b0\xb7\ucd9c\uace0\xb7\uc218\uc1a1 \ub610\ub294 \uac70\ub798\uc758 \uc81c\ud55c\uc774\ub098 \uc6a9\uc5ed\uc758 \uac70\ub798\ub97c \uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.af_,0,'"\uc0dd\uc0b0\xb7\ucd9c\uace0\xb7\uc218\uc1a1 \ub610\ub294 \uac70\ub798\uc758 \uc81c\ud55c" \uc720\ud615\uc740 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud569\uc758\ud558\uc5ec \uc0dd\uc0b0\ub7c9\uc774\ub098 \ucd9c\uace0\ub7c9 \ub4f1\uc744 \uc778\uc704\uc801\uc73c\ub85c \uc81c\ud55c\ud568\uc73c\ub85c\uc368 \uc2dc\uc7a5\uc5d0 \uacf5\uae09\ub418\ub294 \ubb3c\ub7c9\uc744 \uc870\uc808\ud558\uace0, \uc774\ub97c \ud1b5\ud574 \uac00\uaca9 \uc0c1\uc2b9 \ub4f1 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\ub97c \ub3c4\ubaa8\ud558\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.a8c,B.aNY,null)
B.azL=s([u.eT,"\uc0ac\uc5c5\uc790\uac00 \uc790\uccb4\uc801\uc73c\ub85c \ud2b9\uc815 \uc9c0\uc5ed\uc5d0 \uc9d1\uc911\ud558\uc5ec \uc601\uc5c5\ud558\ub294 \uc804\ub7b5\uc744 \uc138\uc6b0\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc2e0\uc6a9\ub3c4\ub97c \ud3c9\uac00\ud558\uc5ec \uac70\ub798 \uc5ec\ubd80\ub97c \uacb0\uc815\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc774 \uc790\ubc1c\uc801\uc73c\ub85c \ud2b9\uc815 \uc0ac\uc5c5\uc790\uc640\ub9cc \uac70\ub798\ud558\uae30\ub85c \uc120\ud0dd\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \ubc95\ub839\uc0c1 \uc81c\ud55c\uc5d0 \ub530\ub77c \ud2b9\uc815 \uc9c0\uc5ed\uc5d0\uc11c \uc601\uc5c5\ud558\uc9c0 \ubabb\ud558\ub294 \ud589\uc704"],t.s)
