B.bK8=new A.a("gen_collusion_type_limit_5","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uc601\uc5c5\uc758 \uc8fc\uc694\ubd80\ubb38\uc744 \uacf5\ub3d9\uc73c\ub85c \uc218\ud589\xb7\uad00\ub9ac\ud558\uae30 \uc704\ud55c \ud68c\uc0ac \ub4f1\uc744 \uc124\ub9bd\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aLc,0,'"\uc601\uc5c5\uc758 \uc8fc\uc694\ubd80\ubb38\uc744 \uacf5\ub3d9\uc73c\ub85c \uc218\ud589\xb7\uad00\ub9ac\ud558\uae30 \uc704\ud55c \ud68c\uc0ac \ub4f1\uc758 \uc124\ub9bd" \uc720\ud615\uc740 \uacbd\uc7c1\uad00\uacc4\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc601\uc5c5\uc758 \ud575\uc2ec\uc801\uc778 \ubd80\ubd84(\uc0dd\uc0b0, \ud310\ub9e4 \ub4f1)\uc744 \uacf5\ub3d9\uc73c\ub85c \uc218\ud589\ud558\ub294 \ubcc4\ub3c4\uc758 \ud68c\uc0ac\ub97c \uc124\ub9bd\ud568\uc73c\ub85c\uc368 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uad00\uacc4\ub97c \uc18c\uba78\uc2dc\ud0a4\ub294 \ud6a8\uacfc\ub97c \uac00\uc838\uc624\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud558\uba70, \uc815\ub2f9\ud55c \uae30\uc5c5\uacb0\ud569 \uc2ec\uc0ac \uc808\ucc28\ub97c \uac70\uce5c \ud569\uc791\ud68c\uc0ac \uc124\ub9bd\uacfc\ub294 \uad6c\ubcc4\ub418\uc5b4\uc57c \ud55c\ub2e4.',B.aV9,B.a_s,null)
B.az2=s([u.wM,"\uc785\ucc30\ub2f4\ud569\uc740 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\uc758 \uc5b4\ub5a0\ud55c \uc720\ud615\uc5d0\ub3c4 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc785\ucc30\ub2f4\ud569\uc740 \uc624\uc9c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc73c\ub85c\ub9cc \uaddc\uc728\ub41c\ub2e4","\uc785\ucc30\ub2f4\ud569\uc740 \ub2f4\ud569\uc758 \uc815\uc758 \uc790\uccb4\uc640 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4","\uc785\ucc30\ub2f4\ud569\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c\ub9cc \uaddc\uc728\ub420 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4"],t.s)
