B.bHH=new A.a("gen_ta_compete_2","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uacbd\uc7c1\uc81c\ud55c \uacf5\ub3d9\ud589\uc704 \uc720\ud615",'\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704 \uc911 "\ubd80\ub2f9\ud558\uac8c \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \uacf5\ub3d9\ud589\uc704"\uc758 \ud310\ub2e8\uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.bhn,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uacbd\uc7c1\uc81c\ud55c\uc801 \uacf5\ub3d9\ud589\uc704 \uc5ec\ubd80\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790 \uac04 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud310\ub2e8\uae30\uc900\uacfc \uc720\uc0ac\ud558\uac8c, \ud574\ub2f9 \ud589\uc704\uac00 \uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub77c\ub294 \ud615\uc2dd\uc774 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \ub2f4\ud569\uacfc \uc2e4\uc9c8\uc801\uc73c\ub85c \ub2e4\ub974\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc5d0\uc11c \uc720\uc0ac\ud55c \uc2ec\uc0ac \ud2c0\uc774 \uc801\uc6a9\ub418\ub294 \uac83\uc774\ub2e4.",B.b6f,B.azp,null)
B.aOr=s(["\uc0dd\uc0b0\ub7c9 \uc81c\ud55c\uc744 \ud1b5\ud574 \uacbd\ufffd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud55c\ub2e4\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4","\ucd1d\ud68c \uc758\uacb0\uc744 \uac70\ucce4\ub2e4\ub294 \uc808\ucc28\uc801 \uc815\ub2f9\uc131\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc801\ubc95\ud558\ub2e4","\uc0dd\uc0b0\ub7c9\uc5d0 \uad00\ud55c \uacb0\uc758\ub294 \uac00\uaca9\uc5d0 \uad00\ud55c \uacb0\uc758\uc640 \ub2ec\ub9ac \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc544\ub2c8\ub77c \uac1c\ubcc4 \uc18c\ube44\uc790\uc5d0 \ub300\ud55c \ubb38\uc81c\uc77c \ubfd0\uc774\ub2e4","\uc0dd\uc0b0\ub7c9 \uc81c\ud55c \uacb0\uc758\ub294 \uacf5\uc815\uac70\ub798\ubc95\uacfc \ubb34\uad00\ud55c \uc0b0\uc5c5\uc815\ucc45 \uc0ac\ud56d\uc774\ub2e4"],t.s)
B.aHH=s(["\uc0dd\uc0b0\ub7c9 \uc81c\ud55c\uc744 \ud1b5\ud574 \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud55c\ub2e4\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aeC=s(["\uc0dd\uc0b0\ub7c9 \uc81c\ud55c \uacb0\uc758"],t.s)
B.bo2=new A.a("gen_ta_compete_3","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uacbd\uc7c1\uc81c\ud55c \uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ucd1d\ud68c\uc758 \uc758\uacb0\uc744 \uac70\uccd0 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\uc758 \uc0dd\uc0b0\ub7c9\uc744 \uc81c\ud55c\ud558\uae30\ub85c \uacb0\uc758\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aOr,0,"\uc0dd\uc0b0\ub7c9 \uc81c\ud55c\uc740 \uac00\uaca9 \ub2f4\ud569\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc2dc\uc7a5\uc758 \uc218\uae09\uc5d0 \uc778\uc704\uc801 \uc601\ud5a5\uc744 \ubbf8\uccd0 \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud560 \uc218 \uc788\ub294 \ub300\ud45c\uc801\uc778 \uacbd\uc7c1\uc81c\ud55c \ud589\uc704 \uc720\ud615\uc774\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ucd1d\ud68c \uc758\uacb0\uc774\ub77c\ub294 \ub0b4\ubd80 \uc808\ucc28\ub97c \uac70\ucce4\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uadf8 \uc2e4\uc9c8\uc801 \uc704\ubc95\uc131\uc774 \uce58\uc720\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uac00 \uc778\uc815\ub418\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc728\ub420 \uc218 \uc788\ub2e4.",B.aHH,B.aeC,null)
B.aCn=s([u.qh,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ub2f4\ud569\uc758 \uc9c1\uc811 \ub2f9\uc0ac\uc790\uac00 \uc544\ub2c8\ubbc0\ub85c \uc5b4\ub5a0\ud55c \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ubc29\uc870\ud589\uc704\ub294 \uc5b8\uc81c\ub098 \ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \ucc45\uc784\uc740 \uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uadc0\uc18d\ub418\uace0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc644\uc804\ud788 \uba74\ucc45\ub41c\ub2e4","\uc720\ub3c4\xb7\ubc29\uc870\ud589\uc704\ub294 \ud615\uc0ac\ubc95\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub420 \ubfd0 \uacf5\uc815\uac70\ub798\ubc95\uacfc\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.Rs=s([u.qh],t.s)
B.aME=s(["\ub2f4\ud569\uc758 \uc720\ub3c4\xb7\ubc29\uc870"],t.s)
B.bw6=new A.a("gen_ta_compete_4","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uacbd\uc7c1\uc81c\ud55c \uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790 \uac04 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704(\ub2f4\ud569)\ub97c \ud558\ub3c4\ub85d \uc720\ub3c4\ud558\uac70\ub098 \uc774\ub97c \ubc29\uc870\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aCn,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4 \uc0ac\uc774\uc758 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704(\ub2f4\ud569)\ub97c \uc9c1\uc811 \uc8fc\ub3c4\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uc774\ub97c \uc720\ub3c4\ud558\uac70\ub098 \ubc29\uc870\ud558\ub294 \ud589\uc704 \uc5ed\uc2dc \uacbd\ufffd\uc7c1\uc81c\ud55c\uc801 \uacb0\uacfc\ub97c \ub0b3\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc728\ub420 \uc218 \uc788\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uac1c\ubcc4 \uad6c\uc131\uc0ac\uc5c5\uc790 \ubaa8\ub450 \uac01\uc790\uc758 \uad00\uc5ec \uc815\ub3c4\uc5d0 \ub530\ub77c \ucc45\uc784\uc744 \uc9c8 \uc218 \uc788\ub2e4.",B.Rs,B.aME,null)
B.a_w=s([u.F,"\uacf5\uac1c\ub41c \ud1b5\uacc4\uc790\ub8cc\ub97c \ub2e8\uc21c\ud788 \uc885\ud569\ud558\uc5ec \ubc30\ud3ec\ud558\ub294 \uacbd\uc6b0","\uc77c\ubc18\uc801\uc778 \uc0b0\uc5c5 \ub3d9\ud5a5\uc5d0 \uad00\ud55c \uacf5\uac1c \uc138\ubbf8\ub098\ub97c \uac1c\ucd5c\ud558\ub294 \uacbd\uc6b0","\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc548\uc804\uc0ac\uace0 \uc608\ubc29\uc744 \uc704\ud55c \uc77c\ubc18\uc801 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub294 \uacbd\uc6b0","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uacf5\ud45c\ud55c \uc815\ucc45\uc790\ub8cc\ub97c \uadf8\ub300\ub85c \uc804\ub2ec\ud558\ub294 \uacbd\uc6b0"],t.s)
B.aCu=s([u.F],t.s)
B.agf=s(["\ubbfc\uac10\uc815\ubcf4 \uad50\ud658\uc758 \uc704\ud5d8\uc131"],t.s)
B.bsV=new A.a("gen_ta_compete_5","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uacbd\uc7c1\uc81c\ud55c \uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc815\ubcf4\uad50\ud658 \ud589\uc704\uac00 \uacbd\uc7c1\uc81c\ud55c\uc801 \uacf5\ub3d9\ud589\uc704\ub85c \ubb38\uc81c\ub420 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a_w,0,"\uac00\uaca9, \uc0dd\uc0b0\ub7c9, \ud310\ub9e4\uc870\uac74 \ub4f1 \uacbd\uc7c1\uc5d0 \ubbfc\uac10\ud55c \uc815\ubcf4\ub97c \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub97c \ub9e4\uac1c\ub85c \uad6c\uc131\uc0ac\uc5c5\uc790 \uac04\uc5d0 \uad50\ud658\ud558\ub3c4\ub85d \ud558\uc5ec \uc0ac\uc2e4\uc0c1 \ub2f4\ud569\uacfc \uc720\uc0ac\ud55c \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\ub97c \ub0b3\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4. \ubc18\uba74 \uacf5\uac1c\ub41c \ud1b5\uacc4\uc790\ub8cc\uc758 \ub2e8\uc21c \uc885\ud569\xb7\ubc30\ud3ec, \uc77c\ubc18\uc801 \uc0b0\uc5c5\ub3d9\ud5a5 \uacf5\uc720, \uc548\uc804 \uad00\ub828 \uc815\ubcf4 \uacf5\uc720 \ub4f1\uc740 \ud1b5\uc0c1\uc801\uc73c\ub85c \uacbd\uc7c1\uc81c\ud55c \uc6b0\ub824\uac00 \ud06c\uc9c0 \uc54a\uc740 \uc815\ub2f9\ud55c \ud65c\ub3d9\uc73c\ub85c \ud3c9\uac00\ub41c\ub2e4.",B.aCu,B.agf,null)
B.aXF=s([u.D7,"\ub450 \uc81c\ub3c4\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uc5ec \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uaddc\uc815\uc740 \ubd88\ud544\uc694\ud55c \uc911\ubcf5\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad00\uc5ec\ud558\uba74 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc5d0 \ub300\ud55c \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uaddc\uc815\uc740 \uc804\ufffd\uba74 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ub2f4\ud569\ubcf4\ub2e4 \ud56d\uc0c1 \uac00\ubccd\uac8c \ucc98\ubc8c\ub41c\ub2e4","\ub450 \uc81c\ub3c4\ub294 \uc804\ud600 \ub2e4\ub978 \ubc95\ub960\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\uc5b4 \uc11c\ub85c \ucc38\uc870\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aDk=s([u.D7],t.s)
B.aUH=s(["\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uaddc\uc81c\uc640 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uaddc\uc81c\uc758 \uad00\uacc4"],t.s)
B.bC2=new A.a("gen_ta_compete_6","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uacbd\uc7c1\uc81c\ud55c \uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uacbd\uc7c1\uc81c\ud55c\uc801 \uacf5\ub3d9\ud589\uc704 \uaddc\uc81c\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790 \uac04 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aXF,0,"\uacbd\uc7c1\uc81c\ud55c\uc801 \ud589\uc704\uc758 \uc8fc\uccb4\uac00 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc790\uccb4\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704(\uc81c51\uc870)\ub85c, \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub4e4 \uac04\uc758 \ud569\uc758\uc778 \uacbd\uc6b0\uc5d0\ub294 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704(\uc81c40\uc870 \ub4f1)\ub85c \uac01\uac01 \uaddc\uc728\ub420 \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uc0ac\uc548\uc5d0\uc11c \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uacb0\uc758\uc640 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \uc2e4\ud589 \ud569\uc758\uac00 \ud568\uaed8 \uc874\uc7ac\ud558\uba74 \ub450 \uaddc\uc815\uc774 \ud568\uaed8 \ubb38\uc81c\ub420 \uc218\ub3c4 \uc788\uc73c\uba70, \uc5b4\ub290 \ud558\ub098\uac00 \ub2e4\ub978 \ud558\ub098\ub97c \uc644\uc804\ud788 \ub300\uccb4\ud558\uac70\ub098 \ubc30\uc81c\ud558\ub294 \uad00\uacc4\ub294 \uc544\ub2c8\ub2e4.",B.aDk,B.aUH,null)
B.azt=s([u.bY,"\uc0ac\uc5c5\uc790 \uc218 \uc81c\ud55c\uc740 \uae30\uc874 \ud68c\uc6d0\uc758 \uc774\uc775 \ubcf4\ud638\ub97c \uc704\ud55c \uac83\uc774\ubbc0\ub85c \ud56d\uc0c1 \uc815\ub2f9\ud558\ub2e4","\uc0ac\uc5c5\uc790 \uc218 \uc81c\ud55c\uc740 \uc624\uc9c1 \uc815\ubd80\uc758 \uc778\ud5c8\uac00 \uc81c\ub3c4\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\uace0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640\ub294 \ubb34\uad00\ud558\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ud68c\uc6d0 \uc790\uaca9 \uc694\uac74\uc744 \uc804\ud600 \uc815\ud560 \uc218 \uc5c6\ub2e4","\uc0ac\uc5c5\uc790 \uc218 \uc81c\ud55c \ud589\uc704\ub294 \uc18c\ube44\uc790\uc5d0\uac8c\ub9cc \uc601\ud5a5\uc744 \ubbf8\uce58\uace0 \uacbd\uc7c1\uacfc\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.avn=s([u.bY],t.s)
B.a2l=s(["\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c"],t.s)
B.bNS=new A.a("gen_ta_restrict_1","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \ud604\uc7ac \ub610\ub294 \uc7a5\ub798\uc758 \uc0ac\uc5c5\uc790 \uc218\ub97c \uc81c\ud55c\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.azt,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \ud604\uc7ac \ub610\ub294 \uc7a5\ub798 \ud65c\ub3d9\ud560 \uc0ac\uc5c5\uc790\uc758 \uc218\ub97c \uc778\uc704\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294 \ud589\uc704\ub294, \uc2e0\uaddc \uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5 \uc9c4\uc785\uc744 \ubd09\uc1c4\ud574 \uae30\uc874 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\uc758 \uacbd\uc7c1 \uc555\ub825\uc744 \ub0ae\ucd94\ub294 \ud6a8\uacfc\ub97c \ub0b3\uc73c\ubbc0\ub85c \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc728\ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud569\ub9ac\uc801 \uae30\uc900\uc5d0 \ub530\ub77c \ucd5c\uc18c\ud55c\uc758 \ud68c\uc6d0\uc790\uaca9\uc694\uac74\uc744 \uc815\ud558\ub294 \uac83 \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \ubd80\ub2f9\ud558\uac8c \uc9c4\uc785\uc744 \ubd09\uc1c4\ud558\ub294 \uacbd\uc6b0\uac00 \ubb38\uc81c\ub41c\ub2e4.",B.avn,B.a2l,null)
B.agE=s([u.pG,"\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc548\uc804\uc0ac\uace0\ub97c \uc608\ubc29\ud558\uae30 \uc704\ud55c \ucd5c\uc18c\ud55c\uc758 \ud569\ub9ac\uc801 \uc9c0\uce68\uc744 \uc81c\uacf5\ud558\ub294 \ud589\uc704","\uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c \uad00\ub828 \ubc95\ub839 \uc900\uc218\ub97c \uc548\ub0b4\ud558\ub294 \ud589\uc704","\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc790\uc728\uc801 \ucc38\uc5ec\ub97c \uc804\uc81c\ub85c \ud55c \uacf5\ub3d9 \ub9c8\ucf00\ud305 \ucea0\ud398\uc778\uc744 \uc81c\uc548\ud558\ub294 \ud589\uc704","\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc694\uccad\uc5d0 \ub530\ub77c \uc5c5\uacc4 \ud1b5\uacc4\uc790\ub8cc\ub97c \uc81c\uacf5\ud558\ub294 \ud589\uc704"],t.s)
B.aPo=s([u.pG],t.s)
B.alu=s(["\uc0ac\uc5c5\ub0b4\uc6a9\xb7\ud65c\ub3d9 \uc81c\ud55c \uc0ac\ub840"],t.s)
B.bAr=new A.a("gen_ta_restrict_2","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9 \ub610\ub294 \ud65c\ub3d9\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704\uc758 \uc0ac\ub840\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.agE,0,'\uad6c\uc131\uc0ac\uc5c5\uc790\uac00 \ubcf8\ub798 \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub294 \uad11\uace0\xb7\ud310\ucd09 \ub4f1 \uc815\ub2f9\ud55c \uc601\uc5c5\ud65c\ub3d9\uc744 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc81c\ud55c\ud558\ub294 \ud589\uc704\ub294 "\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9 \ub610\ub294 \ud65c\ub3d9\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc804\ud615\uc801 \uc0ac\ub840\uc774\ub2e4. \ubc18\uba74 \uc548\uc804 \uad00\ub828 \ucd5c\uc18c\ud55c\uc758 \ud569\ub9ac\uc801 \uc9c0\uce68 \uc81c\uacf5, \ubc95\ub839\uc900\uc218 \uc548\ub0b4, \uc790\uc728\ucc38\uc5ec \uc804\uc81c\uc758 \uacf5\ub3d9\ub9c8\ucf00\ud305 \uc81c\uc548, \ud1b5\uacc4\uc790\ub8cc \uc81c\uacf5 \ub4f1\uc740 \ud1b5\uc0c1 \uc815\ub2f9\ud55c \ud65c\ub3d9\uc73c\ub85c \ud3c9\uac00\ub41c\ub2e4.',B.aPo,B.alu,null)
B.aak=s(["\uc774\ub294 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704\uc774\uc790 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4","\uc815\uad00\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\uc73c\uba74 \ud56d\uc0c1 \uc801\ubc95\ud558\ub2e4","\uac00\uaca9 \ud560\uc778 \uae08\uc9c0\ub294 \uc18c\ube44\uc790 \ubcf4\ud638\ub97c \uc704\ud55c \uc870\uce58\uc774\ubbc0\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\ub7ec\ud55c \uaddc\uc815\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ub0b4\ubd80 \ubb38\uc81c\uc77c \ubfd0 \uacf5\uc815\uac70\ub798\ubc95\uacfc \ubb34\uad00\ud558\ub2e4","\uac00\uaca9 \ud560\uc778 \uae08\uc9c0\ub294 \uc624\uc9c1 \ub300\uae30\uc5c5\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\uc774\ub2e4"],t.s)
B.ajU=s(["\uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704\uc774\uc790 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4"],t.s)
B.Tk=s(["\uac00\uaca9\ud560\uc778\xb7\ud310\ucd09 \uc81c\ud55c"],t.s)
B.bS_=new A.a("gen_ta_restrict_3","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uac00\uaca9 \ud560\uc778\xb7\ud310\ucd09\uc744 \uc815\uad00\uc774\ub098 \ub0b4\ubd80\uaddc\uc815\uc73c\ub85c \uae08\uc9c0\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aak,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc815\uad00\uc774\ub098 \ub0b4\ubd80\uaddc\uc815\uc744 \ud1b5\ud574 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uac00\uaca9 \ud560\uc778\uc774\ub098 \ud310\ucd09\ud65c\ub3d9\uc744 \uae08\uc9c0\ud558\ub294 \uac83\uc740, \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc815\ub2f9\ud55c \uc601\uc5c5\ud65c\ub3d9(\uc0ac\uc5c5\ub0b4\uc6a9)\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \ud589\uc704\uc774\uc790 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud6a8\uacfc\ub97c \ub0b3\ub294 \ud589\uc704\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\ub2e4. \uc815\uad00\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4\ub294 \ud615\uc2dd\uc801 \uc0ac\uc815\ub9cc\uc73c\ub85c \uadf8 \uc704\ubc95\uc131\uc774 \ubd80\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.ajU,B.Tk,null)
B.b5N=s([u.oa,"\uae30\uc874 \uc0ac\uc5c5\uc790\uc758 \ub3d9\uc758 \uc694\uac74\uc740 \ud56d\uc0c1 \ud569\ub9ac\uc801 \uc790\uc728\uaddc\uc81c\ub85c \uc778\uc815\ub41c\ub2e4","\uc774\ub7ec\ud55c \uc694\uac74\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc7ac\uc0b0\uad8c \ud589\uc0ac\uc5d0 \ud574\ub2f9\ud558\uc5ec \uc804\ud600 \uaddc\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2e0\uaddc \ud68c\uc6d0 \uac00\uc785 \uc694\uac74\uc740 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uaddc\uc728 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc624\uc9c1 \ubbfc\ubc95\uc0c1 \uacc4\uc57d\uc790\uc720\uc758 \ubb38\uc81c\uc77c \ubfd0\uc774\ub2e4"],t.s)
B.bdh=s([u.oa],t.s)
B.R9=s(["\uc790\uc758\uc801 \uac00\uc785 \uc694\uac74\uc758 \ubb38\uc81c"],t.s)
B.bsm=new A.a("gen_ta_restrict_4","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc2e0\uaddc \ud68c\uc6d0 \uac00\uc785 \uc694\uac74\uc73c\ub85c \uae30\uc874 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \ub3d9\uc758\ub97c \ubc18\ub4dc\uc2dc \ubc1b\ub3c4\ub85d \ud558\uace0, \uae30\uc874 \uc0ac\uc5c5\uc790\uac00 \uc784\uc758\ub85c \ub3d9\uc758\ub97c \uac70\ubd80\ud560 \uc218 \uc788\uac8c \uc815\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b5N,0,"\uc2e0\uaddc \uac00\uc785 \uc694\uac74\uc73c\ub85c \uae30\uc874 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc784\uc758\uc801 \ub3d9\uc758\ub97c \uc694\uad6c\ud558\uace0 \uadf8 \ub3d9\uc758\ub97c \uc790\uc758\uc801\uc73c\ub85c \uac70\ubd80\ud560 \uc218 \uc788\uac8c \ud558\ub294 \uac83\uc740, \uc0ac\uc2e4\uc0c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc2e0\uaddc \uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5 \uc9c4\uc785 \uc5ec\ubd80\ub97c \uc88c\uc6b0\ud558\ub294 \uacb0\uacfc\ub97c \ub0b3\uc544 \uc0ac\uc5c5\uc790 \uc218 \uc81c\ud55c \ud589\uc704\ub85c \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4. \ud569\ub9ac\uc801\uc774\uace0 \uac1d\uad00\uc801\uc778 \uc790\uaca9\uae30\uc900\uc5d0 \ub530\ub978 \uc2ec\uc0ac\uc640\ub294 \ub2ec\ub9ac, \uae30\uc874 \ud68c\uc6d0\uc758 \uc790\uc758\uc801 \ub3d9\uc758\uc5d0 \uc88c\uc6b0\ub418\ub294 \uad6c\uc870\ub294 \uacbd\uc7c1\uc81c\ud55c \uc6b0\ub824\uac00 \ud06c\ub2e4.",B.bdh,B.R9,null)
B.aUg=s([u.uz,"\uc5b4\ub5a0\ud55c \ud68c\uc6d0\uc790\uaca9 \uc694\uac74\ub3c4 \uc608\uc678 \uc5c6\uc774 \uc804\ubd80 \uc704\ubc95\ud558\ub2e4","\uc804\ubb38\uc131 \uae30\uc900\uc740 \ud56d\uc0c1 \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294 \uac83\uc73c\ub85c \uac04\uc8fc\ub41c\ub2e4","\uc774\ub7ec\ud55c \uae30\uc900\uc740 \ubc18\ub4dc\uc2dc \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc0ac\uc804 \uc2b9\uc778\uc744 \ubc1b\uc544\uc57c\ub9cc \uc815\ud560 \uc218 \uc788\ub2e4","\uc804\ubb38\uc131 \uae30\uc900\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc544\ub2c8\ub77c \uc815\ubd80\ub9cc \uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
B.alX=s([u.uz],t.s)
B.ban=s(["\ud569\ub9ac\uc801 \uc790\uaca9\uc694\uac74\uc758 \ud5c8\uc6a9"],t.s)
B.bHG=new A.a("gen_ta_restrict_5","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud68c\uc6d0\uc790\uaca9 \uc694\uac74\uc73c\ub85c \ud569\ub9ac\uc801\uc774\uace0 \uac1d\uad00\uc801\uc778 \ucd5c\uc18c\ud55c\uc758 \uc804\ubb38\uc131 \uae30\uc900(\uc608: \uad00\ub828 \uc790\uaca9\uc99d \ubcf4\uc720)\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aUg,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc5c5\ubb34\uc758 \uc804\ubb38\uc131\uc774\ub098 \uc548\uc804 \ud655\ubcf4 \ub4f1\uc744 \uc704\ud574 \ud569\ub9ac\uc801\uc774\uace0 \uac1d\uad00\uc801\uc778 \ucd5c\uc18c\ud55c\uc758 \uc790\uaca9\uc694\uac74(\uad00\ub828 \uc790\uaca9\uc99d \ubcf4\uc720 \ub4f1)\uc744 \uc815\ud558\ub294 \uac83\uc740, \uadf8 \uc790\uccb4\ub85c \ubd80\ub2f9\ud55c \uc0ac\uc5c5\uc790 \uc218 \uc81c\ud55c\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uae30 \uc5b4\ub835\ub2e4. \ubb38\uc81c\ub294 \uadf8\ub7ec\ud55c \uae30\uc900\uc774 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc2e0\uaddc \uc9c4\uc785\uc744 \uc790\uc758\uc801\xb7\uacfc\ub3c4\ud558\uac8c \ubd09\uc1c4\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \ub0a8\uc6a9\ub418\ub294\uc9c0 \uc5ec\ubd80\uc774\ub2e4.",B.alX,B.ban,null)
B.abG=s([u.Bs,"\uc601\uc5c5\uc9c0\uc5ed \ubd84\ud560\uc740 \ud56d\uc0c1 \ud6a8\uc728\uc801\uc778 \uacbd\uc601\uae30\ubc95\uc73c\ub85c\uc11c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc601\uc5c5\uc9c0\uc5ed \ubd84\ud560 \uacb0\uc758\ub294 \uc18c\ube44\uc790\uc5d0\uac8c \uc804\ud600 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc774\ub7ec\ud55c \uacb0\uc758\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc544\ub2c8\ub77c \uc815\ubd80\ub9cc \ud560 \uc218 \uc788\ub294 \uc870\uce58\uc774\ub2e4","\uc601\uc5c5\uc9c0\uc5ed \ubd84\ud560\uc740 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uac1c\ubcc4 \uacc4\uc57d\uc73c\ub85c\ub9cc \ub2e4\ub8e8\uc5b4\uc9c8 \ubfd0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640\ub294 \ubb34\uad00\ud558\ub2e4"],t.s)
B.avC=s([u.Bs],t.s)
B.bdX=s(["\uc601\uc5c5\uc9c0\uc5ed \ubd84\ud560 \uacb0\uc758"],t.s)
B.by4=new A.a("gen_ta_restrict_6","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc0ac\uc5c5\uc790\uc218 \uc81c\ud55c\xb7\uc0ac\uc5c5\ub0b4\uc6a9 \uc81c\ud55c","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\uc9c0\uc5ed\uc744 \uc784\uc758\ub85c \ub098\ub204\uc5b4 \uc11c\ub85c\uc758 \uc9c0\uc5ed\uc744 \uce68\ubc94\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \uacb0\uc758\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.abG,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\uc758 \uc601\uc5c5\uc9c0\uc5ed\uc744 \uc784\uc758\ub85c \ubd84\ud560\ud558\uc5ec \uc11c\ub85c \uce68\ubc94\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \uacb0\uc758\ud558\ub294 \uac83\uc740, \uc9c0\uc5ed\ubcc4 \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\uac70\ud558\ub294 \ud589\uc704\ub85c\uc11c \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ub0b4\uc6a9\xb7\ud65c\ub3d9\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc18c\ube44\uc790\uc758 \uc120\ud0dd\uad8c \ucd95\uc18c\uc640 \uac00\uaca9 \uc0c1\uc2b9\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5b4 \uacbd\uc7c1\uc81c\ud55c \uc6b0\ub824\uac00 \ud06c\ub2e4.",B.avC,B.bdX,null)
B.aaq=s(["\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc728\ub41c\ub2e4","\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\ub9cc \ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640\ub294 \ubb34\uad00\ud558\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ubc29\uc870\ud589\uc704\uc5d0 \ub300\ud574 \uc5b4\ub5a0\ud55c \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uc720\ud615\uc740 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc \uac00\ub2a5\ud558\uace0 \ud589\uc815\uc81c\uc7ac\ub294 \ubd88\uac00\ub2a5\ud558\ub2e4","\uc774 \uc720\ud615\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc815\uad00\uc5d0 \uba85\uc2dc\ub418\uc9c0 \uc54a\uc73c\uba74 \uaddc\uc81c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.auX=s(["\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc728\ub41c\ub2e4"],t.s)
B.a27=s(["\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ubc29\uc870"],t.s)
B.brf=new A.a("gen_ta_aid_1","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\xb7\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0 \ubc29\uc870","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\ub85c \ud558\uc5ec\uae08 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub97c \ud558\uac8c \ud558\uac70\ub098 \uc774\ub97c \ubc29\uc870\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aaq,0,"\uacf5\uc815\uac70\ub798\ubc95 \uc81c51\uc870 \uc81c1\ud56d \uc81c4\ud638\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \ub610\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub97c \ud558\uac8c \ud558\uac70\ub098 \uc774\ub97c \ubc29\uc870\ud558\ub294 \ud589\uc704\ub97c \uae08\uc9c0\ud589\uc704\ub85c \uaddc\uc815\ud55c\ub2e4. \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc9c1\uc811 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \uc8fc\uccb4\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4, \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\uc758 \uadf8\ub7ec\ud55c \ud589\uc704\ub97c \uc720\ub3c4\xb7\ubc29\uc870\ud55c\ub2e4\uba74 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc790\uccb4\uac00 \ucc45\uc784\uc744 \uc9c8 \uc218 \uc788\ub2e4.",B.auX,B.a27,null)
B.TY=s([u.s8,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc9c0\uce68\uc740 \uad8c\uace0\uc5d0 \ubd88\uacfc\ud558\ubbc0\ub85c \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uaddc\uc81c \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4","\uac70\ub798\uac70\uc808\uc740 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \uc790\uc720\uc774\ubbc0\ub85c \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc9c0\uce68\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc801\ubc95\ud558\ub2e4","\uc774 \uacbd\uc6b0 \ud2b9\uc815 \uc720\ud1b5\uc5c5\uc790\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \ubc95\uc801 \ubcf4\ud638\ub3c4 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc9c0\uce68\uc740 \uc624\uc9c1 \ub3c4\ub355\uc801 \ubb38\uc81c\uc77c \ubfd0 \ubc95\uc801 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4"],t.s)
