B.bOp=new A.a("gen_ta_aid_5","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\xb7\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0 \ubc29\uc870","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\uc5d0\uac8c \ud2b9\uc815 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc640 \uac70\ub798\ud558\uc9c0 \ub9d0 \uac83\uc744 \uad8c\uace0\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.XX,0,'"\uad8c\uace0"\ub77c\ub294 \ud615\uc2dd\uc744 \ucde8\ud558\ub354\ub77c\ub3c4 \uadf8 \uc2e4\uc9c8\uc774 \uad6c\uc131\uc0ac\uc5c5\uc790\ub4e4\ub85c \ud558\uc5ec\uae08 \ud2b9\uc815 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \ubc30\uc81c\ud558\ub3c4\ub85d \uc720\ub3c4\ud558\ub294 \uac83\uc774\ub77c\uba74, \ubc30\ud0c0\uc870\uac74\ubd80\uac70\ub798\ub098 \uac70\ub798\uac70\uc808\uacfc \uac19\uc740 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\ub97c \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud558\uac8c \ud558\uac70\ub098 \ubc29\uc870\ud55c \uac83\uc73c\ub85c \ud3c9\uac00\ub418\uc5b4 \uaddc\uc728 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4. \ud615\uc2dd\ubcf4\ub2e4 \uc2e4\uc9c8\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc774 \ubd84\uc57c\uc758 \uc77c\ubc18\uc801 \uc811\uadfc\uc774\ub2e4.',B.a8x,B.aSg,null)
B.awY=s(["\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc784\uc9c1\uc6d0 \uac1c\uc778\uc758 \uc0ac\uc801\uc778 \ucde8\ubbf8 \ud65c\ub3d9","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c \ud574\ub2f9 \ud589\uc704\ub97c \ud558\ub3c4\ub85d \uc2e4\uc9c8\uc801\uc778 \uc601\ud5a5\ub825\uc744 \ud589\uc0ac\ud588\ub294\uc9c0 \uc5ec\ubd80","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc9c0\uce68\xb7\uacb0\uc758\xb7\uad8c\uace0 \ub4f1\uc774 \uad6c\uc131\uc0ac\uc5c5\uc790\uc758 \ud589\uc704\uc5d0 \ubbf8\uce5c \uc601\ud5a5\uc758 \uc815\ub3c4","\ud574\ub2f9 \ud589\uc704\ub85c \uc778\ud574 \uc2e4\uc81c\ub85c \uacbd\uc7c1\uc774\ub098 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ubbf8\uce5c \uc601\ud5a5","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc640 \uad6c\uc131\uc0ac\uc5c5\uc790 \uac04\uc758 \uc870\uc9c1\uc801 \uad00\uacc4"],t.s)
