B.bso=new A.a("gen_ta_sanction_4","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58(\uc0ac\uc5c5\uc790\ub2e8\uccb4)","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704 \uc870\uc0ac \uc808\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aeT,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub3c4 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud558\uac70\ub098, \uc774\ud574\uad00\uacc4\uc778\uc758 \uc2e0\uace0\ub97c \uacc4\uae30\ub85c \uc870\uc0ac\ub97c \uc9c4\ud589\ud560 \uc218 \uc788\ub2e4. \uc870\uc0ac\uc5d0 \uad6c\uc131\uc0ac\uc5c5\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\uba70, \uc870\uc0ac \uacb0\uacfc \uc704\ubc18\uc0ac\uc2e4\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uc73c\uba74 \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c0\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4.",B.bfU,B.aI4,null)
B.aU6=s(["\ud574\ub2f9 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud560 \uc218 \uc788\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud560 \uc218 \uc5c6\ub2e4","\ubd88\ubcf5\uc740 \uc624\uc9c1 \uad6c\uc131\uc0ac\uc5c5\uc790 \uac1c\uc778\ub9cc \uc81c\uae30\ud560 \uc218 \uc788\uace0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ubd88\ubcf5\ud560 \uc218 \uc5c6\ub2e4","\ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc740 \ud615\uc0ac\uc7ac\ud310\uc744 \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ubd88\ubcf5\uc808\ucc28\ub294 \uc815\ubd80\uc758 \uc7ac\ub7c9\uc73c\ub85c \uc644\uc804\ud788 \ubc30\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
