B.bK4=new A.a("gen_rpm_sanction_5","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc190\ud574\ubc30\uc0c1","\uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uac00\ub9f9\ubcf8\ubd80\uc5d0 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uad00\ub828 \ub9ac\uc2a4\ud06c\ub97c \uc790\ubb38\ud560 \ub54c \uac15\uc870\ud574\uc57c \ud560 \uc0ac\ud56d\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b4T,0,"\uac00\ub9f9\uac70\ub798\uc0ac\ub294 \uac00\ub9f9\ubcf8\ubd80\uc5d0 \uc790\ubb38\ud560 \ub54c, \uac00\ub9f9\uc810\uc5d0 \ub300\ud55c \ucd5c\uc800\ud310\ub9e4\uac00\uaca9 \uc9c0\uc815\uacfc \uadf8 \uc900\uc218\ub97c \uac15\uc81c\ud558\ub294 \uc870\uce58\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c0\uba74 \ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c\uc11c \uc704\ubc95\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uba85\ud655\ud788 \uc548\ub0b4\ud558\uc5ec \ubc95\uc801 \ub9ac\uc2a4\ud06c\ub97c \uc0ac\uc804\uc5d0 \uad00\ub9ac\ud558\ub3c4\ub85d \ub3c4\uc640\uc57c \ud55c\ub2e4.",B.b2p,B.me,null)
B.aS8=s(["\uc720\ud1b5\uc5c5\uc790 \uac04 \uac00\uaca9\uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uc5ec \uc18c\ube44\uc790\uac00 \ub354 \ub192\uc740 \uac00\uaca9\uc744 \uc9c0\ubd88\ud558\uac8c \ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uc81c\uc870\uc5c5\uccb4\uc758 \uc774\uc775\uc744 \ubb34\uc870\uac74 \uadf9\ub300\ud654\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uc720\ud1b5\uc5c5\uc790\uc758 \uc790\uc720\ub85c\uc6b4 \uc601\uc5c5\uc744 \uc644\uc804\ud788 \uae08\uc9c0\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uc18c\ube44\uc790\uc758 \uc120\ud0dd\uad8c\uc744 \ucd95\uc18c\uc2dc\ud0a4\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
B.aab=s(["\uc720\ud1b5\ub2e8\uacc4\uc758 \uac00\uaca9\uc744 \ud1b5\uc81c\ud558\uba74 \uc720\ud1b5\uc5c5\uc790 \uac04\uc758 \uac00\uaca9\uacbd\uc7c1\uc774 \uc0ac\ub77c\uc838 \uc18c\ube44\uc790\uac00 \ub354 \ub192\uc740 \uac00\uaca9\uc744 \uc9c0\ubd88\ud558\uac8c \ub420 \uac00\ub2a5\uc131\uc774 \ucee4\uc9c0\uae30 \ub54c\ubb38"],t.s)
