B.bAI=new A.a("gen_rpm_extra_1","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc885\ud569 \uc0ac\ub840","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uaddc\uc81c \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aS8,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub97c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ud558\ub294 \uc774\uc720\ub294, \uc81c\uc870\uc5c5\uccb4\uac00 \uc720\ud1b5\ub2e8\uacc4\uc758 \uac00\uaca9\uc744 \ud1b5\uc81c\ud558\uba74 \uc720\ud1b5\uc5c5\uc790 \uac04\uc758 \uac00\uaca9\uacbd\uc7c1(\ube0c\ub79c\ub4dc \ub0b4 \uacbd\uc7c1)\uc774 \uc0ac\ub77c\uc838 \uc18c\ube44\uc790\uac00 \ub354 \ub192\uc740 \uac00\uaca9\uc744 \uc9c0\ubd88\ud558\uac8c \ub420 \uac00\ub2a5\uc131\uc774 \ucee4\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4.",B.aab,B.aks,null)
B.aUc=s(["\uc800\uc791\uad8c\ubc95\uc5d0 \ub530\ub978 \uc800\uc791\ubb3c \uc911 \uc77c\uc815\ud55c \uacbd\uc6b0(\uc608: \uc2e0\ubb38 \ub4f1) \ubc95\ub839\uc5d0\uc11c \uc608\uc678\ub97c \uc778\uc815\ud558\ub294 \uacbd\uc6b0","\ubaa8\ub4e0 \uc18c\ube44\uc7ac\uc5d0 \ub300\ud574 \ud56d\uc0c1 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub41c\ub2e4","\uc911\uc18c\uae30\uc5c5\uc774 \uc81c\uc870\ud55c \uc81c\ud488\uc774\uba74 \uc608\uc678 \uc5c6\uc774 \ud56d\uc0c1 \ud5c8\uc6a9\ub41c\ub2e4","\uc628\ub77c\uc778\uc73c\ub85c\ub9cc \ud310\ub9e4\ub418\ub294 \uc81c\ud488\uc740 \uc608\uc678 \uc5c6\uc774 \ud56d\uc0c1 \ud5c8\uc6a9\ub41c\ub2e4"],t.s)
