B.bOH=new A.a("gen_sp_type_2","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ud558\uc704 \uc720\ud615 \uc911 "\uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc758 \uac70\ub798"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aS5,0,'"\uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc758 \uac70\ub798"\ub294 \uc815\uc0c1\uc801\uc778 \uac70\ub798 \uad00\ud589\uc5d0\uc11c \uc801\uc6a9\ub418\ub294 \uc870\uac74(\uac00\uaca9, \uc774\uc790\uc728 \ub4f1)\uc5d0 \ube44\ud574 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ud604\uc800\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \uc790\uae08\xb7\uc790\uc0b0\xb7\uc0c1\ud488\xb7\uc6a9\uc5ed\uc744 \uac70\ub798\ud568\uc73c\ub85c\uc368 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud558\ub294 \uc0ac\uc775\ud3b8\ucde8 \uaddc\uc81c\uc758 \ub300\ud45c\uc801\uc778 \ud558\uc704 \uc720\ud615\uc774\ub2e4.',B.asj,B.a6U,null)
B.QH=s([u.d2,"\ud68c\uc0ac\uac00 \uc790\uccb4\uc801\uc73c\ub85c \uc0ac\uc5c5\uae30\ud68c\ub97c \uac1c\ubc1c\ud558\uc5ec \ud65c\uc6a9\ud558\ub294 \ud589\uc704","\uc678\ubd80 \uc0ac\uc5c5\uc790\uc640 \uacf5\uc815\ud55c \uc808\ucc28\ub97c \uac70\uccd0 \uc0ac\uc5c5 \uc81c\ud734\ub97c \ub9fa\ub294 \ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc544\ub2cc \uc790\uc5d0\uac8c \uc0ac\uc5c5 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub294 \ud589\uc704","\ud68c\uc0ac\uac00 \uc815\ub2f9\ud55c \ub300\uac00\ub97c \ubc1b\uace0 \uc0ac\uc5c5\uad8c\uc744 \uc591\ub3c4\ud558\ub294 \ud589\uc704"],t.s)
