B.bvZ=new A.a("gen_sp_type_3","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ud558\uc704 \uc720\ud615 \uc911 "\uc0ac\uc5c5\uae30\ud68c \uc81c\uacf5"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.QH,0,'"\uc0ac\uc5c5\uae30\ud68c \uc81c\uacf5"\uc740 \ud68c\uc0ac\uac00 \uc2a4\uc2a4\ub85c \uc218\ud589\ud558\uc600\uc744 \uacbd\uc6b0 \uc0c1\ub2f9\ud55c \uc774\uc775\uc774 \ub420 \uac83\uc73c\ub85c \uc608\uc0c1\ub418\ub294 \uc0ac\uc5c5\uae30\ud68c\ub97c \uc815\ub2f9\ud55c \ub300\uac00 \uc5c6\uc774 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ub118\uaca8\uc8fc\uc5b4 \uadf8 \uc774\uc775\uc744 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud558\uba70, \ud68c\uc0ac\uc758 \uc774\uc775\uc744 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \uc720\ucd9c\ud558\ub294 \ub300\ud45c\uc801\uc778 \uc0ac\uc775\ud3b8\ucde8 \uc720\ud615\uc774\ub2e4.',B.YV,B.bcq,null)
B.Yv=s([u.g6,"\uc5ec\ub7ec \uc0ac\uc5c5\uc790\uc640 \uacf5\uc815\ud55c \uc785\ucc30\uc744 \uac70\uccd0 \ucd5c\uc801\uc758 \uac70\ub798\ucc98\ub97c \uc120\uc815\ud558\ub294 \ud589\uc704","\uac70\ub798 \uaddc\ubaa8\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucd5c\uc800\uac00 \uc785\ucc30\uc790\uc640 \uac70\ub798\ud558\ub294 \ud589\uc704","\ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc544\ub2cc \ud68c\uc0ac\uc640 \ub300\uaddc\ubaa8\ub85c \uac70\ub798\ud558\ub294 \ud589\uc704","\uac70\ub798 \uaddc\ubaa8\ub97c \uc810\uc9c4\uc801\uc73c\ub85c \ucd95\uc18c\ud558\ub294 \ud589\uc704"],t.s)
