B.b_U=s(["\uc77c\uac10\ubab0\uc544\uc8fc\uae30\uc758 \uc758\ubbf8"],t.s)
B.bxl=new A.a("gen_sp_type_4","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ud558\uc704 \uc720\ud615 \uc911 "\ud569\ub9ac\uc801 \uace0\ub824\ub098 \ube44\uad50 \uc5c6\uc774 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\ub85c \uac70\ub798"\ud558\ub294 \ud589\uc704(\uc77c\uac10\ubab0\uc544\uc8fc\uae30)\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.Yv,0,'\uc774\ub978\ubc14 "\uc77c\uac10\ubab0\uc544\uc8fc\uae30"\ub85c \ubd88\ub9ac\ub294 \uc774 \uc720\ud615\uc740, \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc640\uc758 \uac00\uaca9\xb7\ud488\uc9c8\xb7\uae30\uc220\ub825 \ub4f1\uc5d0 \ub300\ud55c \ud569\ub9ac\uc801\uc778 \ube44\uad50\xb7\uac80\ud1a0 \uc5c6\uc774 \ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc9c0\ubc30\ud558\ub294 \ud68c\uc0ac\uc5d0 \uc0c1\ub2f9\ud55c \uaddc\ubaa8\uc758 \uac70\ub798\ub97c \ubab0\uc544\uc90c\uc73c\ub85c\uc368 \uadf8 \ud68c\uc0ac\uc5d0 \ubd80\ub2f9\ud55c \uc774\uc775\uc744 \uadc0\uc18d\uc2dc\ud0a4\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud55c\ub2e4.',B.a1U,B.b_U,null)
B.a38=s([u.bN,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \ub300\uae30\uc5c5\uc758 \uc815\uc0c1\uc801\uc778 \uacc4\uc5f4\uc0ac \uac04 \uac70\ub798 \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc18c\uc561\uc8fc\uc8fc\uc758 \uc774\uc775\uacfc \uc804\ud600 \ubb34\uad00\ud55c \ubb38\uc81c\uc774\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4","\uc774 \uaddc\uc81c\ub294 \uc911\uc18c\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc81c\uc774\ub2e4"],t.s)
B.biQ=s([u.bN],t.s)
B.auc=s(["\uaddc\uc81c\uc758 \uc815\ucc45\uc801 \uc774\uc720"],t.s)
B.bEJ=new A.a("gen_sp_type_5","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uac00 \ud544\uc694\ud55c \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a38,0,'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294, \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \ucd1d\uc218 \uc77c\uac00\ub098 \uacc4\uc5f4\ud68c\uc0ac\uc5d0 \ubd80\ub2f9\ud55c \ubc29\ubc95\uc73c\ub85c \ubd80\ub97c \uc774\uc804\uc2dc\ucf1c \uacbd\uc81c\ub825 \uc9d1\uc911\uc744 \uc2ec\ud654\uc2dc\ud0a4\uace0, \uadf8 \uacfc\uc815\uc5d0\uc11c \uc18c\uc561\uc8fc\uc8fc \ub4f1 \ub2e4\ub978 \uc774\ud574\uad00\uacc4\uc790\uc758 \uc774\uc775\uc744 \uce68\ud574\ud558\ub294 \uc774\ub978\ubc14 "\uc0ac\uc775\ud3b8\ucde8" \ubb38\uc81c\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uc815\ucc45\uc801 \ubaa9\uc801\uc744 \uac16\ub294\ub2e4.',B.biQ,B.auc,null)
B.bgc=s([u.gb,"\ub450 \uaddc\uc81c\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc694\uac74\uacfc \ub300\uc0c1\uc744 \uac16\ub294\ub2e4","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uac00 \ub3c4\uc785\ub418\uba74\uc11c \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uaddc\uc81c\ub294 \uc644\uc804\ud788 \ud3d0\uc9c0\ub418\uc5c8\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uaddc\uc81c\ub294 \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc758 \ud558\uc704 \uac1c\ub150\uc5d0 \ubd88\uacfc\ud558\ub2e4","\ub450 \uaddc\uc81c\ub294 \uc11c\ub85c \ubaa8\uc21c\ub418\uc5b4 \ub3d9\uc2dc\uc5d0 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.Vn=s([u.gb],t.s)
B.ai_=s(["\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc640\uc758 \uad00\uacc4"],t.s)
B.bJY=new A.a("gen_sp_type_6","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc640 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704(\uc81c45\uc870) \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bgc,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704(\uc81c45\uc870)\ub294 \uc9c0\uc6d0 \uc8fc\uccb4 \uc0ac\uc5c5\uc790\uac00 \ud2b9\uc218\uad00\uacc4\uc778\uc774\ub098 \ub2e4\ub978 \ud68c\uc0ac\ub97c \ubd80\ub2f9\ud558\uac8c \uc9c0\uc6d0\ud558\ub294 \ud589\uc704 \uc790\uccb4\uc5d0 \ucd08\uc810\uc744 \ub450\ub294 \ubc18\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5(\uc81c47\uc870)\uc740 \uadf8\ub7ec\ud55c \uac70\ub798\ub97c \ud1b5\ud574 \ubc1c\uc0dd\ud55c \uc774\uc775\uc774 \uad81\uadf9\uc801\uc73c\ub85c \ucd1d\uc218 \uc77c\uac00 \ub4f1 \ud2b9\uc218\uad00\uacc4\uc778 \uac1c\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \ub354 \ucd08\uc810\uc744 \ub454\ub2e4\ub294 \uc810\uc5d0\uc11c \uaddc\uc728\uc758 \uac15\uc870\uc810\uc5d0 \ucc28\uc774\uac00 \uc788\uc73c\uba70, \ub450 \uaddc\uc81c\ub294 \uc911\ucca9\uc801\uc73c\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.Vn,B.ai_,null)
B.SO=s([u.Ew,"\uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \ub9e4\ucd9c \uaddc\ubaa8\ub9cc \uace0\ub824\ud55c\ub2e4","\uc624\uc9c1 \ud2b9\uc218\uad00\uacc4\uc778 \uac1c\uc778\uc758 \ucde8\ubbf8\ub9cc \uace0\ub824\ud55c\ub2e4","\ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uae30\uc900\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc694\uc77c\ub9cc \uace0\ub824\ud55c\ub2e4"],t.s)
B.bfC=s([u.Ew],t.s)
B.t5=s(["\ubd80\ub2f9\uc131 \ud310\ub2e8 \uc694\uc18c"],t.s)
B.bDA=new A.a("gen_sp_sanction_1","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.SO,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c\ub294 \uac70\ub798\uc870\uac74\uc774 \uc815\uc0c1 \uac70\ub798\uc5d0 \ube44\ud574 \uc5bc\ub9c8\ub098 \uc720\ub9ac\ud55c\uc9c0, \uac70\ub798\uaddc\ubaa8\uac00 \uc0c1\ub2f9\ud55c\uc9c0, \uadf8\ub85c \uc778\ud574 \ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc5bb\ub294 \uc774\uc775\uc758 \ud06c\uae30\uac00 \uc5bc\ub9c8\uc778\uc9c0 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.bfC,B.t5,null)
