B.bIy=new A.a("gen_sp_sanction_2","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uc704\ubc18\uc5d0 \ub300\ud574 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.h_,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uc704\ubc18\uc774 \uc778\uc815\ub418\uba74 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ub2e4\ub978 \ubc95 \uc704\ubc18\ud589\uc704\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc2dc\uc815\uc870\uce58(\uc911\uc9c0\uba85\ub839 \ub4f1) \ubc0f \uc704\ubc18 \uc815\ub3c4\uc5d0 \ub530\ub978 \uacfc\uc9d5\uae08 \ubd80\uacfc \ub4f1\uc758 \ud589\uc815\uc801 \uc870\uce58\ub97c \ucde8\ud560 \uc218 \uc788\ub2e4.",B.h1,B.bht,null)
B.b4S=s([u.qP,"\uc624\uc9c1 \uc774\uc775\uc744 \uc81c\uacf5\ud55c \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc81c\uc7ac\uac00 \uac00\ub2a5\ud558\ub2e4","\uc624\uc9c1 \uc774\uc775\uc744 \uc81c\uacf5\ubc1b\uc740 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c\ub9cc \uc81c\uc7ac\uac00 \uac00\ub2a5\ud558\ub2e4","\uc81c\uc7ac\uc758 \uc0c1\ub300\ubc29\uc740 \ubc95\ub960\uc0c1 \uc804\ud600 \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4","\uc81c\uc7ac\ub294 \uc624\uc9c1 \uc18c\ube44\uc790\uc5d0\uac8c\ub9cc \ubd80\uacfc\ub41c\ub2e4"],t.s)
