B.bDY=new A.a("gen_sp_sanction_4","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc73c\ub85c \ud53c\ud574\ub97c \uc785\uc740 \ud68c\uc0ac(\uc18c\uc561\uc8fc\uc8fc \ub4f1)\uc758 \uad6c\uc81c\uc218\ub2e8\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aBe,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc73c\ub85c \uc778\ud574 \ud68c\uc0ac\uc5d0 \uc190\ud574\uac00 \ubc1c\uc0dd\ud558\uace0 \uadf8\ub85c \uc778\ud574 \uc18c\uc561\uc8fc\uc8fc \ub4f1\uc774 \ud53c\ud574\ub97c \uc785\uc740 \uacbd\uc6b0, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\uc640\ub294 \ubcc4\ub3c4\ub85c \uc0c1\ubc95\uc0c1 \uc8fc\uc8fc\ub300\ud45c\uc18c\uc1a1\uc774\ub098 \ubbfc\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1\uccad\uad6c \ub4f1 \ub2e4\ub978 \ubc95\ub960\uc5d0 \ub530\ub978 \uad6c\uc81c\uc218\ub2e8\uc744 \ud568\uaed8 \uace0\ub824\ud560 \uc218 \uc788\ub2e4.",B.axF,B.aWy,null)
B.au9=s([u.DA,"\uc624\uc9c1 \ud2b9\uc218\uad00\uacc4\uc778\uc758 \uc8fc\uad00\uc801 \uc758\uacac\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ud310\ub2e8 \uae30\uc900\uc740 \ubc95\ub960\uc0c1 \uc804\ud600 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uacc4\uc808\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \uc124\ub9bd\uc5f0\ub3c4\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
