B.bMh=new A.a("gen_sp_sanction_5","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac",'\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc5d0\uc11c "\uc815\uc0c1\uc801\uc778 \uac70\ub798\uc5d0\uc11c \uc801\uc6a9\ub418\uc5c8\uc744 \uc870\uac74"\uc744 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.au9,0,'"\uc815\uc0c1\uc801\uc778 \uac70\ub798\uc5d0\uc11c \uc801\uc6a9\ub418\uc5c8\uc744 \uc870\uac74"\uc744 \ud310\ub2e8\ud560 \ub54c\ub294, \uc720\uc0ac\ud55c \uc2dc\uae30\xb7\uaddc\ubaa8\xb7\uc870\uac74\uc758 \ud1b5\uc0c1\uc801\uc778 \uac70\ub798\uc0ac\ub840\ub098 \uc2dc\uc7a5\uc5d0\uc11c \ud615\uc131\ub41c \uac00\uaca9\xb7\uc774\uc790\uc728 \ub4f1\uc744 \ucc38\uace0\ud558\uc5ec \ubb38\uc81c\ub41c \uac70\ub798\uc870\uac74\uacfc \ube44\uad50\xb7\ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \ubc29\uc2dd\uc774\ub2e4.',B.ana,B.RL,null)
B.Rm=s([u.zM,"\uac00\ub9f9\ubcf8\ubd80\uc640 \ucd1d\uc218 \uc77c\uac00 \uac04 \uac70\ub798\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uaddc\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb3c\ub958\uacc4\uc57d\uc740 \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\ub294 \ud56d\uc0c1 \uc815\ub2f9\ud55c \uacbd\uc601\ud310\ub2e8\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4","\uc774\ub7ec\ud55c \uac70\ub798\ub294 \uc624\uc9c1 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c\ub9cc \ud3c9\uac00\ub41c\ub2e4"],t.s)
