B.buV=new A.a("gen_consent_relation_2","economic_law","\ub3d9\uc758\uc758\uacb0","\ub3d9\uc758\uc758\uacb0\uacfc \ub2e4\ub978 \uc808\ucc28\uc758 \uad00\uacc4","\ub3d9\uc758\uc758\uacb0\uc774 \uc18c\ube44\uc790\xb7\uac70\ub798\uc0c1\ub300\ubc29\uc758 \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aKI,0,"\ub3d9\uc758\uc758\uacb0\uc740 \uc0ac\uc5c5\uc790\uac00 \uc81c\uc2dc\ud55c \uc2dc\uc815\ubc29\uc548\uc744 \uc778\uc815\ud558\uc5ec \uc0ac\uac74\uc744 \uc885\uacb0\ud558\ub294 \uac83\uc77c \ubfd0 \uc704\ubc95\uc131\uc744 \ud655\uc815\uc801\uc73c\ub85c \uc778\uc815\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ubbc0\ub85c, \uc774\ud6c4 \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\ub294 \ud53c\ud574\uc790\ub294 \ub3d9\uc758\uc758\uacb0\uacfc\ub294 \ubcc4\uac1c\ub85c \uc2a4\uc2a4\ub85c \uc704\ubc95\uc131\xb7\uc778\uacfc\uad00\uacc4\xb7\uc190\ud574\uc561\uc744 \uc99d\uba85\ud574\uc57c \ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aGS,B.a8t,null)
B.atp=s([u.ss,"\ub3d9\uc758\uc758\uacb0\uc740 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ubd80\uacfc\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\ub3d9\uc758\uc758\uacb0\uc774 \ud655\uc815\ub418\uba74 \uc790\ub3d9\uc73c\ub85c \ucd5c\uace0 \uc218\uc900\uc758 \uacfc\uc9d5\uae08\uc774 \ubd80\uacfc\ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0\uc740 \uc2dc\uc815\uc870\uce58\ubcf4\ub2e4 \ud56d\uc0c1 \ub354 \ubb34\uac70\uc6b4 \uc81c\uc7ac\uc774\ub2e4","\ub3d9\uc758\uc758\uacb0\uacfc \uc2dc\uc815\uc870\uce58\ub294 \ub3d9\uc2dc\uc5d0 \ud568\uaed8 \ubd80\uacfc\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
