B.bEk=new A.a("gen_consent_relation_3","economic_law","\ub3d9\uc758\uc758\uacb0","\ub3d9\uc758\uc758\uacb0\uacfc \ub2e4\ub978 \uc808\ucc28\uc758 \uad00\uacc4","\ub3d9\uc758\uc758\uacb0 \uc81c\ub3c4\uc640 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ubd80\uacfc \uc81c\ub3c4\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.atp,0,"\ub3d9\uc758\uc758\uacb0\uc740 \uc704\ubc18\ud589\uc704\uc758 \uc704\ubc95\uc131\uc744 \ud655\uc815\uc801\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08\uc744 \ubd80\uacfc\ud558\ub294 \ud1b5\uc0c1\uc801\uc778 \uc808\ucc28\uc640 \ub2ec\ub9ac, \uc704\ubc95\uc131 \ud310\ub2e8 \uc5c6\uc774 \uc0ac\uc5c5\uc790\uac00 \uc81c\uc2dc\ud55c \uc2dc\uc815\ubc29\uc548\uc758 \uc774\ud589\uc744 \ud1b5\ud574 \uc0ac\uac74\uc744 \uc2e0\uc18d\ud558\uac8c \uc885\uacb0\ud558\ub294 \ub300\uc548\uc801\uc778 \uc808\ucc28\ub77c\ub294 \uc810\uc5d0\uc11c \uc131\uaca9\uc744 \ub2ec\ub9ac\ud55c\ub2e4.",B.a8p,B.aHk,null)
B.UD=s([u.cE,"\ub3d9\uc758\uc758\uacb0\uc744 \uc2e0\uccad\ud558\uba74 \ubb34\uc870\uac74 \ubb34\ud610\uc758\ub85c \ucc98\ub9ac\ub41c\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0\uc740 \uac00\ub9f9\uac70\ub798\uc640 \uc804\ud600 \ubb34\uad00\ud55c \uc81c\ub3c4\ub77c\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0\uc740 \uc2e0\uccad \uc989\uc2dc \uc544\ubb34\ub7f0 \uc758\ubb34 \uc5c6\uc774 \uc0ac\uac74\uc774 \uc885\uacb0\ub41c\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0\uc740 \uc624\uc9c1 \ub300\uae30\uc5c5\ub9cc \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4"],t.s)
