B.byJ=new A.a("gen_super_extra_6","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9 \uc885\ud569 \uc0ac\ub840","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aVJ,0,"\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \ubd80\ub2f9\uc131\uc740 \ub2e8\uc21c\ud788 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \ubd88\uc774\uc775\uc774 \ubc1c\uc0dd\ud588\ub2e4\ub294 \uacb0\uacfc\ub9cc\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\uace0, \uc815\uc0c1\uc801\uc778 \uac70\ub798\uad00\ud589\uc5d0 \ube44\ucd94\uc5b4 \uadf8 \ud589\uc704\uac00 \uac70\ub798\uc0c1 \uc9c0\uc704\ub97c \ub0a8\uc6a9\ud55c \uac83\uc73c\ub85c \ubcfc \uc218 \uc788\ub294\uc9c0\ub97c \uac70\ub798 \uacbd\uc704, \ub0b4\uc6a9, \uc5c5\uacc4 \uad00\ud589 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4.",B.awn,B.aP9,null)
B.aqs=s(["\ub458 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790 \uac04\uc758 \ud569\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud569\uc758\ub294 \uba85\uc2dc\uc801 \ud569\uc758\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\uc73c\ub85c\ub3c4 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\ud569\uc758\uc758 \uc874\uc7ac\ub294 \uc774\ub97c \uc8fc\uc7a5\ud558\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud569\uc758\uac00 \uc788\uc5c8\ub354\ub77c\ub3c4 \uc2e4\ud589\ud589\uc704\ub85c \ub098\uc544\uac00\uc9c0 \uc54a\uc558\ub2e4\uba74 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub294 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc77c\uc815\ud55c \uac70\ub798\ubd84\uc57c\uc5d0\uc11c \uacbd\uc7c1\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc81c\ud55c\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
