B.aui=s(["\ub2e4\ub978 \uc815\ud669\uc99d\uac70\uc640 \ud568\uaed8 \ud569\uc758\ub97c \uc778\uc815\ud558\ub294 \uc720\ub825\ud55c \uc99d\uac70\ub85c \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uc9c4\uc220\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc99d\uac70\ub85c \uc0ac\uc6a9\ub420 \uc218 \uc5c6\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uc9c4\uc220\ub9cc \uc788\uc73c\uba74 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \ubc18\ubc15 \uae30\ud68c \uc5c6\uc774 \uace7\ubc14\ub85c \ucc98\ubd84\uc774 \ud655\uc815\ub41c\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uc9c4\uc220\uc740 \uc624\uc9c1 \uc790\uc9c4\uc2e0\uace0\uc790 \ubcf8\uc778\uc758 \uc0ac\uac74\uc5d0\ub9cc \uc0ac\uc6a9\ub41c\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uc9c4\uc220\uc740 \ud56d\uc0c1 \uc2e0\ube59\uc131\uc774 \uc5c6\ub294 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.ar2=s(["\ub2e4\ub978 \uc815\ud669\uc99d\uac70\uc640 \ud568\uaed8 \ud569\uc758\ub97c \uc778\uc815\ud558\ub294 \uc720\ub825\ud55c \uc99d\uac70\ub85c \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aze=s(["\uc790\uc9c4\uc2e0\uace0 \uc9c4\uc220\uc758 \uc99d\uac70\uac00\uce58"],t.s)
B.bzQ=new A.a("gen_collusion_presume_5","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758 \ucd94\uc815\xb7\uc99d\uba85\ucc45\uc784","\uc790\uc9c4\uc2e0\uace0(\ub9ac\ub2c8\uc5b8\uc2dc)\ub97c \ud1b5\ud574 \ud655\ubcf4\ub41c \uc9c4\uc220\uc774 \ub2e4\ub978 \ucc38\uc5ec \uc0ac\uc5c5\uc790\uc5d0 \ub300\ud55c \ud569\uc758 \uc99d\uba85\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aui,0,"\uc790\uc9c4\uc2e0\uace0(\ub9ac\ub2c8\uc5b8\uc2dc)\ub97c \ud1b5\ud574 \ud655\ubcf4\ub41c \uc0ac\uc5c5\uc790\uc758 \uc9c4\uc220\uc740 \ub2e4\ub978 \ucc38\uc5ec \uc0ac\uc5c5\uc790\uc5d0 \ub300\ud55c \ud569\uc758\ub97c \uc99d\uba85\ud558\ub294 \ub370 \uc788\uc5b4 \ub2e4\ub978 \uc815\ud669\uc99d\uac70\uc640 \ud568\uaed8 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ub418\ub294 \uc720\ub825\ud55c \uc99d\uac70\ub85c \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uadf8 \uc9c4\uc220\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \ubc18\ubc15 \uae30\ud68c \uc5c6\uc774 \ucc98\ubd84\uc774 \ud655\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.ar2,B.aze,null)
B.a7c=s(["\ud569\uc758 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \ub370 \ucc38\uace0\ub418\ub294 \uc5ec\ub7ec \uc815\ud669 \uc911 \ud558\ub098\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\ub9cc\uc73c\ub85c \ud56d\uc0c1 \ud569\uc758\uac00 \ud655\uc815\uc801\uc73c\ub85c \uc778\uc815\ub41c\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uc740 \ud569\uc758 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uc740 \uc624\uc9c1 \uae30\uc5c5\uacb0\ud569 \uc2ec\uc0ac\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uc740 \ud569\uc758\ub97c \ubd80\uc815\ud558\ub294 \uc808\ub300\uc801 \uc99d\uac70\uc774\ub2e4"],t.s)
B.aAo=s(["\ud569\uc758 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \ub370 \ucc38\uace0\ub418\ub294 \uc5ec\ub7ec \uc815\ud669 \uc911 \ud558\ub098\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aQ6=s(["\uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uacfc \ud569\uc758 \ud310\ub2e8"],t.s)
B.bQt=new A.a("gen_collusion_presume_6","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758 \ucd94\uc815\xb7\uc99d\uba85\ucc45\uc784","\ud569\uc758\uc758 \uc99d\uba85\uacfc \uad00\ub828\ud558\uc5ec \uc0ac\uc5c5\uc790\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9\uc774 \uac16\ub294 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a7c,0,"\uc0ac\uc5c5\uc790\ub4e4\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ubcc0\ub3d9 \uc591\uc0c1\uc740 \uadf8 \uc790\uccb4\ub85c \ud569\uc758\ub97c \ud655\uc815\ud558\ub294 \uc808\ub300\uc801 \uc99d\uac70\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ub2e4\ub978 \uc815\ud669\uc99d\uac70\ub4e4\uacfc \ud568\uaed8 \ud569\uc758 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \ub370 \ucc38\uace0\ud560 \uc218 \uc788\ub294 \uc5ec\ub7ec \uc694\uc18c \uc911 \ud558\ub098\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4.",B.aAo,B.aQ6,null)
B.S6=s([u.a7,"\ud569\uc758\uac00 \uc788\uc5c8\ub358 \ucd5c\ucd08 \uc2dc\uc810\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud558\uace0 \uc774\ud6c4 \uc0ac\uc815\uc740 \uc804\ud600 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \ud56d\uc0c1 \uc815\ubd80\uc758 \uc870\uc0ac \uac1c\uc2dc\uc77c\ub85c \uace0\uc815\ub41c\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \ud310\ub2e8\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uac1c\ub150\uc774\ub2e4","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \uc5b8\ub860\ubcf4\ub3c4\uc77c\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.adg=s([u.a7],t.s)
B.Zz=s(["\uacf5\ub3d9\ud589\uc704 \uc885\uae30\uc758 \ud310\ub2e8\uae30\uc900"],t.s)
B.bxc=new A.a("gen_collusion_end_1","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30(\u7d42\u671f)\ub97c \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.S6,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\ub294 \ub2e8\uc21c\ud788 \ud569\uc758\uac00 \uc131\ub9bd\ud55c \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c, \ud569\uc758\uc5d0 \ub530\ub978 \uc2e4\ud589\ud589\uc704\uac00 \ucd5c\uc885\uc801\uc73c\ub85c \uc885\ub8cc\ub41c \uc2dc\uc810\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4. \uc774\ub294 \uacfc\uc9d5\uae08 \uc0b0\uc815, \ucc98\ubd84\uc2dc\ud6a8 \uae30\uc0b0 \ub4f1\uc5d0 \uc911\uc694\ud55c \uc758\ubbf8\ub97c \uac16\ub294\ub2e4.",B.adg,B.Zz,null)
B.age=s([u.i_,"\ub0b4\uc2ec\uc73c\ub85c\ub9cc \uc774\ud0c8\uc744 \uacb0\uc2ec\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \uadf8 \uc2dc\uc810\ubd80\ud130 \ucc45\uc784\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4","\uc774\ud0c8 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uba74 \uacfc\uac70\uc758 \ucc45\uc784\uae4c\uc9c0 \ubaa8\ub450 \uc18c\uae09\ud558\uc5ec \uba74\uc81c\ub41c\ub2e4","\uc774\ud0c8 \uc758\uc0ac \ud45c\uc2dc\ub294 \ubc95\uc801\uc73c\ub85c \uc544\ubb34\ub7f0 \uc758\ubbf8\uac00 \uc5c6\ub2e4","\uc774\ud0c8 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uba74 \uc624\ud788\ub824 \uac00\uc911\ucc98\ubc8c\ub41c\ub2e4"],t.s)
B.agg=s([u.i_],t.s)
B.af3=s(["\uacf5\ub3d9\ud589\uc704\ub85c\ubd80\ud130\uc758 \uc774\ud0c8"],t.s)
B.bA5=new A.a("gen_collusion_end_2","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\uacf5\ub3d9\ud589\uc704\uc5d0 \ucc38\uc5ec\ud588\ub358 \uc0ac\uc5c5\uc790\uac00 \ub2e4\ub978 \ucc38\uc5ec\uc790\uc5d0\uac8c \uc774\ud0c8 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.age,0,"\uacf5\ub3d9\ud589\uc704\uc5d0 \ucc38\uc5ec\ud588\ub358 \uc0ac\uc5c5\uc790\uac00 \uc774\ub97c \uc885\ub8cc\ud558\ub824\uba74 \ub2e8\uc21c\ud55c \ub0b4\uc2ec\uc758 \uc758\uc0ac\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uc774\ud0c8\uc758 \uc758\uc0ac\uac00 \ub2e4\ub978 \ucc38\uc5ec\uc790\uc5d0\uac8c \uc2e4\uc9c8\uc801\uc73c\ub85c \uc804\ub2ec\ub418\uace0 \uc2e4\uc81c \uc774\ud0c8\uc5d0 \ubd80\ud569\ud558\ub294 \ud589\uc704(\uac00\uaca9 \uc778\ud558 \ub4f1)\uac00 \uc778\uc815\ub418\uc5b4\uc57c \uadf8 \uc2dc\uc810 \uc774\ud6c4\uc758 \ucc45\uc784\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ubc95\ub9ac\ub85c \ub17c\uc758\ub41c\ub2e4.",B.agg,B.af3,null)
B.anO=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uc790\uc2e0\uc774 \uc2e4\uc81c\ub85c \uac00\ub2f4\ud55c \uc2dc\uc810 \uc774\ud6c4\uc758 \ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub9cc \ucc45\uc784\uc744 \uc9c4\ub2e4","\ub4a4\ub2a6\uac8c \uac00\ub2f4\ud574\ub3c4 \ucc98\uc74c\ubd80\ud130 \ucc38\uc5ec\ud55c \uac83\uc73c\ub85c \uac04\uc8fc\ub418\uc5b4 \uc774\uc804 \ud589\uc704\uae4c\uc9c0 \ubaa8\ub450 \ucc45\uc784\uc9c4\ub2e4","\ub4a4\ub2a6\uac8c \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\ub294 \uc5b4\ub5a0\ud55c \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uac00\ub2f4 \uc2dc\uc810\uc740 \ucc45\uc784 \ubc94\uc704 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\ub4a4\ub2a6\uac8c \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\ub294 \ud56d\uc0c1 \uac00\uc7a5 \ubb34\uac70\uc6b4 \ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.ahB=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uc790\uc2e0\uc774 \uc2e4\uc81c\ub85c \uac00\ub2f4\ud55c \uc2dc\uc810 \uc774\ud6c4\uc758 \ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub9cc \ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.ahq=s(["\ub4a4\ub2a6\uac8c \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\uc758 \ucc45\uc784\ubc94\uc704"],t.s)
B.bSj=new A.a("gen_collusion_end_3","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\uacf5\ub3d9\ud589\uc704\uc5d0 \ub4a4\ub2a6\uac8c \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\uc758 \ucc45\uc784 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.anO,0,"\uacf5\ub3d9\ud589\uc704\uc5d0 \ub4a4\ub2a6\uac8c \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\uc2e0\uc774 \uc2e4\uc81c\ub85c \uadf8 \uacf5\ub3d9\ud589\uc704\uc5d0 \ucc38\uc5ec\ud558\uac8c \ub41c \uc2dc\uc810 \uc774\ud6c4\uc758 \ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub9cc \ucc45\uc784\uc744 \uc9c0\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, \uac00\ub2f4 \uc774\uc804\uc5d0 \ub2e4\ub978 \uc0ac\uc5c5\uc790\ub4e4\uc774 \ud589\ud55c \ubd80\ubd84\uae4c\uc9c0 \ub2f9\uc5f0\ud788 \ucc45\uc784\uc744 \uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.ahB,B.ahq,null)
B.bbM=s([u.d,"\ubaa8\ub4e0 \ucc38\uc5ec \uc0ac\uc5c5\uc790\uc5d0\uac8c \ud56d\uc0c1 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\uc7ac\uac00 \ubd80\uacfc\ub41c\ub2e4","\uac00\uc7a5 \uc801\uac8c \uad00\uc5ec\ud55c \uc0ac\uc5c5\uc790\uac00 \uac00\uc7a5 \ubb34\uac70\uc6b4 \uc81c\uc7ac\ub97c \ubc1b\ub294\ub2e4","\uc81c\uc7ac\ub294 \ucc38\uc5ec \uc0ac\uc5c5\uc790 \uc218\uc640 \ubb34\uad00\ud558\uac8c 1\uac1c \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc9d1\uc911\ub41c\ub2e4","\uac1c\ubcc4 \uc0ac\uc5c5\uc790\uc758 \uad00\uc5ec \uc815\ub3c4\ub294 \uc81c\uc7ac \uc218\uc704\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4"],t.s)
B.b3v=s([u.d],t.s)
B.a3P=s(["\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784\uc758 \ucc28\ub4f1\ud654"],t.s)
B.brG=new A.a("gen_collusion_end_4","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\uc5ec\ub7ec \uc0ac\uc5c5\uc790\uac00 \ucc38\uc5ec\ud55c \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc5d0\uc11c \uac01 \uc0ac\uc5c5\uc790\uc5d0 \ub300\ud55c \ucc45\uc784 \ubd80\uacfc \ubc29\uc2dd\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.bbM,0,"\uc5ec\ub7ec \uc0ac\uc5c5\uc790\uac00 \ucc38\uc5ec\ud55c \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0\uc11c\ub294 \uac01 \uc0ac\uc5c5\uc790\ubcc4\ub85c \uacf5\ub3d9\ud589\uc704\uc5d0\uc758 \uad00\uc5ec \uc815\ub3c4, \uac00\ub2f4 \uae30\uac04, \uc8fc\ub3c4\uc801 \uc5ed\ud560 \uc5ec\ubd80 \ub4f1\uc744 \uace0\ub824\ud558\uc5ec \uac1c\ubcc4\uc801\uc73c\ub85c \ucc45\uc784\uacfc \uc81c\uc7ac(\uacfc\uc9d5\uae08 \ub4f1) \uc218\uc704\uac00 \ucc28\ub4f1\uc801\uc73c\ub85c \uc815\ud574\uc9c8 \uc218 \uc788\ub2e4.",B.b3v,B.a3P,null)
B.aPR=s([u.y8,"\uacf5\ub3d9\ud589\uc704\uc758 \uc885\uae30\uc640 \ucc98\ubd84\uc2dc\ud6a8\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\ucc98\ubd84\uc2dc\ud6a8\ub294 \uacf5\ub3d9\ud589\uc704\uac00 \uc2dc\uc791\ub41c \uc2dc\uc810\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud558\uace0 \uc885\uae30\uc640\ub294 \ubb34\uad00\ud558\ub2e4","\uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0\ub294 \ucc98\ubd84\uc2dc\ud6a8 \uac1c\ub150\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ucc98\ubd84\uc2dc\ud6a8\ub294 \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0\uc11c \uc5b8\uc81c\ub098 \ubb34\uc81c\ud55c\uc774\ub2e4"],t.s)
B.bef=s([u.y8],t.s)
B.al1=s(["\uacf5\ub3d9\ud589\uc704 \uc885\uae30\uc640 \ucc98\ubd84\uc2dc\ud6a8\uc758 \uad00\uacc4"],t.s)
B.bnP=new A.a("gen_collusion_end_5","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\uacf5\ub3d9\ud589\uc704 \uc885\ub8cc \uc2dc\uc810 \ud310\ub2e8\uc774 \ucc98\ubd84\uc2dc\ud6a8\uc640 \uac16\ub294 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aPR,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0\uc11c \uc885\uae30(\uc2e4\ud589\ud589\uc704\uac00 \ucd5c\uc885\uc801\uc73c\ub85c \uc885\ub8cc\ub41c \uc2dc\uc810)\ub97c \uc5b8\uc81c\ub85c \ubcfc \uac83\uc778\uc9c0\uc5d0 \ub530\ub77c \ucc98\ubd84\uc2dc\ud6a8\uc758 \uae30\uc0b0\uc810\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4, \uc774\ub294 \uc2e4\ubb34\uc0c1 \ub2e4\ud22c\uc5b4\uc9c0\ub294 \uc911\uc694\ud55c \uc7c1\uc810 \uc911 \ud558\ub098\uc774\ub2e4.",B.bef,B.al1,null)
B.aPy=s(["\uc704\uc6d0\ud68c\ub294 \uc704\uc6d0\uc7a5 1\uba85, \ubd80\uc704\uc6d0\uc7a5 1\uba85\uc744 \ud3ec\ud568\ud55c 9\uba85\uc758 \uc704\uc6d0\uc73c\ub85c \uad6c\uc131\ud55c\ub2e4","\uc704\uc6d0\uc7a5\uacfc \ubd80\uc704\uc6d0\uc7a5\uc740 \uc815\ubb34\uc9c1 \uacf5\ubb34\uc6d0\uc73c\ub85c \uc784\uba85\ud55c\ub2e4","\uc704\uc6d0 \uc911 4\uba85\uc740 \uc0c1\uc784\uc704\uc6d0, 4\uba85\uc740 \ube44\uc0c1\uc784\uc704\uc6d0\uc73c\ub85c \ud55c\ub2e4","\uc704\uc6d0\uc740 \ubaa8\ub450 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5\xb7\ub2e4\ub978 \uc704\uc6d0\uc740 \uad6d\ubb34\ucd1d\ub9ac\uc758 \uc81c\uccad\uc73c\ub85c \ub300\ud1b5\ub839\uc774 \uc784\uba85 \ub610\ub294 \uc704\ucd09\ud55c\ub2e4"],t.s)
B.b5S=s(["\uc704\uc6d0\uc740 \ubaa8\ub450 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.ac6=s(["\uc704\uc6d0\ud68c \uad6c\uc131 \uc778\uc6d0"],t.s)
B.bIz=new A.a("gen_ftc_org_comp_1","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uad6c\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aPy,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc704\uc6d0\uc7a5 1\uba85\uacfc \ubd80\uc704\uc6d0\uc7a5 1\uba85\uc744 \ud3ec\ud568\ud55c 9\uba85\uc758 \uc704\uc6d0(\uc0c1\uc784\uc704\uc6d0 4\uba85, \ube44\uc0c1\uc784\uc704\uc6d0 4\uba85)\uc73c\ub85c \uad6c\uc131\ub418\uba70, \uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5\uc740 \uc815\ubb34\uc9c1 \uacf5\ubb34\uc6d0\uc73c\ub85c \uad6d\ubb34\ucd1d\ub9ac\uc758 \uc81c\uccad\uc744 \uac70\uccd0 \ub300\ud1b5\ub839\uc774 \uc784\uba85\ud55c\ub2e4. \uc704\uc6d0\uc740 \uad6d\ud68c\uc758\uc6d0\uc744 \uacb8\uc9c1\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, "\ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.b5S,B.ac6,null)
B.a6R=s(["\uc704\uc6d0\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uba70, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 \uc885\uc2e0\uc73c\ub85c \ud55c\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 1\ub144\uc774\uba70 \uc5f0\uc784\ud560 \uc218 \uc5c6\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 \ub300\ud1b5\ub839\uc758 \uc784\uae30\uc640 \uc5f0\ub3d9\ub418\uc5b4 \uc790\ub3d9\uc73c\ub85c \ubcc0\uacbd\ub41c\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b9a=s(["\uc704\uc6d0\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uba70, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.av6=s(["\uc704\uc6d0\uc758 \uc784\uae30"],t.s)
B.bRo=new A.a("gen_ftc_org_comp_2","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc784\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a6R,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0(\uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5 \ud3ec\ud568)\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uace0, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc704\uc6d0\ud68c\uc758 \ub3c5\ub9bd\uc131\uacfc \uc804\ubb38\uc131\uc744 \ud655\ubcf4\ud558\uba74\uc11c\ub3c4 \uc9c0\ub098\uce5c \uc7a5\uae30 \uc7ac\uc784\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.b9a,B.av6,null)
B.aHA=s(["\uc704\uc6d0\uc740 \uae08\uace0 \uc774\uc0c1\uc758 \ud615\uc744 \uc120\uace0\ubc1b\uc740 \uacbd\uc6b0\uac00 \uc544\ub2c8\uba74 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \uba74\uc9c1\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc704\uc6d0\uc740 \ud0c4\ud575\uacb0\uc815\uc73c\ub85c \ud30c\uba74\ub420 \uc218 \uc788\ub2e4","\uc7a5\uae30\uac04 \uc2ec\uc2e0\uc1e0\uc57d\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \uacbd\uc6b0 \ub4f1 \ubc95\uc5d0\uc11c \uc815\ud55c \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uba74\uc9c1\ub420 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc740 \uc815\uce58\uc801 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5\uc740 \uc704\uc6d0\ud68c\uc758 \ub3c5\ub9bd\uc801\xb7\uc911\ub9bd\uc801 \uc9c1\ubb34\uc218\ud589\uc744 \ub4b7\ubc1b\uce68\ud558\uae30 \uc704\ud55c \uc7a5\uce58\uc774\ub2e4"],t.s)
B.RY=s(["\uc704\uc6d0\uc740 \uc815\uce58\uc801 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4"],t.s)
B.b3O=s(["\uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5"],t.s)
B.bNi=new A.a("gen_ftc_org_comp_3","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aHA,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc740 \ud0c4\ud575\uacb0\uc815\uc73c\ub85c \ud30c\uba74\ub418\uac70\ub098 \uae08\uace0 \uc774\uc0c1\uc758 \ud615\uc744 \uc120\uace0\ubc1b\uac70\ub098 \uc7a5\uae30\uac04 \uc2ec\uc2e0\uc1e0\uc57d\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud560 \uc218 \uc5c6\uac8c \ub418\ub294 \ub4f1 \ubc95\uc5d0\uc11c \uc815\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \uc544\ub2c8\uba74 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \uba74\uc9c1\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7ec\ud55c \uc2e0\ubd84\ubcf4\uc7a5\uc740 \uc704\uc6d0\ud68c\uac00 \uc815\uce58\uc801 \uc555\ub825\uc5d0\uc11c \ubc97\uc5b4\ub098 \ub3c5\ub9bd\uc801\xb7\uc911\ub9bd\uc801\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud558\ub3c4\ub85d \ud558\uae30 \uc704\ud55c \uac83\uc73c\ub85c, "\uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.RY,B.b3O,null)
B.bgD=s(["\ubc95\ub960\xb7\uacbd\uc81c\xb7\uacbd\uc601 \ub4f1\uc758 \ubd84\uc57c\uc5d0\uc11c \ud559\uc2dd\uacfc \uacbd\ud5d8\uc774 \ud48d\ubd80\ud55c \uc0ac\ub78c","\uacf5\uc815\uac70\ub798 \uad00\ub828 \uc0ac\uac74\uc744 \ub2e4\ub8e8\uc5b4 \ubcf8 \ud310\uc0ac\xb7\uac80\uc0ac \ub610\ub294 \ubcc0\ud638\uc0ac \uacbd\ub825\uc774 \uc788\ub294 \uc0ac\ub78c","\uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \uc0ac\ubb34\uc5d0 \uc885\uc0ac\ud55c 3\uae09 \uc774\uc0c1 \uacf5\ubb34\uc6d0 \uacbd\ub825\uc774 \uc788\ub294 \uc0ac\ub78c","\ubc18\ub4dc\uc2dc \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc790\uaca9","\uacbd\uc81c \uad00\ub828 \uc5f0\uad6c\uae30\uad00\uc5d0\uc11c \ubd80\uad50\uc218\uae09 \uc774\uc0c1\uc758 \uc9c1\uc5d0 \uc788\uc5c8\ub358 \uc0ac\ub78c"],t.s)
B.b0h=s(["\ubc18\ub4dc\uc2dc \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc790\uaca9"],t.s)
B.ajq=s(["\uc704\uc6d0\uc758 \uc790\uaca9\uc694\uac74"],t.s)
B.bJc=new A.a("gen_ftc_org_comp_4","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc790\uaca9\uc694\uac74\uc73c\ub85c \ubc95\uc5d0\uc11c \uc694\uad6c\ud558\ub294 \uac83\uacfc \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.bgD,3,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc740 \ubc95\ub960\xb7\uacbd\uc81c\xb7\uacbd\uc601 \ub4f1\uc758 \ubd84\uc57c\uc758 \ud559\uc2dd\uacfc \uacbd\ud5d8, \ud310\uc0ac\xb7\uac80\uc0ac\xb7\ubcc0\ud638\uc0ac \uacbd\ub825, \uace0\uc704 \uacf5\ubb34\uc6d0 \uacbd\ub825, \uc5f0\uad6c\uae30\uad00 \uacbd\ub825 \ub4f1 \uc804\ubb38\uc131\uc744 \uae30\uc900\uc73c\ub85c \uc784\uba85\xb7\uc704\ucd09\ub41c\ub2e4. \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0 \uc5ec\ubd80\ub294 \uc704\uc6d0 \uc790\uaca9\uc694\uac74\uc73c\ub85c \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc73c\uba70, \uc624\ud788\ub824 \uc704\uc6d0\ud68c\uc758 \uc815\uce58\uc801 \uc911\ub9bd\uc131\uc774 \uac15\uc870\ub41c\ub2e4.",B.b0h,B.ajq,null)
B.a7z=s([u.yp,"\uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uad8c\ud55c\uacfc \uc758\uacb0\uad8c\uc5d0 \uc788\uc5b4 \uc804\ud600 \ucc28\uc774\uac00 \uc5c6\uc5b4 \uad6c\ubcc4\uc758 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\ube44\uc0c1\uc784\uc704\uc6d0\ub9cc \uc758\uacb0\uad8c\uc744 \uac00\uc9c0\uace0 \uc0c1\uc784\uc704\uc6d0\uc740 \uc758\uacb0\uad8c\uc774 \uc5c6\ub2e4","\uc0c1\uc784\uc704\uc6d0\uc740 \ubbfc\uac04\uc778\ub9cc, \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uacf5\ubb34\uc6d0\ub9cc \uc784\uba85\ub420 \uc218 \uc788\ub2e4","\uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc758 \uad6c\ubd84\uc740 \ubc95\ub960\uc0c1 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.axU=s([u.yp],t.s)
B.aPc=s(["\uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc758 \uad6c\ubcc4"],t.s)
B.bLO=new A.a("gen_ftc_org_comp_5","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a7z,0,"\uc0c1\uc784\uc704\uc6d0\uc740 \uc704\uc6d0\ud68c\uc5d0 \uc0c1\uc2dc \uadfc\ubb34\ud558\uba70 \uc5c5\ubb34\uc5d0 \uc804\ub150\ud558\ub294 \ubc18\uba74, \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uc0c1\uc2dc \uadfc\ubb34 \uc758\ubb34 \uc5c6\uc774 \ud68c\uc758 \ub4f1 \ud544\uc694\ud55c \uacbd\uc6b0\uc5d0 \uc9c1\ubb34\ub97c \uc218\ud589\ud55c\ub2e4. \ub2e4\ub9cc \uc758\uacb0\uc5d0 \ucc38\uc5ec\ud560 \ub54c\ub294 \uc0c1\uc784\uc704\uc6d0\xb7\ube44\uc0c1\uc784\uc704\uc6d0 \ubaa8\ub450 \ub3d9\ub4f1\ud55c \uc758\uacb0\uad8c\uc744 \uac00\uc9c4\ub2e4.",B.axU,B.aPc,null)
B.aMe=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uad6d\ubb34\ucd1d\ub9ac \uc18c\uc18d\uc758 \uc911\uc559\ud589\uc815\uae30\uad00\uc73c\ub85c\uc11c \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc0ac\ubc95\ubd80\uc5d0 \uc18c\uc18d\ub41c \ubc95\uc6d0\uc758 \uc77c\uc885\uc774\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc21c\uc218 \ubbfc\uac04\ub2e8\uccb4\ub85c\uc11c \uc544\ubb34\ub7f0 \ud589\uc815\uad8c\ud55c\uc774 \uc5c6\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c0\ubc29\uc790\uce58\ub2e8\uccb4 \uc0b0\ud558 \uae30\uad00\uc774\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uad6d\ud68c\uc5d0 \uc18c\uc18d\ub41c \ubcf4\uc870\uae30\uad00\uc774\ub2e4"],t.s)
B.aT7=s(["\uad6d\ubb34\ucd1d\ub9ac \uc18c\uc18d\uc758 \uc911\uc559\ud589\uc815\uae30\uad00\uc73c\ub85c\uc11c \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4"],t.s)
