B.bNL=new A.a("gen_ftc_org_meet_2","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\ud68c\uc758\uc758 \uc885\ub958\xb7\uc758\uacb0\uc815\uc871\uc218","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc804\uc6d0\ud68c\uc758\uc758 \uc758\uacb0\uc815\uc871\uc218\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aW9,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc804\uc6d0\ud68c\uc758\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc7ac\uc801\uc704\uc6d0 \uacfc\ubc18\uc218\uc758 \ucd9c\uc11d\uc73c\ub85c \uac1c\uc758\ud558\uace0, \ucd9c\uc11d\uc704\uc6d0 \uacfc\ubc18\uc218\uc758 \ucc2c\uc131\uc73c\ub85c \uc758\uacb0\ud55c\ub2e4. \uc774\ub294 \uc77c\ubc18\uc801\uc778 \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc758\uacb0\uc815\uc871\uc218 \uc6d0\uce59\uacfc \uc720\uc0ac\ud55c \uad6c\uc870\uc774\ub2e4.",B.a2E,B.bhx,null)
B.b_G=s(["\uc0c1\uc784\uc704\uc6d0 1\uba85\uc744 \ud3ec\ud568\ud55c 3\uba85\uc758 \uc704\uc6d0\uc73c\ub85c \uad6c\uc131\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc18c\ud68c\uc758\ub294 \ube44\uc0c1\uc784\uc704\uc6d0 9\uba85 \uc804\uc6d0\uc73c\ub85c \uad6c\uc131\ub41c\ub2e4","\uc18c\ud68c\uc758\ub294 \uc704\uc6d0\uc7a5 1\uc778\ub9cc\uc73c\ub85c \uad6c\uc131\ub41c\ub2e4","\uc18c\ud68c\uc758\ub294 \uc0ac\ubb34\ucc98 \uc9c1\uc6d0\ub9cc\uc73c\ub85c \uad6c\uc131\ub41c\ub2e4","\uc18c\ud68c\uc758\uc758 \uad6c\uc131\uc6d0 \uc218\ub294 \ubc95\ub960\uc0c1 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
