B.bP0=new A.a("gen_ftc_org_meet_4","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\ud68c\uc758\uc758 \uc885\ub958\xb7\uc758\uacb0\uc815\uc871\uc218","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ud68c\uc758\uc758 \uacf5\uac1c \uc6d0\uce59\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ais,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud68c\uc758\ub294 \uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\ube44\ubc00 \ub4f1 \ubcf4\ud638 \ud544\uc694\uc131\uc744 \uace0\ub824\ud558\uc5ec \uc6d0\uce59\uc801\uc73c\ub85c \uacf5\uac1c\ud558\uc9c0 \uc544\ub2c8\ud558\ub418, \ud544\uc694\ud558\ub2e4\uace0 \uc778\uc815\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uacf5\uac1c\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\uace0 \uc788\ub2e4.",B.a3e,B.a0G,null)
B.aQJ=s([u.ni,"\ubaa8\ub4e0 \uc0ac\uac74\uc740 \uc608\uc678 \uc5c6\uc774 \uc804\uc6d0\ud68c\uc758\uc5d0\uc11c\ub9cc \ucc98\ub9ac\ub41c\ub2e4","\ubaa8\ub4e0 \uc0ac\uac74\uc740 \uc608\uc678 \uc5c6\uc774 \uc18c\ud68c\uc758\uc5d0\uc11c\ub9cc \ucc98\ub9ac\ub41c\ub2e4","\uc804\uc6d0\ud68c\uc758\uc640 \uc18c\ud68c\uc758\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc0ac\uac74\ub9cc \ucc98\ub9ac\ud55c\ub2e4","\uc0ac\uac74 \ubc30\ubd84\uc740 \ub2f9\uc0ac\uc790\uc758 \uc694\uccad\uc5d0 \ub530\ub77c\uc11c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
