B.bGM=new A.a("gen_conc_6","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uacfc \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a8n,0,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc774 \uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0, \uc21c\ud658\ucd9c\uc790 \uc81c\ud55c, \ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c, \uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c \ub4f1\uc744 \ud1b5\ud574 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uc9c0\ubc30\uad6c\uc870 \uc790\uccb4\ub97c \uad6c\uc870\uc801\uc73c\ub85c \uaddc\uc81c\ud558\ub294 \uac83\uc774\ub77c\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \uadf8\ub7ec\ud55c \uad6c\uc870 \ud558\uc5d0\uc11c \ucd1d\uc218 \uc77c\uac00 \ub4f1 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc774 \uac1c\ubcc4\uc801\uc73c\ub85c \uadc0\uc18d\ub418\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c, \ub450 \uc81c\ub3c4\ub294 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uacbd\uc81c\ub825\uc9d1\uc911\uc774\ub77c\ub294 \uacf5\ud1b5\ub41c \ubb38\uc81c\ub97c \uc11c\ub85c \ub2e4\ub978 \uce35\uc704\uc5d0\uc11c \ub2e4\ub8e8\ub294 \ubcf4\uc644\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.aMv,B.a2a,null)
B.b7e=s(["\ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \ub9cc\ub4e4\uc5b4 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\uc600\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud574 \uc138\ud615 \ub3d9\uac80\uc744 \uc81c\uc791\ud558\uc600\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\ub85c \uc774\uc0ad\uc744 \uc798\ub77c \ubcbc\ub18d\uc0ac\ub97c \uc9c0\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc744 \ub9cc\ub4e4\uc5b4 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \ub098\ud0c0\ub0b4\uc5c8\ub2e4"],t.s)
