B.bBs=new A.a("gen_kh_prehist_9","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300 \uace0\uc778\ub3cc\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b8f,0,"\uace0\uc778\ub3cc\uc740 \uac70\ub300\ud55c \ub36e\uac1c\ub3cc\uc744 \uc62e\uae30\uace0 \uc138\uc6b0\ub294 \ub370 \ub9ce\uc740 \ub178\ub3d9\ub825\uc774 \ud544\uc694\ud588\uae30 \ub54c\ubb38\uc5d0, \uc774\ub97c \uc8fc\ub3c4\ud560 \uc218 \uc788\uc5c8\ub358 \uc9c0\ubc30\uce35\uc758 \uad8c\ub825\uacfc \uccad\ub3d9\uae30\uc2dc\ub300 \uacc4\uae09 \uc0ac\ud68c\uc758 \uc131\ub9bd\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ub300\ud45c\uc801 \uc720\uc801\uc774\ub2e4.",B.aTD,B.b9I,null)
B.bag=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4","\ubf08\ubc14\ub298\uacfc \uac00\ub77d\ubc14\ud034\ub97c \uc774\uc6a9\ud574 \ucc98\uc74c\uc73c\ub85c \uc637\uac10\uc744 \uc9dc\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uae4a\uc774\uac08\uc774\uac00 \uac00\ub2a5\ud574\uc838 \uc0dd\uc0b0\ub825\uc774 \uae09\uc99d\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \uc18c\ub97c \uc774\uc6a9\ud55c \ub18d\uc0ac\uac00 \uc77c\ubc18\ud654\ub418\uc5c8\ub2e4","\uc911\uad6d \ud654\ud3d0\ub97c \ub9e4\uac1c\ub85c \ud55c \uad50\uc5ed\uc774 \uacbd\uc81c\uc758 \uc911\uc2ec\uc744 \uc774\ub8e8\uc5c8\ub2e4"],t.s)
B.aU9=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4"],t.s)
B.b3C=s(["\uccad\ub3d9\uae30\uc2dc\ub300 \ub18d\uacbd\uc758 \ubc1c\ub2ec"],t.s)
B.bJB=new A.a("gen_kh_prehist_10","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc758 \uacbd\uc81c \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bag,0,"\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\ub294 \ubc18\ub2ec \ub3cc\uce7c\uacfc \uac19\uc740 \ub18d\uae30\uad6c\ub97c \uc774\uc6a9\ud574 \ubcbc\ub18d\uc0ac\uac00 \ud655\uc0b0\ub418\uba70 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ub298\uc5b4\ub0ac\ub2e4. \ubf08\ubc14\ub298\xb7\uac00\ub77d\ubc14\ud034\ub294 \uc2e0\uc11d\uae30, \ucca0\uc81c \ub18d\uae30\uad6c\xb7\uc6b0\uacbd \ubcf4\uae09\uc740 \ucca0\uae30\uc2dc\ub300 \uc774\ud6c4, \uc911\uad6d \ud654\ud3d0 \uad50\uc5ed\uc740 \ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aU9,B.b3C,null)
B.aFC=s([u.c8,"\ub5c0\uc11d\uae30 \uc911\uc2ec\uc758 \ub3c4\uad6c \uccb4\uacc4\uac00 \uac04\uc11d\uae30 \uc911\uc2ec\uc73c\ub85c \uc804\ud658\ub418\uc5c8\ub2e4","\ubb34\ub9ac\ub97c \uc774\ub8ec \uc774\ub3d9 \uc0dd\ud65c\uc5d0\uc11c \uc815\ucc29 \uc0dd\ud65c\ub85c \ucc98\uc74c \uc804\ud658\ub418\uc5c8\ub2e4","\uad70\uc7a5 \uad6d\uac00\uac00 \ucc98\uc74c\uc73c\ub85c \ub4f1\uc7a5\ud558\uc5ec \uacc4\uae09 \uc0ac\ud68c\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4","\ud1a0\ud14c\ubbf8\uc998\xb7\uc560\ub2c8\ubbf8\uc998 \ub4f1 \uc6d0\uc2dc \uc2e0\uc559\uc774 \ucc98\uc74c\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4"],t.s)
