B.b2A=s(["8\uc870\ubc95\uc758 \ub0b4\uc6a9\uacfc \uc758\ubbf8"],t.s)
B.bPk=new A.a("gen_kh_prehist_13","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uace0\uc870\uc120","\uace0\uc870\uc120\uc758 \uc0ac\ud68c \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc8fc\ub294 8\uc870\ubc95\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7N,0,"\uace0\uc870\uc120\uc758 8\uc870\ubc95 \uc911 \uc804\ud558\ub294 3\uac1c \uc870\ud56d\uc5d0\ub294 \uc0ac\ub78c\uc744 \uc8fd\uc778 \uc790\ub294 \uc989\uc2dc \uc0ac\ud615\uc5d0 \ucc98\ud558\uace0, \ub0a8\uc5d0\uac8c \uc0c1\ud574\ub97c \uc785\ud78c \uc790\ub294 \uace1\uc2dd\uc73c\ub85c \ubc30\uc0c1\ud558\uba70, \ub3c4\ub451\uc9c8\ud55c \uc790\ub294 \ub178\ube44\ub85c \uc0bc\ub294\ub2e4\ub294 \ub0b4\uc6a9\uc774 \uc788\uc5b4 \uc0dd\uba85\xb7\uc0ac\uc720 \uc7ac\uc0b0 \ubcf4\ud638\uc640 \ub178\ube44(\uacc4\uae09)\uc758 \uc874\uc7ac\ub97c \uc54c \uc218 \uc788\ub2e4.",B.b60,B.b2A,null)
B.aRM=s(["\uc704\ub9cc\uc774 \ubb34\ub9ac\ub97c \uc774\ub04c\uace0 \uace0\uc870\uc120\uc5d0 \ub9dd\uba85\ud558\uc5ec \uc900\uc655\uc758 \uc2e0\uc784\uc744 \uc5bb\uc5c8\ub2e4","\ub2e8\uad70\uc655\uac80\uc774 \uc544\uc0ac\ub2ec\uc5d0 \ub3c4\uc74d\ud558\uc5ec \uace0\uc870\uc120\uc744 \uac74\uad6d\ud558\uc600\ub2e4","\uc6b0\uac70\uc655\uc774 \uc9c4\ubc88\uacfc \uc784\ub454\uc744 \ubcf5\uc18d\uc2dc\ucf1c \uc138\ub825\uc744 \ud655\uc7a5\ud558\uc600\ub2e4","\ud55c \ubb34\uc81c\uac00 \uace0\uc870\uc120\uc744 \uce68\uacf5\ud558\uc5ec \uc655\uac80\uc131\uc744 \ud568\ub77d\uc2dc\ucf30\ub2e4","\uc744\ud30c\uc18c\uac00 \ub4f1\uc6a9\ub418\uc5b4 \uc9c4\ub300\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4"],t.s)
