B.bJl=new A.a("gen_kh_goryeo_13","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)",'\ub2e4\uc74c \ub2f4\ud310 \uc774\ud6c4\uc758 \uc0ac\uc2e4\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uc11c\ud76c\ub294 \uac70\ub780 \uc7a5\uc218 \uc18c\uc190\ub155\uacfc \ub2f4\ud310\ud558\uc5ec, \uace0\ub824\uac00 \uc1a1\uacfc\uc758 \uad00\uacc4\ub97c \ub04a\uace0 \uac70\ub780\uacfc \uad50\ub958\ud560 \uac83\uc744 \uc57d\uc18d\ud558\ub294 \ub300\uc2e0 \uac15\ub3d9 \uc9c0\uc5ed\uc758 \uc601\uc720\uad8c\uc744 \uc778\uc815\ubc1b\uc558\ub2e4."',B.ame,0,"\uc11c\ud76c\uc758 \uc678\uad50 \ub2f4\ud310(\uc131\uc885 \ub300, \uac70\ub780\uc758 1\ucc28 \uce68\uc785) \uacb0\uacfc \uace0\ub824\ub294 \uac15\ub3d9 6\uc8fc\ub97c \ud655\ubcf4\ud558\uc5ec \uc555\ub85d\uac15\uae4c\uc9c0 \uc601\ud1a0\ub97c \ub113\ud790 \uc218 \uc788\uc5c8\ub2e4. \uac15\ud654\ub3c4 \ucc9c\ub3c4\xb7\uc0bc\ubcc4\ucd08 \ud56d\uc7c1\uc740 \ubabd\uace8 \uce68\uc785, \ub3d9\ubd81 9\uc131 \ucd95\uc870\ub294 \uc5ec\uc9c4 \uc815\ubc8c, \ubcc4\ubb34\ubc18 \ucc3d\uc124\uc740 \uc5ec\uc9c4 \uc815\ubc8c \uc900\ube44\uc640 \uad00\ub828\ub41c \uc0ac\uac74\uc774\ub2e4.",B.acx,B.biT,null)
B.ayW=s([u.lr,"\ubcc4\ubb34\ubc18\uc744 \ub3d9\uc6d0\ud558\uc5ec \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud55c \uc804\ud22c\uc600\ub2e4","\ubabd\uace8\uc758 \uce68\uc785\uc5d0 \ub9de\uc11c \ucc98\uc778\uc131\uc5d0\uc11c \uae40\uc724\ud6c4\uac00 \ud65c\uc57d\ud55c \uc804\ud22c\uc600\ub2e4","\uc65c\uad6c\uc758 \uce68\uc785\uc744 \ubb3c\ub9ac\uce5c \ucd5c\uc601\uc758 \ud64d\uc0b0 \ub300\ucca9\uc774\uc5c8\ub2e4","\uc774\uc131\uacc4\uac00 \uc704\ud654\ub3c4\uc5d0\uc11c \ud68c\uad70\uc744 \uacb0\uc815\ud55c \uc0ac\uac74\uc774\uc5c8\ub2e4"],t.s)
