B.b3F=s(["\uc870\uc120\uc758 \uac74\uad6d \uacfc\uc815"],t.s)
B.bLk=new A.a("gen_kh_js1_4","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc870\uc120\uc758 \uac74\uad6d\uacfc \ud55c\uc591 \ucc9c\ub3c4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aCt,0,"\uc774\uc131\uacc4\ub294 \uc704\ud654\ub3c4 \ud68c\uad70(1388)\uc73c\ub85c \uc815\uad8c\uc744 \uc7a5\uc545\ud55c \ub4a4 \uc815\ub3c4\uc804 \ub4f1 \uc2e0\uc9c4 \uc0ac\ub300\ubd80\uc640 \ud568\uaed8 \uc870\uc120\uc744 \uac74\uad6d(1392)\ud558\uace0, \ud55c\uc591\uc73c\ub85c \ub3c4\uc74d\uc744 \uc62e\uaca8 \uacbd\ubcf5\uad81 \ub4f1\uc744 \uc138\uc6b0\uace0 \ud1b5\uce58 \uae30\ubc18\uc744 \ub9c8\ub828\ud558\uc600\ub2e4. \ub098\uba38\uc9c0 \uc120\ud0dd\uc9c0\ub294 \uace0\ub824 \uac74\uad6d \uc804\ud6c4 \ud6c4\uc0bc\uad6d \uc2dc\uae30 \ub610\ub294 \uace0\ub824 \ud6c4\uae30\uc758 \uc0ac\uc2e4\uc774\ub2e4.",B.Uz,B.b3F,null)
B.US=s(["\uce21\uc6b0\uae30, \uc559\ubd80\uc77c\uad6c, \uc790\uaca9\ub8e8 \ub4f1\uc744 \uc81c\uc791\ud558\uc5ec \ub18d\uc5c5\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \ud65c\uc6a9\ud558\uc600\ub2e4","\u300c\uc9c1\uc9c0\uc2ec\uccb4\uc694\uc808\u300d\uc744 \uae08\uc18d \ud65c\uc790\ub85c \uc778\uc1c4\ud558\uc600\ub2e4","\uac70\uc911\uae30\ub97c \uc774\uc6a9\ud558\uc5ec \uc218\uc6d0 \ud654\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4","\u300c\ub3d9\uc758\ubcf4\uac10\u300d\uc744 \ud3b8\ucc2c\ud558\uc5ec \uc758\ud559 \ubc1c\uc804\uc5d0 \uae30\uc5ec\ud558\uc600\ub2e4","\u300c\uace4\uc5ec\ub9cc\uad6d\uc804\ub3c4\u300d\ub97c \ub4e4\uc5ec\uc640 \uc138\uacc4 \uc9c0\ub9ac \uc778\uc2dd\uc744 \ub113\ud614\ub2e4"],t.s)
B.aO1=s(["\uce21\uc6b0\uae30, \uc559\ubd80\uc77c\uad6c, \uc790\uaca9\ub8e8 \ub4f1\uc744 \uc81c\uc791\ud558\uc5ec \ub18d\uc5c5\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \ud65c\uc6a9\ud558\uc600\ub2e4"],t.s)
B.aRc=s(["\uc138\uc885 \ub300 \uacfc\ud559 \uae30\uc220"],t.s)
B.bHA=new A.a("gen_kh_js1_5","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc138\uc885 \ub300\uc758 \uacfc\ud559 \uae30\uc220 \ubc1c\ub2ec\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.US,0,"\uc138\uc885 \ub300\uc5d0\ub294 \uac15\uc6b0\ub7c9\uc744 \uce21\uc815\ud558\ub294 \uce21\uc6b0\uae30, \ud574\uc2dc\uacc4\uc778 \uc559\ubd80\uc77c\uad6c, \ubb3c\uc2dc\uacc4\uc778 \uc790\uaca9\ub8e8 \ub4f1\uc774 \uc81c\uc791\ub418\uc5b4 \ub18d\uc5c5 \uc0dd\uc0b0\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \uc2e4\uc9c8\uc801\uc73c\ub85c \ud65c\uc6a9\ub418\uc5c8\ub2e4. \u300c\uc9c1\uc9c0\uc2ec\uccb4\uc694\uc808\u300d\uc740 \uace0\ub824, \uac70\uc911\uae30\uc640 \uc218\uc6d0 \ud654\uc131\uc740 \uc815\uc870, \u300c\ub3d9\uc758\ubcf4\uac10\u300d\uc740 \uad11\ud574\uad70 \ub300, \u300c\uace4\uc5ec\ub9cc\uad6d\uc804\ub3c4\u300d \uc804\ub798\ub294 \uc870\uc120 \ud6c4\uae30\uc758 \uc77c\uc774\ub2e4.",B.aO1,B.aRc,null)
B.aLV=s([u.hJ,"\uc124\ucd1d\uc774 \ud55c\uc790\uc758 \uc74c\uacfc \ub73b\uc744 \ube4c\ub824 \uc774\ub450\ub97c \uc815\ub9ac\ud558\uc600\ub2e4","\uc8fc\uc2dc\uacbd\uc774 \uad6d\ubb38 \uc5f0\uad6c\uc18c\ub97c \uc138\uc6cc \ud55c\uae00\uc744 \uccb4\uacc4\uc801\uc73c\ub85c \uc815\ub9ac\ud558\uc600\ub2e4","\uace0\ub824 \uad11\uc885\uc774 \uacfc\uac70\uc81c \uc2e4\uc2dc\uc640 \ud568\uaed8 \uc0c8\ub85c\uc6b4 \ubb38\uc790\ub97c \ubc18\ud3ec\ud558\uc600\ub2e4","\uac11\uc624\uac1c\ud601 \ub54c \uacf5\ubb38\uc11c\uc5d0 \ucc98\uc74c\uc73c\ub85c \ud55c\uae00\uc744 \uc0ac\uc6a9\ud558\ub3c4\ub85d \ud558\uc600\ub2e4"],t.s)
B.bir=s([u.hJ],t.s)
B.aOS=s(["\ud6c8\ubbfc\uc815\uc74c \ucc3d\uc81c\uc758 \uc758\uc758"],t.s)
B.by0=new A.a("gen_kh_js1_6","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\ud6c8\ubbfc\uc815\uc74c \ucc3d\uc81c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aLV,0,"\uc138\uc885\uc740 \ubc31\uc131\ub4e4\uc774 \uc790\uc2e0\uc758 \ub73b\uc744 \uc27d\uac8c \ud45c\ud604\ud560 \uc218 \uc788\ub3c4\ub85d \ub3c5\ucc3d\uc801\uc774\uace0 \uacfc\ud559\uc801\uc778 \ubb38\uc790\uc778 \ud6c8\ubbfc\uc815\uc74c\uc744 \ucc3d\uc81c(1443)\xb7\ubc18\ud3ec(1446)\ud558\uc600\ub2e4. \uc774\ub450 \uc815\ub9ac\ub294 \ud1b5\uc77c\uc2e0\ub77c \uc124\ucd1d, \uad6d\ubb38 \uc5f0\uad6c\uc18c \uc124\ub9bd\uc740 \ub300\ud55c\uc81c\uad6d \uc2dc\uae30 \uc8fc\uc2dc\uacbd, \uacf5\ubb38\uc11c \uad6d\ud55c\ubb38 \ud63c\uc6a9\uc740 \uac11\uc624\uac1c\ud601 \ub54c\uc758 \uc77c\uc774\ub2e4.",B.bir,B.aOS,null)
B.apj=s([u.nb,"\uc9d1\ud604\uc804\uc744 \uc124\uce58\ud558\uace0 \ud6c8\ubbfc\uc815\uc74c\uc744 \ucc3d\uc81c\ud558\uc600\ub2e4","\u300c\uacbd\uad6d\ub300\uc804\u300d\uc744 \uc644\uc131\ud558\uc5ec \ubc18\ud3ec\ud558\uc600\ub2e4","\ud0d5\ud3c9\ube44\ub97c \uc138\uc6cc \ubd95\ub2f9\uc758 \ud3d0\ud574\ub97c \uacbd\uacc4\ud558\uc600\ub2e4","\uade0\uc5ed\ubc95\uc744 \uc2e4\uc2dc\ud558\uc5ec \uad70\ud3ec \ubd80\ub2f4\uc744 \uc904\uc5ec \uc8fc\uc5c8\ub2e4"],t.s)
B.ZW=s([u.nb],t.s)
B.bgH=s(["\uc138\uc870\uc758 \uc655\uad8c \uac15\ud654 \uc815\ucc45"],t.s)
B.bS5=new A.a("gen_kh_js1_7","korean_history","\uc870\uc120\uc804\uae30","\ud1b5\uce58\uccb4\uc81c \uc815\ube44(\uc138\uc870~\uc131\uc885)","\uc138\uc870\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apj,0,"\uacc4\uc720\uc815\ub09c\uc73c\ub85c \uc989\uc704\ud55c \uc138\uc870\ub294 \uc655\uad8c \uac15\ud654\ub97c \uc704\ud574 6\uc870 \uc9c1\uacc4\uc81c\ub97c \ubd80\ud65c\uc2dc\ud0a4\uace0, \uacfc\uc804\uc774 \ubd80\uc871\ud574\uc9c0\uc790 \ud604\uc9c1 \uad00\ub9ac\uc5d0\uac8c\ub9cc \ud1a0\uc9c0(\uc218\uc870\uad8c)\ub97c \uc9c0\uae09\ud558\ub294 \uc9c1\uc804\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4. \uc9d1\ud604\uc804\xb7\ud6c8\ubbfc\uc815\uc74c\uc740 \uc138\uc885, \u300c\uacbd\uad6d\ub300\uc804\u300d \uc644\uc131\uc740 \uc131\uc885, \ud0d5\ud3c9\ube44\ub294 \uc601\uc870, \uade0\uc5ed\ubc95\uc740 \uc601\uc870 \ub300\uc758 \uc77c\uc774\ub2e4.",B.ZW,B.bgH,null)
B.bdW=s(["\uc774\xb7\ud638\xb7\uc608\xb7\ubcd1\xb7\ud615\xb7\uacf5\uc804\uc758 6\uc804 \uccb4\uc81c\ub85c \uad6c\uc131\ub41c \uc870\uc120\uc758 \uae30\ubcf8 \ubc95\uc804\uc774\ub2e4","\uace0\ub824 \uc2dc\ub300\uc5d0 \ud3b8\ucc2c\ub418\uc5b4 \uc870\uc120\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \ubc95\uc804\uc774\ub2e4","\uc601\uc870 \ub300\uc5d0 \ucc98\uc74c \ud3b8\ucc2c\ub418\uc5b4 \ubd95\ub2f9 \uc815\uce58\uc758 \uaddc\ubc94\uc774 \ub418\uc5c8\ub2e4","\uac11\uc624\uac1c\ud601 \ub54c \uadfc\ub300\uc801 \uc131\ubb38 \ud5cc\ubc95\uc73c\ub85c \uc81c\uc815\ub418\uc5c8\ub2e4","\uc815\ub3c4\uc804\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc800\uc220\ud55c \uc0ac\ucc2c \ubc95\uc804\uc774\ub2e4"],t.s)
