B.bGL=new A.a("gen_kh_js2_17","korean_history","\uc870\uc120\ud6c4\uae30","\uc0ac\ud68c \ubcc0\ub3d9\uacfc \ub18d\ubbfc \ubd09\uae30","\uc784\uc220 \ub18d\ubbfc \ubd09\uae30\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.az3,0,"\uc784\uc220 \ub18d\ubbfc \ubd09\uae30(1862)\ub294 \uacbd\uc0c1 \uc6b0\ubcd1\uc0ac \ubc31\ub099\uc2e0\uc758 \uc218\ud0c8\uc5d0 \ubc18\ubc1c\ud558\uc5ec \uc9c4\uc8fc\uc5d0\uc11c \uc720\uacc4\ucd98\uc758 \uc8fc\ub3c4\ub85c \uc2dc\uc791\ub41c \ubd09\uae30\uac00 \uc0bc\uc815\uc758 \ubb38\ub780\uc5d0 \ub300\ud55c \ud56d\uc758\ub97c \ubc30\uacbd\uc73c\ub85c \uc804\uad6d \uac01\uc9c0\ub85c \ud655\uc0b0\ub41c \uc0ac\uac74\uc774\ub2e4. \uc815\ubd80\ub294 \uc0bc\uc815\uc774\uc815\uccad\uc744 \uc124\uce58\ud574 \ub300\uc751\ud558\uc600\uc73c\ub098 \uadfc\ubcf8\uc801 \ud574\uacb0\uc5d0\ub294 \uc774\ub974\uc9c0 \ubabb\ud558\uc600\ub2e4.",B.auB,B.mr,null)
B.aZ8=s([u.u8,"\uc544\ub4e4\uacfc \ub538\uc774 \uc7ac\uc0b0\uc744 \uade0\ub4f1\ud558\uac8c \uc0c1\uc18d\ubc1b\ub294 \uad00\ud589\uc774 \uc0c8\ub86d\uac8c \uc815\ucc29\ub418\uc5c8\ub2e4","\uc0ac\uc704\uc640 \uc678\uc190\ub3c4 \ub3cc\uc544\uac00\uba70 \uc81c\uc0ac\ub97c \uc9c0\ub0b4\ub294 \uc724\ud68c \ubd09\uc0ac\uac00 \ubcf4\ud3b8\ud654\ub418\uc5c8\ub2e4","\uc5ec\uc131\uc758 \uc7ac\uac00\uac00 \uc790\uc720\ub86d\uac8c \ud5c8\uc6a9\ub418\uace0 \uc0ac\ud68c\uc801 \uc81c\uc57d\uc774 \uc0ac\ub77c\uc84c\ub2e4","\uc871\ubcf4\uc5d0 \uc544\ub4e4\uacfc \ub538\uc744 \ud0dc\uc5b4\ub09c \uc21c\uc11c\ub300\ub85c \uae30\uc7ac\ud558\ub294 \uad00\ud589\uc774 \uac15\ud654\ub418\uc5c8\ub2e4"],t.s)
