B.bPx=new A.a("gen_kh_js2_18","korean_history","\uc870\uc120\ud6c4\uae30","\uc0ac\ud68c \ubcc0\ub3d9\uacfc \ub18d\ubbfc \ubd09\uae30","\uc870\uc120 \ud6c4\uae30 \uac00\uc871\xb7\uc0c1\uc18d \uc81c\ub3c4\uc758 \ubcc0\ud654\ub85c \uc633\uc740 \uac83\uc740?",B.aZ8,0,"\uc870\uc120 \ud6c4\uae30\uc5d0\ub294 \uc131\ub9ac\ud559\uc801 \uac00\ubd80\uc7a5\uc81c\uac00 \uac15\ud654\ub418\uba74\uc11c \uc544\ub4e4(\ud2b9\ud788 \uc7a5\uc790) \uc911\uc2ec\uc758 \uc0c1\uc18d\uacfc \uc81c\uc0ac \uad00\ud589\uc774 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc774\ub294 \uace0\ub824~\uc870\uc120 \uc804\uae30\uc5d0 \ub110\ub9ac \ub098\ud0c0\ub0ac\ub358 \ub0a8\ub140 \uade0\ubd84 \uc0c1\uc18d, \uc724\ud68c \ubd09\uc0ac, \uc790\uc720\ub85c\uc6b4 \uc7ac\uac00 \ub4f1\uc758 \uad00\ud589\uacfc \ub300\ube44\ub418\ub294 \ubcc0\ud654\uc774\ub2e4.",B.aev,B.acs,null)
B.aOv=s([u.D_,"\ud1a0\uc9c0\uc758 \ub9e4\ub9e4\ub97c \uc81c\ud55c\ud558\ub294 \ud55c\uc804\ub860\uc744 \ucc98\uc74c \uc8fc\uc7a5\ud558\uc600\ub2e4","\uc218\ub808\uc640 \uc120\ubc15\uc758 \uc774\uc6a9, \uc0c1\uacf5\uc5c5 \uc9c4\ud765\uc744 \uac15\uc870\ud558\uc600\ub2e4","\uc11c\uc5bc\uc758 \uccad\uc694\uc9c1 \uc9c4\ucd9c \ud5c8\uc6a9\uc744 \uac74\uc758\ud558\uc600\ub2e4","\u300c\uacfd\uc6b0\ub85d\u300d\uc744 \uc800\uc220\ud558\uc5ec \ud1a0\uc9c0 \uc18c\uc720\ub97c \uc81c\ud55c\ud558\uc790\uace0 \uc8fc\uc7a5\ud558\uc600\ub2e4"],t.s)
