B.bIP=new A.a("gen_kh_js2_19","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\uc911\ub18d\ud559\ud30c \uc2e4\ud559\uc790 \uc815\uc57d\uc6a9\uc758 \uc8fc\uc7a5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aOv,0,"\uc815\uc57d\uc6a9\uc740 \ub9c8\uc744(\uc5ec) \ub2e8\uc704\ub85c \ud1a0\uc9c0\ub97c \uacf5\ub3d9 \uc18c\uc720\xb7\uacbd\uc791\ud558\uace0 \ub178\ub3d9\ub7c9\uc5d0 \ub530\ub77c \uc218\ud655\ubb3c\uc744 \ubd84\ubc30\ud558\uc790\ub294 \uc5ec\uc804\ub860\uc744 \uc8fc\uc7a5\ud558\uc600\uc73c\uba70, \u300c\ubaa9\ubbfc\uc2ec\uc11c\u300d\xb7\u300c\uacbd\uc138\uc720\ud45c\u300d \ub4f1\uc744 \uc800\uc220\ud558\uc5ec \uc2e4\ud559\uc744 \uc9d1\ub300\uc131\ud558\uc600\ub2e4. \ud55c\uc804\ub860\uc740 \uc774\uc775, \uc0c1\uacf5\uc5c5 \uc9c4\ud765\ub860\uc740 \uc911\uc0c1\ud559\ud30c, \u300c\uacfd\uc6b0\ub85d\u300d\ub3c4 \uc774\uc775\uc758 \uc800\uc220\uc774\ub2e4.",B.aIV,B.uq,null)
B.akb=s([u.B8,"\uade0\uc804\ub860\uc744 \ub0b4\uc138\uc6cc \uc790\uc601\ub18d\uc744 \uc721\uc131\ud558\uace0\uc790 \ud558\uc600\ub2e4","\ud55c\uc804\ub860\uc744 \ud1b5\ud574 \ud1a0\uc9c0 \uc18c\uc720\uc758 \uc0c1\ud55c\uc744 \uc815\ud558\uc790\uace0 \uc8fc\uc7a5\ud558\uc600\ub2e4","\uc5ec\uc804\ub860\uc744 \ud1b5\ud574 \ub9c8\uc744 \ub2e8\uc704 \uacf5\ub3d9 \uacbd\uc791\uc744 \uc8fc\uc7a5\ud558\uc600\ub2e4","\u300c\ubc18\uacc4\uc218\ub85d\u300d\uc744 \uc800\uc220\ud558\uc5ec \ud1a0\uc9c0 \uc81c\ub3c4 \uac1c\ud601\uc744 \uc8fc\uc7a5\ud558\uc600\ub2e4"],t.s)
