B.bBt=new A.a("gen_kh_js2_20","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\uc911\uc0c1\ud559\ud30c(\ubd81\ud559\ud30c) \uc2e4\ud559\uc790 \ubc15\uc81c\uac00\uc758 \uc8fc\uc7a5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.akb,0,"\ubc15\uc81c\uac00\ub294 \uccad\uc5d0 \ub2e4\ub140\uc628 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \u300c\ubd81\ud559\uc758\u300d\ub97c \uc800\uc220\ud558\uc5ec \uccad \ubb38\ubb3c\uc758 \uc801\uadf9\uc801 \uc218\uc6a9\uacfc \uc0c1\uacf5\uc5c5 \uc9c4\ud765\uc744 \uc8fc\uc7a5\ud558\uc600\uc73c\uba70, \uc6b0\ubb3c\uc5d0 \ube44\uc720\ud558\uc5ec \uc808\uc57d\ubcf4\ub2e4 \uc18c\ube44\uac00 \uc0dd\uc0b0\uc744 \ucd09\uc9c4\ud55c\ub2e4\ub294 \ub17c\ub9ac(\uc6b0\ubb3c\ub860)\ub97c \ud3c8\ub2e4. \uade0\uc804\ub860\xb7\ud55c\uc804\ub860\uc740 \uac01\uac01 \uc720\ud615\uc6d0\xb7\uc774\uc775, \uc5ec\uc804\ub860\uc740 \uc815\uc57d\uc6a9, \u300c\ubc18\uacc4\uc218\ub85d\u300d\uc740 \uc720\ud615\uc6d0\uc758 \uc800\uc220\uc774\ub2e4.",B.ac4,B.t8,null)
B.a7L=s([u.cC,"\uc870\uc120 \uc815\ubd80\uac00 \uad6d\uac00 \uc774\ub150\uc73c\ub85c \uc801\uadf9 \uc7a5\ub824\ud558\uc5ec \ub110\ub9ac \ud37c\uc84c\ub2e4","\ucd5c\uc81c\uc6b0\uac00 \ucc3d\uc2dc\ud55c \ubbfc\uc871 \uc885\uad50\ub85c \ub3d9\ud559\uacfc \uac19\uc740 \uacc4\uc5f4\uc774\ub2e4","\uc784\uc9c4\uc65c\ub780 \ub54c \uc77c\ubcf8\uc744 \ud1b5\ud574 \ucc98\uc74c \uc804\ub798\ub418\uc5c8\ub2e4","\uac11\uc624\uac1c\ud601 \uc774\ud6c4\uc5d0\uc57c \ucc98\uc74c\uc73c\ub85c \uad6d\ub0b4\uc5d0 \uc18c\uac1c\ub418\uc5c8\ub2e4"],t.s)
B.bhF=s([u.cC],t.s)
B.aJV=s(["\uc11c\ud559(\ucc9c\uc8fc\uad50)\uc758 \uc804\ub798\uc640 \ud655\uc0b0"],t.s)
B.brz=new A.a("gen_kh_js2_21","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\uc11c\ud559(\ucc9c\uc8fc\uad50)\uc758 \uc804\ub798\uc640 \ud655\uc0b0\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7L,0,"\ucc9c\uc8fc\uad50(\uc11c\ud559)\ub294 \ucc98\uc74c \uc911\uad6d\uc744 \uc655\ub798\ud558\ub358 \uc0ac\uc2e0\ub4e4\uc744 \ud1b5\ud574 \uc11c\uc591 \ud559\ubb38\uc758 \ud558\ub098\ub85c \uc18c\uac1c\ub418\uc5c8\ub2e4\uac00, \uc810\ucc28 \uc2e0\uc559\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc838 \ud3c9\ub4f1\uc0ac\uc0c1 \ub4f1\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc31\uc131\ub4e4 \uc0ac\uc774\uc5d0 \ud655\uc0b0\ub418\uc5c8\ub2e4. \uc774\ub294 \uc131\ub9ac\ud559\uc801 \uc9c8\uc11c\ub97c \uc704\ud611\ud55c\ub2e4\ub294 \uc774\uc720\ub85c \uc815\ubd80\uc758 \ud0c4\uc555(\uc2e0\uc720\ubc15\ud574 \ub4f1)\uc744 \ubc1b\uc558\ub2e4. \ub3d9\ud559\uc740 \ucd5c\uc81c\uc6b0\uac00 \uc11c\ud559\uc5d0 \ub300\ud56d\ud574 \ucc3d\uc2dc\ud55c \ubcc4\uac1c\uc758 \ubbfc\uc871 \uc885\uad50\uc774\ub2e4.",B.bhF,B.aJV,null)
B.bbz=s(["\uc720\xb7\ubd88\xb7\uc120\uc744 \uc808\ucda9\ud558\uace0 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \uc11c\ud559\uc758 \ud655\uc0b0\uc5d0 \ub9de\uc11c \ucc3d\uc2dc\ub418\uc5c8\ub2e4","\uc911\uad6d\uc5d0\uc11c \uc804\ub798\ub41c \ucc9c\uc8fc\uad50\uc758 \ub2e4\ub978 \uc774\ub984\uc774\ub2e4","\uc911\uc0c1\ud559\ud30c \uc2e4\ud559\uc790\ub4e4\uc774 \uc8fc\ub3c4\ud558\uc5ec \ub9cc\ub4e0 \ud559\ubb38 \uc720\ud30c\uc774\ub2e4","\uc870\uc120 \uc815\ubd80\uac00 \uad6d\uac00 \uc885\uad50\ub85c \uacf5\uc778\ud558\uc5ec \ub110\ub9ac \ubcf4\uae09\ud558\uc600\ub2e4","\uac11\uc2e0\uc815\ubcc0\uc744 \uc8fc\ub3c4\ud55c \uae09\uc9c4 \uac1c\ud654\ud30c\uac00 \ucc3d\uc2dc\ud558\uc600\ub2e4"],t.s)
B.bc4=s(["\uc720\xb7\ubd88\xb7\uc120\uc744 \uc808\ucda9\ud558\uace0 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \uc11c\ud559\uc758 \ud655\uc0b0\uc5d0 \ub9de\uc11c \ucc3d\uc2dc\ub418\uc5c8\ub2e4"],t.s)
B.u9=s(["\ub3d9\ud559\uc758 \ucc3d\uc2dc"],t.s)
B.bGK=new A.a("gen_kh_js2_22","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\ucd5c\uc81c\uc6b0\uac00 \ucc3d\uc2dc\ud55c \ub3d9\ud559\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bbz,0,"\ub3d9\ud559\uc740 \ucd5c\uc81c\uc6b0\uac00 \uc720\uad50\xb7\ubd88\uad50\xb7\ub3c4\uad50(\uc120)\uc758 \uc0ac\uc0c1\uc744 \uc808\ucda9\ud558\uace0 \uc0ac\ub78c\uc774 \uace7 \ud558\ub298\uc774\ub77c\ub294 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \ucc3d\uc2dc\ud55c \ubbfc\uc871 \uc885\uad50\ub85c, \uc11c\ud559(\ucc9c\uc8fc\uad50)\uc758 \ud655\uc0b0\uc5d0 \ub300\uc751\ud558\ub294 \uc131\uaca9\uc744 \uac00\uc9c0\uace0 \uc788\uc5c8\uc73c\uba70, \uc774\ud6c4 \uad50\uc870 \uc2e0\uc6d0 \uc6b4\ub3d9\uacfc \ub3d9\ud559 \ub18d\ubbfc \uc6b4\ub3d9\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4.",B.bc4,B.u9,null)
B.Ri=s(["\ud55c\uae00 \uc18c\uc124\uacfc \ud310\uc18c\ub9ac, \ud0c8\ucda4 \ub4f1\uc774 \uc720\ud589\ud558\uba70 \uc11c\ubbfc\ub4e4\uc758 \uc0dd\ud65c \uac10\uc815\uc744 \ud45c\ud604\ud558\uc600\ub2e4","\ud55c\ubb38\ud559\uacfc \uc131\ub9ac\ud559 \uc911\uc2ec\uc758 \uc591\ubc18 \ubb38\ud654\ub9cc\uc774 \ubc1c\ub2ec\ud558\uc600\ub2e4","\uace0\ub824\uccad\uc790\uc640 \uac19\uc740 \uadc0\uc871\uc801 \uc608\uc220\ud488\uc774 \ub110\ub9ac \uc720\ud589\ud558\uc600\ub2e4","\uae08\uc18d \ud65c\uc790\ub97c \uc774\uc6a9\ud55c \ubd88\uacbd \uc778\uc1c4\uac00 \ubb38\ud654\uc758 \uc911\uc2ec\uc744 \uc774\ub8e8\uc5c8\ub2e4","\uc11c\uc6d0\uacfc \ud5a5\uc57d\uc744 \ud1b5\ud55c \uc0ac\ub9bc\uc758 \ud5a5\ucd0c \uc9c0\ubc30 \ubb38\ud654\uac00 \uc0c8\ub86d\uac8c \ub098\ud0c0\ub0ac\ub2e4"],t.s)
