B.bBz=new A.a("gen_cl_juridicalact_2","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ub2e8\ub3c5\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740?",B.a_t,0,"\ucc44\ubb34\uba74\uc81c\ub294 \ucc44\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ucc44\uad8c\uc744 \uc18c\uba78\uc2dc\ud0a4\ub294 \ub2e8\ub3c5\ud589\uc704\uc774\ub2e4. \ub9e4\ub9e4\xb7\uc784\ub300\ucc28\xb7\uc870\ud569\xb7\ud654\ud574\ub294 \ubaa8\ub450 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc \ud569\uce58\ub97c \uc694\ud558\ub294 \uacc4\uc57d(\uc30d\ubc29\ud589\uc704)\uc774\ub2e4.",B.aqb,B.aqM,null)
B.aUO=s([u.pR,"\ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ubc29\uc2dd\uc5d0 \uad00\uacc4\uc5c6\uc774 \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4","\ubaa8\ub4e0 \uacc4\uc57d\uc740 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc791\uc131\ub418\uc5b4\uc57c \ud558\ub294 \uc694\uc2dd\ud589\uc704\uc774\ub2e4","\ubd88\uc694\uc2dd\ud589\uc704\ub294 \ubc95\ub960\uc0c1 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc694\uc2dd\ud589\uc704\ub294 \uc0c1\ub300\ubc29 \uc788\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
