B.boc=new A.a("gen_cl_juridicalact_5","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\ubc18\uc0ac\ud68c\uc9c8\uc11c\uc758 \ubc95\ub960\ud589\uc704(\ubbfc\ubc95 \uc81c103\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aDI,0,'\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ubbc0\ub85c \uc774\ud589 \uc804\uc774\ub4e0 \ud6c4\ub4e0 \uadf8 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4. "\uc774\ud589 \uc804\uc774\ub77c\uba74 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ubc18\uba74 \ucc38\uace0\uc778 \ud5c8\uc704 \uc9c4\uc220 \ub300\uac00 \uc57d\uc815, \ub3c4\ubc15\uc790\uae08 \uc18c\ube44\ub300\ucc28 \ub4f1\uc740 \ud310\ub840\uc0c1 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c \ubb34\ud6a8\ub77c\uace0 \ubcf8 \ub300\ud45c\uc801 \uc0ac\ub840\uc774\uba70, \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \ub530\ub77c \uc774\ubbf8 \uae09\ubd80\ud55c \uac83\uc740 \ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \ubc18\ud658\uccad\uad6c\uac00 \ubd80\uc815\ub41c\ub2e4.',B.aUz,B.aX2,null)
B.ZT=s(["\uac1d\uad00\uc801\uc73c\ub85c \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\uc5b4\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ud53c\ud574\uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc758 \uc0c1\ud0dc\uc5d0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc774 \ud53c\ud574\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc54c\uba74\uc11c \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\uc758\uc0ac)\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uad81\ubc15\uc740 \ubc18\ub4dc\uc2dc \uacbd\uc81c\uc801 \uad81\ubc15\uc5d0 \ud55c\uc815\ub418\uc9c0 \uc54a\uace0 \uc815\uc2e0\uc801\xb7\uc2ec\ub9ac\uc801 \uad81\ubc15\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4"],t.s)
B.a14=s(["\uac1d\uad00\uc801\uc73c\ub85c \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc5c6\uc5b4\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4"],t.s)
