B.byC=new A.a("gen_cl_juridicalact_7","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc(\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aF6,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc2dc\ub41c \ub300\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aQn,B.Xp,null)
B.a03=s([u.xW,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0 \uc758\ud55c \ucc44\ubb34\ub97c \ubcf4\uc99d\ud55c \uc790\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc640 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.aXz=s([u.xW],t.s)
B.aE8=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc131\ub9bd\uacfc \ud6a8\uacfc"],t.s)
B.bub=new A.a("gen_cl_juridicalact_8","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\ubbfc\ubc95 \uc81c108\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.a03,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \uc9c4\uc758\uc640 \ub2e4\ub978 \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc73c\ub85c, \uadf8 \uc790\uccb4\ub85c \ubb34\ud6a8\uc774\ub2e4. \ub2e4\ub9cc \uc774 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \uc591\ud574(\ud1b5\uc815)\ub97c \uc804\uc81c\ub85c \ud558\ubbc0\ub85c \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub294 \uc131\ub9bd\ud560 \uc218 \uc5c6\uace0, \ucc29\uc624\uc640\ub294 \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4.",B.aXz,B.aE8,null)
B.alZ=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790","\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778","\uac00\uc7a5\ucc44\uad8c\uc744 \uac00\uc555\ub958\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\uac00\uc7a5\uc591\uc218\uc778\uc73c\ub85c\ubd80\ud130 \ubaa9\uc801\ubb3c\uc744 \ub2e4\uc2dc \ub9e4\uc218\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ub97c \uc804\ud600 \ub2e4\ud22c\uc9c0 \uc54a\ub294 \ub2f9\uc0ac\uc790 \ubcf8\uc778"],t.s)
B.baW=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790"],t.s)
B.b3r=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.btd=new A.a("gen_cl_juridicalact_9","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub294 \uc790\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.alZ,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub85c\ubd80\ud130 \ubcf4\ud638\ub418\ub294 \uc120\uc758\uc758 \uc81c3\uc790\ub780 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub85c\uc11c \uadf8 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc790\ub97c \ub9d0\ud55c\ub2e4. \uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ucc44\uad8c\uc744 \uc555\ub958\ud558\uba74\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790\ub294 \uc774\ub7ec\ud55c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub098, \ub2f9\uc0ac\uc790\xb7\ud3ec\uad04\uc2b9\uacc4\uc778\uc774\ub098 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790(\uc545\uc758)\ub294 \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uac00 \uc544\ub2c8\ub2e4.",B.baW,B.b3r,null)
B.V8=s([u.hc,"\uc740\ub2c9\ud589\uc704\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\ub85c\uc11c \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\uac00 \uc788\ub294 \uacbd\uc6b0 \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704\uc640 \uc740\ub2c9\ub41c \ubc95\ub960\ud589\uc704\ub294 \ubaa8\ub450 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc791\uc131\ub418\uc5b4\uc57c \uc720\ud6a8\ud558\ub2e4","\uc740\ub2c9\ud589\uc704 \uc774\ub860\uc740 \ubb3c\uad8c\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.arV=s([u.hc],t.s)
B.bh9=s(["\uc740\ub2c9\ud589\uc704\uc758 \ubc95\ub9ac"],t.s)
B.bLd=new A.a("gen_cl_juridicalact_10","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\uc740\ub2c9\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.V8,0,"\ub2f9\uc0ac\uc790\uac00 \uc9c4\uc815\uc73c\ub85c \uc758\uc695\ud55c \ubc95\ub960\ud589\uc704(\uc608: \uc99d\uc5ec)\ub97c \ub2e4\ub978 \ubc95\ub960\ud589\uc704(\uc608: \ub9e4\ub9e4)\ub85c \uac00\uc7a5\ud558\uc5ec \ud45c\uc2dc\ud55c \uacbd\uc6b0, \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704(\ub9e4\ub9e4)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubc30\ud6c4\uc5d0 \uc228\uaca8\uc9c4 \uc9c4\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc99d\uc5ec, \uc740\ub2c9\ud589\uc704)\ub294 \uadf8 \uc790\uccb4\uc758 \uc131\ub9bd\xb7\ud6a8\ub825 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4.",B.arV,B.bh9,null)
B.akq=s([u.pt,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\uc9c0\ub9cc, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ud56d\uc0c1 \uc720\ud6a8\uc774\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc694\uac74\uacfc \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aKA=s([u.pt],t.s)
B.b9Y=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uad6c\ubcc4"],t.s)
B.bxe=new A.a("gen_cl_juridicalact_11","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.akq,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc758\uc790 \ud63c\uc790\ub9cc \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \uc788\uc73c\uba74 \ub418\uace0 \uc0c1\ub300\ubc29\uacfc\uc758 \ud569\uc758(\ud1b5\uc815)\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ubc18\uba74, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \ud5c8\uc704\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4. \ub2e4\ub9cc \ub450 \uc81c\ub3c4 \ubaa8\ub450 \uc6d0\uce59\uc801 \ud6a8\ub825\uacfc \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uc5d0 \uc788\uc5b4 \uc720\uc0ac\ud55c \uad6c\uc870\ub97c \ucde8\ud55c\ub2e4.",B.aKA,B.b9Y,null)
B.a89=s([u.k,"\u4e19\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \u7532\uc740 \uc5b8\uc81c\ub098 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\u4e19\uc774 \uc545\uc758\uc600\ub354\ub77c\ub3c4 \u7532\uc740 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\u4e19\uc740 \ub4f1\uae30\ub97c \ub9c8\ucce4\ub354\ub77c\ub3c4 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud560 \uc218 \uc5c6\ub2e4","\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ud5c8\uc704\ud45c\uc2dc\ub294 \uc560\ucd08\uc5d0 \uc720\ud6a8\ud558\ubbc0\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
