B.brN=new A.a("gen_cl_juridicalact_14","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.Z1,0,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uac00 \ucc29\uc624\ub85c \uc778\ud558\uc5ec \uacbd\uc81c\uc801 \ubd88\uc774\uc775\uc744 \uc785\uc9c0 \uc54a\uc558\ub2e4\uba74 \uadf8 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \uad00\ud55c \uac83\uc774\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4. \ubc18\ub300\ub85c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub85c \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\uba70, \uc911\uc694\ubd80\ubd84 \ud574\ub2f9 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uacfc \uc77c\ubc18\uc778\uc758 \uac1d\uad00\uc801 \uae30\uc900\uc744 \ud568\uaed8 \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4.",B.ae3,B.aFP,null)
B.bbQ=s([u.Ay,"\uc81c3\uc790\uc758 \uc0ac\uae30\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uac00 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4","\uae30\ub9dd\ud589\uc704\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
