B.bod=new A.a("gen_cl_juridicalact_18","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\ud558\uc790 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc(\uc0ac\uae30\xb7\uac15\ubc15)\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bac,0,"\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0(\ucde8\uc18c \uc6d0\uc778\uc774 \uc885\ub8cc\ud55c \ub0a0 \ub4f1)\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70, \uc774 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ucde8\uc18c\uad8c\uc740 \uc81c\ucc99\uae30\uac04\uc758 \uacbd\uacfc\ub85c \uc18c\uba78\ud55c\ub2e4.",B.aN4,B.ar1,null)
B.b2R=s([u.gQ,"\ubb34\ud6a8\uc640 \ucde8\uc18c\ub294 \uadf8 \ud6a8\uacfc\uc5d0 \uc788\uc5b4 \uc804\ud600 \ucc28\uc774\uac00 \uc5c6\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\uc5b4\ub3c4 \ub204\uad6c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc790\ub3d9\uc73c\ub85c \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \uc804\ud658\ub41c\ub2e4","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c \uc2dc\uc810\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
