B.bqz=new A.a("gen_cl_juridicalact_19","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b2R,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc73c\ub85c \ud655\uc815\ub418\uc5b4 \uc788\uc73c\ub098, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud558\uba70, \ucde8\uc18c\ub418\uba74 \uc18c\uae09\ud558\uc5ec \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4. \ucde8\uc18c\uad8c\uc740 \ubc95\ub960\uc774 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\ub9cc\uc774 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.ak1,B.VO,null)
B.a7I=s(["\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucd94\uc778\uc5d0 \uc758\ud574 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc5c6\ub2e4","\ubb34\ud6a8\ud589\uc704\ub97c \ucd94\uc778\ud558\uba74 \ucc98\uc74c \ubc95\ub960\ud589\uc704 \uc2dc\uc810\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ud558\uac8c \ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc740 \ubb35\uc2dc\uc801\uc73c\ub85c\ub294 \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc5c6\uace0 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \ud574\uc57c \ud55c\ub2e4","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870 \uc704\ubc18)\ub3c4 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ub420 \uc218 \uc788\ub2e4"],t.s)
B.aRS=s(["\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
