B.bse=new A.a("gen_cl_juridicalact_21","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\ubbfc\ubc95 \uc81c138\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aq4,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0, \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub354\ub77c\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4(\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658). \ub9e4\ub9e4\ub300\uae08 \uacfc\ub2e4\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\ud6a8\ud589\uc704 \uc804\ud658 \ubc95\ub9ac\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.a4e,B.tG,null)
B.aM2=s([u.fy,"\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \ucc44\ubb34\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc774\ud589\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \uc0c1\ub300\ubc29\uc73c\ub85c\ubd80\ud130 \uc774\ud589\uc744 \uccad\uad6c\ubc1b\uc544 \uc774\ub97c \uc218\ub839\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uac15\uc81c\uc9d1\ud589\uc744 \ud55c \uacbd\uc6b0"],t.s)
B.a2Q=s([u.fy],t.s)
B.aNE=s(["\ubc95\uc815\ucd94\uc778\uc758 \uc694\uac74"],t.s)
B.bGJ=new A.a("gen_cl_juridicalact_22","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubc95\uc815\ucd94\uc778(\ubbfc\ubc95 \uc81c145\uc870)\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.aM2,0,"\ubc95\uc815\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uad8c\uc774 \uc788\uc74c\uc744 \uc54c\uace0 \uc77c\uc815\ud55c \uc0ac\uc720(\uc774\ud589, \uc774\ud589\uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc81c\uacf5, \uad8c\ub9ac\uc591\ub3c4, \uac15\uc81c\uc9d1\ud589 \ub4f1)\ub97c \ud589\ud55c \uacbd\uc6b0\uc5d0 \uc778\uc815\ub41c\ub2e4. \ucde8\uc18c\uad8c\uc774 \uc788\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c \ucc44 \ud55c \ud589\uc704\ub294 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.a2Q,B.aNE,null)
B.Va=s([u.iM,"\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc774\uba74 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ud56d\uc0c1 \uc790\ub3d9\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\uc77c\ubd80\ubb34\ud6a8 \ubc95\ub9ac\ub294 \uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\uc640 \ubb34\uad00\ud558\uac8c \ubc95\uc6d0\uc774 \uc77c\ub960\uc801\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc77c\ubd80\ubb34\ud6a8 \ubc95\ub9ac\ub294 \uac15\ud589\ubc95\uaddc \uc704\ubc18\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
