B.bry=new A.a("gen_cl_antisocial_2","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \ud574\ub2f9 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \uae30\uc900 \uc2dc\uc810\uc740 \uc5b8\uc81c\uc778\uac00?",B.Zv,0,"\ud310\ub840\ub294 \uc5b4\ub290 \ubc95\ub960\ud589\uc704\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub54c, \uc989 \uc131\ub9bd \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc131\ub9bd \ub2f9\uc2dc \uc801\ubc95\xb7\uc720\ud6a8\ud588\ub358 \ud589\uc704\uac00 \uc0ac\ud6c4 \uc0ac\uc815\ubcc0\uacbd\ub9cc\uc73c\ub85c \ubb34\ud6a8\ub85c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4.",B.aVa,B.rt,null)
B.b63=s(["\ub3d9\uae30\uac00 \ubd88\ubc95\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ubd88\ubc95\ud55c \ub3d9\uae30\uac00 \ud45c\uc2dc\ub418\uc5c8\uac70\ub098 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\ub3d9\uae30\uc758 \ubd88\ubc95\uc740 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uc804\ud600 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uae30\uac00 \ubd88\ubc95\ud558\uba74 \ucde8\uc18c\uc0ac\uc720\uac00 \ub420 \ubfd0 \ubb34\ud6a8\uc0ac\uc720\ub294 \uc544\ub2c8\ub2e4"],t.s)
B.bhm=s(["\uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5c8\uac70\ub098 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\ub358 \ub54c\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.at4=s(["\ub3d9\uae30\uc758 \ubd88\ubc95"],t.s)
B.bAJ=new A.a("gen_cl_antisocial_3","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,'\ubc95\ub960\ud589\uc704\uc758 "\ub3d9\uae30"\uc758 \ubd88\ubc95\uc774 \ubc18\uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc740?',B.b63,1,"\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9 \uc790\uccb4\ub294 \uc801\ubc95\ud558\ub354\ub77c\ub3c4 \uadf8 \ub3d9\uae30\uac00 \ubd88\ubc95\ud55c \uacbd\uc6b0, \uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5c8\uac70\ub098 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\ub358 \ub54c\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.bhm,B.at4,null)
