B.Ru=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud558\uc5ec"],t.s)
B.bd8=s(["\ud615\uc0ac\ud569\uc758\uae08"],t.s)
B.bL0=new A.a("gen_cl_antisocial_8","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ud615\uc0ac\uc0ac\uac74\uc5d0 \uad00\ud558\uc5ec \uace0\uc18c\ub97c \ucde8\ud558\ud558\ub294 \ub300\uac00\ub85c \uc801\uc815\ud55c \ubc94\uc704\uc758 \ud569\uc758\uae08\uc744 \uc9c0\uae09\ud558\uae30\ub85c \ud55c \uc57d\uc815\uc740?",B.aIQ,1,"\ud615\uc0ac\uc0ac\uac74\uc5d0\uc11c\uc758 \uace0\uc18c \ucde8\ud558 \ub4f1\uc744 \uc870\uac74\uc73c\ub85c \ud55c \ud569\uc758\uae08 \uc9c0\uae09 \uc57d\uc815 \uc790\uccb4\ub294 \ubd84\uc7c1 \ud574\uacb0\uc758 \uc218\ub2e8\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4. \ub2e4\ub9cc \uadf8 \uae08\uc561\uc774 \ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud558\uc5ec \uc0ac\uc2e4\uc0c1 \ub300\uac00\uad00\uacc4\uac00 \uc0ac\ud68c\ud1b5\ub150\uc744 \ud604\uc800\ud788 \ubc97\uc5b4\ub098\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c\uc131\uc774 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.Ru,B.bd8,null)
B.bfl=s(["\ubbfc\uc0ac\uc0ac\uac74\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ud615\uc0ac\uc0ac\uac74 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ud615\uc0ac\uc0ac\uac74\uc5d0\uc11c\uc758 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\uc740 \uc218\uc0ac\xb7\uc7ac\ud310\uc758 \uacb0\uacfc\ub97c \uae08\uc804\uc801 \ub300\uac00\uc640 \uacb0\ubd80\uc2dc\ucf1c \uc0ac\ubc95\uc758 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc704\ud5d8\uc774 \uc788\uc5b4 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\ub77c\uace0 \ubcf4\uc558\ub2e4","\ud615\uc0ac\uc0ac\uac74 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\uc740 \uae08\uc561\uc774 \uacfc\ub2e4\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ubb34\ud6a8\uc774\ub2e4","\ud615\uc0ac\uc0ac\uac74 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\uc740 \ubcc0\ud638\uc0ac\ubc95 \uc704\ubc18\uc77c \ubfd0 \ubbfc\ubc95\uc0c1 \ubb34\ud6a8\ub294 \uc544\ub2c8\ub2e4"],t.s)
B.R8=s(["\uc0ac\ubc95\uc758 \uc2e0\ub8b0\uc640 \uacf5\uc815\uc131\uc744 \uc704\ud0dc\ub86d\uac8c \ud560 \uc704\ud5d8\uc774 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c","\uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ub418\ub294 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8"],t.s)
B.bhG=s(["\ud615\uc0ac \uc131\uacf5\ubcf4\uc218 \ubb34\ud6a8 \ud310\ub840"],t.s)
B.bD5=new A.a("gen_cl_antisocial_9","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ud615\uc0ac\uc0ac\uac74\uc5d0\uc11c\uc758 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\uc5d0 \uad00\ud55c \ub300\ubc95\uc6d0 \uc804\uc6d0\ud569\uc758\uccb4 \ud310\uacb0\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.bfl,1,"\ub300\ubc95\uc6d0 \uc804\uc6d0\ud569\uc758\uccb4\ub294 \ud615\uc0ac\uc0ac\uac74\uc5d0 \uad00\ud55c \ubcc0\ud638\uc0ac\uc758 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815\uc774 \uc218\uc0ac\xb7\uc7ac\ud310 \uacb0\uacfc\ub97c \uae08\uc804\uc801 \uc774\uc775\uacfc \uacb0\ubd80\uc2dc\ucf1c \uc0ac\ubc95\uc758 \uc2e0\ub8b0\uc640 \uacf5\uc815\uc131\uc744 \uc704\ud0dc\ub86d\uac8c \ud560 \uc704\ud5d8\uc774 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c, \uc885\ub798\uc640 \ub2ec\ub9ac \uc774\ub97c \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ub418\ub294 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\ub77c\uace0 \ud310\uc2dc\ud558\uc600\ub2e4.",B.R8,B.bhG,null)
B.aNk=s(["\uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8\uc774\ub2e4","\uc774\ud589\uc774 \uc644\ub8cc\ub418\uba74 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4","\ucde8\uc18c\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.aXy=s(["\uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294 \uac83\uc73c\ub85c\uc11c \ubb34\ud6a8"],t.s)
B.bf1=s(["\uc131\ub9e4\ub9e4 \uc54c\uc120\uacc4\uc57d"],t.s)
B.bR8=new A.a("gen_cl_antisocial_10","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uc131\ub9e4\ub9e4\ub97c \uc54c\uc120\ud558\uace0 \uadf8 \ub300\uac00\ub97c \uc9c0\uae09\ubc1b\uae30\ub85c \ud55c \uc57d\uc815\uc758 \ud6a8\ub825\uc740?",B.aNk,1,"\uc131\ub9e4\ub9e4\uc54c\uc120 \ub4f1 \ud589\uc704\uc758 \ucc98\ubc8c\uc5d0 \uad00\ud55c \ubc95\ub960\uc758 \ucde8\uc9c0\uc5d0 \ube44\ucd94\uc5b4, \uc131\ub9e4\ub9e4\ub97c \uc54c\uc120\ud558\uace0 \uadf8 \ub300\uac00\ub97c \uc9c0\uae09\ubc1b\uae30\ub85c \ud558\ub294 \uc57d\uc815\uc740 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294 \uac83\uc73c\ub85c\uc11c \ubb34\ud6a8\uc774\ub2e4.",B.aXy,B.bf1,null)
B.bdZ=s(["\ubcf4\ud5d8\ub8cc\ub97c \ub0a9\uc785\ud55c \uc774\uc0c1 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ubcf4\ud5d8\uc0ac\uace0 \ubc1c\uc0dd \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud558\ub2e4","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\ubcf4\ud5d8\ud68c\uc0ac\uac00 \uc2b9\ub099\ud558\uba74 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.auE=s(["\ubcf4\ud5d8\uae08\uc744 \ubd80\uc815\ud558\uac8c \ucde8\ub4dd\ud560 \ubaa9\uc801\uc73c\ub85c \ub2e4\uc218\uc758 \ubcf4\ud5d8\uc5d0 \uac00\uc785\ud55c \uacbd\uc6b0","\ubc18\uc0ac\ud68c\uc9c8\uc11c\uc801\uc774\ub77c\uace0 \ud3c9\uac00\ub420 \uc218 \uc788\uc5b4"],t.s)
B.agb=s(["\ubcf4\ud5d8\uc0ac\uae30 \ubaa9\uc801 \uacc4\uc57d"],t.s)
B.bE5=new A.a("gen_cl_antisocial_11","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubcf4\ud5d8\uae08\uc744 \ubd80\uc815\ucde8\ub4dd\ud560 \ubaa9\uc801\uc73c\ub85c \ub2e4\uc218\uc758 \ubcf4\ud5d8\uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uadf8 \ubcf4\ud5d8\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.bdZ,2,"\uc624\ub85c\uc9c0 \ubcf4\ud5d8\uae08\uc744 \ubd80\uc815\ud558\uac8c \ucde8\ub4dd\ud560 \ubaa9\uc801\uc73c\ub85c \ub2e4\uc218\uc758 \ubcf4\ud5d8\uc5d0 \uac00\uc785\ud55c \uacbd\uc6b0, \uadf8 \ubaa9\uc801\uc774 \uc0c1\ub300\ubc29(\ubcf4\ud5d8\uc790)\uc5d0\uac8c \uc54c\ub824\uc84c\ub294\uc9c0 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \uacc4\uc57d \uccb4\uacb0\uc758 \ubaa9\uc801 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\uc801\uc774\ub77c\uace0 \ud3c9\uac00\ub420 \uc218 \uc788\uc5b4 \ud574\ub2f9 \ubcf4\ud5d8\uacc4\uc57d\uc774 \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4.",B.auE,B.agb,null)
B.aUh=s(["\uc774\uc911\ub9e4\ub9e4\ub294 \uadf8 \uc790\uccb4\ub85c \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uba3c\uc800 \ub4f1\uae30\ub97c \ub9c8\uce5c \uc81c2\ub9e4\uc218\uc778\uc774 \uc18c\uc720\uad8c\uc744 \uc720\ud6a8\ud558\uac8c \ucde8\ub4dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc81c1\ub9e4\uc218\uc778\ub9cc \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud560 \uc218 \uc788\ub2e4","\uc774\uc911\ub9e4\ub9e4\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774\ubbc0\ub85c \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.anH=s(["\uc790\uc720\uacbd\uc7c1\uc758 \uacb0\uacfc\ub85c\uc11c \uba3c\uc800 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\ub97c \ub9c8\uce5c \ub9e4\uc218\uc778(\ud1b5\uc0c1 \uc81c2\ub9e4\uc218\uc778)\uc774 \uc720\ud6a8\ud558\uac8c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.b4m=s(["\uc774\uc911\ub9e4\ub9e4 \uc6d0\uce59"],t.s)
B.bIC=new A.a("gen_cl_antisocial_12","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubd80\ub3d9\uc0b0 \uc774\uc911\ub9e4\ub9e4\uc758 \uc6d0\uce59\uc801 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUh,1,"\ubd80\ub3d9\uc0b0 \uc774\uc911\ub9e4\ub9e4\ub294 \uadf8 \uc790\uccb4\ub9cc\uc73c\ub85c\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\uac00 \uc544\ub2c8\uba70, \uc790\uc720\uacbd\uc7c1\uc758 \uacb0\uacfc\ub85c\uc11c \uba3c\uc800 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\ub97c \ub9c8\uce5c \ub9e4\uc218\uc778(\ud1b5\uc0c1 \uc81c2\ub9e4\uc218\uc778)\uc774 \uc720\ud6a8\ud558\uac8c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \ub9e4\ub3c4\uc778\uc740 \uc81c1\ub9e4\uc218\uc778\uc5d0 \ub300\ud574 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc744 \uc9c8 \ubfd0\uc774\ub2e4.",B.anH,B.b4m,null)
B.bdM=s(["\uc81c2\ub9e4\uc218\uc778\uc774 \uc774\uc911\ub9e4\ub9e4 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\ub9e4\ub3c4\uc778\uc758 \ubc30\uc784\ud589\uc704\uc5d0 \uc81c2\ub9e4\uc218\uc778\uc774 \uc801\uadf9 \uac00\ub2f4\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc81c2\ub9e4\uc218\uc778\uc774 \uc81c1\ub9e4\uc218\uc778\ubcf4\ub2e4 \ub2a6\uac8c \uacc4\uc57d\ud55c \uacbd\uc6b0 \ud56d\uc0c1 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ub9e4\ub9e4\ub300\uae08\uc774 \uc2dc\uac00\ubcf4\ub2e4 \uc800\ub834\ud55c \uacbd\uc6b0 \ud56d\uc0c1 \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.SH=s(["\ub9e4\ub3c4\uc778\uc758 \ubc30\uc784\ud589\uc704\uc5d0 \uc81c2\ub9e4\uc218\uc778\uc774 \uc801\uadf9\uc801\uc73c\ub85c \uac00\ub2f4(\uad8c\uc720\xb7\uc694\uccad \ub4f1)\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub41c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b71=s(["\uc801\uadf9\uac00\ub2f4 \uc694\uac74"],t.s)
B.bo4=new A.a("gen_cl_antisocial_13","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubd80\ub3d9\uc0b0 \uc774\uc911\ub9e4\ub9e4\uac00 \uc608\uc678\uc801\uc73c\ub85c \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc740?",B.bdM,1,"\ud310\ub840\ub294 \ubd80\ub3d9\uc0b0 \uc774\uc911\ub9e4\ub9e4\uac00 \ubb34\ud6a8\ub85c \ub418\uae30 \uc704\ud574\uc11c\ub294 \ub2e8\uc21c\ud788 \uc81c2\ub9e4\uc218\uc778\uc774 \uc774\uc911\ub9e4\ub9e4 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \ub9e4\ub3c4\uc778\uc758 \ubc30\uc784\ud589\uc704\uc5d0 \uc81c2\ub9e4\uc218\uc778\uc774 \uc801\uadf9\uc801\uc73c\ub85c \uac00\ub2f4(\uad8c\uc720\xb7\uc694\uccad \ub4f1)\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub41c\ub2e4\uace0 \ubcf8\ub2e4.",B.SH,B.b71,null)
B.a7g=s(["\uc774\uc911\ub9e4\ub9e4 \uc0ac\uc2e4\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\uace0 \uc788\uc5c8\ub358 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\ub9e4\ub3c4\uc778\uc774 \uc774\ubbf8 \ub9e4\ub3c4\ud55c \uc0ac\uc2e4\uc744 \uc54c\uba74\uc11c \ub9e4\ub3c4\uc778\uc5d0\uac8c \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uac70\ub098 \uc694\uccad\ud558\ub294 \ub4f1 \ubc30\uc784\ud589\uc704\uc5d0 \uc801\uadf9\uc801\uc73c\ub85c \uad00\uc5ec\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\uc81c2\ub9e4\uc218\uc778\uc774 \ub9e4\ub9e4\ub300\uae08\uc744 \uba3c\uc800 \uc9c0\uae09\ud55c \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ub4f1\uae30\ub97c \uba3c\uc800 \ub9c8\uce5c \uac83 \uc790\uccb4\ub97c \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.b6z=s(["\ub2e8\uc21c\ud788 \uc54c\uace0 \uc788\ub294 \uac83\uc744 \ub118\uc5b4","\uc801\uadf9\uc801\uc73c\ub85c \uad00\uc5ec\ud558\ub294 \uac83\uc744 \uc758\ubbf8"],t.s)
B.bdl=s(["\uc801\uadf9\uac00\ub2f4\uc758 \uc758\ubbf8"],t.s)
B.bpD=new A.a("gen_cl_antisocial_14","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,'\uc774\uc911\ub9e4\ub9e4\uc5d0\uc11c \uc81c2\ub9e4\uc218\uc778\uc758 "\uc801\uadf9 \uac00\ub2f4"\uc758 \uc758\ubbf8\ub85c \uc633\uc740 \uac83\uc740?',B.a7g,1,"\uc801\uadf9 \uac00\ub2f4\uc774\ub780 \uc81c2\ub9e4\uc218\uc778\uc774 \ub9e4\ub3c4\uc778\uc758 \ubc30\uc784\ud589\uc704(\uc774\uc911\ub9e4\ub9e4)\ub97c \ub2e8\uc21c\ud788 \uc54c\uace0 \uc788\ub294 \uac83\uc744 \ub118\uc5b4, \ub9e4\ub3c4\uc778\uc5d0\uac8c \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uac70\ub098 \uc694\uccad\ud558\ub294 \ub4f1\uc73c\ub85c \ubc30\uc784\ud589\uc704\uc5d0 \uc801\uadf9\uc801\uc73c\ub85c \uad00\uc5ec\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4. \ub2e8\uc21c \uc778\uc2dd\ub9cc\uc73c\ub85c\ub294 \uc801\uadf9 \uac00\ub2f4\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.b6z,B.bdl,null)
B.aMM=s(["\uc81c1\ub9e4\uc218\uc778\uc740 \uc5b4\ub5a0\ud55c \uad8c\ub9ac\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\ub9e4\ub3c4\uc778\uc744 \ub300\uc704\ud558\uc5ec \uc81c2\ub9e4\uc218\uc778 \uba85\uc758\uc758 \ub4f1\uae30 \ub9d0\uc18c\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc81c2\ub9e4\uc218\uc778\uc5d0\uac8c \uc9c1\uc811 \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\uace0 \ub4f1\uae30\ub9d0\uc18c\ub294 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\uad6d\uac00\uc5d0 \ubd80\ub3d9\uc0b0\uc758 \uadc0\uc18d\uc744 \uccad\uad6c\ud574\uc57c \ud55c\ub2e4"],t.s)
B.ai9=s(["\ub9e4\ub3c4\uc778\uc758 \uc81c2\ub9e4\uc218\uc778\uc5d0 \ub300\ud55c \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30 \ub9d0\uc18c\uccad\uad6c\uad8c\uc744 \ub300\uc704\ud589\uc0ac"],t.s)
B.a5n=s(["\ucc44\uad8c\uc790\ub300\uc704\uc640 \uc774\uc911\ub9e4\ub9e4"],t.s)
B.bQe=new A.a("gen_cl_antisocial_15","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uc774\uc911\ub9e4\ub9e4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uc81c1\ub9e4\uc218\uc778\uc774 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uc633\uc740 \uac83\uc740?",B.aMM,1,"\uc774\uc911\ub9e4\ub9e4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uc81c1\ub9e4\uc218\uc778\uc740 \ub9e4\ub3c4\uc778\uc758 \uc81c2\ub9e4\uc218\uc778\uc5d0 \ub300\ud55c \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30 \ub9d0\uc18c\uccad\uad6c\uad8c\uc744 \ub300\uc704\ud589\uc0ac(\ucc44\uad8c\uc790\ub300\uc704\uad8c)\ud558\uc5ec \uc81c2\ub9e4\uc218\uc778 \uba85\uc758\uc758 \ub4f1\uae30\ub97c \ub9d0\uc18c\uc2dc\ud0a4\uace0, \uc774\ud6c4 \uc790\uc2e0\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.ai9,B.a5n,null)
B.aFG=s(["\uae09\ubd80\uc790\ub294 \uc5b8\uc81c\ub098 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\ubbfc\ubc95 \uc81c746\uc870(\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec)\uc5d0 \ub530\ub77c \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\uc218\ub839\uc790\uac00 \ubc18\ud658\uc744 \uac70\ubd80\ud558\uba74 \uad6d\uace0\uc5d0 \uadc0\uc18d\ub41c\ub2e4","\uae09\ubd80\uc790\ub294 \uacc4\uc57d\uc744 \ucde8\uc18c\ud558\uace0 \ubc18\ud658\uc744 \uccad\uad6c\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.acA=s(["\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubbfc\ubc95 \uc81c746\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \uae09\ubd80\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.ayr=s(["\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec \uc81c746\uc870"],t.s)
B.brO=new A.a("gen_cl_antisocial_16","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacc4\uc57d\uc5d0 \ub530\ub77c \uc774\ubbf8 \uae09\ubd80\uac00 \uc774\ud589\ub41c \uacbd\uc6b0\uc758 \ubc95\ub960\uad00\uacc4\ub294?",B.aFG,1,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacc4\uc57d\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uae09\ubd80\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0, \uc774\ub294 \ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubbfc\ubc95 \uc81c746\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \uae09\ubd80\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ubc18\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4. \uc774\ub294 \ubb34\ud6a8 \uc8fc\uc7a5\uc758 \uc2e4\uc775\uc744 \ud06c\uac8c \uc81c\ud55c\ud558\ub294 \ud2b9\uc9d5\uc774\ub2e4.",B.acA,B.ayr,null)
B.aEG=s(["\uae09\ubd80\uc790\uc5d0\uac8c\ub9cc \ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc788\ub294 \uacbd\uc6b0","\uc218\uc775\uc790\uc5d0\uac8c\ub9cc \ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc788\ub294 \uacbd\uc6b0","\uc30d\ubc29 \ubaa8\ub450\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc788\ub294 \uacbd\uc6b0","\ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc788\uc73c\uba74 \uc608\uc678 \uc5c6\uc774 \ubc18\ud658\uccad\uad6c\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.aU1=s(["\ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc218\uc775\uc790\uc5d0\uac8c\ub9cc \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uae09\ubd80\uc790\uc758 \ubc18\ud658\uccad\uad6c\ub97c \ud5c8\uc6a9"],t.s)
B.bdw=s(["\uc81c746\uc870 \ub2e8\uc11c"],t.s)
B.bCp=new A.a("gen_cl_antisocial_17","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubd88\ubc95\uc6d0\uc778\uae09\uc5ec\uc5d0\uc11c \uc608\uc678\uc801\uc73c\ub85c \ubc18\ud658\uccad\uad6c\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\ub294?",B.aEG,1,"\ubbfc\ubc95 \uc81c746\uc870 \ub2e8\uc11c\ub294 \ubd88\ubc95\uc758 \uc6d0\uc778\uc774 \uc218\uc775\uc790\uc5d0\uac8c\ub9cc \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uae09\ubd80\uc790\uc758 \ubc18\ud658\uccad\uad6c\ub97c \ud5c8\uc6a9\ud55c\ub2e4. \ubc18\uba74 \uae09\ubd80\uc790\uc5d0\uac8c\ub9cc \ubd88\ubc95\uc6d0\uc778\uc774 \uc788\uac70\ub098 \uc30d\ubc29\uc5d0\uac8c \ub3d9\ub4f1\ud558\uac8c \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubcf8\ubb38\uc774 \uc801\uc6a9\ub418\uc5b4 \ubc18\ud658\uccad\uad6c\uac00 \ubc30\uc81c\ub41c\ub2e4.",B.aU1,B.bdw,null)
B.aWk=s(["\uc81c104\uc870\ub294 \uc81c103\uc870\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ub3c5\ub9bd\ub41c \ubb34\ud6a8\uc0ac\uc720\uc774\ub2e4","\uc81c104\uc870\ub294 \uc81c103\uc870\uac00 \uc815\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704 \uc911 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud55c \ud3ed\ub9ac\ud589\uc704\ub97c \ubcc4\ub3c4\ub85c \uaddc\uc815\ud55c \ud2b9\ubcc4\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub41c\ub2e4","\uc81c104\uc870 \uc704\ubc18\uc740 \ucde8\uc18c\uc0ac\uc720\uc774\uace0 \uc81c103\uc870 \uc704\ubc18\ub9cc \ubb34\ud6a8\uc0ac\uc720\uc774\ub2e4","\uc81c104\uc870\ub294 \ud615\uc0ac\ucc98\ubc8c\ub9cc \uaddc\uc815\ud558\uace0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4"],t.s)
B.aMt=s(["\uc81c103\uc870\uac00 \uaddc\uc728\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \uc911","\ud3ed\ub9ac\ud589\uc704\ub97c \ubcc4\ub3c4\ub85c \uc720\ud615\ud654\ud55c \ud2b9\ubcc4\uaddc\uc815"],t.s)
B.tu=s(["\uc81c103\uc870\uc640 \uc81c104\uc870\uc758 \uad00\uacc4"],t.s)
B.bPv=new A.a("gen_cl_antisocial_18","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\uc640 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\uc758 \uad00\uacc4\ub85c \uc633\uc740 \uac83\uc740?",B.aWk,1,"\ud1b5\uc124\xb7\ud310\ub840\ub294 \uc81c104\uc870(\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704)\ub97c \uc81c103\uc870\uac00 \uaddc\uc728\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \uc911 \ub2f9\uc0ac\uc790\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud558\uc5ec \ud604\uc800\ud558\uac8c \uade0\ud615\uc744 \uc783\uc740 \ub300\uac00\uad00\uacc4\ub97c \uc131\ub9bd\uc2dc\ud0a4\ub294 \ud3ed\ub9ac\ud589\uc704\ub97c \ubcc4\ub3c4\ub85c \uc720\ud615\ud654\ud55c \ud2b9\ubcc4\uaddc\uc815\uc73c\ub85c \uc774\ud574\ud55c\ub2e4. \ub450 \uc870\ubb38 \ubaa8\ub450 \uc704\ubc18 \uc2dc \ubb34\ud6a8\ub77c\ub294 \ud6a8\uacfc\ub294 \ub3d9\uc77c\ud558\ub2e4.",B.aMt,B.tu,null)
B.aOe=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc774 \uc874\uc7ac\ud560 \uac83","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc874\uc7ac\ud560 \uac83","\uc0c1\ub300\ubc29\uc774 \uadf8\ub7ec\ud55c \uc0ac\uc815\uc744 \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758\uac00 \uc788\uc744 \uac83","\ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uccb4\uacb0\ub41c \uacc4\uc57d\uc77c \uac83"],t.s)
B.bat=s(["\uacc4\uc57d\uc758 \ud615\uc2dd\uc774 \uc11c\uba74\uc778\uc9c0 \uad6c\ub450\uc778\uc9c0\ub294 \uc694\uac74\uacfc \ubb34\uad00"],t.s)
B.a1p=s(["\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704 \uc694\uac74"],t.s)
B.bK5=new A.a("gen_cl_antisocial_19","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aOe,3,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\ub824\uba74 \u2460 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \u2461 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \u2462 \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\ud589\uc704\uc5d0 \ub300\ud55c \uc545\uc758(\uc774\uc6a9\uc758\uc0ac)\uac00 \ud544\uc694\ud558\ub2e4. \uacc4\uc57d\uc758 \ud615\uc2dd\uc774 \uc11c\uba74\uc778\uc9c0 \uad6c\ub450\uc778\uc9c0\ub294 \uc694\uac74\uacfc \ubb34\uad00\ud558\ub2e4.",B.bat,B.a1p,null)
B.aRG=s(["\ubc95\uc6d0\uc740 \uc9c1\uad8c\uc73c\ub85c \uc704\uc57d\ubc8c \uae08\uc561\uc744 \uc801\uc815\ud55c \uc218\uc900\uc73c\ub85c \uac10\uc561\ud560 \uc218 \uc788\ub2e4","\uc704\uc57d\ubc8c\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \ub2ec\ub9ac \uac10\uc561\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uac10\uc561\ud560 \uc218 \uc5c6\ub2e4","\ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \ubd80\ubd84\uc5d0 \ud55c\ud558\uc5ec \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \uadf8 \ubd80\ubd84\uc744 \ubb34\ud6a8\ub85c \ud560 \uc218 \uc788\ub2e4","\uc704\uc57d\ubc8c \uc57d\uc815\uc740 \ud56d\uc0c1 \uc804\ubd80 \ubb34\ud6a8\ub85c \ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aHc=s(["\uadf8 \uc77c\ubd80(\uacfc\ub2e4\ud55c \ubd80\ubd84)\uc5d0 \ud55c\ud558\uc5ec \uacf5\uc11c\uc591\uc18d\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub77c\uace0 \ubcfc \uc218 \uc788\ub2e4"],t.s)
B.bdb=s(["\uc704\uc57d\ubc8c \uc77c\ubd80\ubb34\ud6a8"],t.s)
B.bq8=new A.a("gen_cl_antisocial_20","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uacc4\uc57d\uc758 \uc704\uc57d\ubc8c \uc57d\uc815 \uae08\uc561\uc774 \ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud55c \uacbd\uc6b0, \ubc95\uc6d0\uc774 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub294?",B.aRG,2,"\uc704\uc57d\ubc8c\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815(\uc81c398\uc870)\uacfc \ub2ec\ub9ac \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uac10\uc561\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uadf8 \uae08\uc561\uc774 \ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud558\uc5ec \uacc4\uc57d\uc758 \uccb4\uacb0 \uacbd\uc704 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \uc0ac\ud68c\ud1b5\ub150\uc0c1 \uc6a9\uc778\ub420 \uc218 \uc5c6\ub294 \uc815\ub3c4\ub77c\uba74, \uadf8 \uc77c\ubd80(\uacfc\ub2e4\ud55c \ubd80\ubd84)\uc5d0 \ud55c\ud558\uc5ec \uacf5\uc11c\uc591\uc18d\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub77c\uace0 \ubcfc \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.aHc,B.bdb,null)
B.b3k=s(["\uc57d\uc815 \uc804\ubd80\uac00 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc801\uc815\ud55c \ubcf4\uc218\uc561\uc744 \ucd08\uacfc\ud558\ub294 \ubd80\ubd84\uc5d0 \ud55c\ud558\uc5ec \ubb34\ud6a8\ub85c \ubcfc \uc218 \uc788\ub2e4","\uae08\uc561\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ubcc0\ud638\uc0ac\ubc95 \uc704\ubc18\uc73c\ub85c \ud615\uc0ac\ucc98\ubc8c\ub420 \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc740 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.a4g=s(["\uc801\uc815\ud55c \ubc94\uc704\ub97c \ucd08\uacfc\ud558\ub294 \ubd80\ubd84\uc5d0 \ud55c\ud558\uc5ec \uacf5\uc11c\uc591\uc18d \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.b4q=s(["\ubbfc\uc0ac \uc131\uacf5\ubcf4\uc218 \uc77c\ubd80\ubb34\ud6a8"],t.s)
B.bDB=new A.a("gen_cl_antisocial_21","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubcc0\ud638\uc0ac\uc758 \uc131\uacf5\ubcf4\uc218 \uc57d\uc815 \uae08\uc561\uc774 \ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud55c \ubbfc\uc0ac\uc0ac\uac74\uc758 \uacbd\uc6b0 \uadf8 \ud6a8\ub825\uc740?",B.b3k,1,"\ubbfc\uc0ac\uc0ac\uac74\uc758 \uacbd\uc6b0 \ubcc0\ud638\uc0ac \uc131\uacf5\ubcf4\uc218 \uc57d\uc815 \uc790\uccb4\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub098, \uc0ac\uac74 \uc218\uc784 \uacbd\uc704\xb7\ub09c\uc774\ub3c4\xb7\ub178\ub825 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \uadf8 \ubcf4\uc218\uc561\uc774 \ubd80\ub2f9\ud558\uac8c \uacfc\ub2e4\ud558\uc5ec \uc2e0\uc758\uc131\uc2e4 \uc6d0\uce59\uc5d0 \ubc18\ud55c\ub2e4\uace0 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc801\uc815\ud55c \ubc94\uc704\ub97c \ucd08\uacfc\ud558\ub294 \ubd80\ubd84\uc5d0 \ud55c\ud558\uc5ec \uacf5\uc11c\uc591\uc18d \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.",B.a4g,B.b4q,null)
B.aQr=s(["\uc870\uac74\ubd80\ub85c \uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8\uc774\ub2e4","\uc774\ud589 \ud6c4\uc5d0\ub9cc \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.b6s=s(["\uadf8 \ub0b4\uc6a9 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c \ucc98\uc74c\ubd80\ud130 \uc808\ub300\uc801\uc73c\ub85c \ubb34\ud6a8"],t.s)
