B.bMp=new A.a("gen_cl_antisocial_23","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\uac74\ubb3c\uc744 \ub3c4\ubc15\uc7a5\uc73c\ub85c \uc0ac\uc6a9\ud560 \ubaa9\uc801\uc784\uc744 \uc54c\uba74\uc11c\ub3c4 \uadf8 \uc0ac\uc815\uc744 \uc778\uc2dd\ud55c \uc784\ub300\uc778\uc774 \uccb4\uacb0\ud55c \uc784\ub300\ucc28\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.ady,1,"\uc784\ub300\uc778\uc774 \uac74\ubb3c\uc774 \ub3c4\ubc15\uc7a5 \ub4f1 \ubd88\ubc95\ud55c \uc6a9\ub3c4\ub85c \uc0ac\uc6a9\ub420 \uac83\uc784\uc744 \uc54c\uba74\uc11c\ub3c4 \uc774\ub97c \uc784\ub300\ud55c \uacbd\uc6b0, \uadf8 \uc784\ub300\ucc28\uacc4\uc57d\uc740 \ub3d9\uae30\uc758 \ubd88\ubc95\uc744 \uc784\ub300\uc778\uc774 \uc778\uc2dd\ud55c \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.",B.Si,B.aFE,null)
B.a0x=s(["\ucd94\uc778\ud558\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4","\ucd94\uc778 \uc2dc\uc810\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc77c\ubc18 \ubc95\ub9ac(\uc81c139\uc870)\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc544 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4","\ucd94\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\uace0 \uadf8 \ubc16\uc5d0\ub294 \ud6a8\uacfc\uac00 \uc5c6\ub2e4"],t.s)
