B.bzF=new A.a("gen_cl_agency_14","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc784\uc758\ub300\ub9ac\uc5d0 \ud2b9\uc720\ud55c \ub300\ub9ac\uad8c \uc18c\uba78\uc0ac\uc720\ub85c \uc633\uc740 \uac83\uc740?",B.b7r,1,"\ubbfc\ubc95 \uc81c127\uc870\uc758 \uacf5\ud1b5 \uc18c\uba78\uc0ac\uc720 \uc678\uc5d0, \uc784\uc758\ub300\ub9ac\uad8c\uc740 \uc81c128\uc870\uc5d0 \ub530\ub77c \uadf8 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4(\uc704\uc784\uacc4\uc57d \ub4f1)\uc758 \uc885\ub8cc\ub85c \uc18c\uba78\ud558\uba70, \uadf8 \ubc95\ub960\uad00\uacc4\uac00 \uc885\ub8cc\ub418\uae30 \uc804\uc774\ub77c\ub3c4 \ubcf8\uc778\uc774 \uc218\uad8c\ud589\uc704\ub97c \ucca0\ud68c\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc18c\uba78\ud55c\ub2e4.",B.aDe,B.bgf,null)
B.TR=s(["\ub300\ub9ac\uad8c \uc5c6\uc774 \ud0c0\uc778\uc758 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uacc4\uc57d\uc740 \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub300\ub9ac\uad8c \uc5c6\uc774 \ud55c \uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uba70 \ucd94\uc778\ud574\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4","\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc774 \uc120\uc758\uc774\uba74 \uace7\ubc14\ub85c \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ub300\ub9ac\uc778 \uc790\uc2e0\uc5d0\uac8c \ud56d\uc0c1 \ud6a8\ub825\uc774 \uadc0\uc18d\ub41c\ub2e4"],t.s)
