B.bRZ=new A.a("gen_cl_agency_15","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubb34\uad8c\ub300\ub9ac(\ud611\uc758\uc758 \ubb34\uad8c\ub300\ub9ac)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.TR,0,"\ubbfc\ubc95 \uc81c130\uc870\uc5d0 \ub530\ub77c \ub300\ub9ac\uad8c \uc5c6\ub294 \uc790\uac00 \ud0c0\uc778\uc758 \ub300\ub9ac\uc778\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \ubcf8\uc778\uc774 \uc774\ub97c \ucd94\uc778\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4. \uc989 \ubb34\uad8c\ub300\ub9ac\ub294 \ud655\uc815\uc801 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c \ubcf8\uc778\uc758 \ucd94\uc778 \uc5ec\ubd80\uc5d0 \ub530\ub77c \ud6a8\ub825\uc774 \uc88c\uc6b0\ub418\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc774\ub2e4.",B.asw,B.aaJ,null)
B.a6b=s(["\ucd94\uc778\ud55c \ub54c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec\ub9cc \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ub2e4\ub978 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc5c6\uc73c\uba74 \uacc4\uc57d \uc2dc\uc5d0 \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ucd94\uc778\ud558\uc5ec\ub3c4 \uc81c3\uc790\uc758 \uad8c\ub9ac\ub97c \ud574\ud558\uc9c0 \ubabb\ud560 \ubfd0 \uc18c\uae09\ud6a8\ub294 \uc804\ud600 \uc5c6\ub2e4","\ucd94\uc778\uc740 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \ud560 \uc218 \uc788\uace0 \ubb34\uad8c\ub300\ub9ac\uc778\uc5d0\uac8c\ub294 \ud560 \uc218 \uc5c6\ub2e4"],t.s)
