B.bvs=new A.a("gen_cl_agency_18","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubb34\uad8c\ub300\ub9ac \uc0c1\ub300\ubc29\uc758 \ucca0\ud68c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Uo,1,"\ubbfc\ubc95 \uc81c134\uc870\uc5d0 \ub530\ub77c \ub300\ub9ac\uad8c \uc5c6\ub294 \uc790\uac00 \ud55c \uacc4\uc57d\uc740, \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uc744 \ub54c\uae4c\uc9c0 \uacc4\uc57d \ub2f9\uc2dc\uc5d0 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc5d0 \ud55c\ud558\uc5ec \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4. \uc545\uc758\uc758 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub294 \ucca0\ud68c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aJm,B.a63,null)
B.alh=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub358 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c \uc218 \uc788\uc5c8\ub358 \uacbd\uc6b0(\uacfc\uc2e4 \uc788\ub294 \uacbd\uc6b0)","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \ud589\uc704\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0"],t.s)
B.b0i=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c, \ub610\ub294 \ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \ub54c\uc5d0\ub294 \uc774 \ucc45\uc784\uc774 \ubc30\uc81c\ub41c\ub2e4"],t.s)
