B.bNk=new A.a("gen_cl_intent_19","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud55c \uacbd\uc6b0, \ucc29\uc624\ucde8\uc18c\uac00 \ud5c8\uc6a9\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.ahJ,1,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\ub77c\ub3c4, \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \ucc29\uc624\ub97c \uc54c\uba74\uc11c \uc774\ub97c \uc774\uc6a9\ud55c \ub54c\uc5d0\ub294 \uc2e0\uc758\uce59\uc5d0 \ubc18\ud558\ubbc0\ub85c \ud45c\uc758\uc790\uc758 \ucc29\uc624\ucde8\uc18c\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.b0X,B.aXq,null)
B.aNN=s(["\uae30\ub9dd\ud589\uc704\uc758 \uc874\uc7ac","\uae30\ub9dd\ud589\uc704\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc84c\uc744 \uac83"],t.s)
B.ans=s(["\uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.aH9=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc \uc694\uac74"],t.s)
B.bG1=new A.a("gen_cl_intent_20","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\uc81c110\uc870 \uc81c1\ud56d)\uc758 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2cc \uac83\uc740?",B.aNN,3,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc131\ub9bd\ud558\ub824\uba74 \u2460 \uae30\ub9dd\ud589\uc704, \u2461 \uadf8\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd, \u2462 \uadf8 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc, \u2463 \uae30\ub9dd\ud589\uc704\uc758 \uc704\ubc95\uc131\uc774 \uc694\uad6c\ub41c\ub2e4. \uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.ans,B.aH9,null)
B.asE=s(["\uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uc758 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ud55c \uacbd\uc6b0","\ub2e8\uc21c\ud788 \uac81\uc744 \uba39\uc740 \uc815\ub3c4\uc5d0 \ubd88\uacfc\ud55c \uacbd\uc6b0","\uac15\ubc15\uc744 \ud589\ud55c \uc790\uac00 \uc81c3\uc790\uc778 \uacbd\uc6b0","\uac15\ubc15 \ud6c4 \uc0c1\ub2f9 \uae30\uac04\uc774 \uc9c0\ub09c \uacbd\uc6b0"],t.s)
B.biV=s(["\uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uac00 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ub2f9\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ubb34\ud6a8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4"],t.s)
B.bah=s(["\uadf9\uc2ec\ud55c \uac15\ubc15\uacfc \ubb34\ud6a8"],t.s)
B.bDU=new A.a("gen_cl_intent_21","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \ubb34\ud6a8(\ucde8\uc18c\uac00 \uc544\ub2cc \uc808\ub300\uc801 \ubb34\ud6a8)\ub85c \ub418\ub294 \uacbd\uc6b0\ub294?",B.asE,0,"\ud1b5\uc0c1\uc758 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc81c110\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ub370 \uadf8\uce58\uc9c0\ub9cc, \uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uac00 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ub2f9\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ubb34\ud6a8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.biV,B.bah,null)
B.a9h=s(["\uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0 \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.auq=s(["\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.Z9=s(["\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.bN3=new A.a("gen_cl_intent_22","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uc694\uac74\uc740?",B.a9h,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.",B.auq,B.Z9,null)
