B.bxq=new A.a("gen_cl_unfair_1","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c104\uc870\uac00 \uc815\ud558\ub294 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.anq,1,"\ubbfc\ubc95 \uc81c104\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e8\uc21c\ud55c \ubd88\uade0\ud615\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc774\ub77c\ub294 \uc8fc\uad00\uc801 \uc694\uac74\uacfc \ud604\uc800\ud55c \ubd88\uacf5\uc815\uc774\ub77c\ub294 \uac1d\uad00\uc801 \uc694\uac74\uc774 \ud568\uaed8 \uc694\uad6c\ub41c\ub2e4.",B.apZ,B.and,null)
B.asf=s(["\uacbd\uc81c\uc801 \uc5b4\ub824\uc6c0\ub9cc\uc744 \uc758\ubbf8\ud558\uace0 \uc815\uc2e0\uc801 \uc5b4\ub824\uc6c0\uc740 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc81c\uc801 \uad81\ubc15\ubfd0 \uc544\ub2c8\ub77c \uc815\uc2e0\uc801\xb7\uc2ec\ub9ac\uc801 \uad81\ubc15\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc774\ub2e4","\ubc18\ub4dc\uc2dc \ud30c\uc0b0 \uc0c1\ud0dc\uc5d0 \uc774\ub978 \uacbd\uc6b0\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ubbf8\uc131\ub144\uc790\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub418\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
