B.aKJ=s(["\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac"],t.s)
B.bzp=new A.a("gen_cl_unfair_7","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud55c "\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758"\ub780 \ubb34\uc5c7\uc744 \uc758\ubbf8\ud558\ub294\uac00?',B.azx,1,"\ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uc774\ub97c \uc54c\uba74\uc11c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758)\uae4c\uc9c0 \uc788\uc5b4\uc57c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.am3,B.aKJ,null)
B.aiZ=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \ud604\uc800\ud55c \ubd88\uade0\ud615, \ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29(\ud3ed\ub9ac\ud589\uc704\uc790\ub85c \uc9c0\ubaa9\ub41c \uc790)\uc774 \uc790\uc2e0\uc758 \uc120\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d\uc11c \uc791\uc131\uc790\uac00 \uc99d\uba85\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.ahM=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815, \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \uadf8\ub9ac\uace0 \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\ud589\uc704\uc5d0 \ub300\ud55c \uc545\uc758(\uc774\uc6a9\uc758\uc0ac)\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
