B.bPd=new A.a("gen_cl_unfair_13","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacc4\uc57d\uc744 \ub2f9\uc0ac\uc790\uac00 \ub098\uc911\uc5d0 \ucd94\uc778\ud55c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.aA3,1,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub294 \uc81c103\uc870\uc758 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0ac\ud68c\uc9c8\uc11c \uc720\uc9c0\ub97c \uc704\ud55c \uac15\ud589\ubc95\uaddc\uc801 \uc131\uaca9\uc744 \uac00\uc9c0\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud310\ub840\xb7\ud1b5\uc124\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.ba8,B.rN,null)
B.a4k=s(["\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4","\ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c\uc758 \uc694\uac74\uc744 \uac16\ucd94\uace0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \uadf8\uac83\uc744 \uc758\uc695\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\ub294 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4","\uc804\ud658\uc774 \uc778\uc815\ub418\uba74 \uc6d0\ub798\uc758 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub3c4 \uc720\ud6a8\ub85c \ubd80\ud65c\ud55c\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ub4f1\uae30\uac00 \ub9c8\uccd0\uc9c4 \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.afX=s(["\ub2e4\ub978 \ubc95\ub960\ud589\uc704(\uc608: \ub300\uae08\uac10\uc561 \ub4f1)\ub85c\uc11c\uc758 \uc694\uac74\uc744 \uac16\ucd94\uace0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \uc758\uc695\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294","\uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.bG5=new A.a("gen_cl_unfair_14","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacc4\uc57d\uc5d0 \ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870) \ubc95\ub9ac\uac00 \uc801\uc6a9\ub420 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.a4k,1,"\ud310\ub840\ub294 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \ub9e4\ub9e4\uacc4\uc57d\uc774\ub77c\ub3c4, \ub2e4\ub978 \ubc95\ub960\ud589\uc704(\uc608: \ub300\uae08\uac10\uc561 \ub4f1)\ub85c\uc11c\uc758 \uc694\uac74\uc744 \uac16\ucd94\uace0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \uc758\uc695\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294, \uc81c138\uc870\uc758 \ubb34\ud6a8\ud589\uc704 \uc804\ud658 \ubc95\ub9ac\uc5d0 \ub530\ub77c \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.afX,B.tG,null)
B.aY1=s(["\ub450 \uc870\ubb38\uc740 \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4","\uc81c104\uc870\ub294 \uc81c103\uc870\uac00 \uaddc\uc728\ud558\ub294 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704 \uc911 \ud3ed\ub9ac\ud589\uc704\ub97c \uc720\ud615\ud654\ud55c \ud2b9\ubcc4\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub41c\ub2e4","\uc81c103\uc870\uac00 \uc81c104\uc870\uc758 \ud2b9\ubcc4\uaddc\uc815\uc774\ub2e4","\uc81c104\uc870\uac00 \uc6b0\uc120 \uc801\uc6a9\ub418\uace0 \uc81c103\uc870\ub294 \ubcf4\ucda9\uc801\uc73c\ub85c\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
