B.bMb=new A.a("gen_cl_cond_5","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\uc778 \ub3d9\uc548 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \uce68\ud574\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc(\uc81c148\uc870)\ub85c \uc633\uc740 \uac83\uc740?",B.azs,1,"\ubbfc\ubc95 \uc81c148\uc870\uc5d0 \ub530\ub77c \uc870\uac74 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\ub294 \uc870\uac74\uc758 \uc131\ubd80\uac00 \ubbf8\uc815\ud55c \ub3d9\uc548\uc5d0 \uc870\uac74\uc774 \uc131\ucde8\ub41c \uacbd\uc6b0\uc5d0 \uc0c1\ub300\ubc29\uc774 \uc5bb\uc744 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4. \uc870\uac74\ubd80 \uad8c\ub9ac \uc5ed\uc2dc \uc77c\uc885\uc758 \uae30\ub300\uad8c\uc73c\ub85c\uc11c \ubcf4\ud638\ub41c\ub2e4.",B.bcg,B.a4b,null)
B.aJo=s(["\uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud55c \ucc98\ubd84","\uc0c1\uc18d","\ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud558\ub294 \ud589\uc704","\uc870\uac74\ubd80 \uad8c\ub9ac \uc790\uccb4\ub97c \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uc77c\ubc29\uc801 \ud3ec\uae30"],t.s)
B.b37=s(["\uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\ud55c \uad8c\ub9ac\uc758\ubb34\ub294 \uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ucc98\ubd84, \uc0c1\uc18d, \ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud560 \uc218 \uc788\ub2e4"],t.s)
