B.be4=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc758 \ud6a8\ub825"],t.s)
B.bsy=new A.a("gen_cl_void_13","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ajV,0,"\uac15\ud589\ubc95\uaddc(\uac15\ud589\uaddc\uc815)\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc5c6\ub294 \uaddc\uc815\uc73c\ub85c, \uc774\ub97c \uc704\ubc18\ud55c \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4. \uc774\uc640 \ub2ec\ub9ac \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc788\ub294 \uaddc\uc815\uc740 \uc784\uc758\ubc95\uaddc(\uc784\uc758\uaddc\uc815)\ub77c \ud558\uba70, \uc774\ub97c \uc704\ubc18\ud574\ub3c4 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4.",B.b0s,B.be4,null)
B.aRb=s(["\ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\ub294 \uc0c1\ud0dc\uc774\ub2e4","\ud5c8\uac00 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub3c4 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4","\uc720\ub3d9\uc801 \ubb34\ud6a8\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.avh=s(["\ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\ub294 \uc0c1\ud0dc"],t.s)
B.a7H=s(["\uc720\ub3d9\uc801 \ubb34\ud6a8"],t.s)
B.bvX=new A.a("gen_cl_void_14","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc720\ub3d9\uc801 \ubb34\ud6a8(\uc608: \ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4 \ud5c8\uac00 \uc804 \ub9e4\ub9e4\uacc4\uc57d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aRb,0,"\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4\uc5d0\uc11c \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0 \uccb4\uacb0\ub41c \ub9e4\ub9e4\uacc4\uc57d\uc740 \ud310\ub840\uc0c1 \uc720\ub3d9\uc801 \ubb34\ud6a8\ub85c \ucde8\uae09\ub41c\ub2e4. \uad00\uccad\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uacc4\uc57d\uccb4\uacb0 \uc2dc\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ud55c \uacc4\uc57d\uc774 \ub418\uace0, \ubd88\ud5c8\uac00\uac00 \ud655\uc815\ub418\uac70\ub098 \ub2f9\uc0ac\uc790\uac00 \ud5c8\uac00\uc2e0\uccad\uc744 \ud558\uc9c0 \uc54a\uae30\ub85c \ud611\uc758\ud558\ub294 \ub4f1\uc758 \uc0ac\uc815\uc774 \uc788\uc73c\uba74 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4.",B.avh,B.a7H,null)
B.a34=s(["\ubb34\ud6a8\ub294 \ud2b9\uc815 \uc8fc\uc7a5\uad8c\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\uace0, \ucde8\uc18c\ub294 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\uace0, \ucde8\uc18c\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0 \uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\uc73c\ub098, \ucde8\uc18c\uad8c\uc5d0\ub294 \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\uc774 \uc788\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucd94\uc778\ud574\ub3c4 \ud6a8\ub825\uc774 \uc0dd\uae30\uc9c0 \uc54a\uc73c\ub098, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294 \ucd94\uc778\ud558\uba74 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.awU=s(["\ucde8\uc18c\ub294 \uc81c140\uc870\uac00 \uc815\ud55c \ud2b9\uc815 \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aSN=s(["\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uc885\ud569 \ube44\uad50"],t.s)
B.bHg=new A.a("gen_cl_void_15","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a34,0,"\uc8fc\uc7a5\uad8c\uc790\uc5d0 \uad00\ud558\uc5ec\ub294 \uc624\ud788\ub824 \ubc18\ub300\ub85c, \ucde8\uc18c\ub294 \uc81c140\uc870\uac00 \uc815\ud55c \ud2b9\uc815 \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\uace0, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4. \ub098\uba38\uc9c0 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uc810, \uae30\uac04 \uc81c\ud55c, \ucd94\uc778\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc740 \ubaa8\ub450 \uc633\ub2e4.",B.awU,B.aSN,null)
B.beK=s(["\ud53c\ud574\uc790 \uce21\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \uc911 \ud558\ub098","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615","\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac(\uc545\uc758)","\ud53c\ud574\uc790\uc5d0\uac8c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc788\uc744 \uac83"],t.s)
