B.bx9=new A.a("gen_cl_void_28","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aIX,1,'\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub77c\ub3c4 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uadf8 \uc720\ud6a8\xb7\ubb34\ud6a8 \uc5ec\ubd80\uc5d0 \uad00\ud55c \ub2e4\ud23c\uc774 \uc788\uac70\ub098, \uc0c1\ub300\ubc29\uc774 \ubb34\ud6a8\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c "\uc774\ud589 \uc804\uc774\ub77c\uba74 \uc544\ubb34 \ubb38\uc81c\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\uc81c\ub85c\ub294 \ud655\uc778\uc758 \uc18c \ub4f1\uc744 \ud1b5\ud574 \ubb34\ud6a8\uc784\uc744 \uba85\ud655\ud788 \ud560 \ud544\uc694\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.',B.a8G,B.apQ,null)
