B.bwe=new A.a("gen_cl_void_30","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ub2e4\uc74c \uc911 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74? \u2460 \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ub2e4\ud234 \ud544\uc694 \uc5c6\uc774 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4 \u2461 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4 \u2462 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4 \u2463 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4",B.b_l,0,'\u2460\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uace0, \u2461\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\uc73c\uba70, \u2463\uadf8\ub7ec\ud55c \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \u2462\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0, \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uae30\uc874 \ud589\uc704\ub97c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704"\ub85c\uc11c \uadf8\ub54c\ubd80\ud130 \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.aBs,B.WI,null)
B.a_6=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub97c \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.bcP=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4"],t.s)
B.afb=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c1\ud56d)"],t.s)
B.byr=new A.a("gen_cl_minor_1","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc6d0\uce59\uc801 \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_6,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d\uc740 \ubbf8\uc131\ub144\uc790\uac00 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \ub370\uc5d0\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub3d9\uc758\ub97c \uc5bb\uc73c\uba74 \ubbf8\uc131\ub144\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4.",B.bcP,B.afb,null)
B.azc=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8\uc774\ub2e4","\ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ud6a8\ub825\uc774 \uc815\uc9c0\ub41c\ub2e4"],t.s)
B.a52=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bhz=s(["\ub3d9\uc758 \uc5c6\ub294 \ubbf8\uc131\ub144\uc790 \ud589\uc704\uc758 \ud6a8\ub825(\uc81c5\uc870 \uc81c2\ud56d)"],t.s)
B.bzi=new A.a("gen_cl_minor_2","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc740?",B.azc,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c, \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.a52,B.bhz,null)
B.a4z=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704","\ubd80\ub3d9\uc0b0\uc744 \ub9e4\uc218\ud558\ub294 \ud589\uc704","\uae08\uc804\uc744 \ub300\ucc28(\ube4c\ub9ac\ub294)\ud558\ub294 \ud589\uc704","\ud0c0\uc778\uc758 \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \ud589\uc704"],t.s)
B.b3h=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704"],t.s)
B.Y4=s(["\ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c)"],t.s)
B.bqE=new A.a("gen_cl_minor_3","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294?",B.a4z,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub294 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \ud589\uc704\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubc18\uba74 \ubd80\ub3d9\uc0b0 \ub9e4\uc218, \uae08\uc804 \ub300\ucc28, \ubcf4\uc99d\ud589\uc704\ub294 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.b3h,B.Y4,null)
B.a3x=s(["\ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc7ac\uc0b0\uc5d0 \uad00\ud558\uc5ec\ub294 \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc744 \ud5c8\ub77d\ubc1b\uc544\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uac1c\ubcc4 \ub3d9\uc758\uac00 \ub9e4\ubc88 \ud544\uc694\ud558\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc774\ub77c\ub3c4 \ucc98\ubd84\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84 \ud5c8\ub77d\uc740 \uc5b8\uc81c\ub098 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b8R=s(["\uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a1L=s(["\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84(\uc81c6\uc870)"],t.s)
B.bNG=new A.a("gen_cl_minor_4","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ucc98\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a3x,0,"\ubbfc\ubc95 \uc81c6\uc870\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubc94\uc704\ub97c \uc815\ud558\uc5ec \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud574\uc11c\ub294 \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \uc6a9\ub3c8\uc73c\ub85c \uc900 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub300\ud45c\uc801\uc774\uba70, \uc774 \uacbd\uc6b0 \ub9e4\ubc88 \uac1c\ubcc4 \ub3d9\uc758\ub97c \ub2e4\uc2dc \ubc1b\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4.",B.b8R,B.a1L,null)
B.Ty=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4","\ud5c8\ub77d\ubc1b\uc740 \uc601\uc5c5\uc774\ub77c\ub3c4 \ub9e4 \uac70\ub798\ub9c8\ub2e4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\uc601\uc5c5\uc758 \ud5c8\ub77d\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ud655\uc815\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aR2=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aV7=s(["\uc601\uc5c5\uc758 \ud5c8\ub77d\uacfc \ud589\uc704\ub2a5\ub825(\uc81c8\uc870)"],t.s)
B.buc=new A.a("gen_cl_minor_5","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\uc758 \uc9c0\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Ty,0,"\ubbfc\ubc95 \uc81c8\uc870 \uc81c1\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc73c\ub85c\ubd80\ud130 \ud2b9\uc815 \uc601\uc5c5\uc744 \ud5c8\ub77d\ubc1b\uc740 \ubbf8\uc131\ub144\uc790\ub294 \uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc774 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \uc601\uc5c5\uc5d0 \ubd80\uc801\ub2f9\ud568\uc774 \ubc1c\uacac\ub418\uba74 \uadf8 \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4.",B.aR2,B.aV7,null)
B.a2I=s(["\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc774 \ub418\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcc4\ub3c4 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
B.b8T=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub300\ub9ac(\uc81c117\uc870)"],t.s)
B.bGQ=new A.a("gen_cl_minor_6","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2I,0,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub300\ub9ac\ud589\uc704\uc758 \ubc95\ub960\ud6a8\uacfc\ub294 \ub300\ub9ac\uc778\uc774 \uc544\ub2c8\ub77c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c, \ubbf8\uc131\ub144\uc790\ub3c4 \uc720\ud6a8\ud558\uac8c \ub300\ub9ac\uc778\uc774 \ub418\uc5b4 \ub300\ub9ac\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4.",B.tH,B.b8T,null)
B.a3_=s(["\ud63c\uc778\uc73c\ub85c \uc131\ub144\uc5d0 \uc774\ub978 \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc131\ub144\uc758\uc81c)","\ud63c\uc778\ud574\ub3c4 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0\ub294 \ubcc0\ud654\uac00 \uc5c6\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc5ec\uc804\ud788 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\uc5d0 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc774\ud63c\ud558\uba74 \ub2e4\uc2dc \ubbf8\uc131\ub144\uc790 \uc9c0\uc704\ub85c \ubcf5\uadc0\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.Vj=s(["\ubbf8\uc131\ub144\uc790\uac00 \ud63c\uc778\uc744 \ud55c \ub54c\uc5d0\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4"],t.s)
