B.bGe=new A.a("gen_cl_prescription_4","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubbfc\ubc95 \uc81c163\uc870\uc758 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \ucc44\uad8c\uc740?",B.VP,3,"\uc5ec\uad00\xb7\uc74c\uc2dd\uc810 \ub4f1\uc758 \uc219\ubc15\ub8cc, \uc74c\uc2dd\ub8cc \ub4f1\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c164\uc870\uc5d0 \uc758\ud574 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4. \uc774\uc790\xb7\ubd80\uc591\ub8cc\xb7\uae09\ub8cc \ub4f1 \uc815\uae30\uae08 \ucc44\uad8c, \uc758\ub8cc\uc778\uc758 \uce58\ub8cc\ube44 \ucc44\uad8c, \ubcc0\ud638\uc0ac \ub4f1 \uc804\ubb38\uc9c1\uc758 \uc9c1\ubb34\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.",B.aEQ,B.a9Q,null)
B.b22=s([u.wv,"\uc758\ubcf5, \uce68\uad6c, \uc7a5\uad6c \uae30\ud0c0 \ub3d9\uc0b0\uc758 \uc0ac\uc6a9\ub8cc\uc758 \ucc44\uad8c","\ub178\uc5ed\uc778, \uc5f0\uc608\uc778\uc758 \uc784\uae08 \ubc0f \uadf8\uc5d0 \uacf5\uae09\ud55c \ubb3c\uac74\uc758 \ub300\uae08\ucc44\uad8c","\ub3c4\uae09\ubc1b\uc740 \uc790, \uae30\uc0ac \uae30\ud0c0 \uacf5\uc0ac\uc758 \uc124\uacc4 \ub610\ub294 \uac10\ub3c5\uc5d0 \uc885\uc0ac\ud558\ub294 \uc790\uc758 \uacf5\uc0ac\uc5d0 \uad00\ud55c \ucc44\uad8c"],t.s)
B.aIN=s(["\ubbfc\ubc95 \uc81c163\uc870 \uc81c3\ud638\uc5d0 \uc758\ud574 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4"],t.s)
