B.bEd=new A.a("gen_cl_prescription_6","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc0c1\uc0ac\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aq9,0,"\uc0c1\ubc95 \uc81c64\uc870\ub294 \uc0c1\ud589\uc704\ub85c \uc778\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc740 \ub2e4\ub978 \ubc95\ub839\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 5\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ubbfc\ubc95 \ub4f1 \ub2e4\ub978 \ubc95\ub839\uc5d0 5\ub144\ubcf4\ub2e4 \ub2e8\uae30\uc758 \uc2dc\ud6a8\uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8 \uaddc\uc815\uc774 \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4.",B.a1P,B.aCA,null)
B.aiC=s(["\uccad\uad6c","\uc555\ub958 \ub610\ub294 \uac00\uc555\ub958, \uac00\ucc98\ubd84","\uc2b9\uc778","\ucc44\ubb34\uc790\uc758 \uc0ac\ub9dd"],t.s)
B.UQ=s(["\uccad\uad6c, \uc555\ub958 \ub610\ub294 \uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778\uc744 \uaddc\uc815\ud55c\ub2e4"],t.s)
