B.bRT=new A.a("gen_cl_security_4","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uc790\uc758 \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aAL,3,"\ubbfc\ubc95 \uc81c324\uc870\uc5d0 \ub530\ub77c \uc720\uce58\uad8c\uc790\ub294 \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c \uc720\uce58\ubb3c\uc744 \uc810\uc720\ud558\uc5ec\uc57c \ud558\uba70, \ucc44\ubb34\uc790\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc720\uce58\ubb3c\uc744 \uc0ac\uc6a9\xb7\ub300\uc5ec\xb7\ub2f4\ubcf4\uc81c\uacf5\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ub2e4\ub9cc \uc720\uce58\ubb3c\uc758 \ubcf4\uc874\uc5d0 \ud544\uc694\ud55c \uc0ac\uc6a9\uc740 \uc608\uc678\ub85c \ud5c8\uc6a9\ub41c\ub2e4. \uc720\uce58\uad8c\uc790\uac00 \uc774 \uc758\ubb34\ub97c \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc720\uce58\uad8c\uc758 \uc18c\uba78\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.aWV,B.avO,null)
B.b9T=s(["\ucc44\ubb34\uc790\uac00 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\ub97c \uc81c\uacf5\ud558\uace0 \uc720\uce58\uad8c\uc758 \uc18c\uba78\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0","\uc720\uce58\uad8c\uc790\uac00 \uc810\uc720\ub97c \uc0c1\uc2e4\ud55c \uacbd\uc6b0","\uc720\uce58\uad8c\uc790\uac00 \uc120\uad00\uc8fc\uc758\uc758\ubb34\ub97c \uc704\ubc18\ud558\uc5ec \ucc44\ubb34\uc790\uac00 \uc18c\uba78\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0","\ud53c\ub2f4\ubcf4\ucc44\uad8c\uc758 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uacbd\uc6b0"],t.s)
B.a7h=s(["\ub2e8\uc21c\ud788 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc758 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \uc720\uce58\uad8c\uc774 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.S_=s(["\uc720\uce58\uad8c \uc18c\uba78\uc0ac\uc720"],t.s)
B.bES=new A.a("gen_cl_security_5","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.b9T,3,"\uc720\uce58\uad8c\uc740 \ucc44\ubb34\uc790\uc758 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\uc81c\uacf5\uc5d0 \uc758\ud55c \uc18c\uba78\uccad\uad6c(\uc81c327\uc870), \uc810\uc720\uc758 \uc0c1\uc2e4(\uc81c328\uc870), \uc120\uad00\uc8fc\uc758\uc758\ubb34 \uc704\ubc18\uc5d0 \ub530\ub978 \uc18c\uba78\uccad\uad6c(\uc81c324\uc870 \uc81c3\ud56d) \ub4f1\uc5d0 \uc758\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc758 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \uc720\uce58\uad8c\uc774 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.a7h,B.S_,null)
B.baf=s(["\uc9c8\uad8c\uc124\uc815\uc790\ub294 \uc9c8\uad8c\uc124\uc815\uacc4\uc57d\uacfc \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub85c \uc9c8\uad8c\uc744 \uc124\uc815\ud55c\ub2e4.","\uc9c8\uad8c\uc790\ub294 \uc124\uc815\uc790\ub85c \ud558\uc5ec\uae08 \uc9c8\ubb3c\uc758 \uc810\uc720\ub97c \ud558\uac8c \ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc9c8\uad8c\uc740 \ucc44\ubb34\uc758 \ubcc0\uc81c\uac00 \uc788\uc744 \ub54c\uae4c\uc9c0 \ubaa9\uc801\ubb3c\uc744 \uc810\uc720\ud558\uc5ec \uac04\uc811\uc801\uc73c\ub85c \ucc44\ubb34\ubcc0\uc81c\ub97c \uac15\uc81c\ud558\ub294 \ud6a8\ub825\uc774 \uc788\ub2e4.","\uc9c8\uad8c\uc790\ub294 \uc720\uce58\uad8c\uc790\uc640 \ub2ec\ub9ac \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.a91=s(["\uc9c8\uad8c\uc790\ub294 \uc720\uce58\uc801 \ud6a8\ub825\uacfc \ud568\uaed8 \uc6b0\uc120\ubcc0\uc81c\uad8c\ub3c4 \uac00\uc9c0\ub294 \uc810\uc5d0\uc11c \uc720\uce58\uad8c\uacfc \uad6c\ubcc4\ub41c\ub2e4."],t.s)
B.aSm=s(["\ub3d9\uc0b0\uc9c8\uad8c","\uc6b0\uc120\ubcc0\uc81c\uad8c"],t.s)
B.bSf=new A.a("gen_cl_security_6","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\ub3d9\uc0b0\uc9c8\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.baf,3,"\ubbfc\ubc95 \uc81c329\uc870 \uc774\ud558\uc758 \ub3d9\uc0b0\uc9c8\uad8c\uc740 \uc9c8\uad8c\uc124\uc815\uacc4\uc57d\uacfc \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub85c \uc131\ub9bd\ud558\uba70, \uc81c332\uc870\uc5d0 \ub530\ub77c \uc9c8\uad8c\uc790\ub294 \uc124\uc815\uc790\ub85c \ud558\uc5ec\uae08 \uc9c8\ubb3c\uc758 \uc810\uc720\ub97c \ud558\uac8c \ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc9c8\uad8c\uc790\ub294 \uc720\uce58\uc801 \ud6a8\ub825\uacfc \ud568\uaed8 \uc6b0\uc120\ubcc0\uc81c\uad8c\ub3c4 \uac00\uc9c0\ub294 \uc810\uc5d0\uc11c \uc720\uce58\uad8c\uacfc \uad6c\ubcc4\ub41c\ub2e4.",B.a91,B.aSm,null)
B.alz=s(["\uad8c\ub9ac\uc9c8\uad8c\uc740 \ubd80\ub3d9\uc0b0\uc5d0 \ub300\ud574\uc11c\ub9cc \uc124\uc815\ud560 \uc218 \uc788\ub2e4.","\ucc44\uad8c\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc9c8\uad8c\uc758 \uc124\uc815\uc740 \ucc44\uad8c\uc99d\uc11c\uc758 \uad50\ubd80\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc99d\uc11c\ub97c \uad50\ubd80\ud568\uc73c\ub85c\uc368 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\uad8c\ub9ac\uc9c8\uad8c\uc5d0\ub294 \ub3d9\uc0b0\uc9c8\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc900\uc6a9\ub420 \uc218 \uc5c6\ub2e4.","\uad8c\ub9ac\uc9c8\uad8c\uc740 \uc800\ub2f9\uad8c\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ubc18\ub4dc\uc2dc \ub4f1\uae30\uac00 \ud544\uc694\ud558\ub2e4."],t.s)
B.amQ=s(["\ucc44\uad8c\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc9c8\uad8c\uc758 \uc124\uc815\uc740 \uc99d\uc11c\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc99d\uc11c\ub97c \uad50\ubd80\ud568\uc73c\ub85c\uc368 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.acB=s(["\uad8c\ub9ac\uc9c8\uad8c","\uc81c347\uc870"],t.s)
B.bMW=new A.a("gen_cl_security_7","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uad8c\ub9ac\uc9c8\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.alz,1,"\ubbfc\ubc95 \uc81c345\uc870\ub294 \uad8c\ub9ac\uc9c8\uad8c\uc744 \uc7ac\uc0b0\uad8c\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc9c8\uad8c\uc73c\ub85c \uaddc\uc815\ud558\uba70, \uc81c347\uc870\uc5d0 \ub530\ub77c \ucc44\uad8c\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc9c8\uad8c\uc758 \uc124\uc815\uc740 \uc99d\uc11c\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc99d\uc11c\ub97c \uad50\ubd80\ud568\uc73c\ub85c\uc368 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4. \uad8c\ub9ac\uc9c8\uad8c\uc5d0\ub294 \uc131\uc9c8\uc5d0 \ubc18\ud558\uc9c0 \uc54a\ub294 \ud55c \ub3d9\uc0b0\uc9c8\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc900\uc6a9\ub41c\ub2e4(\uc81c346\uc870).",B.amQ,B.acB,null)
B.ba1=s(["\uc800\ub2f9\uad8c\uc740 \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\uacfc \ub4f1\uae30\uc5d0 \uc758\ud558\uc5ec \uc131\ub9bd\ud55c\ub2e4.","\uc800\ub2f9\uad8c\uc758 \ubaa9\uc801\ubb3c\uc740 \ubd80\ub3d9\uc0b0\uc5d0 \ud55c\uc815\ub418\uba70, \uc9c0\uc0c1\uad8c\xb7\uc804\uc138\uad8c\ub3c4 \uadf8 \ubaa9\uc801\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc124\uc815\uc790\ub294 \ubc18\ub4dc\uc2dc \ucc44\ubb34\uc790\uc774\uc5b4\uc57c \ud558\uba70 \ubb3c\uc0c1\ubcf4\uc99d\uc778\uc740 \ub420 \uc218 \uc5c6\ub2e4.","\uc800\ub2f9\uad8c\uc740 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud558\uc5ec \uc124\uc815\ub418\ub294 \uc57d\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc774\ub2e4."],t.s)
B.aYB=s(["\ucc44\ubb34\uc790 \uc544\ub2cc \uc81c3\uc790\ub3c4 \ubb3c\uc0c1\ubcf4\uc99d\uc778\uc73c\ub85c\uc11c \uc800\ub2f9\uad8c\uc744 \uc124\uc815\ud560 \uc218 \uc788\ub2e4."],t.s)
B.adR=s(["\uc800\ub2f9\uad8c \uc131\ub9bd","\ubb3c\uc0c1\ubcf4\uc99d\uc778"],t.s)
B.bM8=new A.a("gen_cl_security_8","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\uad8c\uc758 \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ba1,2,"\ubbfc\ubc95 \uc81c356\uc870\uc5d0 \ub530\ub77c \uc800\ub2f9\uad8c\uc740 \ubd80\ub3d9\uc0b0\uc5d0 \ub4f1\uae30\ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\uba70, \uc81c371\uc870\uc5d0 \uc758\ud574 \uc9c0\uc0c1\uad8c\xb7\uc804\uc138\uad8c\ub3c4 \uc800\ub2f9\uad8c\uc758 \ubaa9\uc801\uc774 \ub420 \uc218 \uc788\ub2e4. \ucc44\ubb34\uc790 \uc544\ub2cc \uc81c3\uc790\ub3c4 \ubb3c\uc0c1\ubcf4\uc99d\uc778\uc73c\ub85c\uc11c \uc800\ub2f9\uad8c\uc744 \uc124\uc815\ud560 \uc218 \uc788\ub2e4.",B.aYB,B.adR,null)
B.bhE=s(["\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ub41c \ubb3c\uac74\uacfc \uc885\ubb3c\uc5d0 \ubbf8\uce58\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.","\uc800\ub2f9\ubd80\ub3d9\uc0b0\uc758 \uc885\ubb3c\uc740 \uc800\ub2f9\uad8c \uc124\uc815 \ud6c4\uc5d0 \ubd80\uc18d\ub41c \uac83\uc774\uba74 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.","\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacfc\uc2e4\uc5d0\ub294 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.","\uc800\ub2f9\uad8c\uc124\uc815\uc790\uac00 \ubd80\ud569\uc2dc\ud0a8 \ubb3c\uac74\uc5d0\ub294 \uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aQ7=s(["\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc774 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ub41c \ubb3c\uac74\uacfc \uc885\ubb3c\uc5d0 \ubbf8\uce5c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4."],t.s)
B.a1f=s(["\uc800\ub2f9\uad8c \ud6a8\ub825\ubc94\uc704","\ubd80\ud569\ubb3c\xb7\uc885\ubb3c","\uc81c358\uc870"],t.s)
B.bzD=new A.a("gen_cl_security_9","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\ub294 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bhE,0,"\ubbfc\ubc95 \uc81c358\uc870\ub294 \uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc774 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ubd80\ud569\ub41c \ubb3c\uac74\uacfc \uc885\ubb3c\uc5d0 \ubbf8\uce5c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc124\uc815\ud589\uc704\uc5d0 \ub2e4\ub978 \uc57d\uc815\uc774 \uc788\uac70\ub098 \uc81c406\uc870\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\ub300\uc0c1\uc774 \ub418\ub294 \uacbd\uc6b0 \ub4f1\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4. \ub610\ud55c \uc555\ub958 \uc774\ud6c4\uc5d0\ub294 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc758 \uacfc\uc2e4\uc5d0\ub3c4 \ud6a8\ub825\uc774 \ubbf8\uce5c\ub2e4(\uc81c359\uc870).",B.aQ7,B.a1f,null)
B.aa7=s(["\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ub300\ud55c \uc555\ub958\uac00 \uc788\uc740 \ud6c4\uc758 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc758 \uacfc\uc2e4\uc5d0 \ubbf8\uce5c\ub2e4.","\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \ud56d\uc0c1 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc758 \uacfc\uc2e4\uc5d0 \ubbf8\uce5c\ub2e4.","\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc555\ub958\uc640 \ubb34\uad00\ud558\uac8c \uacfc\uc2e4\uc5d0 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4.","\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \ubc95\uc815\uacfc\uc2e4\uc5d0\ub294 \ubbf8\uce58\uc9c0\ub9cc \ucc9c\uc5f0\uacfc\uc2e4\uc5d0\ub294 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aj5=s(["\uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ub300\ud55c \uc555\ub958\uac00 \uc788\uc740 \ud6c4\uc5d0 \uadf8 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc73c\ub85c\ubd80\ud130 \uc0dd\uae34 \uacfc\uc2e4\uc5d0 \ubbf8\uce5c\ub2e4."],t.s)
B.aIK=s(["\uc800\ub2f9\uad8c \ud6a8\ub825","\uacfc\uc2e4","\uc81c359\uc870"],t.s)
B.bNe=new A.a("gen_cl_security_10","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\ubd80\ub3d9\uc0b0\uc758 \uacfc\uc2e4\uc5d0 \ub300\ud55c \uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aa7,0,"\ubbfc\ubc95 \uc81c359\uc870\uc5d0 \ub530\ub77c \uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc740 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \ub300\ud55c \uc555\ub958\uac00 \uc788\uc740 \ud6c4\uc5d0 \uadf8 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc73c\ub85c\ubd80\ud130 \uc0dd\uae34 \uacfc\uc2e4\uc5d0 \ubbf8\uce5c\ub2e4. \uc555\ub958 \uc804\uc758 \uacfc\uc2e4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc800\ub2f9\uad8c\uc758 \ud6a8\ub825\uc774 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4.",B.aj5,B.aIK,null)
B.aXX=s(["\uc800\ub2f9\uad8c\uc124\uc815\uc790\ub294 \uc800\ub2f9\uad8c\uc758 \uc2e4\ud589 \uc804\uae4c\uc9c0 \uc800\ub2f9\ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\xb7\uc218\uc775\ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc124\uc815 \ud6c4 \uc800\ub2f9\ubd80\ub3d9\uc0b0\uc5d0 \uc9c0\uc0c1\uad8c \ub610\ub294 \uc804\uc138\uad8c\uc744 \uc124\uc815\ud558\ub294 \uac83\uc740 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc800\ub2f9\uad8c\uc124\uc815 \ud6c4\uc758 \uc6a9\uc775\uad8c\uc790\ub294 \uc800\ub2f9\uad8c \uc2e4\ud589\uc73c\ub85c \uacbd\ub9e4\uac00 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uadf8 \uad8c\ub9ac\ub97c \uc783\uc744 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc740 \ubaa9\uc801\ubb3c\uc758 \uc810\uc720\ub97c \uc774\uc804\ud558\uc9c0 \uc54a\ub294 \ube44\uc810\uc720\ub2f4\ubcf4\ubb3c\uad8c\uc774\ub2e4."],t.s)
B.Rw=s(["\uc124\uc815\uc790\ub294 \uc800\ub2f9\uad8c \uc2e4\ud589 \uc804\uae4c\uc9c0 \uc790\uc720\ub86d\uac8c \uc0ac\uc6a9\xb7\uc218\uc775\ud560 \uc218 \uc788\uace0 \uadf8 \ubd80\ub3d9\uc0b0\uc5d0 \uc9c0\uc0c1\uad8c\uc774\ub098 \uc804\uc138\uad8c \ub4f1 \uc6a9\uc775\uad8c\uc744 \uc124\uc815\ud558\ub294 \uac83\ub3c4 \uac00\ub2a5\ud558\ub2e4."],t.s)
B.agy=s(["\uc800\ub2f9\uad8c\uacfc \uc6a9\uc775\uad8c"],t.s)
B.bof=new A.a("gen_cl_security_11","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\uad8c\uacfc \uc6a9\uc775\uad8c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aXX,1,"\uc800\ub2f9\uad8c\uc740 \ubaa9\uc801\ubb3c\uc758 \uc810\uc720\ub97c \uc800\ub2f9\uad8c\uc124\uc815\uc790\uc5d0\uac8c \ub0a8\uaca8\ub450\ub294 \ube44\uc810\uc720\ub2f4\ubcf4\ubb3c\uad8c\uc73c\ub85c, \uc124\uc815\uc790\ub294 \uc800\ub2f9\uad8c \uc2e4\ud589 \uc804\uae4c\uc9c0 \uc790\uc720\ub86d\uac8c \uc0ac\uc6a9\xb7\uc218\uc775\ud560 \uc218 \uc788\uace0 \uadf8 \ubd80\ub3d9\uc0b0\uc5d0 \uc9c0\uc0c1\uad8c\uc774\ub098 \uc804\uc138\uad8c \ub4f1 \uc6a9\uc775\uad8c\uc744 \uc124\uc815\ud558\ub294 \uac83\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ub2e4\ub9cc \uc800\ub2f9\uad8c \uc2e4\ud589\uc73c\ub85c \uacbd\ub9e4\uac00 \uc774\ub8e8\uc5b4\uc9c0\uba74 \ud6c4\uc21c\uc704 \uc6a9\uc775\uad8c\uc740 \uc18c\uba78\ud560 \uc218 \uc788\ub2e4(\ubbfc\ubc95 \uc81c91\uc870, \ubbfc\uc0ac\uc9d1\ud589\ubc95 \uad00\ub828 \uaddc\uc815 \ucc38\uc870).",B.Rw,B.agy,null)
B.aVr=s(["\uc800\ub2f9\uad8c \uc124\uc815 \ub2f9\uc2dc \ud1a0\uc9c0 \uc704\uc5d0 \uac74\ubb3c\uc774 \uc874\uc7ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc800\ub2f9\uad8c \uc124\uc815 \ub2f9\uc2dc \ud1a0\uc9c0\uc640 \uac74\ubb3c\uc774 \ub3d9\uc77c\uc778\uc758 \uc18c\uc720\uc5d0 \uc18d\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uacbd\ub9e4\ub85c \uc778\ud558\uc5ec \ud1a0\uc9c0\uc640 \uac74\ubb3c\uc758 \uc18c\uc720\uc790\uac00 \ub2e4\ub974\uac8c \ub418\uc5b4\uc57c \ud55c\ub2e4.","\ud1a0\uc9c0\uc640 \uac74\ubb3c \uc911 \uc5b4\ub290 \ud558\ub098\uc5d0\ub9cc \uc800\ub2f9\uad8c\uc774 \uc124\uc815\ub418\uc5b4\uc11c\ub294 \uc548 \ub418\uace0 \ubc18\ub4dc\uc2dc \uc591\uc790 \ubaa8\ub450\uc5d0 \uc800\ub2f9\uad8c\uc774 \uc124\uc815\ub418\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.a2r=s(["\uc800\ub2f9\uad8c\uc740 \ud1a0\uc9c0\ub098 \uac74\ubb3c \uc911 \uc5b4\ub290 \ud55c\ucabd\uc5d0\ub9cc \uc124\uc815\ub418\uc5b4\ub3c4 \ubb34\ubc29\ud558\ub2e4."],t.s)
B.a2M=s(["\ubc95\uc815\uc9c0\uc0c1\uad8c","\uc81c366\uc870"],t.s)
B.bya=new A.a("gen_cl_security_12","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\ubbfc\ubc95 \uc81c366\uc870\uc758 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aVr,3,"\ubbfc\ubc95 \uc81c366\uc870\uc758 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc740 \uc800\ub2f9\uad8c \uc124\uc815 \ub2f9\uc2dc \ud1a0\uc9c0 \uc704\uc5d0 \uac74\ubb3c\uc774 \uc874\uc7ac\ud558\uace0 \ud1a0\uc9c0\uc640 \uac74\ubb3c\uc774 \ub3d9\uc77c\uc778 \uc18c\uc720\uc774\uc5c8\ub2e4\uac00 \uc800\ub2f9\uad8c \uc2e4\ud589\uc5d0 \uc758\ud55c \uacbd\ub9e4\ub85c \uc18c\uc720\uc790\uac00 \ub2ec\ub77c\uc9c4 \uacbd\uc6b0\uc5d0 \uc131\ub9bd\ud55c\ub2e4. \uc800\ub2f9\uad8c\uc740 \ud1a0\uc9c0\ub098 \uac74\ubb3c \uc911 \uc5b4\ub290 \ud55c\ucabd\uc5d0\ub9cc \uc124\uc815\ub418\uc5b4\ub3c4 \ubb34\ubc29\ud558\ub2e4.",B.a2r,B.a2M,null)
B.T0=s(["\uac74\ubb3c\uc774 \uc7ac\ucd95\xb7\uac1c\ucd95\ub41c \uacbd\uc6b0\uc5d0\ub294 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uac74\ubb3c\uc774 \uc7ac\ucd95\xb7\uac1c\ucd95\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \uad6c\uac74\ubb3c\uc744 \uae30\uc900\uc73c\ub85c \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ubc95\uc815\uc9c0\uc0c1\uad8c\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.","\uc7ac\ucd95\xb7\uac1c\ucd95\uc758 \uacbd\uc6b0 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc740 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc7ac\ucd95\xb7\uac1c\ucd95\ub41c \uac74\ubb3c\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uc0c8\ub85c\uc6b4 \uc800\ub2f9\uad8c \uc124\uc815\uc774 \ud544\uc694\ud558\ub2e4."],t.s)
B.aS9=s(["\uadf8 \uc874\uc18d\uae30\uac04\uc774\ub098 \ubc94\uc704 \ub4f1\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uad6c\uac74\ubb3c\uc744 \uae30\uc900\uc73c\ub85c \uacb0\uc815\ud55c\ub2e4\uace0 \ubcf8\ub2e4."],t.s)
B.aqN=s(["\ubc95\uc815\uc9c0\uc0c1\uad8c","\uc7ac\ucd95\xb7\uac1c\ucd95"],t.s)
B.bJq=new A.a("gen_cl_security_13","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\ubc95\uc815\uc9c0\uc0c1\uad8c\uc758 \uc131\ub9bd\uacfc \uad00\ub828\ud558\uc5ec \uac74\ubb3c\uc774 \uc7ac\ucd95\xb7\uac1c\ucd95\ub41c \uacbd\uc6b0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.T0,1,"\ud310\ub840\ub294 \uc800\ub2f9\uad8c \uc124\uc815 \ub2f9\uc2dc \uc874\uc7ac\ud558\ub358 \uac74\ubb3c\uc774 \uadf8 \ud6c4 \uac1c\ucd95, \uc99d\ucd95\ub418\uac70\ub098 \uc2ec\uc9c0\uc5b4 \uba78\uc2e4 \ud6c4 \uc7ac\ucd95\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc758 \uc131\ub9bd\uc744 \uc778\uc815\ud558\ub418, \uadf8 \uc874\uc18d\uae30\uac04\uc774\ub098 \ubc94\uc704 \ub4f1\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uad6c\uac74\ubb3c\uc744 \uae30\uc900\uc73c\ub85c \uacb0\uc815\ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc774\ub294 \ubc95\uc815\uc9c0\uc0c1\uad8c \uc81c\ub3c4\uac00 \uc0ac\ud68c\uacbd\uc81c\uc801 \uc190\uc2e4\uc744 \ubc29\uc9c0\ud558\ub824\ub294 \ucde8\uc9c0\uc5d0\uc11c \uc778\uc815\ub418\uae30 \ub54c\ubb38\uc774\ub2e4.",B.aS9,B.aqN,null)
B.az0=s(["\uc800\ub2f9\uad8c\uc790\ub294 \uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \uac10\uc18c\ub41c \uacbd\uc6b0 \uc6d0\uc0c1\ud68c\ubcf5 \ub610\ub294 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\uc81c\uacf5\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc790\ub294 \uc800\ub2f9\uad8c\uc5d0 \uae30\ud55c \ubb3c\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c\uc11c \ubc29\ud574\ubc30\uc81c\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc790\ub294 \uc800\ub2f9\ubb3c\uc758 \uce68\ud574\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\uad8c\uc790\ub294 \uc800\ub2f9\ubb3c\uc758 \uce68\ud574\uac00 \uc788\ub294 \uacbd\uc6b0 \uc5b8\uc81c\ub098 \uc989\uc2dc \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4."],t.s)
B.avB=s(["\uc800\ub2f9\uad8c\uc740 \ube44\uc810\uc720\ub2f4\ubcf4\ubb3c\uad8c\uc774\ubbc0\ub85c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uccad\uad6c\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aoN=s(["\uc800\ub2f9\uad8c \uce68\ud574 \uad6c\uc81c","\uc81c362\uc870"],t.s)
B.bJ6=new A.a("gen_cl_security_14","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\uad8c\uc758 \uce68\ud574\uc5d0 \ub300\ud55c \uad6c\uc81c\uc218\ub2e8\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.az0,3,"\ubbfc\ubc95 \uc81c362\uc870\ub294 \uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \ud604\uc800\ud788 \uac10\uc18c\ub41c \ub54c \uc800\ub2f9\uad8c\uc790\uac00 \uc6d0\uc0c1\ud68c\ubcf5 \ub610\ub294 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\uc81c\uacf5\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc800\ub2f9\uad8c\uc790\ub294 \ubc29\ud574\ubc30\uc81c\uccad\uad6c\uad8c \ubc0f \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc800\ub2f9\uad8c\uc740 \ube44\uc810\uc720\ub2f4\ubcf4\ubb3c\uad8c\uc774\ubbc0\ub85c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uccad\uad6c\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.avB,B.aoN,null)
B.b3B=s(["\uc800\ub2f9\uad8c \uc124\uc815\uc790\uc758 \ud589\uc704\ub85c \uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \ud604\uc800\ud788 \uac10\uc18c\ub41c \ub54c\uc5d0\ub294 \uc800\ub2f9\uad8c\uc790\ub294 \uc989\uc2dc \uadf8 \uc6d0\uc0c1\ud68c\ubcf5 \ub4f1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uac10\uc18c\ub294 \uc800\ub2f9\uad8c\uc790\uc640 \ubb34\uad00\ud55c \uc0ac\uc720\uc774\ubbc0\ub85c \uc5b4\ub5a0\ud55c \uccad\uad6c\ub3c4 \ud560 \uc218 \uc5c6\ub2e4.","\uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \uac10\uc18c\ub418\uc5b4\ub3c4 \ucc44\ubb34\uc790\ub294 \uc544\ubb34\ub7f0 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uac10\uc18c\ub294 \uadfc\uc800\ub2f9\uad8c\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \ubc95\ub9ac\uc774\ub2e4."],t.s)
B.bfn=s(["\uc800\ub2f9\uad8c\uc124\uc815\uc790\uc758 \ud589\uc704\ub85c \uc778\ud558\uc5ec \uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \ud604\uc800\ud788 \uac10\uc18c\ub41c \ub54c\uc5d0\ub294 \uc800\ub2f9\uad8c\uc790\ub294 \uadf8 \uc6d0\uc0c1\ud68c\ubcf5 \ub610\ub294 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\uc81c\uacf5\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4."],t.s)
B.akI=s(["\uc800\ub2f9\uad8c \uce68\ud574","\uc81c362\uc870"],t.s)
B.bqO=new A.a("gen_cl_security_15","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc800\ub2f9\uad8c\uc790\uc758 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4 \ubc0f \uc989\uc2dc\ubcc0\uc81c\uccad\uad6c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b3B,0,"\ubbfc\ubc95 \uc81c362\uc870\uc5d0 \ub530\ub77c \uc800\ub2f9\uad8c\uc124\uc815\uc790\uc758 \ud589\uc704\ub85c \uc778\ud558\uc5ec \uc800\ub2f9\ubb3c\uc758 \uac00\uc561\uc774 \ud604\uc800\ud788 \uac10\uc18c\ub41c \ub54c\uc5d0\ub294 \uc800\ub2f9\uad8c\uc790\ub294 \uadf8 \uc6d0\uc0c1\ud68c\ubcf5 \ub610\ub294 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\uc81c\uacf5\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc800\ub2f9\uad8c \uce68\ud574\uc5d0 \ub300\ud55c \uad6c\uc81c\uc218\ub2e8\uc758 \ud558\ub098\uc774\ub2e4.",B.bfn,B.akI,null)
B.asl=s(["\uadfc\uc800\ub2f9\uad8c\uc740 \uc7a5\ub798 \uc99d\uac10\xb7\ubcc0\ub3d9\ud558\ub294 \ubd88\ud2b9\uc815\uc758 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud558\uc5ec \uc124\uc815\ud558\ub294 \uc800\ub2f9\uad8c\uc774\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc740 \ucc44\uad8c\ucd5c\uace0\uc561\uc744 \uc815\ud558\uc5ec \ub4f1\uae30\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc740 \uacb0\uc0b0\uae30\uc5d0 \ud655\uc815\ub41c\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc758 \ucc44\uad8c\ucd5c\uace0\uc561\uc740 \uc774\uc790\ub97c \ud3ec\ud568\ud558\uc9c0 \uc54a\uace0 \uc6d0\ubcf8\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4."],t.s)
B.a8i=s(["\ucc44\uad8c\ucd5c\uace0\uc561\uc740 \uc6d0\ubcf8\ubfd0 \uc544\ub2c8\ub77c \uc774\uc790, \uc704\uc57d\uae08 \ub4f1\uc744 \ud3ec\ud568\ud558\ub294 \ud55c\ub3c4\uc561\uc744 \uc758\ubbf8\ud55c\ub2e4."],t.s)
B.Ug=s(["\uadfc\uc800\ub2f9\uad8c","\ucc44\uad8c\ucd5c\uace0\uc561","\uc81c357\uc870"],t.s)
B.bDp=new A.a("gen_cl_security_16","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uadfc\uc800\ub2f9\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.asl,3,"\ubbfc\ubc95 \uc81c357\uc870\uc758 \uadfc\uc800\ub2f9\uad8c\uc740 \uacc4\uc18d\uc801 \uac70\ub798\uad00\uacc4\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \uc7a5\ub798\uc758 \ubd88\ud2b9\uc815 \ucc44\uad8c\uc744 \ucc44\uad8c\ucd5c\uace0\uc561\uc758 \ud55c\ub3c4\uc5d0\uc11c \ub2f4\ubcf4\ud558\ub294 \uc800\ub2f9\uad8c\uc73c\ub85c, \uacb0\uc0b0\uae30 \ub3c4\ub798 \ub4f1\uc73c\ub85c \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc774 \ud655\uc815\ub41c\ub2e4. \ucc44\uad8c\ucd5c\uace0\uc561\uc740 \uc6d0\ubcf8\ubfd0 \uc544\ub2c8\ub77c \uc774\uc790, \uc704\uc57d\uae08 \ub4f1\uc744 \ud3ec\ud568\ud558\ub294 \ud55c\ub3c4\uc561\uc744 \uc758\ubbf8\ud55c\ub2e4.",B.a8i,B.Ug,null)
B.b8c=s(["\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc740 \uacb0\uc0b0\uae30\uc758 \ub3c4\ub798, \uc874\uc18d\uae30\uac04\uc758 \ub9cc\ub8cc, \uadfc\uc800\ub2f9\uad8c \uc2e4\ud589\uc758 \uc2e0\uccad \ub4f1\uc758 \uc0ac\uc720\ub85c \ud655\uc815\ub41c\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc740 \uacb0\ucf54 \ud655\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc774 \ud655\uc815\ub418\uba74 \ucc44\uad8c\ucd5c\uace0\uc561\ub3c4 \uc790\ub3d9\uc73c\ub85c \ubcc0\uacbd\ub41c\ub2e4.","\uadfc\uc800\ub2f9\uad8c\uc740 \ud655\uc815 \uc774\ud6c4\uc5d0\ub3c4 \uacc4\uc18d\ud558\uc5ec \uc0c8\ub85c\uc6b4 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud55c\ub2e4."],t.s)
B.b0e=s(["\ud655\uc815 \uc774\ud6c4\uc5d0\ub294 \uc0c8\ub85c \ubc1c\uc0dd\ud558\ub294 \ucc44\uad8c\uc740 \uadf8 \uadfc\uc800\ub2f9\uad8c\uc5d0 \uc758\ud558\uc5ec \ub2f4\ubcf4\ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4."],t.s)
B.b9w=s(["\uadfc\uc800\ub2f9\uad8c \ud655\uc815"],t.s)
B.byH=new A.a("gen_cl_security_17","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c \ud655\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b8c,0,"\uadfc\uc800\ub2f9\uad8c\uc758 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc740 \uacb0\uc0b0\uae30\uc758 \ub3c4\ub798, \uc874\uc18d\uae30\uac04\uc758 \ub9cc\ub8cc, \uacc4\uc57d\uc758 \ud574\uc9c0, \uadfc\uc800\ub2f9\uad8c \uc2e4\ud589\uc758 \uc2e0\uccad \ub4f1 \uc77c\uc815\ud55c \uc0ac\uc720\uac00 \ubc1c\uc0dd\ud558\uba74 \ud655\uc815\ub418\uba70, \ud655\uc815 \uc774\ud6c4\uc5d0\ub294 \uc0c8\ub85c \ubc1c\uc0dd\ud558\ub294 \ucc44\uad8c\uc740 \uadf8 \uadfc\uc800\ub2f9\uad8c\uc5d0 \uc758\ud558\uc5ec \ub2f4\ubcf4\ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4.",B.b0e,B.b9w,null)
B.b21=s(["\uacf5\ub3d9\uc800\ub2f9\uc740 \ub3d9\uc77c\ud55c \ucc44\uad8c\uc758 \ub2f4\ubcf4\ub97c \uc704\ud558\uc5ec \uc218\uac1c\uc758 \ubd80\ub3d9\uc0b0\uc5d0 \uc800\ub2f9\uad8c\uc744 \uc124\uc815\ud558\ub294 \uac83\uc774\ub2e4.","\uacf5\ub3d9\uc800\ub2f9\uc758 \ubaa9\uc801\ubd80\ub3d9\uc0b0 \uc911 \uc77c\ubd80\uc758 \uacbd\ub9e4\ub300\uac00\ub97c \uba3c\uc800 \ubc30\ub2f9\ud558\ub294 \uacbd\uc6b0 \uadf8 \ub300\uac00\uc5d0\uc11c \ucc44\uad8c \uc804\ubd80\uc758 \ubcc0\uc81c\ub97c \ubc1b\uc744 \uc218 \uc788\ub2e4.","\uacf5\ub3d9\uc800\ub2f9\uc5d0\uc11c \uac01 \ubd80\ub3d9\uc0b0\uc758 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcf4\ud638\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uacf5\ub3d9\uc800\ub2f9 \ubd80\ub3d9\uc0b0 \uc804\ubd80\ub97c \ub3d9\uc2dc\uc5d0 \uacbd\ub9e4\ud558\ub294 \uacbd\uc6b0 \uac01 \ubd80\ub3d9\uc0b0\uc758 \uac00\uc561\uc5d0 \ube44\ub840\ud558\uc5ec \ucc44\uad8c\uc744 \ubd84\ub2f4\ud55c\ub2e4."],t.s)
B.a0v=s(["\ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub3c4 \ub300\uc704 \ub4f1\uc744 \ud1b5\ud574 \ubcf4\ud638\ub420 \uc218 \uc788\ub2e4."],t.s)
B.b9_=s(["\uacf5\ub3d9\uc800\ub2f9","\uc81c368\uc870"],t.s)
B.bNR=new A.a("gen_cl_security_18","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uacf5\ub3d9\uc800\ub2f9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b21,2,"\ubbfc\ubc95 \uc81c368\uc870\ub294 \uacf5\ub3d9\uc800\ub2f9\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\ubc30\ub2f9 \uc2dc \uac01 \ubd80\ub3d9\uc0b0\uc758 \uacbd\ub9e4\ub300\uac00\uc5d0 \ube44\ub840\ud558\uc5ec \ucc44\uad8c \ubd84\ub2f4\uc561\uc744 \uc815\ud558\uace0(\uc81c1\ud56d), \uc774\uc2dc\ubc30\ub2f9 \uc2dc\uc5d0\ub294 \uc120\uc21c\uc704\uc800\ub2f9\uad8c\uc790\uac00 \ub9cc\uc871\uc744 \uc5bb\uc740 \ubd80\ub3d9\uc0b0\uc758 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \ub3d9\uc2dc\ubc30\ub2f9\uc774\uc5c8\ub2e4\uba74 \ub2e4\ub978 \ubd80\ub3d9\uc0b0\uc73c\ub85c\ubd80\ud130 \ubcc0\uc81c\ubc1b\uc744 \uc218 \uc788\uc5c8\ub358 \ud55c\ub3c4\uc5d0\uc11c \uc120\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub97c \ub300\uc704\ud560 \uc218 \uc788\ub2e4\uace0 \uc815\ud55c\ub2e4(\uc81c2\ud56d). \uc989 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub3c4 \ub300\uc704 \ub4f1\uc744 \ud1b5\ud574 \ubcf4\ud638\ub420 \uc218 \uc788\ub2e4.",B.a0v,B.b9_,null)
B.aPn=s(["\uba3c\uc800 \uacbd\ub9e4\ub41c \ubd80\ub3d9\uc0b0\uc758 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \ub3d9\uc2dc\ubc30\ub2f9\uc774\uc5c8\ub354\ub77c\uba74 \ub2e4\ub978 \ubd80\ub3d9\uc0b0\uc758 \ub300\uac00\uc5d0\uc11c \ubcc0\uc81c\ubc1b\uc744 \uc218 \uc788\uc5c8\ub358 \uae08\uc561\uc758 \ud55c\ub3c4\uc5d0\uc11c \uc120\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub97c \ub300\uc704\ud558\uc5ec \uc800\ub2f9\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc774\uc2dc\ubc30\ub2f9\uc758 \uacbd\uc6b0 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \uc5b4\ub5a0\ud55c \ub300\uc704\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.","\uc774\uc2dc\ubc30\ub2f9\uc740 \uacf5\ub3d9\uc800\ub2f9\uc5d0\uc11c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ubc30\ub2f9\ubc29\uc2dd\uc774\ub2e4.","\ub300\uc704\ub294 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\uac00 \uc544\ub2cc \ubb3c\uc0c1\ubcf4\uc99d\uc778\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4."],t.s)
B.abp=s(["\uadf8 \ubd80\ub3d9\uc0b0\uc758 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \ub3d9\uc2dc\ubc30\ub2f9\uc774\uc5c8\ub2e4\uba74 \ub2e4\ub978 \ubd80\ub3d9\uc0b0\uc758 \uacbd\ub9e4\ub300\uac00\uc5d0\uc11c \ubcc0\uc81c\ubc1b\uc744 \uc218 \uc788\uc5c8\ub358 \uae08\uc561\uc758 \ud55c\ub3c4\uc5d0\uc11c \uc120\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub97c \ub300\uc704\ud558\uc5ec \uadf8 \uc800\ub2f9\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.as7=s(["\uacf5\ub3d9\uc800\ub2f9","\uc774\uc2dc\ubc30\ub2f9","\ub300\uc704","\uc81c368\uc870 \uc81c2\ud56d"],t.s)
B.bqq=new A.a("gen_cl_security_19","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uacf5\ub3d9\uc800\ub2f9\uc5d0\uc11c \uc774\uc2dc\ubc30\ub2f9\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\uc758 \ub300\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aPn,0,"\ubbfc\ubc95 \uc81c368\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uacf5\ub3d9\uc800\ub2f9\uc758 \ubaa9\uc801\ubd80\ub3d9\uc0b0 \uc911 \uc77c\ubd80\ub9cc\uc774 \uba3c\uc800 \uacbd\ub9e4\ub418\uc5b4 \uadf8 \ub300\uac00\ub97c \ubc30\ub2f9\ud558\ub294 \uc774\uc2dc\ubc30\ub2f9\uc758 \uacbd\uc6b0, \uadf8 \ubd80\ub3d9\uc0b0\uc758 \ud6c4\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub294 \ub3d9\uc2dc\ubc30\ub2f9\uc774\uc5c8\ub2e4\uba74 \ub2e4\ub978 \ubd80\ub3d9\uc0b0\uc758 \uacbd\ub9e4\ub300\uac00\uc5d0\uc11c \ubcc0\uc81c\ubc1b\uc744 \uc218 \uc788\uc5c8\ub358 \uae08\uc561\uc758 \ud55c\ub3c4\uc5d0\uc11c \uc120\uc21c\uc704\uc800\ub2f9\uad8c\uc790\ub97c \ub300\uc704\ud558\uc5ec \uadf8 \uc800\ub2f9\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.abp,B.as7,null)
B.akS=s(["\uc720\uce58\uad8c\uc740 \ubc95\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc774\ub098 \uc800\ub2f9\uad8c\uc740 \uc57d\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc774\ub2e4.","\uc720\uce58\uad8c\uc740 \ubaa9\uc801\ubb3c\uc758 \uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\ub098 \uc800\ub2f9\uad8c\uc740 \uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c \ubaa8\ub450 \ubaa9\uc801\ubb3c\uc5d0 \ub300\ud55c \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc778\uc815\ub418\ub294 \uac83\uc740 \ub3d9\uc77c\ud558\ub2e4.","\uc720\uce58\uad8c\uc740 \ub4f1\uae30\ub97c \uc694\ud558\uc9c0 \uc54a\uc73c\ub098 \uc800\ub2f9\uad8c\uc740 \ub4f1\uae30\ud558\uc5ec\uc57c \uc131\ub9bd\ud55c\ub2e4."],t.s)
B.b6y=s(["\uc720\uce58\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uc0ac\uc2e4\uc0c1\uc758 \uc6b0\uc120\ubcc0\uc81c \ud6a8\uacfc\ub9cc \uc788\ub294 \uc810\uc5d0\uc11c \uc800\ub2f9\uad8c\uacfc \ub2e4\ub974\ub2e4."],t.s)
B.aIo=s(["\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c \ube44\uad50"],t.s)
B.bFJ=new A.a("gen_cl_security_20","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uacfc \uc800\ub2f9\uad8c\uc758 \ube44\uad50\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.akS,2,"\uc720\uce58\uad8c\uc740 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \uc131\ub9bd\ud558\ub294 \ubc95\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc73c\ub85c \ubaa9\uc801\ubb3c\uc758 \uc810\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uba70 \ub4f1\uae30\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ubc18\uba74, \uc800\ub2f9\uad8c\uc740 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uacfc \ub4f1\uae30\uc5d0 \uc758\ud558\uc5ec \uc131\ub9bd\ud558\ub294 \uc57d\uc815\ub2f4\ubcf4\ubb3c\uad8c\uc73c\ub85c \uc810\uc720\uc758 \uc774\uc804\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc720\uce58\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uc0ac\uc2e4\uc0c1\uc758 \uc6b0\uc120\ubcc0\uc81c \ud6a8\uacfc\ub9cc \uc788\ub294 \uc810\uc5d0\uc11c \uc800\ub2f9\uad8c\uacfc \ub2e4\ub974\ub2e4.",B.b6y,B.aIo,null)
B.b4O=s(["\uc9c0\uc0c1\uad8c\uc740 \ud0c0\uc778\uc758 \ud1a0\uc9c0\uc5d0\uc11c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc774\ub098 \uc218\ubaa9\uc744 \uc18c\uc720\ud558\uae30 \uc704\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \ubb3c\uad8c\uc774\ub2e4","\uc9c0\uc0c1\uad8c\uc740 \ucc44\uad8c\uc774\ubbc0\ub85c \ub4f1\uae30 \uc5c6\uc774\ub3c4 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc0c1\uad8c\uc740 \ubc18\ub4dc\uc2dc \uc9c0\ub8cc \uc9c0\uae09\uc744 \uc694\uc18c\ub85c \ud558\ub294 \uc720\uc0c1\uacc4\uc57d\uc774\ub2e4","\uc9c0\uc0c1\uad8c\uc740 \ud1a0\uc9c0\uc18c\uc720\uc790\ub9cc\uc774 \uc124\uc815\ud560 \uc218 \uc788\uace0 \uc9c0\uc0c1\uad8c\uc790\ub294 \uc774\ub97c \uc591\ub3c4\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a_p=s(["\ud0c0\uc778\uc758 \ud1a0\uc9c0\uc5d0\uc11c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc774\ub098 \uc218\ubaa9\uc744 \uc18c\uc720\ud558\uae30 \uc704\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud55c\ub2e4"],t.s)
B.ayO=s(["\uc9c0\uc0c1\uad8c\uc758 \uc758\uc758","\ubbfc\ubc95 \uc81c279\uc870"],t.s)
B.bNZ=new A.a("gen_cl_usufruct_1","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc0c1\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b4O,0,"\ubbfc\ubc95 \uc81c279\uc870\ub294 \uc9c0\uc0c1\uad8c\uc744 \ud0c0\uc778\uc758 \ud1a0\uc9c0\uc5d0\uc11c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc774\ub098 \uc218\ubaa9\uc744 \uc18c\uc720\ud558\uae30 \uc704\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud55c\ub2e4. \uc9c0\uc0c1\uad8c\uc740 \ubb3c\uad8c\uc774\ubbc0\ub85c \ub4f1\uae30\ud558\uc5ec\uc57c \ub300\ud56d\ub825\uc774 \uc0dd\uae30\uace0, \uc9c0\ub8cc\ub294 \uc9c0\uc0c1\uad8c\uc758 \uc131\ub9bd\uc694\uc18c\uac00 \uc544\ub2c8\ub2e4. \ub610\ud55c \uc9c0\uc0c1\uad8c\uc790\ub294 \uc9c0\uc0c1\uad8c\uc744 \uc790\uc720\ub85c\uc774 \uc591\ub3c4\ud558\uac70\ub098 \uadf8 \uc874\uc18d\uae30\uac04 \ub0b4\uc5d0\uc11c \ud1a0\uc9c0\ub97c \uc784\ub300\ud560 \uc218 \uc788\ub2e4(\uc81c282\uc870).",B.a_p,B.ayO,null)
B.aaQ=s(["\uc11d\uc870\xb7\uc11d\ud68c\uc870\xb7\uc5f0\uc640\uc870 \ub610\ub294 \uc774\uc640 \uc720\uc0ac\ud55c \uacac\uace0\ud55c \uac74\ubb3c\uc774\ub098 \uc218\ubaa9 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ub54c\uc5d0\ub294 \ucd5c\ub2e8 \uc874\uc18d\uae30\uac04\uc740 30\ub144\uc774\ub2e4","\uadf8 \ubc16\uc758 \uac74\ubb3c \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ub54c\uc5d0\ub294 \ucd5c\ub2e8 \uc874\uc18d\uae30\uac04\uc740 15\ub144\uc774\ub2e4","\uac74\ubb3c \uc774\uc678\uc758 \uacf5\uc791\ubb3c \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ub54c\uc5d0\ub294 \ucd5c\ub2e8 \uc874\uc18d\uae30\uac04\uc740 5\ub144\uc774\ub2e4","\ub2f9\uc0ac\uc790\uac00 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud55c \uacbd\uc6b0 \uadf8 \uae30\uac04\uc774 \uc81c280\uc870\uc758 \ucd5c\ub2e8\uae30\uac04\ubcf4\ub2e4 \uc9e7\ub354\ub77c\ub3c4 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.avZ=s(["\uc124\uc815\ud589\uc704\ub85c \uc774\ubcf4\ub2e4 \ub2e8\uae30\uac04\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uc81c280\uc870\uc758 \uae30\uac04\uae4c\uc9c0 \uc5f0\uc7a5\ub418\ubbc0\ub85c(\uc81c281\uc870)"],t.s)
B.YY=s(["\ucd5c\ub2e8\uc874\uc18d\uae30\uac04","\ubbfc\ubc95 \uc81c280\uc870","\uc81c281\uc870"],t.s)
B.bMC=new A.a("gen_cl_usufruct_2","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc0c1\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aaQ,3,"\ubbfc\ubc95 \uc81c280\uc870\ub294 \uc9c0\uc0c1\uad8c\uc758 \ubaa9\uc801\ubb3c \uc885\ub958\uc5d0 \ub530\ub77c \ucd5c\ub2e8 \uc874\uc18d\uae30\uac04\uc744 \uacac\uace0\ud55c \uac74\ubb3c\xb7\uc218\ubaa9 30\ub144, \uadf8 \ubc16\uc758 \uac74\ubb3c 15\ub144, \uacf5\uc791\ubb3c 5\ub144\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \uc124\uc815\ud589\uc704\ub85c \uc774\ubcf4\ub2e4 \ub2e8\uae30\uac04\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uc81c280\uc870\uc758 \uae30\uac04\uae4c\uc9c0 \uc5f0\uc7a5\ub418\ubbc0\ub85c(\uc81c281\uc870), \uc9e7\uac8c \uc815\ud55c \uc57d\uc815\uc774 \uadf8\ub300\ub85c \uc720\ud6a8\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4.",B.avZ,B.YY,null)
B.a4i=s(["\uc9c0\uc0c1\uad8c\uc740 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uadf8 \uae30\uac04\uc740 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc73c\ub85c \ud55c\ub2e4","\uc9c0\uc0c1\uad8c\uc790\uac00 \uc784\uc758\ub85c \uc874\uc18d\uae30\uac04\uc744 \uc815\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc0c1\uad8c\uc124\uc815\uc790\uac00 \uc989\uc2dc \uc18c\uba78\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ai5=s(["\uadf8 \uae30\uac04\uc744 \uc81c280\uc870\uc5d0\uc11c \uc815\ud55c \uac01 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.ad3=s(["\uc874\uc18d\uae30\uac04 \ubbf8\uc815","\ubbfc\ubc95 \uc81c281\uc870"],t.s)
B.bOt=new A.a("gen_cl_usufruct_3","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc0c1\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc744 \uc57d\uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a4i,1,"\ubbfc\ubc95 \uc81c281\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uacc4\uc57d\uc73c\ub85c \uc9c0\uc0c1\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uadf8 \uae30\uac04\uc744 \uc81c280\uc870\uc5d0\uc11c \uc815\ud55c \uac01 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc73c\ub85c \ud55c\ub2e4. \uc774\ub294 \uc9c0\uc0c1\uad8c\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac15\ud589\uaddc\uc815\uc801 \uc131\uaca9\uc744 \uac16\ub294\ub2e4.",B.ai5,B.ad3,null)
B.YU=s(["\uc9c0\uc0c1\uad8c\uc740 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \ubabb\ud55c \ud558\uc790\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc218\ubaa9\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud558\uc5ec \ucd5c\ub2e8\uae30\uac04 30\ub144\uc73c\ub85c \ubcf8\ub2e4","\uadf8 \uacf5\uc791\ubb3c\uc758 \uc885\ub958\uc640 \uc874\uc18d\uae30\uac04\uc740 \uacac\uace0\ud55c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uac83\uc73c\ub85c \ubcf4\uc544 30\ub144\uc73c\ub85c \ud55c\ub2e4","\uc874\uc18d\uae30\uac04\uc740 5\ub144\uc73c\ub85c \ud655\uc815\ub41c\ub2e4"],t.s)
B.biP=s(["\uadf8 \uacf5\uc791\ubb3c\uc740 \uacac\uace0\ud55c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uac83\uc73c\ub85c \ubcf4\uc544 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc778 30\ub144\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aBB=s(["\uc885\ub958\xb7\uae30\uac04 \ubbf8\uc815","\ubbfc\ubc95 \uc81c281\uc870 \uc81c2\ud56d"],t.s)
B.bxV=new A.a("gen_cl_usufruct_4","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc0c1\uad8c\uc124\uc815 \ub2f9\uc2dc \uacf5\uc791\ubb3c\uc758 \uc885\ub958\uc640 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0, \uadf8 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.YU,2,"\ubbfc\ubc95 \uc81c281\uc870 \uc81c2\ud56d\uc740 \uacf5\uc791\ubb3c\uc758 \uc885\ub958\uc640 \uc874\uc18d\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uacf5\uc791\ubb3c\uc740 \uacac\uace0\ud55c \uac74\ubb3c \uae30\ud0c0 \uacf5\uc791\ubb3c\uc758 \uc18c\uc720\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uac83\uc73c\ub85c \ubcf4\uc544 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc778 30\ub144\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc9c0\uc0c1\uad8c\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ud568\uc73c\ub85c\uc368 \uadf8 \uc9c0\uc704\ub97c \ub450\ud141\uac8c \ubcf4\ud638\ud558\ub824\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.biP,B.aBB,null)
B.a8k=s(["\uc9c0\uc0c1\uad8c\uc774 \uc874\uc18d\uae30\uac04\uc758 \ub9cc\ub8cc\ub85c \uc18c\uba78\ud55c \uacbd\uc6b0 \uc9c0\uc0c1\ubb3c\uc774 \ud604\uc874\ud558\ub294 \ub54c\uc5d0\ub294 \uc9c0\uc0c1\uad8c\uc790\ub294 \uac31\uc2e0\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc0c1\uad8c\uc124\uc815\uc790\ub294 \uac31\uc2e0\uccad\uad6c\ub97c \ubc1b\uc73c\uba74 \ubc18\ub4dc\uc2dc \uacc4\uc57d\uc744 \uac31\uc2e0\ud558\uc5ec\uc57c \ud55c\ub2e4","\uac31\uc2e0\uccad\uad6c\uad8c\uc740 \uc9c0\uc0c1\ubb3c\uc758 \uc874\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc778\uc815\ub41c\ub2e4","\uac31\uc2e0\uccad\uad6c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uccad\uad6c\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \uac31\uc2e0\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
