B.bMg=new A.a("gen_cl_usufruct_14","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc5ed\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aMW,2,"\ubbfc\ubc95 \uc81c293\uc870 \uc81c1\ud56d\uc740 \ud1a0\uc9c0\uacf5\uc720\uc790\uc758 1\uc778\uc740 \uc9c0\ubd84\uc5d0 \uad00\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc704\ud55c \uc9c0\uc5ed\uad8c\uc744 \uc18c\uba78\ud558\uac8c \ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc81c295\uc870 \uc81c2\ud56d\uc740 \uacf5\uc720\uc790 1\uc778\uc5d0 \ub300\ud55c \uc9c0\uc5ed\uad8c \ucde8\ub4dd\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \ub2e4\ub978 \uacf5\uc720\uc790\ub97c \uc704\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub7ec\ud55c \ubd88\uac00\ubd84\uc131\uc740 \uc9c0\uc5ed\uad8c\uc758 \uc131\uc9c8\uc0c1 \uc778\uc815\ub418\ub294 \uac83\uc73c\ub85c, \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8 \ubc0f \uc815\uc9c0\uc5d0\ub3c4 \ub9c8\ucc2c\uac00\uc9c0 \ubc95\ub9ac\uac00 \uc801\uc6a9\ub41c\ub2e4.",B.agJ,B.aNI,null)
B.aSG=s(["\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \ubcc4\ub3c4\ub85c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc5d0 \ubd80\uc885\ud558\uc5ec \uc774\uc804\ud558\uba70, \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \uc591\ub3c4\ud560 \uc218 \uc5c6\ub2e4","\uc694\uc5ed\uc9c0\uac00 \uc591\ub3c4\ub418\uba74 \uc9c0\uc5ed\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc2b9\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc774 \uc774\uc804\ub418\ub294 \uacbd\uc6b0\uc5d0\ub9cc \ud568\uaed8 \uc774\uc804\ud55c\ub2e4"],t.s)
