B.bzV=new A.a("gen_cl_usufruct_17","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc758 \uc758\uc758\uc640 \uc874\uc18d\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aNC,3,"\ubbfc\ubc95 \uc81c303\uc870\ub294 \uc804\uc138\uad8c\uc744 \uc804\uc138\uae08\uc744 \uc9c0\uae09\ud558\uace0 \ud0c0\uc778\uc758 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud558\uc5ec \uadf8 \ubd80\ub3d9\uc0b0\uc758 \uc6a9\ub3c4\uc5d0 \uc887\uc544 \uc0ac\uc6a9\xb7\uc218\uc775\ud558\ub294 \uad8c\ub9ac\ub85c \uc815\uc758\ud558\uace0, \uc81c312\uc870\ub294 \uc874\uc18d\uae30\uac04\uc744 10\ub144\uc744 \ub118\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\uba70 \uac74\ubb3c\uc804\uc138\uad8c\uc758 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc744 1\ub144\uc73c\ub85c \uc815\ud55c\ub2e4. \ub2f9\uc0ac\uc790\uac00 1\ub144\ubcf4\ub2e4 \ub2e8\ucd95\ud55c \uae30\uac04\uc744 \uc815\ud55c \ub54c\uc5d0\ub294 \uc774\ub97c 1\ub144\uc73c\ub85c \ubcf8\ub2e4.",B.az5,B.aIZ,null)
B.b6R=s(["\uc804\uc138\uad8c\uc790\ub294 \uc804\uc138\uae08\uc758 \ubc18\ud658\uc5d0 \uad00\ud558\uc5ec \ud6c4\uc21c\uc704\uad8c\ub9ac\uc790 \uae30\ud0c0 \ucc44\uad8c\uc790\ubcf4\ub2e4 \uc790\uae30\uc758 \uc804\uc138\uae08\uc758 \uc6b0\uc120\ubcc0\uc81c\ub97c \ubc1b\uc744 \uad8c\ub9ac\uac00 \uc788\ub2e4","\uc804\uc138\uad8c\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacbd\ub9e4\ub97c \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\uc804\uc138\uad8c\uc790\uc758 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc740 \ub4f1\uae30 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \uc778\uc815\ub41c\ub2e4","\uc804\uc138\uad8c\uc790\ub294 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc774 \uc5c6\uace0 \uc77c\ubc18\ucc44\uad8c\uc790\uc640 \ub3d9\uc21c\uc704\uc774\ub2e4"],t.s)
B.a42=s(["\uc804\uc138\uad8c\uc790\uac00 \ubd80\ub3d9\uc0b0 \uc804\ubd80\uc5d0 \ub300\ud558\uc5ec \ud6c4\uc21c\uc704\uad8c\ub9ac\uc790 \uae30\ud0c0 \ucc44\uad8c\uc790\ubcf4\ub2e4 \uc804\uc138\uae08\uc758 \uc6b0\uc120\ubcc0\uc81c\ub97c \ubc1b\uc744 \uad8c\ub9ac\uac00 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aw2=s(["\uc804\uc138\uad8c\uc790\uc758 \uc6b0\uc120\ubcc0\uc81c\uad8c","\ubbfc\ubc95 \uc81c303\uc870","\uc81c318\uc870"],t.s)
B.bwB=new A.a("gen_cl_usufruct_18","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc790\uc758 \uc6b0\uc120\ubcc0\uc81c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b6R,0,"\ubbfc\ubc95 \uc81c303\uc870 \uc81c1\ud56d\uc740 \uc804\uc138\uad8c\uc790\uac00 \ubd80\ub3d9\uc0b0 \uc804\ubd80\uc5d0 \ub300\ud558\uc5ec \ud6c4\uc21c\uc704\uad8c\ub9ac\uc790 \uae30\ud0c0 \ucc44\uad8c\uc790\ubcf4\ub2e4 \uc804\uc138\uae08\uc758 \uc6b0\uc120\ubcc0\uc81c\ub97c \ubc1b\uc744 \uad8c\ub9ac\uac00 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc804\uc138\uad8c\uc790\ub294 \uc804\uc138\uae08 \ubc18\ud658\uc774 \uc9c0\uccb4\ub41c \ub54c\uc5d0\ub294 \ubbfc\uc0ac\uc9d1\ud589\ubc95\uc774 \uc815\ud55c \ubc14\uc5d0 \ub530\ub77c \ubaa9\uc801\ubb3c\uc758 \uacbd\ub9e4\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4(\uc81c318\uc870).",B.a42,B.aw2,null)
B.atH=s(["\uc804\uc138\uad8c\uc774 \uc18c\uba78\ud55c \ub54c\uc5d0\ub294 \uc804\uc138\uad8c\uc124\uc815\uc790\ub294 \uc804\uc138\uae08\uc758 \ubc18\ud658\uacfc \ub3d9\uc2dc\uc5d0 \uc804\uc138\uad8c\uc758 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ubc1b\ub294\ub2e4","\uc804\uc138\uae08 \ubc18\ud658\uc740 \uc804\uc138\uad8c\uc124\uc815\ub4f1\uae30 \ub9d0\uc18c\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uc9c0 \uc54a\ub2e4","\uc804\uc138\uad8c\uc790\ub294 \uc804\uc138\uae08\uc744 \ubc18\ud658\ubc1b\uae30 \uc804\uc774\ub77c\ub3c4 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4\ub294 \ud56d\ubcc0\uc744 \ud560 \uc218 \uc5c6\ub2e4","\uc804\uc138\uad8c\uc124\uc815\uc790\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uacfc \uc804\uc138\uad8c\uc790\uc758 \uc804\uc138\uae08\ubc18\ud658\uccad\uad6c\uad8c\uc740 \ubcc4\uac1c\ub85c \uc544\ubb34 \uad00\ub828\uc774 \uc5c6\ub2e4"],t.s)
B.aQC=s(["\ubaa9\uc801\ubb3c \ubc18\ud658 \ubc0f \uc804\uc138\uad8c\uc124\uc815\ub4f1\uae30\uc758 \ub9d0\uc18c\uc5d0 \ud544\uc694\ud55c \uc11c\ub958\uc758 \uad50\ubd80\uc640 \uc804\uc138\uae08\uc758 \ubc18\ud658\uc740 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
