B.bDJ=new A.a("gen_cl_usufruct_19","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc758 \uc18c\uba78\uacfc \uc804\uc138\uae08 \ubc18\ud658\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.atH,0,"\ubbfc\ubc95 \uc81c317\uc870\ub294 \uc804\uc138\uad8c\uc774 \uc18c\uba78\ud55c \ub54c\uc5d0\ub294 \uc804\uc138\uad8c\uc124\uc815\uc790\ub294 \uc804\uc138\uad8c\uc790\ub85c\ubd80\ud130 \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc778\ub3c4\ubc1b\uc74c\uacfc \ub3d9\uc2dc\uc5d0 \uc804\uc138\uae08\uc744 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ubaa9\uc801\ubb3c \ubc18\ud658 \ubc0f \uc804\uc138\uad8c\uc124\uc815\ub4f1\uae30\uc758 \ub9d0\uc18c\uc5d0 \ud544\uc694\ud55c \uc11c\ub958\uc758 \uad50\ubd80\uc640 \uc804\uc138\uae08\uc758 \ubc18\ud658\uc740 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.aQC,B.aWP,null)
B.auS=s(["\uac74\ubb3c\uc758 \uc804\uc138\uad8c\uc124\uc815\uc790\uac00 \uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04 \ub9cc\ub8cc \uc804 6\uc6d4\ubd80\ud130 1\uc6d4\uae4c\uc9c0 \uc0ac\uc774\uc5d0 \uc804\uc138\uad8c\uc790\uc5d0 \ub300\ud558\uc5ec \uac31\uc2e0\uac70\uc808\uc758 \ud1b5\uc9c0 \ub610\ub294 \uc870\uac74\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uac31\uc2e0\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\ub294 \ud1b5\uc9c0\ub97c \ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc804\uc138\uad8c\uc740 \ub3d9\uc77c\ud55c \uc870\uac74\uc73c\ub85c \ub2e4\uc2dc \uc804\uc138\uad8c\uc744 \uc124\uc815\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubc95\uc815\uac31\uc2e0\uc774 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uadf8 \uc874\uc18d\uae30\uac04\uc740 \uc885\uc804\uacfc \ub3d9\uc77c\ud558\uac8c \uc815\ud558\uc5ec\uc9c4\ub2e4","\ubc95\uc815\uac31\uc2e0\uc740 \ud1a0\uc9c0\uc804\uc138\uad8c\uc5d0\ub9cc \uc778\uc815\ub418\uace0 \uac74\ubb3c\uc804\uc138\uad8c\uc5d0\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubc95\uc815\uac31\uc2e0 \uc2dc \uc804\uc138\uad8c\uc790\ub294 \uc804\uc138\uae08\uc744 \uc99d\uc561\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.a_o=s(["\uadf8 \uae30\uac04\uc774 \ub9cc\ub8cc\ub41c \ub54c\uc5d0 \uc804 \uc804\uc138\uad8c\uacfc \ub3d9\uc77c\ud55c \uc870\uac74\uc73c\ub85c \ub2e4\uc2dc \uc804\uc138\uad8c\uc744 \uc124\uc815\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uba70"],t.s)
