B.bBr=new A.a("gen_cl_usufruct_20","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04 \ub9cc\ub8cc \uc2dc \ubc95\uc815\uac31\uc2e0(\ubb35\uc2dc\uc758 \uac31\uc2e0)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.auS,0,"\ubbfc\ubc95 \uc81c312\uc870 \uc81c4\ud56d\uc740 \uac74\ubb3c\uc804\uc138\uad8c\uc5d0\uc11c \uc804\uc138\uad8c\uc124\uc815\uc790\uac00 \uc874\uc18d\uae30\uac04 \ub9cc\ub8cc \uc804 6\uc6d4\ubd80\ud130 1\uc6d4\uae4c\uc9c0 \uc0ac\uc774\uc5d0 \uac31\uc2e0\uac70\uc808 \ub610\ub294 \uc870\uac74\ubcc0\uacbd\uc758 \ud1b5\uc9c0\ub97c \ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \uae30\uac04\uc774 \ub9cc\ub8cc\ub41c \ub54c\uc5d0 \uc804 \uc804\uc138\uad8c\uacfc \ub3d9\uc77c\ud55c \uc870\uac74\uc73c\ub85c \ub2e4\uc2dc \uc804\uc138\uad8c\uc744 \uc124\uc815\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc774 \uacbd\uc6b0 \uadf8 \uc874\uc18d\uae30\uac04\uc740 \uc815\ud568\uc774 \uc5c6\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4.",B.a_o,B.aQK,null)
B.aQ2=s(["\ubc95\ub960 \u2192 \uad00\uc2b5\ubc95 \u2192 \uc870\ub9ac","\uad00\uc2b5\ubc95 \u2192 \ubc95\ub960 \u2192 \uc870\ub9ac","\uc870\ub9ac \u2192 \ubc95\ub960 \u2192 \uad00\uc2b5\ubc95","\ubc95\ub960 \u2192 \uc870\ub9ac \u2192 \uad00\uc2b5\ubc95"],t.s)
B.an0=s(["\ubbfc\uc0ac\uc5d0 \uad00\ud558\uc5ec \ubc95\ub960\uc5d0 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uace0 \uad00\uc2b5\ubc95\uc774 \uc5c6\uc73c\uba74 \uc870\ub9ac\uc5d0 \uc758\ud55c\ub2e4"],t.s)
B.b_7=s(["\ubbfc\ubc95 \uc81c1\uc870","\ubc95\uc6d0\uc758 \uc21c\uc11c"],t.s)
B.bCB=new A.a("gen_cl_source_1","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\ubbfc\ubc95 \uc81c1\uc870\uc5d0 \ub530\ub978 \ubc95\uc6d0(\u6cd5\u6e90)\uc758 \uc801\uc6a9 \uc21c\uc11c\ub85c \uc633\uc740 \uac83\uc740?",B.aQ2,0,'\ubbfc\ubc95 \uc81c1\uc870\ub294 "\ubbfc\uc0ac\uc5d0 \uad00\ud558\uc5ec \ubc95\ub960\uc5d0 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uace0 \uad00\uc2b5\ubc95\uc774 \uc5c6\uc73c\uba74 \uc870\ub9ac\uc5d0 \uc758\ud55c\ub2e4"\uace0 \uaddc\uc815\ud558\uc5ec, \ubc95\ub960\uc744 1\ucc28\uc801 \ubc95\uc6d0\uc73c\ub85c \ud558\uace0 \uad00\uc2b5\ubc95\uacfc \uc870\ub9ac\ub97c \ubcf4\ucda9\uc801 \ubc95\uc6d0\uc73c\ub85c \uc0bc\ub294\ub2e4. \uc989 \ubc95\ub960\uc758 \ud760\uacb0\uc774 \uc788\uc744 \ub54c \ube44\ub85c\uc18c \uad00\uc2b5\ubc95\uc774, \uad00\uc2b5\ubc95\ub3c4 \uc5c6\uc744 \ub54c \uc870\ub9ac\uac00 \uc801\uc6a9\ub41c\ub2e4.',B.an0,B.b_7,null)
B.a0u=s(["\uc0ac\ud68c\uad6c\uc131\uc6d0\uc758 \uacc4\uc18d\uc801 \uad00\ud589\uacfc \uadf8\uac83\uc774 \ubc95\uc801 \uaddc\ubc94\uc73c\ub85c\uc11c \uc2b9\uc778\ub420 \uc815\ub3c4\uc758 \uc0ac\ud68c\uc758 \ubc95\uc801 \ud655\uc2e0","\uad6d\ud68c\uc758 \uba85\uc2dc\uc801 \uc785\ubc95 \uc808\ucc28","\ud589\uc815\ubd80\uc758 \uace0\uc2dc \ub610\ub294 \ud6c8\ub839","\ub2f9\uc0ac\uc790 \uac04\uc758 \uac1c\ubcc4 \uc57d\uc815"],t.s)
B.aKp=s(["\uadf8 \uad00\ud589\uc774 \ubc95\uc801 \uaddc\ubc94\uc73c\ub85c\uc11c \uad6d\ubbfc\uc758 \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \uac15\ud589\ub418\uae30\uc5d0 \uc774\ub978 \uac83\uc774\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.a3G=s(["\uad00\uc2b5\ubc95","\ubc95\uc801 \ud655\uc2e0"],t.s)
B.bqp=new A.a("gen_cl_source_2","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad00\uc2b5\ubc95\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \ud310\ub840\uac00 \uc694\uad6c\ud558\ub294 \uac83\uc740?",B.a0u,0,"\ud310\ub840\ub294 \uad00\uc2b5\ubc95\uc774 \uc131\ub9bd\ud558\ub824\uba74 \uc5b4\ub5a4 \uc0ac\ud56d\uc5d0 \uad00\ud55c \uc0ac\ud68c\uc758 \uad00\ud589\uc774 \uacc4\uc18d\uc801\uc73c\ub85c \ubc18\ubcf5\ub418\uace0, \uadf8 \uad00\ud589\uc774 \ubc95\uc801 \uaddc\ubc94\uc73c\ub85c\uc11c \uad6d\ubbfc\uc758 \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \uac15\ud589\ub418\uae30\uc5d0 \uc774\ub978 \uac83\uc774\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \ub2e8\uc21c\ud55c \uad00\ud589\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \ubc95\uc801 \ud655\uc2e0\uc774\ub77c\ub294 \uc694\uac74\uc774 \uac16\ucd94\uc5b4\uc838\uc57c \uad00\uc2b5\ubc95\uc73c\ub85c \uc778\uc815\ub41c\ub2e4.",B.aKp,B.a3G,null)
B.aSX=s(["\uad00\uc2b5\ubc95\uc740 \ubc95\uc801 \ud655\uc2e0\uc744 \uc5bb\uc5b4 \ubc95\uc6d0\uc73c\ub85c\uc11c \ud6a8\ub825\uc744 \uac16\uc9c0\ub9cc, \uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ubc95\uc801 \ud655\uc2e0\uc5d0 \uc774\ub974\uc9c0 \ubabb\ud55c \uad00\ud589\uc73c\ub85c \ubc95\ub960\ud589\uc704 \ud574\uc11d\uc758 \uae30\uc900\uc774 \ub420 \ubfd0\uc774\ub2e4","\uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \uad00\uc2b5\ubc95\ubcf4\ub2e4 \uc0c1\uc704\uc758 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4","\uad00\uc2b5\ubc95\uacfc \uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ub3d9\uc77c\ud55c \uac1c\ub150\uc73c\ub85c \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc0ac\uc2e4\uc778 \uad00\uc2b5\uc740 \ubc95\uc6d0(\u6cd5\u9662)\uc758 \uc7ac\ud310\uc5d0 \uc758\ud574\uc11c\ub9cc \uc131\ub9bd\ud55c\ub2e4"],t.s)
