B.bSo=new A.a("gen_cl_source_8","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a1A,0,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc5d0\uc11c \ud30c\uc0dd\ub41c \ubc95\ub9ac\ub85c, \uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \uc0ac\uc815\ubcc0\uacbd\uc73c\ub85c \uc778\ud558\uc5ec \ub2f9\ucd08 \uc57d\uc815\ub41c \ub300\ub85c\uc758 \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc5d0\uac8c \uc2ec\ud788 \ubd80\ub2f9\ud55c \uacb0\uacfc\ub97c \ucd08\ub798\ud558\ub294 \uacbd\uc6b0, \uadf8 \uacc4\uc57d\uc758 \ub0b4\uc6a9\uc744 \uc218\uc815\ud558\uac70\ub098 \ud574\uc81c\xb7\ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\ub294 \uc6d0\uce59\uc774\ub2e4.",B.aMi,B.SX,null)
B.aUM=s(["\uc0ac\ubb3c\uc758 \ubcf8\uc9c8\uc801 \uc131\uc9c8 \ub0b4\uc9c0 \ub3c4\ub9ac\ub85c\uc11c, \ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \uc5c6\ub294 \uacbd\uc6b0 \uc7ac\ud310\uc758 \ucd5c\ud6c4 \uae30\uc900\uc774 \ub418\ub294 \ubcf4\ucda9\uc801 \ubc95\uc6d0","\uad6d\ud68c\uac00 \uc81c\uc815\ud55c \uc131\ubb38\uc758 \ubc95\ub960\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc758 \uac1c\ubcc4\uc801 \ud569\uc758\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc678\uad6d\uc758 \ud310\ub840\ub97c \uadf8\ub300\ub85c \uc801\uc6a9\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.aSH=s(["\ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \ubc95\uad00\uc774 \uc7ac\ud310\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294 \ucd5c\ud6c4\xb7\ubcf4\ucda9\uc801 \ubc95\uc6d0"],t.s)
