B.br5=new A.a("gen_cl_source_9","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,'\ubbfc\ubc95 \uc81c1\uc870\uc5d0\uc11c \ub9d0\ud558\ub294 "\uc870\ub9ac"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aUM,0,"\uc870\ub9ac\ub780 \uc0ac\ubb3c\uc758 \ubcf8\uc9c8\uc801 \ubc95\uce59 \ub0b4\uc9c0 \uc0ac\ubb3c\uc758 \ub3c4\ub9ac\ub97c \uc758\ubbf8\ud558\uba70, \ubbfc\ubc95 \uc81c1\uc870\uc5d0 \ub530\ub77c \ubc95\ub960\uacfc \uad00\uc2b5\ubc95\uc774 \ubaa8\ub450 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \ubc95\uad00\uc774 \uc7ac\ud310\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294 \ucd5c\ud6c4\xb7\ubcf4\ucda9\uc801 \ubc95\uc6d0\uc774\ub2e4. \uc870\ub9ac\ub294 \ubc95\uad00\uc758 \uc790\uc758\uc801 \ud310\ub2e8\uc774 \uc544\ub2c8\ub77c \uc0ac\ud68c\ud1b5\ub150\uc5d0 \ubd80\ud569\ud558\ub294 \ud569\ub9ac\uc801 \uae30\uc900\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aSH,B.XG,null)
B.a2A=s(["\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uc5d0 \ub300\ud558\uc5ec \ubcf4\ucda9\uc801 \ud6a8\ub825\uc744 \uac00\uc9c8 \ubfd0\uc774\uace0, \ubc95\ub960\uc5d0 \uc800\ucd09\ub418\ub294 \uad00\uc2b5\ubc95\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\ubcf4\ub2e4 \ud56d\uc0c1 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uacfc \ub3d9\ub4f1\ud55c \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc2e0\ubc95\uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4","\uad00\uc2b5\ubc95\uc740 \ubc95\ub960\uc758 \uac1c\uc815\uc774 \uc788\uc5b4\ub3c4 \uadf8 \ud6a8\ub825\uc774 \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.RS=s(["\uad00\uc2b5\ubc95\uc740 \uc131\ubb38\uc758 \ubc95\ub960\uc774 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \uc774\ub97c \ubcf4\ucda9\ud558\ub294 \ud6a8\ub825\ub9cc\uc744 \uac00\uc9c0\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4(\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124)"],t.s)
B.aWK=s(["\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124","\uad00\uc2b5\ubc95\uacfc \ubc95\ub960"],t.s)
B.boR=new A.a("gen_cl_source_10","civil_law","\ubbfc\ubc95\uc758 \ubc95\uc6d0(\u6cd5\u6e90)",null,"\uad00\uc2b5\ubc95\uacfc \uc131\ubb38\ubc95(\ubc95\ub960)\uc758 \ud6a8\ub825\uad00\uacc4\uc5d0 \uad00\ud55c \ud1b5\uc124\uc801 \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2A,0,"\ud1b5\uc124\uc740 \ubbfc\ubc95 \uc81c1\uc870\uc758 \ubc95\uc6d0 \uc21c\uc11c\uc5d0 \ub530\ub77c \uad00\uc2b5\ubc95\uc740 \uc131\ubb38\uc758 \ubc95\ub960\uc774 \ud760\uacb0\ub41c \uacbd\uc6b0\uc5d0 \uc774\ub97c \ubcf4\ucda9\ud558\ub294 \ud6a8\ub825\ub9cc\uc744 \uac00\uc9c0\ub294 \uac83\uc73c\ub85c \ubcf8\ub2e4(\ubcf4\ucda9\uc801 \ud6a8\ub825\uc124). \ub530\ub77c\uc11c \ubc95\ub960\uc5d0 \uba85\ubb38\uc758 \uaddc\uc815\uc774 \uc788\ub294 \uc0ac\ud56d\uc5d0 \uad00\ud558\uc5ec\ub294 \uadf8\uc640 \ubc30\uce58\ub418\ub294 \uad00\uc2b5\ubc95\uc774 \uc6b0\uc120 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4.",B.RS,B.aWK,null)
B.aD2=s(["\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc774 \uad8c\ub9ac\ud589\uc0ac\uc758 \uad6d\uba74\uc5d0\uc11c \uad6c\uccb4\ud654\ub41c \ud558\ub098\uc758 \ud30c\uc0dd \uc6d0\uce59\uc774\ub2e4","\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uacfc \ubb34\uad00\ud55c \ub3c5\ub9bd\ub41c \ubcc4\uac1c\uc758 \ubc95\uc6d0(\u6cd5\u6e90)\uc774\ub2e4","\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \ucc44\uad8c\uad00\uacc4\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\ub294 \ubb3c\uad8c\uad00\uacc4\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uad8c\ub9ac\ub0a8\uc6a9\uae08\uc9c0\uc758 \uc6d0\uce59\uc774 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\ubcf4\ub2e4 \uc0c1\uc704\uc758 \uc77c\ubc18\uc6d0\uce59\uc774\ub2e4"],t.s)
B.aei=s(["\uad8c\ub9ac\ud589\uc0ac\uc758 \uad6d\uba74\uc5d0\uc11c \uc2e0\uc758\uce59\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ubc1c\ud604\ub41c \ud30c\uc0dd \uc6d0\uce59\uc73c\ub85c \uc774\ud574\ub41c\ub2e4"],t.s)
