B.bP1=new A.a("gen_cl_contractgen_23","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c552\uc870(\ucd5c\uace0\uad8c)\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Wh,0,"\ubbfc\ubc95 \uc81c552\uc870\ub294 \ud574\uc81c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0 \uc0c1\ub300\ubc29\uc740 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ud574\uc81c\uad8c \ud589\uc0ac \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ud574\uc81c\uad8c\uc790\uc5d0\uac8c \ucd5c\uace0\ud560 \uc218 \uc788\uace0, \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud574\uc81c\uc758 \ud1b5\uc9c0\ub97c \ubc1b\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc0c1\ub300\ubc29\uc744 \ubd88\ud655\uc815\ud55c \ubc95\ub960\uad00\uacc4\ub85c\ubd80\ud130 \ubc97\uc5b4\ub098\uac8c \ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4.",B.a_K,B.Xh,null)
B.aUN=s(["\ud574\uc81c\uad8c\uc758 \ud589\uc0ac\uc5d0 \uc788\uc5b4\uc11c \uc0c1\ub300\ubc29\uc73c\ub85c\ubd80\ud130 \ubc18\ud658\ubc1b\uc744 \ubb3c\uac74\uc774 \ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c \ub610\ub294 \uac00\uacf5\uc774\ub098 \uac1c\uc870\ub85c \uc778\ud558\uc5ec \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ubaa9\uc801\ubb3c\uc758 \ud6fc\uc190 \uc5ec\ubd80\ub294 \ud574\uc81c\uad8c \uc18c\uba78\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc790\uc758 \uacbd\uacfc\uc2e4\ub85c \ubaa9\uc801\ubb3c\uc774 \uba78\uc2e4\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c \uc18c\uba78\uc0ac\uc720\ub294 \uc624\uc9c1 \uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0 \uc758\ud55c \uacbd\uc6b0\ubfd0\uc774\ub2e4"],t.s)
B.aGy=s(["\ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc774 \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub418\uac70\ub098 \uac00\uacf5\xb7\uac1c\uc870\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.XJ=s(["\ud574\uc81c\uad8c \uc18c\uba78","\ubaa9\uc801\ubb3c \ud6fc\uc190","\uc81c553\uc870"],t.s)
B.bpB=new A.a("gen_cl_contractgen_24","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc0ac\uc720(\ubbfc\ubc95 \uc81c553\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUN,0,"\ubbfc\ubc95 \uc81c553\uc870\ub294 \ud574\uc81c\uad8c\uc790\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc774 \ud604\uc800\ud788 \ud6fc\uc190\ub418\uac70\ub098 \ubc18\ud658\ud560 \uc218 \uc5c6\uac8c \ub418\uac70\ub098 \uac00\uacf5\xb7\uac1c\uc870\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ub41c \ub54c\uc5d0\ub294 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ud574\uc81c\uad8c\uc790\uac00 \uc6d0\uc0c1\ud68c\ubcf5\uc744 \uc2a4\uc2a4\ub85c \ubd88\uac00\ub2a5\ud558\uac8c \ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c \ud589\uc0ac\ub97c \uc81c\ud55c\ud558\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.aGy,B.XJ,null)
B.bbF=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\uacc4\uc57d\uc758 \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\ub97c \uac00\uc9c0\ubbc0\ub85c \uc774\ubbf8 \uc774\ud589\ub41c \uae09\ubd80\ub3c4 \ubaa8\ub450 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\uace0 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.ZQ=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aLn=s(["\ud574\uc9c0\uc758 \uc7a5\ub798\ud6a8","\uc81c550\uc870"],t.s)
B.bCH=new A.a("gen_cl_contractgen_25","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uc758 \ud574\uc9c0(\ubbfc\ubc95 \uc81c550\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bbF,0,"\ubbfc\ubc95 \uc81c550\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud55c \ub54c\uc5d0\ub294 \uacc4\uc57d\uc740 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9\xb7\uc704\uc784 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \uc778\uc815\ub418\ub294 \uac83\uc73c\ub85c, \ud574\uc81c\uc640 \ub2ec\ub9ac \uc18c\uae09\ud6a8\uac00 \uc5c6\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \uc544\ub2cc \uccad\uc0b0\uad00\uacc4\ub9cc \ubc1c\uc0dd\ud55c\ub2e4.",B.ZQ,B.aLn,null)
B.apw=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\uc5b4 \uacc4\uc57d\uc774 \ucc98\uc74c\ubd80\ud130 \uc5c6\uc5c8\ub358 \uac83\uacfc \uac19\uc740 \uc0c1\ud0dc\ub85c \ub418\ub098, \ud574\uc9c0\ub294 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ud574\uc81c\ub294 \uc77c\uc2dc\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c, \ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c \uc8fc\ub85c \ubb38\uc81c\ub41c\ub2e4","\ud574\uc81c\uc758 \uacbd\uc6b0 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub098, \ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub294 \uccad\uc0b0\uc758\ubb34\ub9cc \ubb38\uc81c\ub420 \ubfd0 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uc640 \ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.arP=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \ubc18\uba74 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uccad\uc0b0\uad00\uacc4\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.aPL=s(["\ud574\uc81c\uc640 \ud574\uc9c0\uc758 \uad6c\ubcc4","\uc18c\uae09\ud6a8\uc640 \uc7a5\ub798\ud6a8"],t.s)
B.bCc=new A.a("gen_cl_contractgen_26","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uc640 \ud574\uc9c0\uc758 \ucc28\uc774\uc810\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.apw,3,"\ud574\uc81c\ub294 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \ubc18\uba74 \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uc5b4 \uccad\uc0b0\uad00\uacc4\ub9cc \ubb38\uc81c\ub41c\ub2e4. \ub2e4\ub9cc \ubbfc\ubc95 \uc81c551\uc870\ub294 \ud574\uc81c\ubfd0 \uc544\ub2c8\ub77c \uc81c550\uc870\uac00 \uc900\uc6a9\ud558\ub294 \ubc14\uc5d0 \ub530\ub77c \ud574\uc9c0\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc544 \uc774 \ubd80\ubd84\uc740 \ud574\uc81c\xb7\ud574\uc9c0\uac00 \uacf5\ud1b5\ub41c\ub2e4. \ub530\ub77c\uc11c \ud574\uc81c\uc640 \ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc11c\uc220 \uc790\uccb4\ub294 \uc633\uc73c\ub098, \ubb38\ud56d\uc740 \ucc28\uc774\uc810\uc744 \ubb3b\ub294 \uac83\uc774\ubbc0\ub85c \uc774\ub294 \ucc28\uc774\uc810\uc774 \uc544\ub2cc \uacf5\ud1b5\uc810\uc5d0 \ud574\ub2f9\ud558\uc5ec \uc624\ub2f5\uc774\ub2e4.",B.arP,B.aPL,null)
B.a7l=s(["\ud574\uc81c\uc870\uac74\uc740 \uc870\uac74\uc131\ucde8\ub85c \ub2f9\uc5f0\ud788 \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud558\ub294 \uac83\uc774\ub098, \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \ud574\uc81c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \ubaa8\ub450 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uc774 \uc131\ucde8\ub418\uc5b4\ub3c4 \ubcc4\ub3c4\ub85c \ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc5ec\uc57c \uacc4\uc57d\uc774 \uc18c\uba78\ud55c\ub2e4","\uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uc870\uac74\uc131\ucde8\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.aLY=s(["\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \ubbfc\ubc95 \uc81c147\uc870\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \uc131\ucde8\ub41c \ub54c\ub85c\ubd80\ud130 \ub2f9\uc5f0\ud788 \uadf8 \ud6a8\ub825\uc744 \uc783\ub294 \ubc18\uba74"],t.s)
B.b8K=s(["\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uc758 \uad6c\ubcc4"],t.s)
B.bNK=new A.a("gen_cl_contractgen_27","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uc870\uac74\ubd80 \uacc4\uc57d\uacfc \uacc4\uc57d\uc758 \ud574\uc81c\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7l,0,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \ubbfc\ubc95 \uc81c147\uc870\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \uc131\ucde8\ub41c \ub54c\ub85c\ubd80\ud130 \ub2f9\uc5f0\ud788 \uadf8 \ud6a8\ub825\uc744 \uc783\ub294 \ubc18\uba74, \uacc4\uc57d\uc758 \ud574\uc81c(\uc81c543\uc870)\ub294 \ud574\uc81c\uad8c\uc790\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\ub294 \ud615\uc131\uad8c \ud589\uc0ac\uc774\ub2e4. \uc591\uc790\ub294 \ubc95\uc801 \uc131\uc9c8\uacfc \ud6a8\ub825\ubc1c\uc0dd\uc694\uac74\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4.",B.aLY,B.b8K,null)
B.XF=s(["\ud569\uc758\ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc0c8\ub85c\uc6b4 \uacc4\uc57d\uc5d0 \uc758\ud558\uc5ec \uae30\uc874 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774\ub2e4","\ud569\uc758\ud574\uc81c\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\uc815\ud574\uc81c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c548\uc870 \uc81c2\ud56d\uc758 \uc774\uc790 \uac00\uc0b0 \uaddc\uc815\uc774 \ub2f9\uc5f0\ud788 \uc801\uc6a9\ub41c\ub2e4","\ud569\uc758\ud574\uc81c\uc758 \uacbd\uc6b0 \ubcc4\ub3c4\uc758 \uc57d\uc815\uc774 \uc5c6\ub294 \ud55c \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud569\uc758\ud574\uc81c\ub3c4 \ud574\uc81c\uc774\ubbc0\ub85c \uc81c3\uc790\uc758 \uad8c\ub9ac\ub97c \ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4\ub294 \ubc95\ub9ac\uac00 \uc720\ucd94\uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aK8=s(["\ud310\ub840\ub294 \ud569\uc758\ud574\uc81c\uc758 \uacbd\uc6b0 \ubc95\uc815\ud574\uc81c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c548\uc870 \uc81c2\ud56d\uc758 \uc774\uc790 \uac00\uc0b0 \uaddc\uc815\uc774 \ub2f9\uc5f0\ud788 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uace0"],t.s)
B.a7S=s(["\ud569\uc758\ud574\uc81c","\uc774\uc790\uac00\uc0b0 \ubbf8\uc801\uc6a9"],t.s)
B.bPC=new A.a("gen_cl_contractgen_28","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud569\uc758\ud574\uc81c(\ud569\uc758\ud574\uc9c0)\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.XF,1,"\ud310\ub840\ub294 \ud569\uc758\ud574\uc81c\uc758 \uacbd\uc6b0 \ubc95\uc815\ud574\uc81c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c548\uc870 \uc81c2\ud56d\uc758 \uc774\uc790 \uac00\uc0b0 \uaddc\uc815\uc774 \ub2f9\uc5f0\ud788 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub2e4\ub978 \uc57d\uc815\uc774 \uc788\uc73c\uba74 \uadf8\uc5d0 \ub530\ub978\ub2e4\uace0 \ubcf8\ub2e4. \ub610\ud55c \ud569\uc758\ud574\uc81c \uc2dc \ubcc4\ub3c4 \uc57d\uc815\uc774 \uc5c6\ub294 \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aK8,B.a7S,null)
B.adM=s(["\uc784\ub300\ucc28, \uace0\uc6a9, \uc704\uc784 \ub4f1 \uacc4\uc18d\uc801 \ucc44\uad8c\uad00\uacc4\uc5d0\uc11c\ub294 \ub2f9\uc0ac\uc790 \uac04 \uc2e0\ub8b0\uad00\uacc4\uac00 \ud30c\uad34\ub41c \uacbd\uc6b0 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\ub85c \uc778\ud55c \ud574\uc9c0\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud574\uc9c0\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc704\uc784\uacc4\uc57d\uc740 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uace0\uc6a9\uacc4\uc57d\uc740 \uae30\uac04\uc758 \uc57d\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uc784\uc758\ub85c \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a17=s(["\ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0 \ud310\ub840\uc0c1 \ud574\uc9c0\uad8c\uc774 \uc778\uc815\ub41c\ub2e4"],t.s)
B.a1W=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4","\ud574\uc9c0\uad8c","\uc2e0\ub8b0\uad00\uacc4 \ud30c\uad34"],t.s)
B.bt3=new A.a("gen_cl_contractgen_29","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c \ud574\uc9c0\uad8c \ubc1c\uc0dd\uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.adM,0,"\uc784\ub300\ucc28\xb7\uace0\uc6a9\xb7\uc704\uc784 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub294 \ub2f9\uc0ac\uc790 \uac04 \uc2e0\ub8b0\uad00\uacc4\ub97c \uae30\ucd08\ub85c \ud558\ubbc0\ub85c, \uc2e0\ub8b0\uad00\uacc4\uac00 \ud30c\uad34\ub418\ub294 \ub4f1 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0 \ud310\ub840\uc0c1 \ud574\uc9c0\uad8c\uc774 \uc778\uc815\ub41c\ub2e4. \ubbfc\ubc95 \uc81c689\uc870\ub294 \uc704\uc784\uacc4\uc57d\uc758 \uacbd\uc6b0 \uac01 \ub2f9\uc0ac\uc790\uac00 \uc5b8\uc81c\ub4e0\uc9c0 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc774\ub7ec\ud55c \uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud2b9\uc131\uc744 \ubc18\uc601\ud55c\ub2e4.",B.a17,B.a1W,null)
B.aTe=s(["\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uacc4\uc57d\ud574\uc81c \uc2dc \uc190\ud574\ubc30\uc0c1\uc561\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ud589\uc774\uc775\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4","\ud574\uc81c \uc2dc \uc190\ud574\ubc30\uc0c1\uc561\uc740 \ubc18\ub4dc\uc2dc \uc2e0\ub8b0\uc774\uc775\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc81c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud568\uc744 \uc804\uc81c\ub85c \ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc774\ud589\uc774\uc775 \uc0b0\uc815\uc774 \ubd88\uac00\ub2a5\ud558\ub2e4","\ud574\uc81c \ud6c4\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uc190\ud574\ubc30\uc0c1\ub3c4 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aFs=s(["\uadf8 \uc190\ud574\ubc30\uc0c1\uc561\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uacc4\uc57d\uc774 \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \uc5bb\uc5c8\uc744 \uc774\uc775, \uc989 \uc774\ud589\uc774\uc775\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aFT=s(["\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc561","\uc774\ud589\uc774\uc775 \uae30\uc900"],t.s)
B.bwb=new A.a("gen_cl_contractgen_30","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ud574\uc81c\uc758 \ud6a8\uacfc\ub85c\uc11c \uc190\ud574\ubc30\uc0c1\uc561 \uc0b0\uc815 \uae30\uc900\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.aTe,0,"\ud310\ub840\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uacc4\uc57d\uc744 \ud574\uc81c\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubbfc\ubc95 \uc81c551\uc870\uc5d0 \ub530\ub77c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uace0, \uadf8 \uc190\ud574\ubc30\uc0c1\uc561\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uacc4\uc57d\uc774 \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \uc5bb\uc5c8\uc744 \uc774\uc775, \uc989 \uc774\ud589\uc774\uc775\uc744 \uae30\uc900\uc73c\ub85c \uc0b0\uc815\ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc774\ub294 \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc5d0 \ub530\ub978 \uacc4\uc57d\uccb4\uacb0\uc0c1 \uacfc\uc2e4\ucc45\uc784\uc758 \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\uacfc \uad6c\ubcc4\ub41c\ub2e4.",B.aFs,B.aFT,null)
B.ah2=s(["\uc0ac\ub78c\uc740 \uc0dd\uc874\ud55c \ub3d9\uc548 \uad8c\ub9ac\uc640 \uc758\ubb34\uc758 \uc8fc\uccb4\uac00 \ub41c\ub2e4.","\ud0dc\uc544\ub294 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc5d0 \uad00\ud558\uc5ec\ub294 \uc774\ubbf8 \ucd9c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud0dc\uc544\ub294 \uc0c1\uc18d\uc5d0 \uad00\ud558\uc5ec\ub294 \uc774\ubbf8 \ucd9c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud0dc\uc544\ub294 \uc0b4\uc544\uc11c \ud0dc\uc5b4\ub098\uae30 \uc804\uc774\ub77c\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc744 \ud1b5\ud574 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub97c \ub300\ub9ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.ajN=s(["\uac1c\ubcc4 \uaddc\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \uc774\ubbf8 \ucd9c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4(\uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758)"],t.s)
B.abZ=s(["\ud0dc\uc544\uc758 \uad8c\ub9ac\ub2a5\ub825","\uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758","\ubbfc\ubc95 \uc81c3\uc870"],t.s)
B.bxn=new A.a("gen_cl_capacity_1","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc790\uc5f0\uc778\uc758 \uad8c\ub9ac\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ah2,3,"\ubbfc\ubc95 \uc81c3\uc870\ub294 \uc0ac\ub78c\uc740 \uc0dd\uc874\ud55c \ub3d9\uc548 \uad8c\ub9ac\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ud0dc\uc544\ub294 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c(\uc81c762\uc870)\uacfc \uc0c1\uc18d(\uc81c1000\uc870 \uc81c3\ud56d) \ub4f1 \uac1c\ubcc4 \uaddc\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \uc774\ubbf8 \ucd9c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4(\uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758). \ud0dc\uc544 \uc790\uccb4\ub294 \uc544\uc9c1 \uad8c\ub9ac\ub2a5\ub825\uc774 \uc5c6\uc73c\ubbc0\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ud0dc\uc544\ub97c \ub300\ub9ac\ud558\uc5ec \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.ajN,B.abZ,null)
B.ar4=s(["\ubcf4\ud1b5\uc2e4\uc885\uc758 \uacbd\uc6b0 \uc2e4\uc885\uae30\uac04\uc740 5\ub144\uc774\ub2e4.","\ud2b9\ubcc4\uc2e4\uc885(\uc804\uc7c1\xb7\uc120\ubc15\uce68\ubab0 \ub4f1)\uc758 \uacbd\uc6b0 \uc2e4\uc885\uae30\uac04\uc740 1\ub144\uc774\ub2e4.","\uc2e4\uc885\uc120\uace0\ub97c \ubc1b\uc740 \uc790\ub294 \uc2e4\uc885\uae30\uac04\uc774 \ub9cc\ub8cc\ud55c \ub54c\uc5d0 \uc0ac\ub9dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uc2e4\uc885\uc120\uace0\uac00 \ucde8\uc18c\ub418\uba74 \uadf8 \uc120\uace0\ub97c \uc9c1\uc811 \uc6d0\uc778\uc73c\ub85c \ud558\uc5ec \uc7ac\uc0b0\uc744 \ucde8\ub4dd\ud55c \uc790\ub294 \uc5b8\uc81c\ub098 \ud604\uc874\uc774\uc775 \uc720\ubb34\uc640 \uad00\uacc4\uc5c6\uc774 \ucde8\ub4dd\ud55c \uc7ac\uc0b0 \uc804\ubd80\ub97c \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.b0U=s(["\uc120\uc758\ub85c \uc7ac\uc0b0\uc744 \ucde8\ub4dd\ud55c \uc790\ub294 \uadf8 \ud604\uc874\uc774\uc775\uc758 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.b3_=s(["\uc2e4\uc885\uc120\uace0","\uc2e4\uc885\uae30\uac04","\ud604\uc874\uc774\uc775 \ubc18\ud658"],t.s)
B.bKg=new A.a("gen_cl_capacity_2","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc2e4\uc885\uc120\uace0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ar4,3,"\ubbfc\ubc95 \uc81c27\uc870\ub294 \ubcf4\ud1b5\uc2e4\uc885 5\ub144, \ud2b9\ubcc4\uc2e4\uc885 1\ub144\uc758 \uc2e4\uc885\uae30\uac04\uc744 \uaddc\uc815\ud558\uace0, \uc81c28\uc870\ub294 \uc2e4\uc885\uae30\uac04 \ub9cc\ub8cc \uc2dc \uc0ac\ub9dd\ud55c \uac83\uc73c\ub85c \uc758\uc81c\ud55c\ub2e4. \uc2e4\uc885\uc120\uace0\uac00 \ucde8\uc18c\ub41c \uacbd\uc6b0 \uc81c29\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc120\uc758\ub85c \uc7ac\uc0b0\uc744 \ucde8\ub4dd\ud55c \uc790\ub294 \uadf8 \ud604\uc874\uc774\uc775\uc758 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc744 \uc9c4\ub2e4.",B.b0U,B.b3_,null)
B.aSs=s(["\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubc95\ub960\ud589\uc704\ub294 \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\ub2e4.","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\uace0, \ub3d9\uc758 \uc5c6\uc774 \ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.","\uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4.","\ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc758\uc81c\uac00 \ub418\ub354\ub77c\ub3c4 \ud63c\uc778 \uc804\uc758 \ubc95\ub960\ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4."],t.s)
B.a7W=s(["\ub3d9\uc758\ub97c \uc5bb\uc9c0 \uc544\ub2c8\ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c5\uc870 \uc81c2\ud56d)"],t.s)
B.amk=s(["\ubbf8\uc131\ub144\uc790","\ubc95\uc815\ub300\ub9ac\uc778 \ub3d9\uc758","\ucde8\uc18c\uad8c"],t.s)
B.bAV=new A.a("gen_cl_capacity_3","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aSs,1,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ubbf8\uc131\ub144\uc790\uac00 \ubc95\ub960\ud589\uc704\ub97c \ud568\uc5d0\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \ud558\uba70, \ub3d9\uc758\ub97c \uc5bb\uc9c0 \uc544\ub2c8\ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c5\uc870 \uc81c2\ud56d). \ub2e4\ub9cc \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub294 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc720\ud6a8\ud558\ub2e4(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c). \ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc790\ub85c \uc758\uc81c\ub418\uc5b4(\uc81c826\uc870\uc7582) \uadf8 \uc774\ud6c4 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4.",B.a7W,B.amk,null)
B.axA=s(["\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc740 \uc9c8\ubcd1, \uc7a5\uc560, \ub178\ub839 \ub4f1\uc73c\ub85c \uc0ac\ubb34\ucc98\ub9ac\ub2a5\ub825\uc774 \uc9c0\uc18d\uc801\uc73c\ub85c \uacb0\uc5ec\ub41c \uc0ac\ub78c\uc5d0 \ub300\ud574 \uac00\uc815\ubc95\uc6d0\uc758 \uc2ec\ud310\uc73c\ub85c \uac1c\uc2dc\ub41c\ub2e4.","\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.","\uac00\uc815\ubc95\uc6d0\uc740 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc758 \ubc95\ub960\ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud560 \uc218 \uc788\ub2e4.","\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.aEf=s(["\uac00\uc815\ubc95\uc6d0\uc774 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud560 \uc218 \uc788\uace0"],t.s)
B.aFp=s(["\ud53c\uc131\ub144\ud6c4\uacac\uc778","\ucde8\uc18c\uad8c","\uc77c\uc0c1\ud589\uc704"],t.s)
B.btQ=new A.a("gen_cl_capacity_4","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ud53c\uc131\ub144\ud6c4\uacac\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.axA,3,"\ubbfc\ubc95 \uc81c9\uc870\uc5d0 \ub530\ub77c \ud53c\uc131\ub144\ud6c4\uacac\uc778\uc740 \uc0ac\ubb34\ucc98\ub9ac\ub2a5\ub825\uc774 \uc9c0\uc18d\uc801\uc73c\ub85c \uacb0\uc5ec\ub41c \uc0ac\ub78c\uc5d0 \ub300\ud558\uc5ec \uac00\uc815\ubc95\uc6d0\uc758 \uc2ec\ud310\uc73c\ub85c \uac1c\uc2dc\ub418\uace0, \uc81c10\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uadf8 \ubc95\ub960\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc81c10\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uac00\uc815\ubc95\uc6d0\uc774 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud560 \uc218 \uc788\uace0, \uc81c10\uc870 \uc81c4\ud56d\uc758 \uc77c\uc6a9\ud488 \uad6c\uc785 \ub4f1 \uc77c\uc0c1\uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ud589\uc704\ub294 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\ub2e4.",B.aEf,B.aFp,null)
B.aNm=s(["\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud589\uc704\ub2a5\ub825\uc774 \uc81c\ud55c\ub418\uc9c0 \uc54a\uc73c\uba70, \uac00\uc815\ubc95\uc6d0\uc774 \ud55c\uc815\ud6c4\uacac\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\ub3c4\ub85d \uc815\ud55c \ud589\uc704\uc5d0 \ud55c\ud558\uc5ec \ub3d9\uc758 \uc5c6\uc774 \ud558\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.","\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc758 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub294 \ud55c\uc815\ud6c4\uacac\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4.","\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc740 \uc131\ub144\ud6c4\uacac\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \ud589\uc704\ub2a5\ub825\uc774 \uc804\uba74 \ubd80\uc815\ub41c\ub2e4.","\ud55c\uc815\ud6c4\uacac\uc778\uc740 \ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud574 \ub3d9\uc758\uad8c\uc744 \uac00\uc9c8 \uc218 \uc5c6\ub2e4."],t.s)
B.aiu=s(["\uac00\uc815\ubc95\uc6d0\uc774 \ud55c\uc815\ud6c4\uacac\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c \ud558\ub294 \ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud55c \uacbd\uc6b0"],t.s)
B.Uy=s(["\ud53c\ud55c\uc815\ud6c4\uacac\uc778","\ub3d9\uc758\uc720\ubcf4","\uc81c13\uc870"],t.s)
B.bIq=new A.a("gen_cl_capacity_5","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNm,0,"\ubbfc\ubc95 \uc81c12\uc870 \ubc0f \uc81c13\uc870\uc5d0 \ub530\ub77c \ud53c\ud55c\uc815\ud6c4\uacac\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c0\uba70, \uac00\uc815\ubc95\uc6d0\uc774 \ud55c\uc815\ud6c4\uacac\uc778\uc758 \ub3d9\uc758\ub97c \ubc1b\uc544\uc57c \ud558\ub294 \ud589\uc704\uc758 \ubc94\uc704\ub97c \uc815\ud55c \uacbd\uc6b0 \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4. \uc774 \ubc94\uc704\ub97c \ub118\uc5b4 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c13\uc870 \uc81c4\ud56d).",B.aiu,B.Uy,null)
B.b1d=s(["\ud2b9\uc815\ud6c4\uacac\uc740 \uc815\uc2e0\uc801 \uc81c\uc57d\uc73c\ub85c \uc77c\uc2dc\uc801 \ud6c4\uc6d0 \ub610\ub294 \ud2b9\uc815 \uc0ac\ubb34\uc5d0 \uad00\ud55c \ud6c4\uc6d0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0 \ub300\ud558\uc5ec \uac1c\uc2dc\ub41c\ub2e4.","\ud2b9\uc815\ud6c4\uacac\uc758 \uc2ec\ud310\uc740 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \ud560 \uc218 \uc5c6\ub2e4.","\ud2b9\uc815\ud6c4\uacac\uc740 \ubcf8\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \uc81c\ud55c\ud558\ub294 \ud6a8\uacfc\ub97c \ubc1c\uc0dd\uc2dc\ud0a8\ub2e4.","\uac00\uc815\ubc95\uc6d0\uc740 \ud2b9\uc815\ud6c4\uacac\uc758 \uc2ec\ud310\uc744 \ud558\ub294 \uacbd\uc6b0 \uae30\uac04\uc774\ub098 \uc0ac\ubb34\uc758 \ubc94\uc704\ub97c \uc815\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.b9y=s(["\ubcf8\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \uc81c\ud55c\ud558\uc9c0 \uc54a\uace0"],t.s)
B.a0m=s(["\ud53c\ud2b9\uc815\ud6c4\uacac\uc778","\ud589\uc704\ub2a5\ub825 \uc81c\ud55c \uc5c6\uc74c","\uc81c14\uc870\uc7582"],t.s)
B.bxd=new A.a("gen_cl_capacity_6","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ud53c\ud2b9\uc815\ud6c4\uacac\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b1d,2,"\ubbfc\ubc95 \uc81c14\uc870\uc7582\uc5d0 \ub530\ub77c \ud2b9\uc815\ud6c4\uacac\uc740 \uc77c\uc2dc\uc801 \ud6c4\uc6d0 \ub610\ub294 \ud2b9\uc815 \uc0ac\ubb34\uc5d0 \uad00\ud55c \ud6c4\uc6d0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0 \ub300\ud574 \uac1c\uc2dc\ub418\uba70 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \ud560 \uc218 \uc5c6\ub2e4. \ud2b9\uc815\ud6c4\uacac\uc740 \uc131\ub144\ud6c4\uacac\xb7\ud55c\uc815\ud6c4\uacac\uacfc \ub2ec\ub9ac \ubcf8\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc744 \uc81c\ud55c\ud558\uc9c0 \uc54a\uace0, \uac00\uc815\ubc95\uc6d0\uc740 \ud2b9\uc815\ud6c4\uacac\uc758 \uae30\uac04 \ub610\ub294 \uc0ac\ubb34\uc758 \ubc94\uc704\ub97c \uc815\ud558\uc5ec\uc57c \ud55c\ub2e4(\uc81c14\uc870\uc7582 \uc81c3\ud56d).",B.b9y,B.a0m,null)
B.aBf=s(["\uc0c1\ub300\ubc29\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub2a5\ub825\uc790\uac00 \ub41c \ud6c4 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc544\uc9c1 \ub2a5\ub825\uc790\uac00 \ub418\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub2e4.","\ud655\ub2f5\ucd09\uad6c\ub97c \ubc1b\uc740 \uc790\uac00 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud2b9\ubcc4\ud55c \uc808\ucc28\ub97c \uc694\ud558\ub294 \ud589\uc704\uc5d0 \ub300\ud574 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ubc1f\uc740 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4."],t.s)
B.b4I=s(["\uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
