B.bDI=new A.a("gen_cl_capacity_8","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc758 \ucca0\ud68c\uad8c\uacfc \uac70\uc808\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bbB,0,"\ubbfc\ubc95 \uc81c16\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc81c\ud55c\ub2a5\ub825\uc790\uc640 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uc0c1\ub300\ubc29\uc740 \uadf8 \uc0c1\ub300\ubc29\uc774 \uacc4\uc57d \ub2f9\uc2dc \uc81c\ud55c\ub2a5\ub825\uc790\uc784\uc744 \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0(\uc120\uc758)\uc5d0 \ud55c\ud574, \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4. \ub2e8\ub3c5\ud589\uc704\uc758 \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc740 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \uac70\uc808\ud560 \uc218 \uc788\ub2e4(\uc81c16\uc870 \uc81c2\ud56d). \ucca0\ud68c\uc640 \uac70\uc808\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c\ub3c4 \ud560 \uc218 \uc788\ub2e4(\uc81c16\uc870 \uc81c3\ud56d).",B.aSE,B.aIC,null)
B.a1v=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc18d\uc784\uc218\ub85c\uc368 \uc790\uae30\ub97c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uadf8 \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc18d\uc784\uc218\ub85c\uc368 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4.","\ub2e8\uc21c\ud788 \uc790\uc2e0\uc774 \ub2a5\ub825\uc790\ub77c\uace0 \ub9d0\ud55c \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc18d\uc784\uc218\uc5d0 \ud574\ub2f9\ud558\uc5ec \ucde8\uc18c\uad8c\uc774 \ubc30\uc81c\ub41c\ub2e4.","\uc18d\uc784\uc218 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ucde8\uc18c\uad8c\uc740 \ud56d\uc0c1 \ubcf4\ud638\ub41c\ub2e4."],t.s)
B.ai1=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.VD=s(["\uc18d\uc784\uc218","\ucde8\uc18c\uad8c \ubc30\uc81c","\uc81c17\uc870"],t.s)
B.bS4=new A.a("gen_cl_capacity_9","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc18d\uc784\uc218(\uc0ac\uc220)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a1v,1,"\ubbfc\ubc95 \uc81c17\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc18d\uc784\uc218\ub85c\uc368 \uc790\uae30\ub97c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud558\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud589\uc704\ub97c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\ub294 \ub2e8\uc21c\ud55c \ubb35\ube44\ub098 \ubbf8\uc131\ub144\uc790\ub77c\ub294 \uc0ac\uc2e4\uc744 \ubc1d\ud788\uc9c0 \uc54a\uc740 \uac83\ub9cc\uc73c\ub85c\ub294 \uc18d\uc784\uc218\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uace0, \uc801\uadf9\uc801\uc778 \uae30\ub9dd\uc218\ub2e8\uc744 \uc0ac\uc6a9\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uc18d\uc784\uc218\ub85c \uc778\uc815\ud55c\ub2e4.",B.ai1,B.VD,null)
B.bgF=s(["\uc0dd\ud65c\uc758 \uadfc\uac70\ub418\ub294 \uacf3\uc744 \uc8fc\uc18c\ub85c \ud55c\ub2e4.","\uc8fc\uc18c\ub97c \uc54c \uc218 \uc5c6\uc73c\uba74 \uac70\uc18c\ub97c \uc8fc\uc18c\ub85c \ubcf8\ub2e4.","\uad6d\ub0b4\uc5d0 \uc8fc\uc18c \uc5c6\ub294 \uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \uad6d\ub0b4\uc5d0 \uc788\ub294 \uac70\uc18c\ub97c \uc8fc\uc18c\ub85c \ubcf8\ub2e4.","\uc8fc\uc18c\ub294 \ub3d9\uc2dc\uc5d0 \ub450 \uacf3 \uc774\uc0c1 \ub458 \uc218 \uc5c6\ub2e4."],t.s)
B.aSW=s(["\uc8fc\uc18c\ub294 \ub3d9\uc2dc\uc5d0 \ub450 \uacf3 \uc774\uc0c1 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc815\ud55c\ub2e4(\ubcf5\uc218\uc8fc\uc758)"],t.s)
B.adZ=s(["\uc8fc\uc18c","\uac70\uc18c","\ubcf5\uc218\uc8fc\uc758"],t.s)
B.bp2=new A.a("gen_cl_capacity_10","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc8fc\uc18c\uc640 \uac70\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bgF,3,"\ubbfc\ubc95 \uc81c18\uc870 \uc81c1\ud56d\uc740 \uc0dd\ud65c\uc758 \uadfc\uac70\ub418\ub294 \uacf3\uc744 \uc8fc\uc18c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ub3d9\uc870 \uc81c2\ud56d\uc740 \uc8fc\uc18c\ub294 \ub3d9\uc2dc\uc5d0 \ub450 \uacf3 \uc774\uc0c1 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc815\ud55c\ub2e4(\ubcf5\uc218\uc8fc\uc758). \uc81c19\uc870\ub294 \uc8fc\uc18c\ub97c \uc54c \uc218 \uc5c6\uc73c\uba74 \uac70\uc18c\ub97c \uc8fc\uc18c\ub85c \ubcf8\ub2e4\uace0 \ud558\uace0, \uc81c20\uc870\ub294 \uad6d\ub0b4\uc5d0 \uc8fc\uc18c \uc5c6\ub294 \uc790\uc5d0 \ub300\ud558\uc5ec\ub294 \uad6d\ub0b4\uc5d0 \uc788\ub294 \uac70\uc18c\ub97c \uc8fc\uc18c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aSW,B.adZ,null)
B.WO=s(["\uc885\ub798\uc758 \uc8fc\uc18c\ub098 \uac70\uc18c\ub97c \ub5a0\ub09c \uc790\ub97c \ubd80\uc7ac\uc790\ub77c \ud558\uace0, \uadf8\uac00 \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \ub450\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \ubc95\uc6d0\uc740 \uc774\ud574\uad00\uacc4\uc778\uc774\ub098 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud574 \uc7ac\uc0b0\uad00\ub9ac\uc5d0 \ud544\uc694\ud55c \ucc98\ubd84\uc744 \uba85\ud560 \uc218 \uc788\ub2e4.","\ubd80\uc7ac\uc790\uac00 \uadf8 \ud6c4 \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \uc815\ud55c \uacbd\uc6b0 \ubd80\uc7ac\uc790 \ubcf8\uc778\uc758 \uccad\uad6c\uc5d0 \uc758\ud574\uc11c\ub9cc \ubc95\uc6d0\uc740 \uac1c\uc784\ud560 \uc218 \uc788\ub2e4.","\ubc95\uc6d0\uc774 \uc120\uc784\ud55c \uc7ac\uc0b0\uad00\ub9ac\uc778\uc740 \uad00\ub9ac\ud589\uc704\ub97c \ub118\ub294 \ud589\uc704\ub97c \ud558\uae30 \uc704\ud574\uc11c\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4.","\uc7ac\uc0b0\uad00\ub9ac\uc778\uc758 \uad8c\ud55c\uc740 \ubd80\uc7ac\uc790 \uc7ac\uc0b0\uc758 \ubcf4\uc874\ud589\uc704, \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\uc5d0 \ubbf8\uce5c\ub2e4."],t.s)
B.b_n=s(["\ubd80\uc7ac\uc790\uc758 \uc0dd\uc0ac\uac00 \ubd84\uba85\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ubc95\uc6d0\uc740 \uc774\ud574\uad00\uacc4\uc778\uc774\ub098 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \uac1c\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.RU=s(["\ubd80\uc7ac\uc790 \uc7ac\uc0b0\uad00\ub9ac","\uc7ac\uc0b0\uad00\ub9ac\uc778 \uac1c\uc784","\uc81c22\uc870\xb7\uc81c23\uc870"],t.s)
B.bLF=new A.a("gen_cl_capacity_11","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubd80\uc7ac\uc790\uc758 \uc7ac\uc0b0\uad00\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.WO,1,"\ubbfc\ubc95 \uc81c22\uc870\ub294 \ubd80\uc7ac\uc790\uac00 \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \ub450\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc774\ud574\uad00\uacc4\uc778\uc774\ub098 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc7ac\uc0b0\uad00\ub9ac\uc5d0 \uad00\ud558\uc5ec \ud544\uc694\ud55c \ucc98\ubd84\uc744 \uba85\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c23\uc870\uc5d0 \ub530\ub974\uba74 \ubd80\uc7ac\uc790\uac00 \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \uc815\ud55c \uacbd\uc6b0\ub77c\ub3c4 \ubd80\uc7ac\uc790\uc758 \uc0dd\uc0ac\uac00 \ubd84\uba85\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ubc95\uc6d0\uc740 \uc774\ud574\uad00\uacc4\uc778\uc774\ub098 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc7ac\uc0b0\uad00\ub9ac\uc778\uc744 \uac1c\uc784\ud560 \uc218 \uc788\ub2e4. \uc7ac\uc0b0\uad00\ub9ac\uc778\uc758 \uad8c\ud55c\uc740 \uc81c25\uc870\uc5d0 \ub530\ub77c \ubcf4\uc874\xb7\uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\uc5d0 \ubbf8\uce58\uba70 \uadf8 \ubc94\uc704\ub97c \ub118\ub294 \ud589\uc704\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \uc694\ud55c\ub2e4(\uc81c25\uc870).",B.b_n,B.RU,null)
B.a94=s(["\ud559\uc220, \uc885\uad50, \uc790\uc120, \uae30\uc608, \uc0ac\uad50 \uae30\ud0c0 \uc601\ub9ac \uc544\ub2cc \uc0ac\uc5c5\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc0ac\ub2e8 \ub610\ub294 \uc7ac\ub2e8\uc740 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \ubc95\uc778\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4.","\uc601\ub9ac\ubc95\uc778\uc740 \uc0c1\uc0ac\ud68c\uc0ac \uc124\ub9bd\uc758 \uc870\uac74\uc5d0 \uc887\uc544 \uc774\ub97c \ubc95\uc778\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4.","\uc7ac\ub2e8\ubc95\uc778\uc758 \uc124\ub9bd\uc790\uac00 \uadf8 \uba85\uce6d, \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0\ub97c \uc815\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc0ac\ub9dd\ud55c \uacbd\uc6b0 \uc774\ud574\uad00\uacc4\uc778\uc774\ub098 \uac80\uc0ac\uc758 \uccad\uad6c\ub85c \ubc95\uc6d0\uc774 \uc774\ub97c \uc815\ud55c\ub2e4.","\ubc95\uc778\uc740 \uadf8 \uc8fc\ub41c \uc0ac\ubb34\uc18c\uc758 \uc18c\uc7ac\uc9c0\uc5d0 \uc774\uc804\ub4f1\uae30\ub97c \ud568\uc73c\ub85c\uc368 \uc124\ub9bd\ub41c\ub2e4."],t.s)
B.b0v=s(["\ubc95\uc778\uc740 \uc124\ub9bd\ub4f1\uae30\uac00 \uc544\ub2c8\ub77c \uadf8 \uc8fc\ub41c \uc0ac\ubb34\uc18c\uc758 \uc18c\uc7ac\uc9c0\uc5d0\uc11c \uc124\ub9bd\ub4f1\uae30\ub97c \ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294\ub370"],t.s)
B.b2i=s(["\ubc95\uc778 \uc124\ub9bd","\uc124\ub9bd\ub4f1\uae30","\uc81c32\uc870\xb7\uc81c33\uc870"],t.s)
B.bvb=new A.a("gen_cl_capacity_12","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uc124\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a94,3,"\ubbfc\ubc95 \uc81c32\uc870\ub294 \ube44\uc601\ub9ac \uc0ac\ub2e8\xb7\uc7ac\ub2e8\uc740 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \ubc95\uc778\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c39\uc870\ub294 \uc601\ub9ac\ubc95\uc778\uc740 \uc0c1\uc0ac\ud68c\uc0ac \uc124\ub9bd\uc758 \uc870\uac74\uc5d0 \uc887\uc544 \ubc95\uc778\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubc95\uc778\uc740 \uc124\ub9bd\ub4f1\uae30\uac00 \uc544\ub2c8\ub77c \uadf8 \uc8fc\ub41c \uc0ac\ubb34\uc18c\uc758 \uc18c\uc7ac\uc9c0\uc5d0\uc11c \uc124\ub9bd\ub4f1\uae30\ub97c \ud568\uc73c\ub85c\uc368 \uc131\ub9bd\ud558\ub294\ub370, \uc774\ub294 \uc774\uc804\ub4f1\uae30\uac00 \uc544\ub2cc \uc124\ub9bd\ub4f1\uae30\uc774\ub2e4(\uc81c33\uc870). \uc7ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\ubcf4\ucda9\uc740 \uc81c44\uc870\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4.",B.b0v,B.b2i,null)
B.bgM=s(["\ubc95\uc778\uc740 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc887\uc544 \uc815\uad00\uc73c\ub85c \uc815\ud55c \ubaa9\uc801\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uad8c\ub9ac\uc640 \uc758\ubb34\uc758 \uc8fc\uccb4\uac00 \ub41c\ub2e4.","\ubc95\uc778\uc758 \ubaa9\uc801\ubc94\uc704\ub294 \uc815\uad00\uc5d0 \uba85\uc2dc\ub41c \ubaa9\uc801 \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubaa9\uc801\uc744 \uc218\ud589\ud558\ub294 \ub370 \ud544\uc694\ud55c \ud589\uc704\ub3c4 \ud3ec\ud568\ud558\ub294 \uac83\uc73c\ub85c \ud3ed\ub113\uac8c \ud574\uc11d\ub41c\ub2e4.","\ubc95\uc778\uc740 \uc131\uc9c8\uc0c1 \uc790\uc5f0\uc778\ub9cc\uc774 \ub204\ub9b4 \uc218 \uc788\ub294 \uc2e0\uccb4\uc0c1\uc758 \uad8c\ub9ac\ub3c4 \uc790\uc720\ub86d\uac8c \ud5a5\uc720\ud560 \uc218 \uc788\ub2e4.","\ubc95\uc778\uc758 \ub300\ud45c\uc774\uc0ac\uac00 \uc815\uad00\uc0c1 \ubaa9\uc801\ubc94\uc704\ub97c \ubc97\uc5b4\ub09c \ud589\uc704\ub97c \ud558\uba74 \uadf8 \ud589\uc704\uc758 \ud6a8\uacfc\uac00 \ubc95\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\uc9c0 \uc54a\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4."],t.s)
B.acK=s(["\ubaa9\uc801\ubc94\uc704\ub97c \ubaa9\uc801 \uc218\ud589\uc5d0 \uc9c1\uc811\xb7\uac04\uc811\uc73c\ub85c \ud544\uc694\ud55c \ud589\uc704\uae4c\uc9c0 \ud3ed\ub113\uac8c \ud574\uc11d\ud558\uc5ec"],t.s)
B.akT=s(["\ubc95\uc778\uc758 \uad8c\ub9ac\ub2a5\ub825","\ubaa9\uc801\ubc94\uc704","\uc81c34\uc870"],t.s)
B.bQJ=new A.a("gen_cl_capacity_13","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uad8c\ub9ac\ub2a5\ub825\uacfc \ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bgM,2,"\ubbfc\ubc95 \uc81c34\uc870\ub294 \ubc95\uc778\uc740 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc887\uc544 \uc815\uad00\uc73c\ub85c \uc815\ud55c \ubaa9\uc801\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uad8c\ub9ac\uc640 \uc758\ubb34\uc758 \uc8fc\uccb4\uac00 \ub41c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\ub294 \ubaa9\uc801\ubc94\uc704\ub97c \ubaa9\uc801 \uc218\ud589\uc5d0 \uc9c1\uc811\xb7\uac04\uc811\uc73c\ub85c \ud544\uc694\ud55c \ud589\uc704\uae4c\uc9c0 \ud3ed\ub113\uac8c \ud574\uc11d\ud558\uc5ec \uac70\ub798 \uc548\uc804\uc744 \ub3c4\ubaa8\ud55c\ub2e4. \ub2e4\ub9cc \ubc95\uc778\uc740 \uc131\uc9c8\uc0c1 \uc0dd\uba85\uad8c, \uc2e0\uccb4\uc0c1\uc758 \uc790\uc720 \ub4f1 \uc790\uc5f0\uc778\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uad8c\ub9ac\ub294 \ud5a5\uc720\ud560 \uc218 \uc5c6\ub2e4.",B.acK,B.akT,null)
B.ab7=s(["\ubc95\uc778\uc740 \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uadf8 \uc9c1\ubb34\uc5d0 \uad00\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \uac00\ud55c \uc190\ud574\ub97c \ubc30\uc0c1\ud560 \ucc45\uc784\uc774 \uc788\ub2e4.","\uc9c1\ubb34\uc5d0 \uad00\ud55c \ud589\uc704\uc778\uc9c0 \uc5ec\ubd80\ub294 \ud589\uc704\uc758 \uc678\ud615\uc0c1 \uc9c1\ubb34\ud589\uc704\ub77c\uace0 \uc778\uc815\ub418\ub294 \uac83\ub3c4 \ud3ec\ud568\ud558\ub294 \uc678\ud615\uc774\ub860\uc5d0 \ub530\ub77c \ud310\ub2e8\ud55c\ub2e4.","\uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uc758 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \uc788\ub294 \uacbd\uc6b0 \ubc95\uc778\uc740 \uadf8 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uba74\ud55c\ub2e4.","\ub300\ud45c\uae30\uad00\uc774 \uc9c1\ubb34 \uc678\ud615\uacfc \uad00\uacc4\uc5c6\uc774 \uac1c\uc778\uc801\uc778 \uc774\uc775\uc744 \ub3c4\ubaa8\ud560 \ubaa9\uc801\uc73c\ub85c \ud589\uc704\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc54c\uc558\uac70\ub098 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uac00 \uc544\ub2c8\ub77c\uba74 \uc678\ud615\uc774\ub860\uc774 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4."],t.s)
B.acp=s(["\uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\ub294 \uadf8 \uc790\uae30\uc758 \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aac=s(["\ubc95\uc778\uc758 \ubd88\ubc95\ud589\uc704\ub2a5\ub825","\uc678\ud615\uc774\ub860","\uc81c35\uc870"],t.s)
B.bt4=new A.a("gen_cl_capacity_14","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubbfc\ubc95 \uc81c35\uc870 \ubc95\uc778\uc758 \ubd88\ubc95\ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ab7,2,"\ubbfc\ubc95 \uc81c35\uc870 \uc81c1\ud56d\uc740 \ubc95\uc778\uc740 \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uadf8 \uc9c1\ubb34\uc5d0 \uad00\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \uac00\ud55c \uc190\ud574\ub97c \ubc30\uc0c1\ud560 \ucc45\uc784\uc774 \uc788\uace0, \uc774 \uacbd\uc6b0 \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\ub294 \uadf8 \uc790\uae30\uc758 \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\ub294 \uc9c1\ubb34\uad00\ub828\uc131\uc744 \uc678\ud615\uc774\ub860\uc5d0 \ub530\ub77c \ud310\ub2e8\ud558\ub418, \uc0c1\ub300\ubc29\uc774 \ub300\ud45c\uc790\uc758 \uc9c4\uc758\ub97c \uc54c\uc558\uac70\ub098 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \ubc95\uc778\uc758 \ucc45\uc784\uc774 \ubd80\uc815\ub41c\ub2e4.",B.acp,B.aac,null)
B.ak0=s(["\uc774 \uacbd\uc6b0 \uc0ac\uc6d0\uc774\ub098 \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uc5f0\ub300\ud558\uc5ec \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uaddc\uc815\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubbfc\ubc95 \uc81c35\uc870 \uc81c2\ud56d\uc740 \ubc95\uc778\uc758 \ubaa9\uc801\ubc94\uc704 \uc678\uc758 \ud589\uc704\ub85c \ud0c0\uc778\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc0ac\ud56d\uc758 \uc758\uacb0\uc5d0 \ucc2c\uc131\ud558\uac70\ub098 \uadf8 \uc758\uacb0\uc744 \uc9d1\ud589\ud55c \uc0ac\uc6d0, \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uc5f0\ub300\ud558\uc5ec \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.","\uc774 \uacbd\uc6b0 \ubc95\uc778\ub9cc\uc774 \ub2e8\ub3c5\uc73c\ub85c \ubc30\uc0c1\ucc45\uc784\uc744 \ubd80\ub2f4\ud55c\ub2e4.","\ud53c\ud574\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ud45c\uc790 \uac1c\uc778\uc5d0\uac8c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
B.b9A=s(["\uadf8 \uc0ac\ud56d\uc758 \uc758\uacb0\uc5d0 \ucc2c\uc131\ud558\uac70\ub098 \uadf8 \uc758\uacb0\uc744 \uc9d1\ud589\ud55c \uc0ac\uc6d0, \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uc5f0\ub300\ud558\uc5ec \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec"],t.s)
B.axK=s(["\ubc95\uc778 \ubd88\ubc95\ud589\uc704","\uc5f0\ub300\ubc30\uc0c1\ucc45\uc784","\uc81c35\uc870 \uc81c2\ud56d"],t.s)
B.bz3=new A.a("gen_cl_capacity_15","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \ubd88\ubc95\ud589\uc704\ub85c \uc778\ud55c \ubc30\uc0c1\ucc45\uc784\uacfc \uad00\ub828\ud558\uc5ec, \ub300\ud45c\uc790\uc758 \ud589\uc704\uac00 \uc9c1\ubb34\ubc94\uc704\uc5d0 \uc18d\ud558\uc9c0 \uc54a\uc544 \ubc95\uc778\uc774 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294 \uacbd\uc6b0 \ud53c\ud574\uc790 \ubcf4\ud638\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ak0,1,"\ubbfc\ubc95 \uc81c35\uc870 \uc81c2\ud56d\uc740 \ubc95\uc778\uc758 \ubaa9\uc801\ubc94\uc704 \uc678\uc758 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \ub54c\uc5d0\ub294 \uadf8 \uc0ac\ud56d\uc758 \uc758\uacb0\uc5d0 \ucc2c\uc131\ud558\uac70\ub098 \uadf8 \uc758\uacb0\uc744 \uc9d1\ud589\ud55c \uc0ac\uc6d0, \uc774\uc0ac \uae30\ud0c0 \ub300\ud45c\uc790\uac00 \uc5f0\ub300\ud558\uc5ec \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \ud53c\ud574\uc790\ub97c \ubcf4\ud638\ud55c\ub2e4.",B.b9A,B.axK,null)
B.aW_=s(["\ubc95\uc778\uc740 \uc774\uc0ac\ub97c \ub450\uc5b4\uc57c \ud558\uba70, \uc774\uc0ac\ub294 \ubc95\uc778\uc758 \uc0ac\ubb34\uc5d0 \uad00\ud558\uc5ec \uac01\uc790 \ubc95\uc778\uc744 \ub300\ud45c\ud55c\ub2e4.","\uc774\uc0ac\uac00 \uc218\uc778\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ubc95\uc778\uc744 \ub300\ud45c\ud55c\ub2e4.","\uc774\uc0ac\uc758 \ub300\ud45c\uad8c\uc5d0 \ub300\ud55c \uc81c\ud55c\uc740 \uc815\uad00\uc5d0 \uae30\uc7ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\uc774\uc0ac\uc640 \ubc95\uc778\uc758 \uc774\uc775\uc774 \uc0c1\ubc18\ud558\ub294 \uc0ac\ud56d\uc5d0 \uad00\ud558\uc5ec\ub294 \uc774\uc0ac\uac00 \ubc95\uc778\uc744 \ub300\ud45c\ud560 \uc218 \uc788\ub2e4."],t.s)
B.bfv=s(["\uc774\uc0ac\uc640 \ubc95\uc778\uc758 \uc774\uc775\uc774 \uc0c1\ubc18\ud558\ub294 \uc0ac\ud56d\uc5d0 \uad00\ud558\uc5ec\ub294 \uc774\uc0ac\ub294 \ub300\ud45c\uad8c\uc774 \uc5c6\uace0"],t.s)
B.aXd=s(["\uc774\uc0ac","\ub300\ud45c\uad8c","\ud2b9\ubcc4\ub300\ub9ac\uc778"],t.s)
B.bQK=new A.a("gen_cl_capacity_16","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uc774\uc0ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aW_,3,"\ubbfc\ubc95 \uc81c57\uc870\ub294 \ubc95\uc778\uc740 \uc774\uc0ac\ub97c \ub450\uc5b4\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c59\uc870 \uc81c1\ud56d\uc740 \uc774\uc0ac\ub294 \ubc95\uc778\uc758 \uc0ac\ubb34\uc5d0 \uad00\ud558\uc5ec \uac01\uc790 \ubc95\uc778\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c41\uc870\ub294 \uc774\uc0ac\uc758 \ub300\ud45c\uad8c\uc5d0 \ub300\ud55c \uc81c\ud55c\uc740 \uc815\uad00\uc5d0 \uae30\uc7ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc81c64\uc870\uc5d0 \ub530\ub77c \uc774\uc0ac\uc640 \ubc95\uc778\uc758 \uc774\uc775\uc774 \uc0c1\ubc18\ud558\ub294 \uc0ac\ud56d\uc5d0 \uad00\ud558\uc5ec\ub294 \uc774\uc0ac\ub294 \ub300\ud45c\uad8c\uc774 \uc5c6\uace0, \uc774 \uacbd\uc6b0 \ud2b9\ubcc4\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.bfv,B.aXd,null)
B.bf7=s(["\ubc95\uc778\uc740 \uc815\uad00 \ub610\ub294 \ucd1d\ud68c\uc758 \uacb0\uc758\ub85c \uac10\uc0ac\ub97c \ub458 \uc218 \uc788\ub2e4.","\uac10\uc0ac\ub294 \ubc95\uc778\uc758 \uc7ac\uc0b0\uc0c1\ud669\uc744 \uac10\uc0ac\ud558\ub294 \uc784\ubb34\ub97c \uac00\uc9c4\ub2e4.","\uac10\uc0ac\ub294 \uc774\uc0ac\uc758 \uc5c5\ubb34\uc9d1\ud589 \uc0c1\ud669\uc744 \uac10\uc0ac\ud558\ub294 \uc784\ubb34\ub97c \uac00\uc9c4\ub2e4.","\uac10\uc0ac\ub294 \ubc95\uc778\uc758 \ud544\uc218\uae30\uad00\uc73c\ub85c\uc11c \ubc18\ub4dc\uc2dc \ub450\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.b_c=s(["\ubc95\uc778\uc740 \uc815\uad00 \ub610\ub294 \ucd1d\ud68c\uc758 \uacb0\uc758\ub85c \uac10\uc0ac\ub97c \ub458 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uac10\uc0ac\ub97c \uc784\uc758\uae30\uad00\uc73c\ub85c \uc815\ud55c\ub2e4"],t.s)
B.aQb=s(["\uac10\uc0ac","\uc784\uc758\uae30\uad00","\uc81c66\uc870\xb7\uc81c67\uc870"],t.s)
B.brF=new A.a("gen_cl_capacity_17","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uac10\uc0ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bf7,3,"\ubbfc\ubc95 \uc81c66\uc870\ub294 \ubc95\uc778\uc740 \uc815\uad00 \ub610\ub294 \ucd1d\ud68c\uc758 \uacb0\uc758\ub85c \uac10\uc0ac\ub97c \ub458 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uac10\uc0ac\ub97c \uc784\uc758\uae30\uad00\uc73c\ub85c \uc815\ud55c\ub2e4. \uc81c67\uc870\ub294 \uac10\uc0ac\uc758 \uc9c1\ubb34\ub85c \uc7ac\uc0b0\uc0c1\ud669 \uac10\uc0ac, \uc774\uc0ac\uc758 \uc5c5\ubb34\uc9d1\ud589\uc0c1\ud669 \uac10\uc0ac, \ubd80\uc815 \ub610\ub294 \ubd80\ub2f9\ud55c \uc0ac\ud56d \ubc1c\uacac \uc2dc \ucd1d\ud68c \ub610\ub294 \uc8fc\ubb34\uad00\uccad\uc5d0 \ubcf4\uace0\ud558\ub294 \uc784\ubb34 \ub4f1\uc744 \uaddc\uc815\ud55c\ub2e4.",B.b_c,B.aQb,null)
B.b0a=s(["\uc0ac\ub2e8\ubc95\uc778\uc758 \uc0ac\ubb34\ub294 \uc815\uad00\uc73c\ub85c \uc774\uc0ac \ub610\ub294 \uae30\ud0c0 \uc784\uc6d0\uc5d0\uac8c \uc704\uc784\ud55c \uc0ac\ud56d \uc678\uc5d0\ub294 \ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ucd1d\ud68c\ub294 \uc815\uad00\ubcc0\uacbd, \uc784\uc758\ud574\uc0b0 \ub4f1 \ubc95\uc778\uc758 \uadfc\ubcf8\uc801 \uc0ac\ud56d\uc744 \uc758\uacb0\ud560 \uad8c\ud55c\uc744 \uac00\uc9c4\ub2e4.","\uc815\uad00\uc758 \ubcc0\uacbd\uc740 \ucd1d\uc0ac\uc6d0 3\ubd84\uc758 2 \uc774\uc0c1\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud558\uba70 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub3c4 \uadf8 \uaddc\uc815\uc5d0 \ub530\ub97c \uc218 \uc5c6\ub2e4.","\uc0ac\uc6d0\ucd1d\ud68c\uc758 \uc18c\uc9d1\uc740 \uc774\uc0ac\uac00 \ud558\uba70, \ucd1d\uc0ac\uc6d0 5\ubd84\uc758 1 \uc774\uc0c1\uc774 \uccad\uad6c\ud55c \ub54c\uc5d0\ub294 \uc774\uc0ac\ub294 \uc784\uc2dc\ucd1d\ud68c\ub97c \uc18c\uc9d1\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.a0Q=s(["\uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub294 \uadf8 \uaddc\uc815\uc5d0 \uc758\ud55c\ub2e4\uace0 \uc815\ud558\uc5ec \uc784\uc758\uaddc\uc815\uc784\uc744 \ubc1d\ud788\uace0 \uc788\ub2e4"],t.s)
B.abQ=s(["\uc0ac\uc6d0\ucd1d\ud68c","\uc815\uad00\ubcc0\uacbd","\uc81c42\uc870\xb7\uc81c68\uc870"],t.s)
B.bDF=new A.a("gen_cl_capacity_18","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc0ac\ub2e8\ubc95\uc778\uc758 \uc0ac\uc6d0\ucd1d\ud68c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b0a,2,"\ubbfc\ubc95 \uc81c68\uc870\ub294 \uc0ac\ub2e8\ubc95\uc778\uc758 \uc0ac\ubb34\ub294 \uc815\uad00\uc73c\ub85c \uc774\uc0ac \ub610\ub294 \uae30\ud0c0 \uc784\uc6d0\uc5d0\uac8c \uc704\uc784\ud55c \uc0ac\ud56d \uc678\uc5d0\ub294 \ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c42\uc870 \uc81c1\ud56d\uc740 \uc815\uad00\uc758 \ubcc0\uacbd\uc740 \ucd1d\uc0ac\uc6d0 3\ubd84\uc758 2 \uc774\uc0c1\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \ud558\ub098, \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc788\ub294 \ub54c\uc5d0\ub294 \uadf8 \uaddc\uc815\uc5d0 \uc758\ud55c\ub2e4\uace0 \uc815\ud558\uc5ec \uc784\uc758\uaddc\uc815\uc784\uc744 \ubc1d\ud788\uace0 \uc788\ub2e4. \uc784\uc2dc\ucd1d\ud68c \uc18c\uc9d1\uc5d0 \uad00\ud558\uc5ec\ub294 \uc81c70\uc870\uac00 \uaddc\uc815\ud55c\ub2e4.",B.a0Q,B.abQ,null)
B.a7d=s(["\uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc740 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uac01 \uc0ac\uc6d0\ub9c8\ub2e4 \ud3c9\ub4f1\ud55c \uac83\uc73c\ub85c \ud55c\ub2e4.","\uc0ac\uc6d0\uc740 \uc11c\uba74\uc774\ub098 \ub300\ub9ac\uc778\uc73c\ub85c\ub294 \uacb0\uc758\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.","\uc0ac\ub2e8\ubc95\uc778\uc740 \uc0ac\uc6d0\uc774 \uc5c6\uac8c \ub418\uc5b4\ub3c4 \uc815\uad00\uc5d0 \uc815\ud568\uc774 \uc5c6\ub294 \ud55c \ud574\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ucd1d\ud68c\uc758 \uacb0\uc758\ub294 \ubcf8\ubc95 \ub610\ub294 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uc0ac\uc6d0 \uacfc\ubc18\uc218\uc758 \ucd9c\uc11d\uacfc \ucd9c\uc11d\uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc758 \uacfc\ubc18\uc218\ub85c\uc368 \ud55c\ub2e4."],t.s)
B.agP=s(["\uac01 \uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc740 \ud3c9\ub4f1\ud55c \uac83\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70"],t.s)
B.bcQ=s(["\uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c","\ud3c9\ub4f1\uc6d0\uce59","\uc81c73\uc870"],t.s)
B.bNp=new A.a("gen_cl_capacity_19","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc0ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\ubcc0\uacbd \ubc0f \uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7d,0,"\ubbfc\ubc95 \uc81c73\uc870 \uc81c1\ud56d\uc740 \uac01 \uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc740 \ud3c9\ub4f1\ud55c \uac83\uc73c\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8\uc5d0 \ub530\ub97c \uc218 \uc788\ub2e4. \ub3d9\uc870 \uc81c2\ud56d\uc740 \uc0ac\uc6d0\uc740 \uc11c\uba74\uc774\ub098 \ub300\ub9ac\uc778\uc73c\ub85c \uacb0\uc758\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c75\uc870\ub294 \ucd1d\ud68c \uacb0\uc758\ub294 \uc815\uad00\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uc0ac\uc6d0 \uacfc\ubc18\uc218\uc758 \ucd9c\uc11d\uacfc \ucd9c\uc11d\uc0ac\uc6d0\uc758 \uacb0\uc758\uad8c\uc758 \uacfc\ubc18\uc218\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.agP,B.bcQ,null)
B.arN=s(["\uc874\ub9bd\uae30\uac04\uc758 \ub9cc\ub8cc, \ubc95\uc778\uc758 \ubaa9\uc801 \ub2ec\uc131 \ub610\ub294 \ub2ec\uc131\uc758 \ubd88\ub2a5 \uae30\ud0c0 \uc815\uad00\uc5d0 \uc815\ud55c \ud574\uc0b0\uc0ac\uc720\uc758 \ubc1c\uc0dd","\ud30c\uc0b0","\uc124\ub9bd\ud5c8\uac00\uc758 \ucde8\uc18c","\uc774\uc0ac\uc758 \uc0ac\uc784"],t.s)
