B.bJG=new A.a("gen_cl_capacity_22","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uc794\uc5ec\uc7ac\uc0b0 \uadc0\uc18d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aZo,3,"\ubbfc\ubc95 \uc81c80\uc870\ub294 \ud574\uc0b0\ud55c \ubc95\uc778\uc758 \uc7ac\uc0b0\uc740 \uc815\uad00\uc73c\ub85c \uc9c0\uc815\ud55c \uc790\uc5d0\uac8c \uadc0\uc18d\ud558\uace0, \uc815\uad00\uc73c\ub85c \uadc0\uc18d\uad8c\ub9ac\uc790\ub97c \uc9c0\uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uc774\uc0ac \ub610\ub294 \uccad\uc0b0\uc778\uc774 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \uc720\uc0ac\ud55c \ubaa9\uc801\uc744 \uc704\ud574 \ucc98\ubd84\ud560 \uc218 \uc788\uc73c\uba70, \uc774\ub7ec\ud55c \ubc29\ubc95\uc73c\ub85c \ucc98\ubd84\ub418\uc9c0 \uc544\ub2c8\ud55c \uc7ac\uc0b0\uc740 \uad6d\uace0\uc5d0 \uadc0\uc18d\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc0ac\ub2e8\ubc95\uc778\uc774\ub77c\ub3c4 \uc815\uad00\uc5d0 \uc0ac\uc6d0\uc5d0\uac8c \ubd84\ubc30\ud55c\ub2e4\ub294 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uc0ac\uc6d0\uc5d0\uac8c \ub2f9\uc5f0\ud788 \uadc0\uc18d\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.af9,B.Rn,null)
B.aoS=s(["\ud310\ub840\ub294 \uc885\uc911\uc774\ub098 \uad50\ud68c\uc640 \uac19\uc774 \uc0ac\ub2e8\uc758 \uc2e4\uccb4\ub97c \uac16\ucd94\uc5c8\uc73c\ub098 \ubc95\uc778\uaca9\uc744 \ucde8\ub4dd\ud558\uc9c0 \ubabb\ud55c \ub2e8\uccb4\ub97c \uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8\uc73c\ub85c \uc778\uc815\ud55c\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8\uc758 \uc7ac\uc0b0\uc740 \ucd1d\uc720\ub85c \ud558\uba70, \uadf8 \uad00\ub9ac \ubc0f \ucc98\ubd84\uc740 \uc0ac\uc6d0\ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud55c\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8\uc740 \ub300\ud45c\uc790\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc0ac\ub2e8\uc758 \uba85\uc758\ub85c \uc18c\uc1a1\ub2f9\uc0ac\uc790\uac00 \ub420 \uc218 \uc788\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8\uc758 \uc0ac\uc6d0\uc740 \ucd1d\uc720\uc7ac\uc0b0\uc5d0 \ub300\ud558\uc5ec \uc9c0\ubd84\uad8c\uc744 \uac00\uc9c0\uba70 \uc774\ub97c \uac1c\uc778\uc801\uc73c\ub85c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4."],t.s)
B.ai7=s(["\ucd1d\uc720\uc758 \uc131\uc9c8\uc0c1 \uc0ac\uc6d0 \uac1c\uac1c\uc778\uc740 \uc9c0\ubd84\uad8c\uc744 \uac00\uc9c0\uc9c0 \uc544\ub2c8\ud558\uba70 \ucd1d\uc720\uc7ac\uc0b0\uc744 \uac1c\uc778\uc801\uc73c\ub85c \ucc98\ubd84\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aDj=s(["\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8","\ucd1d\uc720","\uc81c275\uc870\xb7\uc81c276\uc870"],t.s)
B.br1=new A.a("gen_cl_capacity_23","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc0ac\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aoS,3,"\ubbfc\ubc95 \uc81c275\uc870\ub294 \ubc95\uc778\uc774 \uc544\ub2cc \uc0ac\ub2e8\uc758 \uc0ac\uc6d0\uc774 \uc9d1\ud569\uccb4\ub85c\uc11c \ubb3c\uac74\uc744 \uc18c\uc720\ud558\ub294 \ub54c\uc5d0\ub294 \ucd1d\uc720\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c276\uc870\ub294 \ucd1d\uc720\ubb3c\uc758 \uad00\ub9ac \ubc0f \ucc98\ubd84\uc740 \uc0ac\uc6d0\ucd1d\ud68c\uc758 \uacb0\uc758\uc5d0 \uc758\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ucd1d\uc720\uc758 \uc131\uc9c8\uc0c1 \uc0ac\uc6d0 \uac1c\uac1c\uc778\uc740 \uc9c0\ubd84\uad8c\uc744 \uac00\uc9c0\uc9c0 \uc544\ub2c8\ud558\uba70 \ucd1d\uc720\uc7ac\uc0b0\uc744 \uac1c\uc778\uc801\uc73c\ub85c \ucc98\ubd84\ud560 \uc218 \uc5c6\ub2e4. \uc18c\uc1a1\ubc95\uc0c1\uc73c\ub85c\ub294 \ubbfc\uc0ac\uc18c\uc1a1\ubc95 \uc81c52\uc870\uc5d0 \ub530\ub77c \ub300\ud45c\uc790\uac00 \uc788\ub294 \ube44\ubc95\uc778\uc0ac\ub2e8\uc740 \uadf8 \uc0ac\ub2e8 \uba85\uc758\ub85c \ub2f9\uc0ac\uc790\uac00 \ub420 \uc218 \uc788\ub2e4.",B.ai7,B.aDj,null)
B.aw3=s(["\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc740 \uc0ac\ub2e8\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucd1d\uc720 \ud615\ud0dc\ub85c \uc7ac\uc0b0\uc744 \uc18c\uc720\ud55c\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc740 \ucd9c\uc5f0\ub41c \uc7ac\uc0b0\uc774 \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd \uc694\uac74\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\uc744 \ubfd0 \uadf8 \uc2e4\uc9c8\uc740 \uc7ac\ub2e8\uc774\ubbc0\ub85c \ubd80\ub3d9\uc0b0\ub4f1\uae30\ubc95\uc0c1 \ub4f1\uae30\ub2a5\ub825\uc774 \uc778\uc815\ub41c\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc740 \uc0ac\uc6d0\ucd1d\ud68c\ub97c \ud1b5\ud574 \uc7ac\uc0b0\uc744 \uad00\ub9ac\ud55c\ub2e4.","\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc740 \ubc95\uc778\uaca9\uc774 \uc5c6\uc73c\ubbc0\ub85c \uc5b4\ub5a0\ud55c \ubc95\ub960\uad00\uacc4\uc758 \uc8fc\uccb4\ub3c4 \ub420 \uc218 \uc5c6\ub2e4."],t.s)
B.bfK=s(["\uadf8 \uba85\uc758\ub85c \ubd80\ub3d9\uc0b0 \ub4f1\uae30\ub97c \ud560 \uc218 \uc788\ub294 \ub4f1\uae30\ub2a5\ub825\uc744 \uc778\uc815\ud558\uace0 \uc788\ub2e4"],t.s)
B.Yu=s(["\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8","\ub4f1\uae30\ub2a5\ub825","\uc7ac\uc0b0\uc758 \uc9d1\ud569\uccb4"],t.s)
B.bqD=new A.a("gen_cl_capacity_24","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aw3,1,"\uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc740 \uc0ac\ub2e8\uacfc \ub2ec\ub9ac \uc0ac\uc6d0\uc774 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc73c\uba70 \ucd9c\uc5f0\uc7ac\uc0b0\uc744 \uc911\uc2ec\uc73c\ub85c \ud558\ub294 \uc7ac\uc0b0\uc758 \uc9d1\ud569\uccb4\uc774\ub2e4. \ud310\ub840\uc640 \ubd80\ub3d9\uc0b0\ub4f1\uae30\ubc95\uc740 \ud559\uad50, \uc720\uce58\uc6d0 \ub4f1 \uad8c\ub9ac\ub2a5\ub825 \uc5c6\ub294 \uc7ac\ub2e8\uc5d0 \ub300\ud574 \uadf8 \uba85\uc758\ub85c \ubd80\ub3d9\uc0b0 \ub4f1\uae30\ub97c \ud560 \uc218 \uc788\ub294 \ub4f1\uae30\ub2a5\ub825\uc744 \uc778\uc815\ud558\uace0 \uc788\ub2e4.",B.bfK,B.Yu,null)
B.a_x=s(["\ud1a0\uc9c0 \ubc0f \uadf8 \uc815\ucc29\ubb3c\uc740 \ubd80\ub3d9\uc0b0\uc774\ub2e4.","\ubd80\ub3d9\uc0b0 \uc774\uc678\uc758 \ubb3c\uac74\uc740 \ub3d9\uc0b0\uc774\ub2e4.","\uae08\uc804\uc740 \ub3d9\uc0b0\uc5d0 \ud574\ub2f9\ud558\ub098 \ubb3c\uac74\uc73c\ub85c\uc11c\uc758 \uac1c\uc131\ubcf4\ub2e4 \uac00\uce58\uc758 \ud45c\uc0c1\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4.","\uc785\ubaa9\uc5d0 \uad00\ud55c \ubc95\ub960\uc5d0 \uc758\ud558\uc5ec \ub4f1\uae30\ub41c \uc785\ubaa9\uc740 \ud1a0\uc9c0\uc758 \uc815\ucc29\ubb3c\ub85c\uc11c \ub3c5\ub9bd\ub41c \ubb3c\uac74\uc73c\ub85c \ucde8\uae09\ub420 \uc218 \uc5c6\ub2e4."],t.s)
B.aej=s(["\ub4f1\uae30\ub41c \uc785\ubaa9\uc740 \ud1a0\uc9c0\uc640 \ubcc4\uac1c\uc758 \ubd80\ub3d9\uc0b0\uc73c\ub85c\uc11c \ub3c5\ub9bd\ud558\uc5ec \uac70\ub798\uc758 \uac1d\uccb4\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.atY=s(["\ubd80\ub3d9\uc0b0\xb7\ub3d9\uc0b0","\uc785\ubaa9","\uc81c99\uc870"],t.s)
B.bH7=new A.a("gen_cl_capacity_25","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubd80\ub3d9\uc0b0\uacfc \ub3d9\uc0b0\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a_x,3,"\ubbfc\ubc95 \uc81c99\uc870\ub294 \ud1a0\uc9c0 \ubc0f \uadf8 \uc815\ucc29\ubb3c\uc744 \ubd80\ub3d9\uc0b0\uc73c\ub85c, \ubd80\ub3d9\uc0b0 \uc774\uc678\uc758 \ubb3c\uac74\uc744 \ub3d9\uc0b0\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \uc785\ubaa9\uc5d0 \uad00\ud55c \ubc95\ub960\uc5d0 \ub530\ub77c \ub4f1\uae30\ub41c \uc785\ubaa9\uc740 \ud1a0\uc9c0\uc640 \ubcc4\uac1c\uc758 \ubd80\ub3d9\uc0b0\uc73c\ub85c\uc11c \ub3c5\ub9bd\ud558\uc5ec \uac70\ub798\uc758 \uac1d\uccb4\uac00 \ub420 \uc218 \uc788\ub2e4. \uae08\uc804\uc740 \ub3d9\uc0b0\uc774\uc9c0\ub9cc \ubb3c\uac74 \uc790\uccb4\uc758 \uac1c\uc131\ubcf4\ub2e4\ub294 \uac00\uce58\ucc99\ub3c4\ub85c\uc11c \uae30\ub2a5\uc774 \uac15\uc870\ub418\uc5b4 \ud2b9\uc218\ud558\uac8c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4.",B.aej,B.atY,null)
B.axD=s(["\ubb3c\uac74\uc758 \uc18c\uc720\uc790\uac00 \uadf8 \ubb3c\uac74\uc758 \uc0c1\uc6a9\uc5d0 \uacf5\ud558\uae30 \uc704\ud558\uc5ec \uc790\uae30\uc18c\uc720\uc778 \ub2e4\ub978 \ubb3c\uac74\uc744 \uc774\uc5d0 \ubd80\uc18d\ud558\uac8c \ud55c \ub54c\uc5d0\ub294 \uadf8 \ubd80\uc18d\ubb3c\uc740 \uc885\ubb3c\uc774\ub2e4.","\uc885\ubb3c\uc740 \uc8fc\ubb3c\uc758 \ucc98\ubd84\uc5d0 \ub530\ub978\ub2e4.","\uc885\ubb3c\uc740 \ubc18\ub4dc\uc2dc \uc8fc\ubb3c\uc758 \uc18c\uc720\uc790 \uc18c\uc720\uc77c \ud544\uc694\ub294 \uc5c6\uace0 \ud0c0\uc778 \uc18c\uc720\ubb3c\ub3c4 \uc885\ubb3c\uc774 \ub420 \uc218 \uc788\ub2e4.","\uc885\ubb3c\uc740 \uc8fc\ubb3c \uc790\uccb4\uc758 \ud6a8\uc6a9\uacfc \uc9c1\uc811 \uad00\uacc4\uc5c6\uc774 \uc18c\uc720\uc790\uc758 \uc0c1\uc6a9\uc5d0 \uacf5\uc5ec\ub418\ub294 \ubb3c\uac74\uc774\ub77c\ub3c4 \ubb34\ubc29\ud558\ub2e4."],t.s)
B.aW6=s(["\uc885\ubb3c\uc740 \uc8fc\ubb3c\uacfc \ub3d9\uc77c\ud55c \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud558\uc5ec\uc57c \ud558\uace0"],t.s)
B.bgz=s(["\uc8fc\ubb3c\uacfc \uc885\ubb3c","\uc81c100\uc870","\uc18c\uc720\uc790 \ub3d9\uc77c\uc131"],t.s)
B.brr=new A.a("gen_cl_capacity_26","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc8fc\ubb3c\uacfc \uc885\ubb3c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.axD,2,"\ubbfc\ubc95 \uc81c100\uc870 \uc81c1\ud56d\uc740 \ubb3c\uac74\uc758 \uc18c\uc720\uc790\uac00 \uadf8 \ubb3c\uac74\uc758 \uc0c1\uc6a9\uc5d0 \uacf5\ud558\uae30 \uc704\ud558\uc5ec \uc790\uae30\uc18c\uc720\uc778 \ub2e4\ub978 \ubb3c\uac74\uc744 \uc774\uc5d0 \ubd80\uc18d\ud558\uac8c \ud55c \ub54c\uc5d0\ub294 \uadf8 \ubd80\uc18d\ubb3c\uc744 \uc885\ubb3c\uc774\ub77c \ud558\uace0, \uc81c2\ud56d\uc740 \uc885\ubb3c\uc740 \uc8fc\ubb3c\uc758 \ucc98\ubd84\uc5d0 \ub530\ub978\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ud310\ub840\uc0c1 \uc885\ubb3c\uc740 \uc8fc\ubb3c\uacfc \ub3d9\uc77c\ud55c \uc18c\uc720\uc790\uc5d0\uac8c \uc18d\ud558\uc5ec\uc57c \ud558\uace0, \uc8fc\ubb3c \uc790\uccb4\uc758 \ud6a8\uc6a9\uc5d0 \uc774\ubc14\uc9c0\ud558\ub294 \ubb3c\uac74\uc774\uc5b4\uc57c \ud558\ubbc0\ub85c \uc18c\uc720\uc790\uc758 \uc0c1\uc6a9\uc5d0\ub9cc \uacf5\uc5ec\ub418\ub294 \ubb3c\uac74\uc740 \uc885\ubb3c\uc774 \uc544\ub2c8\ub2e4.",B.aW6,B.bgz,null)
B.bge=s(["\ubb3c\uac74\uc758 \uc6a9\ubc95\uc5d0 \uc758\ud558\uc5ec \uc218\ucde8\ud558\ub294 \uc0b0\ucd9c\ubb3c\uc744 \ucc9c\uc5f0\uacfc\uc2e4\uc774\ub77c \ud55c\ub2e4.","\ucc9c\uc5f0\uacfc\uc2e4\uc740 \uadf8 \uc6d0\ubb3c\ub85c\ubd80\ud130 \ubd84\ub9ac\ud558\ub294 \ub54c\uc5d0 \uc774\ub97c \uc218\ucde8\ud560 \uad8c\ub9ac\uc790\uc5d0\uac8c \uc18d\ud55c\ub2e4.","\ubb3c\uac74\uc758 \uc0ac\uc6a9\ub300\uac00\ub85c \ubc1b\ub294 \uae08\uc804 \uae30\ud0c0\uc758 \ubb3c\uac74\uc740 \ubc95\uc815\uacfc\uc2e4\uc774\ub2e4.","\ubc95\uc815\uacfc\uc2e4\uc740 \uc218\ucde8\ud560 \uad8c\ub9ac\uc758 \uc874\uc18d\uae30\uac04\uacfc \uad00\uacc4\uc5c6\uc774 \uc218\ucde8\uc77c\uc5d0 \uc804\uc561\uc774 \uadc0\uc18d\ub41c\ub2e4."],t.s)
B.aO9=s(["\ubc95\uc815\uacfc\uc2e4\uc740 \uc218\ucde8\ud560 \uad8c\ub9ac\uc758 \uc874\uc18d\uae30\uac04\uc77c\uc218\uc758 \ube44\uc728\ub85c \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec"],t.s)
B.afz=s(["\uc6d0\ubb3c\uacfc \uacfc\uc2e4","\ucc9c\uc5f0\uacfc\uc2e4\xb7\ubc95\uc815\uacfc\uc2e4","\uc81c101\uc870\xb7\uc81c102\uc870"],t.s)
B.bIT=new A.a("gen_cl_capacity_27","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc6d0\ubb3c\uacfc \uacfc\uc2e4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.bge,3,"\ubbfc\ubc95 \uc81c101\uc870 \uc81c1\ud56d\uc740 \ubb3c\uac74\uc758 \uc6a9\ubc95\uc5d0 \uc758\ud558\uc5ec \uc218\ucde8\ud558\ub294 \uc0b0\ucd9c\ubb3c\uc744 \ucc9c\uc5f0\uacfc\uc2e4\uc774\ub77c \ud558\uace0, \uc81c2\ud56d\uc740 \ubb3c\uac74\uc758 \uc0ac\uc6a9\ub300\uac00\ub85c \ubc1b\ub294 \uae08\uc804 \uae30\ud0c0 \ubb3c\uac74\uc744 \ubc95\uc815\uacfc\uc2e4\uc774\ub77c \uaddc\uc815\ud55c\ub2e4. \uc81c102\uc870 \uc81c1\ud56d\uc740 \ucc9c\uc5f0\uacfc\uc2e4\uc740 \ubd84\ub9ac\ud558\ub294 \ub54c\uc758 \uc218\ucde8\uad8c\uc790\uc5d0\uac8c \uc18d\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c2\ud56d\uc740 \ubc95\uc815\uacfc\uc2e4\uc740 \uc218\ucde8\ud560 \uad8c\ub9ac\uc758 \uc874\uc18d\uae30\uac04\uc77c\uc218\uc758 \ube44\uc728\ub85c \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \uc804\uc561\uc774 \uc544\ub2c8\ub77c \uc77c\uc218 \ube44\uc728\ub85c \uc548\ubd84\ub428\uc744 \ubc1d\ud788\uace0 \uc788\ub2e4.",B.aO9,B.afz,null)
B.anc=s(["\ubd88\ubc95\ud589\uc704\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c(\uc81c762\uc870)","\uc0c1\uc18d(\uc81c1000\uc870 \uc81c3\ud56d)","\uc720\uc99d(\uc81c1064\uc870)","\ud0dc\uc544 \uba85\uc758\ub85c \ud558\ub294 \ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uacc4\uc57d\uc758 \uccb4\uacb0"],t.s)
B.aPG=s(["\uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758\ub97c \ucde8\ud558\uc5ec \ud0dc\uc544\uc5d0\uac8c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c(\uc81c762\uc870), \uc0c1\uc18d(\uc81c1000\uc870 \uc81c3\ud56d), \ub300\uc2b5\uc0c1\uc18d, \uc720\uc99d"],t.s)
B.a74=s(["\ud0dc\uc544\uc758 \uad8c\ub9ac\ub2a5\ub825","\uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758","\uc81c762\uc870\xb7\uc81c1000\uc870"],t.s)
B.bKc=new A.a("gen_cl_capacity_28","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ud0dc\uc544\uc758 \uad8c\ub9ac\ub2a5\ub825\uc774 \uac1c\ubcc4\uc801\uc73c\ub85c \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.anc,3,"\ubbfc\ubc95\uc740 \uac1c\ubcc4\uc801 \ubcf4\ud638\uc8fc\uc758\ub97c \ucde8\ud558\uc5ec \ud0dc\uc544\uc5d0\uac8c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c(\uc81c762\uc870), \uc0c1\uc18d(\uc81c1000\uc870 \uc81c3\ud56d), \ub300\uc2b5\uc0c1\uc18d, \uc720\uc99d(\uc81c1064\uc870\uc5d0\uc11c \uc81c1000\uc870 \uc81c3\ud56d \uc900\uc6a9) \ub4f1\uc5d0 \uad00\ud558\uc5ec\ub9cc \uc774\ubbf8 \ucd9c\uc0dd\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub9e4\ub9e4\uacc4\uc57d \uccb4\uacb0\uacfc \uac19\uc740 \uc77c\ubc18 \uc7ac\uc0b0\ubc95\uc0c1 \ubc95\ub960\ud589\uc704 \ub2a5\ub825\uc740 \ud0dc\uc544\uc5d0\uac8c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aPG,B.a74,null)
B.a3l=s(["\ubc95\uc778 \uc544\ub2cc \uc0ac\ub2e8\uc5d0\ub294 \ubbfc\ubc95 \uc81c35\uc870\uac00 \uc720\ucd94\uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ud310\ub840\ub294 \ubc95\uc778 \uc544\ub2cc \uc0ac\ub2e8\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ud45c\uc790\uc758 \uc9c1\ubb34\uc5d0 \uad00\ud55c \ubd88\ubc95\ud589\uc704\ub85c \ud0c0\uc778\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \ub54c\uc5d0\ub294 \ubbfc\ubc95 \uc81c35\uc870\ub97c \uc720\ucd94\uc801\uc6a9\ud558\uc5ec \uc0ac\ub2e8\uc774 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \ubcf8\ub2e4.","\ubc95\uc778 \uc544\ub2cc \uc0ac\ub2e8\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\ub300\ud45c\uc790 \uac1c\uc778\uc740 \uc9c1\ubb34\uad00\ub828 \ubd88\ubc95\ud589\uc704\uc5d0 \ub300\ud574 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aYk=s(["\ubbfc\ubc95 \uc81c35\uc870 \uc81c1\ud56d\uc744 \uc720\ucd94\uc801\uc6a9\ud558\uc5ec \uc0ac\ub2e8 \uc790\uccb4\uac00 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aLP=s(["\ube44\ubc95\uc778\uc0ac\ub2e8","\uc81c35\uc870 \uc720\ucd94\uc801\uc6a9","\ud310\ub840"],t.s)
B.bNn=new A.a("gen_cl_capacity_29","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778 \uc544\ub2cc \uc0ac\ub2e8\uc758 \ub300\ud45c\uc790\uc758 \ubd88\ubc95\ud589\uc704\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.a3l,1,"\ud310\ub840\ub294 \ubc95\uc778\uaca9\uc774 \uc5c6\ub294 \uc0ac\ub2e8\uc774\ub77c\ub3c4 \uc0ac\ub2e8\uc73c\ub85c\uc11c\uc758 \uc2e4\uccb4\ub97c \uac16\ucd94\uace0 \uc788\ub294 \uc774\uc0c1 \uadf8 \ub300\ud45c\uc790\uac00 \uc9c1\ubb34\uc5d0 \uad00\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \uac00\ud55c \uc190\ud574\uc5d0 \ub300\ud558\uc5ec \ubbfc\ubc95 \uc81c35\uc870 \uc81c1\ud56d\uc744 \uc720\ucd94\uc801\uc6a9\ud558\uc5ec \uc0ac\ub2e8 \uc790\uccb4\uac00 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \ubcf8\ub2e4. \uc774 \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ud45c\uc790 \uac1c\uc778\uc758 \ucc45\uc784\uc740 \uba74\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aYk,B.aLP,null)
B.aBM=s(["\uc7ac\ub2e8\ubc95\uc778\uc758 \uc124\ub9bd\uc790\uac00 \uadf8 \uba85\uce6d, \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0 \ub610\ub294 \uc774\uc0ac\uc784\uba74\uc758 \ubc29\ubc95\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc0ac\ub9dd\ud55c \ub54c\uc5d0\ub294 \uc774\ud574\uad00\uacc4\uc778 \ub610\ub294 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \ubc95\uc6d0\uc774 \uc774\ub97c \uc815\ud55c\ub2e4.","\uc7ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\uc740 \uadf8 \ubcc0\uacbd\ubc29\ubc95\uc744 \uc815\uad00\uc5d0 \uc815\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4.","\uc7ac\ub2e8\ubc95\uc778\uc758 \ubaa9\uc801\ub2ec\uc131 \ub610\ub294 \uc7ac\uc0b0\ubcf4\uc804\uc744 \uc704\ud558\uc5ec \uc801\ub2f9\ud55c \uacbd\uc6b0, \uc124\ub9bd\uc790\ub098 \uc774\uc0ac\ub294 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \uadf8 \uba85\uce6d \ub610\ub294 \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0\ub97c \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4.","\uc7ac\ub2e8\ubc95\uc778\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \ub54c\uc5d0\ub294 \uc124\ub9bd\uc790\ub098 \uc774\uc0ac\ub294 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \uc124\ub9bd \ucde8\uc9c0\ub97c \ucc38\uc791\ud558\uc5ec \uadf8 \ubaa9\uc801 \uae30\ud0c0 \uc815\uad00\uc758 \uaddc\uc815\uc744 \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4."],t.s)
B.aKG=s(["\uba85\uce6d \ub610\ub294 \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0 \ubcc0\uacbd\uc740 \uadf8\ub7ec\ud55c \uc815\ud568\uc774 \uc5c6\uc5b4\ub3c4 \ubaa9\uc801\ub2ec\uc131 \ub610\ub294 \uc7ac\uc0b0\ubcf4\uc804\uc744 \uc704\ud574 \uac00\ub2a5\ud558\ub2e4\uace0 \uaddc\uc815\ud558\uba70"],t.s)
B.aSZ=s(["\uc7ac\ub2e8\ubc95\uc778 \uc815\uad00\ubcc0\uacbd","\uc81c44\uc870\xb7\uc81c45\uc870\xb7\uc81c46\uc870","\uc815\uad00\ubcf4\ucda9"],t.s)
B.btO=new A.a("gen_cl_capacity_30","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc7ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\ubcf4\ucda9 \ubc0f \ubaa9\uc801 \ub4f1 \ubcc0\uacbd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aBM,1,"\ubbfc\ubc95 \uc81c44\uc870\ub294 \uc7ac\ub2e8\ubc95\uc778\uc758 \uc124\ub9bd\uc790\uac00 \uba85\uce6d, \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0 \ub610\ub294 \uc774\uc0ac\uc784\uba74\uc758 \ubc29\ubc95\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \uc0ac\ub9dd\ud55c \ub54c\uc5d0\ub294 \uc774\ud574\uad00\uacc4\uc778 \ub610\ub294 \uac80\uc0ac\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \ubc95\uc6d0\uc774 \uc774\ub97c \uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc81c45\uc870 \uc81c1\ud56d\uc740 \uc7ac\ub2e8\ubc95\uc778\uc758 \uc815\uad00\uc740 \uadf8 \ubcc0\uacbd\ubc29\ubc95\uc744 \uc815\uad00\uc5d0 \uc815\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \ub3d9\uc870 \uc81c2\ud56d\uc740 \uba85\uce6d \ub610\ub294 \uc0ac\ubb34\uc18c \uc18c\uc7ac\uc9c0 \ubcc0\uacbd\uc740 \uadf8\ub7ec\ud55c \uc815\ud568\uc774 \uc5c6\uc5b4\ub3c4 \ubaa9\uc801\ub2ec\uc131 \ub610\ub294 \uc7ac\uc0b0\ubcf4\uc804\uc744 \uc704\ud574 \uac00\ub2a5\ud558\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc81c46\uc870\ub294 \ubaa9\uc801\ub2ec\uc131 \ubd88\ub2a5 \uc2dc \ubaa9\uc801 \ub4f1\uc744 \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aKG,B.aSZ,null)
B.aQB=s(["\ubb3c\uad8c\uc740 \ubc95\ub960 \ub610\ub294 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\ub294 \uc678\uc5d0\ub294 \uc784\uc758\ub85c \ucc3d\uc124\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub2f9\uc0ac\uc790\ub294 \uc0c8\ub85c\uc6b4 \uc885\ub958\uc758 \ubb3c\uad8c\uc744 \uc790\uc720\ub86d\uac8c \ucc3d\uc124\ud560 \uc218 \uc788\ub2e4.","\uad00\uc2b5\ubc95\uc0c1 \ubc95\uc815\uc9c0\uc0c1\uad8c\uc740 \ud310\ub840\uc0c1 \uc778\uc815\ub418\ub294 \ubb3c\uad8c\uc774\ub2e4.","\ubb3c\uad8c\uc758 \uc885\ub958\uc640 \ub0b4\uc6a9\uc740 \ubc95\ub960\ub85c \uc815\ud574\uc9c4 \uac83\uc5d0 \ud55c\uc815\ub41c\ub2e4."],t.s)
B.b8I=s(["\ubb3c\uad8c\uc740 \ubc95\ub960 \ub610\ub294 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uc9c0 \uc544\ub2c8\ud558\uace0\ub294 \uc784\uc758\ub85c \ucc3d\uc124\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.SL=s(["\ubb3c\uad8c\ubc95\uc815\uc8fc\uc758","\uc81c185\uc870"],t.s)
B.bKr=new A.a("gen_cl_realright_1","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubb3c\uad8c\ubc95\uc815\uc8fc\uc758\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c185\uc870\uc758 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aQB,1,"\ubbfc\ubc95 \uc81c185\uc870\ub294 \ubb3c\uad8c\ubc95\uc815\uc8fc\uc758\ub97c \uaddc\uc815\ud558\uc5ec \ubb3c\uad8c\uc740 \ubc95\ub960 \ub610\ub294 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uc9c0 \uc544\ub2c8\ud558\uace0\ub294 \uc784\uc758\ub85c \ucc3d\uc124\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ub2f9\uc0ac\uc790\uac00 \uc0c8\ub85c\uc6b4 \uc885\ub958\uc758 \ubb3c\uad8c\uc744 \uc790\uc720\ub86d\uac8c \ucc3d\uc124\ud558\ub294 \uac83\uc740 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.b8I,B.SL,null)
B.Rb=s(["\ub9e4\ub9e4\uacc4\uc57d\ub9cc\uc73c\ub85c \uc18c\uc720\uad8c\uc774\uc804\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4.","\ubbfc\ubc95 \uc81c186\uc870\uc5d0 \ub530\ub77c \ub4f1\uae30\ud558\uc5ec\uc57c \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\uc778\ub3c4\uac00 \uc788\uc73c\uba74 \ub4f1\uae30\uac00 \uc5c6\uc5b4\ub3c4 \uc18c\uc720\uad8c\uc774 \uc774\uc804\ub41c\ub2e4.","\uc810\uc720\uac1c\uc815\uc73c\ub85c \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ubcc0\ub3d9\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
