B.bRJ=new A.a("gen_cl_realright_20","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub4f1\uae30\ubd80\ucde8\ub4dd\uc2dc\ud6a8(\ubbfc\ubc95 \uc81c245\uc870 \uc81c2\ud56d)\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7V,0,"\ubbfc\ubc95 \uc81c245\uc870 \uc81c2\ud56d\uc740 \ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\ub85c \ub4f1\uae30\ud55c \uc790\uac00 10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\uc774 \uadf8 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc810\uc720\ucde8\ub4dd\uc2dc\ud6a8\uc640 \ub2ec\ub9ac \ub4f1\uae30\uc758 \uc874\uc7ac\ub97c \uc804\uc81c\ub85c \ud558\uace0 \uc810\uc720\uae30\uac04\ub3c4 10\ub144\uc73c\ub85c \ub2e8\ucd95\ub41c\ub2e4.",B.b78,B.b8l,null)
B.asn=s(["10\ub144\uac04 \uc18c\uc720\uc758 \uc758\uc0ac\ub85c \ud3c9\uc628\xb7\uacf5\uc5f0\ud558\uac8c \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \uc790\ub294 \uadf8 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\uc810\uc720\uc758 \uac1c\uc2dc\uc5d0 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \ub54c\uc5d0\ub294 5\ub144\uc758 \uc810\uc720\ub85c \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\ub3d9\uc0b0\uc758 \ucde8\ub4dd\uc2dc\ud6a8 \uae30\uac04\uc740 \ubd80\ub3d9\uc0b0\uacfc \ub3d9\uc77c\ud558\uac8c 20\ub144\uc774\ub2e4.","\ub3d9\uc0b0\uc5d0\ub294 \ucde8\ub4dd\uc2dc\ud6a8\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
