B.bJA=new A.a("gen_ba_ppe_17","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\uc720\ud615\uc790\uc0b0 \ucc98\ubd84 \uc2dc \ucc98\ubd84\uc190\uc775 \uacc4\uc0b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2U,0,"\uc720\ud615\uc790\uc0b0 \ucc98\ubd84\uc190\uc775\uc740 \ucc98\ubd84\uac00\uc561\uc5d0\uc11c \uc7a5\ubd80\uae08\uc561(\ucde8\ub4dd\uc6d0\uac00 \u2212 \uac10\uac00\uc0c1\uac01\ub204\uacc4\uc561 \u2212 \uc190\uc0c1\ucc28\uc190\ub204\uacc4\uc561 \ub4f1)\uc744 \ucc28\uac10\ud558\uc5ec \uacc4\uc0b0\ud55c\ub2e4. \ucc98\ubd84\uac00\uc561\uc774 \uc7a5\ubd80\uae08\uc561\ubcf4\ub2e4 \ud06c\uba74 \ucc98\ubd84\uc774\uc775, \uc791\uc73c\uba74 \ucc98\ubd84\uc190\uc2e4\uc774 \ubc1c\uc0dd\ud55c\ub2e4.",B.a7s,B.aDi,null)
