B.b3l=s(["\ub3d9\uae30\uc694\uc778\uacfc \uc704\uc0dd\uc694\uc778"],t.s)
B.by1=new A.a("gen_ba_ob_motiv_2","business_admin","\uc870\uc9c1\ud589\ub3d9\xb7\uc778\uc0ac\uad00\ub9ac","\ub3d9\uae30\ubd80\uc5ec\uc774\ub860","\ud5c8\uce20\ubc84\uadf8(F. Herzberg)\uc758 \ub3d9\uae30-\uc704\uc0dd\uc774\ub860(motivation-hygiene theory)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.baC,2,"\ud5c8\uce20\ubc84\uadf8\ub294 \ub9cc\uc871\uacfc \ubd88\ub9cc\uc871\uc744 \uc11c\ub85c \ub2e4\ub978 \ubcc4\uac1c\uc758 \ucc28\uc6d0\uc73c\ub85c \ubcf4\uc558\ub2e4. \uc784\uae08\xb7\uadfc\ubb34\uc870\uac74 \ub4f1 \uc704\uc0dd\uc694\uc778\uc740 \ubd80\uc871\ud558\uba74 \ubd88\ub9cc\uc871\uc744 \uc720\ubc1c\ud558\uc9c0\ub9cc, \ucda9\uc871\ub418\uc5b4\ub3c4 \ub2e8\uc9c0 \ubd88\ub9cc\uc871\uc744 \uc5c6\uc560\uc904 \ubfd0 \uc801\uadf9\uc801\uc778 \ub3d9\uae30\ubd80\uc5ec(\ub9cc\uc871)\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc131\ucde8\uac10\xb7\uc778\uc815\xb7\ucc45\uc784\uac10 \uac19\uc740 \ub3d9\uae30\uc694\uc778\uc774 \ucda9\uc871\ub418\uc5b4\uc57c \ube44\ub85c\uc18c \ub9cc\uc871\uacfc \ub3d9\uae30\ubd80\uc5ec\uac00 \ubc1c\uc0dd\ud55c\ub2e4.",B.b3G,B.b3l,null)
