B.bHZ=new A.a("gen_ba_ob_motiv_3","business_admin","\uc870\uc9c1\ud589\ub3d9\xb7\uc778\uc0ac\uad00\ub9ac","\ub3d9\uae30\ubd80\uc5ec\uc774\ub860","\ube0c\ub8f8(V. Vroom)\uc758 \uae30\ub300\uc774\ub860(expectancy theory)\uc5d0\uc11c \ub3d9\uae30\ubd80\uc5ec\uc758 \uac15\ub3c4\ub97c \uacb0\uc815\ud558\ub294 \uc694\uc18c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aC6,3,"\ube0c\ub8f8\uc758 \uae30\ub300\uc774\ub860\uc740 \ub178\ub825\ud558\uba74 \uc131\uacfc\ub97c \ub0bc \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c\uc778 \uae30\ub300, \uc131\uacfc\uac00 \ubcf4\uc0c1\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\ub294 \ubbff\uc74c\uc778 \uc218\ub2e8\uc131, \uadf8 \ubcf4\uc0c1\uc5d0 \ub300\ud574 \uac1c\uc778\uc774 \ub290\ub07c\ub294 \ub9e4\ub825\uc758 \uc815\ub3c4\uc778 \uc720\uc758\uc131, \uc774 \uc138 \uc694\uc18c\uc758 \uacf1\uc73c\ub85c \ub3d9\uae30\ubd80\uc5ec\uc758 \uac15\ub3c4\uac00 \uacb0\uc815\ub41c\ub2e4\uace0 \ubcf8\ub2e4. \ud615\ud3c9\uc131(\uacf5\uc815\uc131)\uc740 \uc544\ub2f4\uc2a4\uc758 \uacf5\uc815\uc131\uc774\ub860\uc5d0\uc11c \ub2e4\ub8e8\ub294 \uac1c\ub150\uc774\ub2e4.",B.aVl,B.aCw,null)
B.aIM=s(["\uac1c\uc778\uc740 \uc790\uc2e0\uc758 \ud22c\uc785 \ub300\ube44 \uc0b0\ucd9c \ube44\uc728\uc744 \uc900\uac70\uc778\ubb3c\uc758 \ube44\uc728\uacfc \ube44\uad50\ud558\uc5ec \uacf5\uc815\uc131\uc744 \uc9c0\uac01\ud55c\ub2e4","\uac1c\uc778\uc740 \ud56d\uc0c1 \uc808\ub300\uc801\uc778 \ubcf4\uc0c1\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \ub9cc\uc871\uc744 \ub290\ub080\ub2e4","\ubd88\uacf5\uc815\uc131\uc744 \uc9c0\uac01\ud558\ub354\ub77c\ub3c4 \uac1c\uc778\uc758 \ud589\ub3d9\uc5d0\ub294 \uc544\ubb34\ub7f0 \ubcc0\ud654\uac00 \ub098\ud0c0\ub098\uc9c0 \uc54a\ub294\ub2e4","\uacf5\uc815\uc131\uc774\ub860\uc740 \uac1c\uc778\uc758 \ud558\uc704 \uc695\uad6c \ucda9\uc871\ub9cc\uc744 \ub2e4\ub8ec\ub2e4"],t.s)
