B.RC=s(["\uc720\ud1b5\uc8fc\uc2dd\uc218\ub97c \uc904\uc5ec \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc744 \ub192\uc774\ub294 \ud6a8\uacfc\uac00 \uc788\ub2e4","\ud604\uae08\ubc30\ub2f9\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc8fc\uc8fc\uc5d0\uac8c \ud604\uae08\uc744 \ud658\uc6d0\ud558\ub294 \uc218\ub2e8 \uc911 \ud558\ub098\uc774\ub2e4","\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ud754\ud788 \uacbd\uc601\uc9c4\uc774 \uc790\uc0ac \uc8fc\uac00\uac00 \uc800\ud3c9\uac00\ub418\uc5b4 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ud558\uae30\ub3c4 \ud55c\ub2e4","\uc790\uc0ac\uc8fc\ub9e4\uc785\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc8fc\ub2f9\uc21c\uc774\uc775\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.apm=s(["\uc720\ud1b5\uc8fc\uc2dd\uc218\uac00 \uc904\uc5b4\ub4e4\uba74, \ub3d9\uc77c\ud55c \ub2f9\uae30\uc21c\uc774\uc775\uc744 \ub354 \uc801\uc740 \uc8fc\uc2dd\uc218\ub85c \ub098\ub204\uac8c \ub418\uc5b4 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc774 \ud1b5\uc0c1\uc801\uc73c\ub85c \ub192\uc544\uc9c0\ub294 \ud6a8\uacfc"],t.s)
