B.bKR=new A.a("gen_ba_fin_dividend_3","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\uc790\uc0ac\uc8fc\ub9e4\uc785(stock repurchase)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.RC,3,'\uc790\uc0ac\uc8fc\ub9e4\uc785\uc73c\ub85c \uc720\ud1b5\uc8fc\uc2dd\uc218\uac00 \uc904\uc5b4\ub4e4\uba74, \ub3d9\uc77c\ud55c \ub2f9\uae30\uc21c\uc774\uc775\uc744 \ub354 \uc801\uc740 \uc8fc\uc2dd\uc218\ub85c \ub098\ub204\uac8c \ub418\uc5b4 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc774 \ud1b5\uc0c1\uc801\uc73c\ub85c \ub192\uc544\uc9c0\ub294 \ud6a8\uacfc\uac00 \uc788\ub2e4. "\uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.apm,B.VC,null)
B.aJG=s(["\ucc44\uad8c\uc744 \ub9cc\uae30\uae4c\uc9c0 \ubcf4\uc720\ud560 \ub54c \uc5bb\uac8c \ub418\ub294 \ub0b4\ubd80\uc218\uc775\ub960 \uac1c\ub150\uc758 \uc218\uc775\ub960\uc774\ub2e4","\ucc44\uad8c\uc758 \ud45c\uba74(\uc561\uba74)\uc774\uc790\uc728\uacfc \ud56d\uc0c1 \ub3d9\uc77c\ud55c \uac12\uc744 \uac16\ub294\ub2e4","\uc2dc\uc7a5\uc774\uc790\uc728\uc774 \uc0c1\uc2b9\ud558\uba74 \ucc44\uad8c\uac00\uaca9\uacfc \ub9cc\uae30\uc218\uc775\ub960\uc774 \ud568\uaed8 \uc0c1\uc2b9\ud55c\ub2e4","\ub9cc\uae30\uc218\uc775\ub960\uc740 \ucc44\uad8c \ubc1c\ud589 \ub2f9\uc2dc \ud55c\ubc88 \uc815\ud574\uc9c0\uba74 \uc774\ud6c4 \ubcc0\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aF8=s(["\ucc44\uad8c\uc758 \ud604\uc7ac \uc2dc\uc7a5\uac00\uaca9\uc744 \ubbf8\ub798 \ud604\uae08\ud750\ub984(\uc774\uc790\uc640 \uc6d0\uae08)\uc758 \ud604\uc7ac\uac00\uce58\uc640 \uac19\uac8c \ub9cc\ub4dc\ub294 \ud560\uc778\uc728\ub85c, \ucc44\uad8c\uc744 \ub9cc\uae30\uae4c\uc9c0 \ubcf4\uc720\ud588\uc744 \ub54c\uc758 \ub0b4\ubd80\uc218\uc775\ub960"],t.s)
