B.bxf=new A.a("gen_ba_fin_dividend_4","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\ucc44\uad8c\uc758 \ub9cc\uae30\uc218\uc775\ub960(yield to maturity)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aJG,0,"\ub9cc\uae30\uc218\uc775\ub960\uc740 \ucc44\uad8c\uc758 \ud604\uc7ac \uc2dc\uc7a5\uac00\uaca9\uc744 \ubbf8\ub798 \ud604\uae08\ud750\ub984(\uc774\uc790\uc640 \uc6d0\uae08)\uc758 \ud604\uc7ac\uac00\uce58\uc640 \uac19\uac8c \ub9cc\ub4dc\ub294 \ud560\uc778\uc728\ub85c, \ucc44\uad8c\uc744 \ub9cc\uae30\uae4c\uc9c0 \ubcf4\uc720\ud588\uc744 \ub54c\uc758 \ub0b4\ubd80\uc218\uc775\ub960\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc2dc\uc7a5\uc774\uc790\uc728\uc774 \uc0c1\uc2b9\ud558\uba74 \ucc44\uad8c\uac00\uaca9\uc740 \ud558\ub77d\ud558\uace0 \ub9cc\uae30\uc218\uc775\ub960\uc740 \uc0c1\uc2b9\ud558\ub294 \ubc18\ub300 \uad00\uacc4\ub97c \uac00\uc9c0\uba70, \uc2dc\uc7a5\uac00\uaca9 \ubcc0\ub3d9\uc5d0 \ub530\ub77c \ub9cc\uae30\uc218\uc775\ub960\ub3c4 \uacc4\uc18d \ubcc0\ud55c\ub2e4.",B.aF8,B.amx,null)
B.a6Z=s(["\uc2dc\uc7a5\uc774\uc790\uc728\uc774 \uc0c1\uc2b9\ud558\uba74 \ucc44\uad8c\uac00\uaca9\uc740 \ud558\ub77d\ud55c\ub2e4","\ucc44\uad8c\uac00\uaca9\uacfc \uc2dc\uc7a5\uc774\uc790\uc728\uc740 \uc11c\ub85c \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4","\ub2e4\ub978 \uc870\uac74\uc774 \ub3d9\uc77c\ud558\ub2e4\uba74 \ub9cc\uae30\uac00 \uae34 \ucc44\uad8c\uc77c\uc218\ub85d \uc774\uc790\uc728 \ubcc0\ub3d9\uc5d0 \ub300\ud55c \uac00\uaca9 \ubbfc\uac10\ub3c4\uac00 \ud06c\ub2e4","\ucc44\uad8c\uac00\uaca9\uc740 \uc2dc\uc7a5\uc774\uc790\uc728\uacfc \uad00\uacc4\uc5c6\uc774 \uc561\uba74\uac00\ub85c \ud56d\uc0c1 \uace0\uc815\ub418\uc5b4 \uc788\ub2e4"],t.s)
B.b5Z=s(["\ucc44\uad8c\uac00\uaca9\uc740 \uc2dc\uc7a5\uc774\uc790\uc728(\ud560\uc778\uc728)\uc758 \ubcc0\ub3d9\uc5d0 \ub530\ub77c \uacc4\uc18d \ubcc0\ub3d9\ud55c\ub2e4"],t.s)
B.a78=s(["\ucc44\uad8c\uac00\uaca9\uacfc \uc774\uc790\uc728\uc758 \ubc18\ube44\ub840 \uad00\uacc4"],t.s)
B.bqs=new A.a("gen_ba_fin_dividend_5","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\ucc44\uad8c\uac00\uaca9\uacfc \uc2dc\uc7a5\uc774\uc790\uc728\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a6Z,3,"\ucc44\uad8c\uac00\uaca9\uc740 \uc2dc\uc7a5\uc774\uc790\uc728(\ud560\uc778\uc728)\uc758 \ubcc0\ub3d9\uc5d0 \ub530\ub77c \uacc4\uc18d \ubcc0\ub3d9\ud55c\ub2e4. \uc2dc\uc7a5\uc774\uc790\uc728\uc774 \uc0c1\uc2b9\ud558\uba74 \ubbf8\ub798 \ud604\uae08\ud750\ub984\uc758 \ud604\uc7ac\uac00\uce58\uac00 \uc791\uc544\uc838 \ucc44\uad8c\uac00\uaca9\uc740 \ud558\ub77d\ud558\uace0, \ud558\ub77d\ud558\uba74 \ucc44\uad8c\uac00\uaca9\uc740 \uc0c1\uc2b9\ud558\ub294 \ubc18\ube44\ub840 \uad00\uacc4\ub97c \uac00\uc9c0\uba70, \ub9cc\uae30\uac00 \uae38\uc218\ub85d \uc774\ub7ec\ud55c \uac00\uaca9 \ubcc0\ub3d9\ud3ed\uc774 \ub354 \ud06c\uac8c \ub098\ud0c0\ub09c\ub2e4.",B.b5Z,B.a78,null)
B.a9B=s(["\ubc30\ub2f9\uc758 \ubcc0\ud654\uac00 \uacbd\uc601\uc9c4\uc774 \uac00\uc9c4 \ubbf8\ub798 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc0ac\uc801 \uc815\ubcf4\ub97c \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ud558\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc2dc\uc7a5\uc5d0 \uc544\ubb34\ub7f0 \uc815\ubcf4\ub97c \uc804\ub2ec\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc744 \ub298\ub9ac\uba74 \uc608\uc678 \uc5c6\uc774 \uc8fc\uac00\uac00 \ud558\ub77d\ud55c\ub2e4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc815\ucc45\uacfc \uae30\uc5c5\uc758 \ubbf8\ub798 \uc218\uc775\uc131\uc740 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud558\ub2e4\uace0 \ub2e8\uc815\ud558\ub294 \uc774\ub860\uc774\ub2e4"],t.s)
B.aCY=s(["\uacbd\uc601\uc9c4\uc758 \ubc30\ub2f9 \uc99d\uc561\xb7\uac10\uc561 \uacb0\uc815\uc774 \uadf8 \uae30\uc5c5\uc758 \ubbf8\ub798 \uc218\uc775\uc131\uc5d0 \ub300\ud574 \uacbd\uc601\uc9c4\uc774 \uac00\uc9c4 \uc0ac\uc801 \uc815\ubcf4\ub97c \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ud558\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9"],t.s)
