B.bRu=new A.a("gen_ba_fin_dividend_6","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\ubc30\ub2f9\uc758 \uc2e0\ud638\ud6a8\uacfc(signaling effect)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a9B,0,"\ubc30\ub2f9\uc758 \uc2e0\ud638\ud6a8\uacfc \uc774\ub860\uc740 \uc815\ubcf4\ube44\ub300\uce6d \uc0c1\ud669\uc5d0\uc11c \uacbd\uc601\uc9c4\uc758 \ubc30\ub2f9 \uc99d\uc561\xb7\uac10\uc561 \uacb0\uc815\uc774 \uadf8 \uae30\uc5c5\uc758 \ubbf8\ub798 \uc218\uc775\uc131\uc5d0 \ub300\ud574 \uacbd\uc601\uc9c4\uc774 \uac00\uc9c4 \uc0ac\uc801 \uc815\ubcf4\ub97c \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ud558\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc77c\ubc18\uc801\uc73c\ub85c \ubc30\ub2f9 \uc99d\uc561\uc740 \uae0d\uc815\uc801 \uc2e0\ud638\ub85c, \ubc30\ub2f9 \uac10\uc561\uc740 \ubd80\uc815\uc801 \uc2e0\ud638\ub85c \uc2dc\uc7a5\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.aCY,B.a2P,null)
B.baF=s(["\ud0c0\uc778\uc790\ubcf8\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \uc790\uae30\uc790\ubcf8\ub9cc\uc73c\ub85c \uc790\uae08\uc744 \uc870\ub2ec\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uace0\uc815\uc601\uc5c5\ube44\uc6a9\uc758 \uc874\uc7ac\ub85c \uc778\ud574 \ub9e4\ucd9c\uc561 \ubcc0\ud654\uc728\ubcf4\ub2e4 \uc601\uc5c5\uc774\uc775 \ubcc0\ud654\uc728\uc774 \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \ud6a8\uacfc\uc774\ub2e4","\ud0c0\uc778\uc790\ubcf8(\ubd80\ucc44) \uc0ac\uc6a9\uc73c\ub85c \uc778\ud574 \uc601\uc5c5\uc774\uc775 \ubcc0\ud654\uc728\ubcf4\ub2e4 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS) \ubcc0\ud654\uc728\uc774 \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \ud6a8\uacfc\uc774\ub2e4","\uc7ac\ubb34\ub808\ubc84\ub9ac\uc9c0\uac00 \ub192\uc744\uc218\ub85d \uae30\uc5c5\uc758 \uc7ac\ubb34\uc704\ud5d8\uc740 \ud56d\uc0c1 \ub0ae\uc544\uc9c4\ub2e4"],t.s)
B.X8=s(["\ud0c0\uc778\uc790\ubcf8(\ubd80\ucc44) \uc0ac\uc6a9\uc73c\ub85c \uc778\ud574 \uc601\uc5c5\uc774\uc775 \ubcc0\ud654\uc728\ubcf4\ub2e4 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS) \ubcc0\ud654\uc728\uc774 \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \ud6a8\uacfc"],t.s)
B.Tc=s(["\uc601\uc5c5\ub808\ubc84\ub9ac\uc9c0\uc640 \uc7ac\ubb34\ub808\ubc84\ub9ac\uc9c0\uc758 \uad6c\ubd84"],t.s)
B.bNg=new A.a("gen_ba_fin_capstr_1","business_admin","\uc7ac\ubb34\uad00\ub9ac","\uc790\ubcf8\uad6c\uc870\uc640 \uc7ac\ubb34\ube44\uc728","\uc7ac\ubb34\ub808\ubc84\ub9ac\uc9c0(financial leverage)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.baF,2,"\uc7ac\ubb34\ub808\ubc84\ub9ac\uc9c0\ub294 \uc774\uc790\ube44\uc6a9\uacfc \uac19\uc740 \uace0\uc815\uc7ac\ubb34\ube44\uc6a9\uc774 \uc874\uc7ac\ud558\ub294 \ubd80\ucc44\ub97c \uc0ac\uc6a9\ud568\uc73c\ub85c\uc368, \uc601\uc5c5\uc774\uc775\uc758 \ubcc0\ud654\uc728\ubcf4\ub2e4 \uc8fc\uc8fc \ubaab\uc778 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc758 \ubcc0\ud654\uc728\uc774 \ud655\ub300\ub418\uc5b4 \ub098\ud0c0\ub098\ub294 \ud6a8\uacfc\ub97c \ub9d0\ud55c\ub2e4. \ub9e4\ucd9c\uc561 \ubcc0\ud654\uc728 \ub300\ube44 \uc601\uc5c5\uc774\uc775 \ubcc0\ud654\uc728\uc774 \ud655\ub300\ub418\ub294 \ud6a8\uacfc\ub294 \uc601\uc5c5\ub808\ubc84\ub9ac\uc9c0\uc774\ub2e4.",B.X8,B.Tc,null)
B.aO_=s(["\uc644\uc804\uc790\ubcf8\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc790\ubcf8\uad6c\uc870(\ubd80\ucc44\uc640 \uc790\uae30\uc790\ubcf8\uc758 \ube44\uc728)\uac00 \uae30\uc5c5\uac00\uce58\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4","\ubd80\ucc44\ube44\uc728\uc774 \ub192\uc544\uc9c8\uc218\ub85d \uae30\uc5c5\uac00\uce58\uac00 \ud56d\uc0c1 \uc99d\uac00\ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud55c\ub2e4","\ubc95\uc778\uc138\uac00 \uc788\ub294 \ud604\uc2e4\uc5d0\uc11c\ub3c4 \uc790\ubcf8\uad6c\uc870\ub294 \uae30\uc5c5\uac00\uce58\uc640 \ubb34\uad00\ud558\ub2e4\uace0 \uacb0\ub860\uc9d3\ub294\ub2e4","\uc790\uae30\uc790\ubcf8\ub9cc \uc0ac\uc6a9\ud558\ub294 \uae30\uc5c5\uc758 \uac00\uce58\uac00 \ud56d\uc0c1 \uac00\uc7a5 \ub192\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
