B.aGG=s(["\ud488\uc9c8\uad00\ub9ac \ubd80\uc11c\ub9cc\uc758 \ucc45\uc784\uc774 \uc544\ub2c8\ub77c \uc804 \uc870\uc9c1 \uad6c\uc131\uc6d0\uc758 \ucc38\uc5ec\ub97c \uac15\uc870\ud55c\ub2e4","\uace0\uac1d\ub9cc\uc871\uc744 \ud488\uc9c8\uacbd\uc601\uc758 \ud575\uc2ec \ubaa9\ud45c\ub85c \uc0bc\ub294\ub2e4","\uc9c0\uc18d\uc801\uc778 \ud504\ub85c\uc138\uc2a4 \uac1c\uc120(\uce74\uc774\uc820)\uc744 \uc911\uc2dc\ud55c\ub2e4","\uac80\uc0ac\ub97c \ud1b5\ud55c \ubd88\ub7c9\ud488 \uc0ac\ud6c4 \uc120\ubcc4\uc5d0\ub9cc \uc9d1\uc911\ud558\uace0 \uc608\ubc29\ud65c\ub3d9\uc740 \uc911\uc694\ud558\uac8c \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b4s=s(["\uc0ac\ud6c4 \uac80\uc0ac\ub97c \ud1b5\ud55c \ubd88\ub7c9 \uc120\ubcc4\ubcf4\ub2e4, \uc560\ucd08\uc5d0 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud504\ub85c\uc138\uc2a4 \uc790\uccb4\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \uac1c\uc120\ud558\ub294 \uc608\ubc29 \uc911\uc2ec\uc758 \uc811\uadfc"],t.s)
B.bgX=s(["\uc804\uc0ac\uc801\ud488\uc9c8\uacbd\uc601(TQM)\uc758 \ud575\uc2ec"],t.s)
B.bt6=new A.a("gen_ba_ops_qc_6","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\ud488\uc9c8\uad00\ub9ac","\uc804\uc0ac\uc801\ud488\uc9c8\uacbd\uc601(TQM: Total Quality Management)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aGG,3,'TQM\uc740 \uc0ac\ud6c4 \uac80\uc0ac\ub97c \ud1b5\ud55c \ubd88\ub7c9 \uc120\ubcc4\ubcf4\ub2e4, \uc560\ucd08\uc5d0 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud504\ub85c\uc138\uc2a4 \uc790\uccb4\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \uac1c\uc120\ud558\ub294 \uc608\ubc29 \uc911\uc2ec\uc758 \uc811\uadfc\uacfc \uc804\uc0ac\uc801 \ucc38\uc5ec, \uace0\uac1d\ub9cc\uc871\uc744 \ud575\uc2ec\uc73c\ub85c \ud55c\ub2e4. "\uc608\ubc29\ud65c\ub3d9\uc740 \uc911\uc694\ud558\uac8c \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.b4s,B.bgX,null)
B.ams=s(["\ud544\uc694\ud55c \ubd80\ud488\uc744 \ud544\uc694\ud55c \uc2dc\uc810\uc5d0 \ud544\uc694\ud55c \ub9cc\ud07c\ub9cc \uacf5\uae09\ubc1b\uc544 \uc7ac\uace0\ub97c \ucd5c\uc18c\ud654\ud558\ub294 \uac83\uc744 \uc9c0\ud5a5\ud55c\ub2e4","\uc7ac\uace0\ub97c \ub0ad\ube44\uc758 \ud55c \ud615\ud0dc\ub85c \ubcf4\uace0 \uc774\ub97c \uc904\uc774\ub294 \uac83\uc744 \ud575\uc2ec \ubaa9\ud45c\ub85c \uc0bc\ub294\ub2e4","\uc218\uc694 \ubcc0\ub3d9\uc774\ub098 \ud488\uc9c8 \ubb38\uc81c\uc5d0 \ub300\uc751\ud558\uae30 \uc704\ud574 \ub109\ub109\ud55c \uc644\ucda9\uc7ac\uace0\ub97c \uc720\uc9c0\ud558\ub294 \uac83\uc744 \uc6d0\uce59\uc73c\ub85c \ud55c\ub2e4","\ud611\ub825\uc5c5\uccb4\uc640\uc758 \uae34\ubc00\ud55c \uc815\ubcf4 \uacf5\uc720\uc640 \uc548\uc815\uc801\uc778 \ub0a9\ud488 \uccb4\uacc4\uac00 \ub4b7\ubc1b\uce68\ub418\uc5b4\uc57c \ud6a8\uacfc\uc801\uc73c\ub85c \uc6b4\uc601\ub41c\ub2e4"],t.s)
B.V4=s(["JIT\ub294 \uc7ac\uace0\ub97c \ub0ad\ube44\ub85c \uac04\uc8fc\ud558\uace0 \uc774\ub97c \ucd5c\uc18c\ud654\ud558\ub294 \uac83\uc774 \ud575\uc2ec \ucca0\ud559\uc774\ubbc0\ub85c, \ub109\ub109\ud55c \uc644\ucda9\uc7ac\uace0\ub97c \uc720\uc9c0\ud558\ub294 \uac83\uacfc\ub294 \uc815\ubc18\ub300\uc758 \ubc29\ud5a5"],t.s)
B.a_X=s(["JIT \uc0dd\uc0b0\ubc29\uc2dd\uc758 \ucca0\ud559"],t.s)
B.bMj=new A.a("gen_ba_ops_system_1","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","JIT(just in time) \uc0dd\uc0b0\ubc29\uc2dd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ams,2,"JIT\ub294 \uc7ac\uace0\ub97c \ub0ad\ube44\ub85c \uac04\uc8fc\ud558\uace0 \uc774\ub97c \ucd5c\uc18c\ud654\ud558\ub294 \uac83\uc774 \ud575\uc2ec \ucca0\ud559\uc774\ubbc0\ub85c, \ub109\ub109\ud55c \uc644\ucda9\uc7ac\uace0\ub97c \uc720\uc9c0\ud558\ub294 \uac83\uacfc\ub294 \uc815\ubc18\ub300\uc758 \ubc29\ud5a5\uc774\ub2e4. \uc624\ud788\ub824 \uc7ac\uace0\ub97c \uc904\uc774\ub294 \ub300\uc2e0 \ud611\ub825\uc5c5\uccb4\uc640\uc758 \uc815\ubcf4 \uacf5\uc720\xb7\ud488\uc9c8 \uc548\uc815\ud654\ub97c \ud1b5\ud574 \ubb38\uc81c \ubc1c\uc0dd \uac00\ub2a5\uc131 \uc790\uccb4\ub97c \ub0ae\ucd94\ub294 \ubc29\uc2dd\uc73c\ub85c \ub300\uc751\ud55c\ub2e4.",B.V4,B.a_X,null)
B.aqE=s(["\uc218\uc694 \ubcc0\ub3d9\uacfc \ubb34\uad00\ud558\uac8c \uc0dd\uc0b0\uc728\uc744 \ud56d\uc0c1 \uc77c\uc815\ud558\uac8c \uc720\uc9c0\ud558\ub294 \uc804\ub7b5\uc774\ub2e4","\uc218\uc694 \ubcc0\ub3d9\uc5d0 \ub9de\ucd94\uc5b4 \uace0\uc6a9 \uc218\uc900\uc774\ub098 \uc0dd\uc0b0\uc728\uc744 \uadf8\ub54c\uadf8\ub54c \uc870\uc815\ud574 \ub098\uac00\ub294 \uc804\ub7b5\uc774\ub2e4","\uc7ac\uace0\ub97c \uc804\ud600 \ubcf4\uc720\ud558\uc9c0 \uc54a\uace0 \uc218\uc694\ub97c \ubaa8\ub450 \uc774\uc6d4\uc8fc\ubb38\uc73c\ub85c \ucc98\ub9ac\ud558\ub294 \uc804\ub7b5\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc218\uc694\uc608\uce21 \uc790\uccb4\ub97c \ud558\uc9c0 \uc54a\uace0 \uc0dd\uc0b0\uacc4\ud68d\uc744 \uc218\ub9bd\ud558\ub294 \uc804\ub7b5\uc774\ub2e4"],t.s)
B.aI0=s(["\uc218\uc694\ucd94\uc885\uc804\ub7b5(chase strategy)\uc740 \uc608\uce21\ub41c \uc218\uc694 \ubcc0\ub3d9\uc5d0 \ub9de\ucd94\uc5b4 \uace0\uc6a9\ub7c9\uc774\ub098 \uc0dd\uc0b0\uc728, \uc794\uc5c5 \ub4f1\uc744 \uadf8\ub54c\uadf8\ub54c \uc870\uc815\ud558\uc5ec \ub300\uc751\ud558\ub294 \uc804\ub7b5"],t.s)
B.b8h=s(["\uc218\uc694\ucd94\uc885\uc804\ub7b5\uacfc \ud3c9\uc900\ud654\uc804\ub7b5"],t.s)
B.byD=new A.a("gen_ba_ops_system_2","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","\ucd1d\uad04\uc0dd\uc0b0\uacc4\ud68d\uc5d0\uc11c \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \uc218\uc694\uc804\ub7b5(\ucd94\uc885\uc804\ub7b5)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aqE,1,"\uc218\uc694\ucd94\uc885\uc804\ub7b5(chase strategy)\uc740 \uc608\uce21\ub41c \uc218\uc694 \ubcc0\ub3d9\uc5d0 \ub9de\ucd94\uc5b4 \uace0\uc6a9\ub7c9(\ucc44\uc6a9\xb7\ud574\uace0)\uc774\ub098 \uc0dd\uc0b0\uc728, \uc794\uc5c5 \ub4f1\uc744 \uadf8\ub54c\uadf8\ub54c \uc870\uc815\ud558\uc5ec \ub300\uc751\ud558\ub294 \uc804\ub7b5\uc774\ub2e4. \uc0dd\uc0b0\uc728\uc744 \uc77c\uc815\ud558\uac8c \uc720\uc9c0\ud558\uba70 \uc7ac\uace0\ub85c \uc218\uc694 \ubcc0\ub3d9\uc744 \ud761\uc218\ud558\ub294 \uc804\ub7b5\uc740 \ud3c9\uc900\ud654\uc804\ub7b5(level strategy)\uc774\ub2e4.",B.aI0,B.b8h,null)
B.bfk=s(["\ub3c5\ub9bd\uc218\uc694\ub97c \uac16\ub294 \uc644\uc81c\ud488\uc758 \uc218\uc694\uc608\uce21\uc5d0\ub294 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub294 \uae30\ubc95\uc774\ub2e4","\uc644\uc81c\ud488\uc758 \uc0dd\uc0b0\uc77c\uc815(\uae30\uc900\uc0dd\uc0b0\uacc4\ud68d)\uc744 \ud1a0\ub300\ub85c \uc885\uc18d\uc218\uc694\ub97c \uac16\ub294 \ubd80\ud488\xb7\uc6d0\uc790\uc7ac\uc758 \uc18c\uc694\ub7c9\uacfc \uc2dc\uae30\ub97c \uc5ed\uc0b0\ud558\ub294 \uae30\ubc95\uc774\ub2e4","\uc7ac\uace0 \uc218\uc900\uacfc \uad00\uacc4\uc5c6\uc774 \uc815\ud574\uc9c4 \uc8fc\uae30\ub9c8\ub2e4 \ub3d9\uc77c\ud55c \uc591\uc744 \uc8fc\ubb38\ud558\ub294 \uae30\ubc95\uc774\ub2e4","\uc11c\ube44\uc2a4\uc5c5\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ub418\uace0 \uc81c\uc870\uc5c5\uc5d0\uc11c\ub294 \ud65c\uc6a9\ub418\uc9c0 \uc54a\ub294 \uae30\ubc95\uc774\ub2e4"],t.s)
B.b5p=s(["\uc644\uc81c\ud488\uc758 \uc0dd\uc0b0\uc77c\uc815(\uae30\uc900\uc0dd\uc0b0\uacc4\ud68d)\uc744 \ud1a0\ub300\ub85c \uc885\uc18d\uc218\uc694\ub97c \uac16\ub294 \ubd80\ud488\xb7\uc6d0\uc790\uc7ac\uc758 \uc18c\uc694\ub7c9\uacfc \uc2dc\uae30\ub97c \uc5ed\uc0b0\ud558\ub294 \uae30\ubc95"],t.s)
B.agB=s(["MRP\uc758 \uac1c\ub150"],t.s)
B.bQH=new A.a("gen_ba_ops_system_3","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","\uc790\uc7ac\uc18c\uc694\uacc4\ud68d(MRP: Material Requirements Planning)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.bfk,1,"MRP\ub294 \uc644\uc81c\ud488\uc5d0 \ub300\ud55c \uae30\uc900\uc0dd\uc0b0\uacc4\ud68d(MPS)\uacfc \uc790\uc7ac\uba85\uc138\uc11c(BOM)\ub97c \ubc14\ud0d5\uc73c\ub85c, \uc644\uc81c\ud488 \uc0dd\uc0b0\uc5d0 \ud544\uc694\ud55c \ubd80\ud488\xb7\uc6d0\uc790\uc7ac\ucc98\ub7fc \uc644\uc81c\ud488 \uc218\uc694\uc5d0 \uc885\uc18d\ub418\uc5b4 \ubc1c\uc0dd\ud558\ub294 \uc885\uc18d\uc218\uc694 \ud488\ubaa9\uc758 \ud544\uc694 \uc218\ub7c9\uacfc \uc2dc\uae30\ub97c \uc5ed\uc0b0\ud558\uc5ec \uc0b0\ucd9c\ud558\ub294 \uc0dd\uc0b0\uad00\ub9ac \uae30\ubc95\uc774\ub2e4.",B.b5p,B.agB,null)
B.amB=s(["\ud45c\uc900\ud654\ub41c \uc81c\ud488\uc744 \ub300\ub7c9\uc73c\ub85c \uc0dd\uc0b0\ud558\ub294 \ub370 \uc801\ud569\ud558\ub2e4","\uc124\ube44\uac00 \uc81c\ud488\uc758 \uc791\uc5c5 \uc21c\uc11c\uc5d0 \ub530\ub77c \uc77c\ub82c\ub85c \ubc30\uce58\ub41c\ub2e4","\ud55c \uacf5\uc815\uc5d0\uc11c \ubcd1\ubaa9\uc774 \ubc1c\uc0dd\ud558\uba74 \uc804\uccb4 \ub77c\uc778\uc758 \uc0dd\uc0b0 \uc18d\ub3c4\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4","\ub2e4\ud488\uc885 \uc18c\ub7c9\uc0dd\uc0b0\uacfc \uc7a6\uc740 \uc81c\ud488 \uc0ac\uc591 \ubcc0\uacbd\uc5d0 \uac00\uc7a5 \uc801\ud569\ud55c \ubc29\uc2dd\uc774\ub2e4"],t.s)
B.akx=s(["\ub77c\uc778\uc0dd\uc0b0\ubc29\uc2dd\uc740 \ud45c\uc900\ud654\ub41c \uc18c\ud488\uc885\uc744 \ub300\ub7c9\uc73c\ub85c \uc0dd\uc0b0\ud560 \ub54c \ud6a8\uc728\uc774 \uadf9\ub300\ud654\ub418\ub294 \ubc29\uc2dd\uc73c\ub85c, \ub2e4\ud488\uc885 \uc18c\ub7c9\uc0dd\uc0b0\uc774\ub098 \uc7a6\uc740 \uc0ac\uc591 \ubcc0\uacbd\uc5d0\ub294 \uc624\ud788\ub824 \uc801\ud569\ud558\uc9c0 \uc54a\ub2e4"],t.s)
B.aio=s(["\ub77c\uc778\uc0dd\uc0b0\ubc29\uc2dd\uacfc \uac1c\ubcc4\uc0dd\uc0b0\ubc29\uc2dd"],t.s)
B.bMm=new A.a("gen_ba_ops_system_4","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","\uc0dd\uc0b0\uacf5\uc815 \uc720\ud615 \uc911 \ub77c\uc778\uc0dd\uc0b0\ubc29\uc2dd(line production)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.amB,3,"\ub77c\uc778\uc0dd\uc0b0\ubc29\uc2dd\uc740 \ud45c\uc900\ud654\ub41c \uc18c\ud488\uc885\uc744 \ub300\ub7c9\uc73c\ub85c \uc0dd\uc0b0\ud560 \ub54c \ud6a8\uc728\uc774 \uadf9\ub300\ud654\ub418\ub294 \ubc29\uc2dd\uc73c\ub85c, \ub2e4\ud488\uc885 \uc18c\ub7c9\uc0dd\uc0b0\uc774\ub098 \uc7a6\uc740 \uc0ac\uc591 \ubcc0\uacbd\uc5d0\ub294 \uc624\ud788\ub824 \uc801\ud569\ud558\uc9c0 \uc54a\ub2e4. \ub2e4\ud488\uc885 \uc18c\ub7c9\uc0dd\uc0b0\uc5d0\ub294 \uc720\uc5f0\uc131\uc774 \ub192\uc740 \uac1c\ubcc4\uc0dd\uc0b0(job shop) \ubc29\uc2dd\uc774 \ub354 \uc801\ud569\ud558\ub2e4.",B.akx,B.aio,null)
B.a53=s(["\uc0dd\uc0b0\ub7c9\uc774 \ub298\uc5b4\ub0a8\uc5d0 \ub530\ub77c \uace0\uc815\ube44\uac00 \ub354 \ub9ce\uc740 \uc81c\ud488 \ub2e8\uc704\uc5d0 \ubd84\uc0b0\ub418\uc5b4 \ub2e8\uc704\ub2f9 \uace0\uc815\ube44\uac00 \uac10\uc18c\ud55c\ub2e4","\ub300\ub7c9\uad6c\ub9e4\ub97c \ud1b5\ud574 \uc6d0\uc7ac\ub8cc \uad6c\ub9e4 \uc2dc \ub2e8\uac00 \ud611\uc0c1\ub825\uc774 \ub192\uc544\uc9c4\ub2e4","\uc0dd\uc0b0 \uacbd\ud5d8\uc774 \ub204\uc801\ub428\uc5d0 \ub530\ub77c \uc791\uc5c5\uc790\uc758 \uc219\ub828\ub3c4\uac00 \ud5a5\uc0c1\ub41c\ub2e4","\uc0dd\uc0b0\ub7c9\uc774 \uc77c\uc815 \uc218\uc900\uc744 \ub118\uc5b4\uc11c\uba74 \uad00\ub9ac\uc758 \ubcf5\uc7a1\uc131\uc774 \uc99d\uac00\ud574 \ub2e8\uc704\ub2f9 \ube44\uc6a9\uc774 \ud56d\uc0c1 \uacc4\uc18d \uac10\uc18c\ud55c\ub2e4"],t.s)
B.bdP=s(["\uc0dd\uc0b0 \uaddc\ubaa8\uac00 \uc77c\uc815 \uc218\uc900\uc744 \ub118\uc5b4\uc11c\uba74 \uc624\ud788\ub824 \uad00\ub9ac\uc758 \ubcf5\uc7a1\uc131 \uc99d\uac00\ub85c \ub2e8\uc704\ub2f9 \ube44\uc6a9\uc774 \ub2e4\uc2dc \uc0c1\uc2b9\ud558\ub294 \uaddc\ubaa8\uc758 \ubd88\uacbd\uc81c \ud604\uc0c1\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4"],t.s)
B.Rc=s(["\uaddc\ubaa8\uc758 \uacbd\uc81c\uc640 \uaddc\ubaa8\uc758 \ubd88\uacbd\uc81c"],t.s)
B.boO=new A.a("gen_ba_ops_system_5","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","\uaddc\ubaa8\uc758 \uacbd\uc81c(economies of scale)\uac00 \ubc1c\uc0dd\ud558\ub294 \uc774\uc720\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a53,3,'\uc0dd\uc0b0 \uaddc\ubaa8\uac00 \uc77c\uc815 \uc218\uc900\uc744 \ub118\uc5b4\uc11c\uba74 \uc624\ud788\ub824 \uad00\ub9ac\uc758 \ubcf5\uc7a1\uc131 \uc99d\uac00, \uc758\uc0ac\uc18c\ud1b5 \ube44\ud6a8\uc728 \ub4f1\uc73c\ub85c \ub2e8\uc704\ub2f9 \ube44\uc6a9\uc774 \ub2e4\uc2dc \uc0c1\uc2b9\ud558\ub294 \uaddc\ubaa8\uc758 \ubd88\uacbd\uc81c(diseconomies of scale) \ud604\uc0c1\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. "\ub2e8\uc704\ub2f9 \ube44\uc6a9\uc774 \ud56d\uc0c1 \uacc4\uc18d \uac10\uc18c\ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.bdP,B.Rc,null)
B.aQA=s(["\ub204\uc801\uc0dd\uc0b0\ub7c9\uc774 \uc99d\uac00\ud560\uc218\ub85d \ub2e8\uc704\ub2f9 \uc0dd\uc0b0\uc18c\uc694\uc2dc\uac04(\ub610\ub294 \ube44\uc6a9)\uc774 \uc77c\uc815\ud55c \ube44\uc728\ub85c \uac10\uc18c\ud558\ub294 \ud604\uc0c1\uc774\ub2e4","\ub204\uc801\uc0dd\uc0b0\ub7c9\uacfc \uad00\uacc4\uc5c6\uc774 \ub2e8\uc704\ub2f9 \uc0dd\uc0b0\uc2dc\uac04\uc740 \ud56d\uc0c1 \uc77c\uc815\ud558\ub2e4\ub294 \uc774\ub860\uc774\ub2e4","\uc791\uc5c5\uc790\uc758 \uc219\ub828\ub3c4\uc640\ub294 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \uc21c\uc218\ud55c \uc124\ube44 \uc131\ub2a5 \uac1c\uc120 \ud6a8\uacfc\uc774\ub2e4","\uc0dd\uc0b0\ub7c9\uc774 \ub298\uc5b4\ub0a0\uc218\ub85d \ub2e8\uc704\ub2f9 \uc0dd\uc0b0\uc2dc\uac04\uc774 \uc624\ud788\ub824 \uc99d\uac00\ud558\ub294 \ud604\uc0c1\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.Ra=s(["\ub204\uc801\uc0dd\uc0b0\ub7c9\uc774 \ub450 \ubc30\ub85c \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ub2e8\uc704\ub2f9 \uc791\uc5c5\uc18c\uc694\uc2dc\uac04(\ub610\ub294 \ube44\uc6a9)\uc774 \uc77c\uc815\ud55c \ube44\uc728(\ud559\uc2b5\ub960)\ub85c \uac10\uc18c\ud558\ub294 \ud604\uc0c1"],t.s)
B.aMg=s(["\ud559\uc2b5\uace1\uc120 \ud6a8\uacfc"],t.s)
B.bsT=new A.a("gen_ba_ops_system_6","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uc0dd\uc0b0\uc2dc\uc2a4\ud15c\uacfc \uc0dd\uc0b0\uacc4\ud68d","\ud559\uc2b5\uace1\uc120(learning curve) \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aQA,0,"\ud559\uc2b5\uace1\uc120 \ud6a8\uacfc\ub294 \ub204\uc801\uc0dd\uc0b0\ub7c9\uc774 \ub450 \ubc30\ub85c \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ub2e8\uc704\ub2f9 \uc791\uc5c5\uc18c\uc694\uc2dc\uac04(\ub610\ub294 \ube44\uc6a9)\uc774 \uc77c\uc815\ud55c \ube44\uc728(\ud559\uc2b5\ub960)\ub85c \uac10\uc18c\ud558\ub294 \ud604\uc0c1\uc744 \ub9d0\ud558\uba70, \uc774\ub294 \ubc18\ubcf5 \uc791\uc5c5\uc744 \ud1b5\ud55c \uc791\uc5c5\uc790\uc758 \uc219\ub828\ub3c4 \ud5a5\uc0c1, \uc791\uc5c5\ubc29\ubc95 \uac1c\uc120 \ub4f1\uc5d0 \uae30\uc778\ud55c\ub2e4.",B.Ra,B.aMg,null)
B.TQ=s(["\uacf5\uae09\uc0ac\uc2ac\uc758 \ud558\ub958(\uc18c\ub9e4\uc0c1)\uc5d0\uc11c \uc0c1\ub958(\uc81c\uc870\uc5c5\uccb4)\ub85c \uac08\uc218\ub85d \uc218\uc694 \uc815\ubcf4\uc758 \ubcc0\ub3d9\uc131\uc774 \ud655\ub300\ub418\ub294 \ud604\uc0c1\uc774\ub2e4","\uac01 \ub2e8\uacc4\uc5d0\uc11c \ub3c5\ub9bd\uc801\uc73c\ub85c \uc218\uc694\ub97c \uc608\uce21\ud558\uace0 \uc548\uc804\uc7ac\uace0\ub97c \ud655\ubcf4\ud558\ub824\ub294 \ud589\ub3d9\uc774 \uc8fc\uc694 \uc6d0\uc778 \uc911 \ud558\ub098\uc774\ub2e4","\uacf5\uae09\uc0ac\uc2ac \uad6c\uc131\uc6d0 \uac04 \uc2e4\uc2dc\uac04 \ud310\ub9e4\uc815\ubcf4(POS \ub370\uc774\ud130)\ub97c \uacf5\uc720\ud558\uba74 \uc644\ud654\ub420 \uc218 \uc788\ub2e4","\ucc44\ucc0d\ud6a8\uacfc\ub294 \uacf5\uae09\uc0ac\uc2ac\uc758 \ud558\ub958\ub85c \uac08\uc218\ub85d \ub354\uc6b1 \uc2ec\ud654\ub418\uc5b4 \ub098\ud0c0\ub098\ub294 \ud604\uc0c1\uc774\ub2e4"],t.s)
B.QS=s(["\uc18c\ub9e4\uc0c1(\ud558\ub958)\uc5d0\uc11c \uc81c\uc870\uc5c5\uccb4(\uc0c1\ub958) \ubc29\ud5a5\uc73c\ub85c \uc815\ubcf4\uac00 \uc804\ub2ec\ub418\uba70 \uac08\uc218\ub85d \uc218\uc694 \ubcc0\ub3d9\ud3ed\uc774 \uc99d\ud3ed\ub418\ub294 \ud604\uc0c1"],t.s)
B.akV=s(["\ucc44\ucc0d\ud6a8\uacfc\uc758 \ubc29\ud5a5\uacfc \uc6d0\uc778"],t.s)
B.bLc=new A.a("gen_ba_ops_scm_1","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\ucc44\ucc0d\ud6a8\uacfc(bullwhip effect)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.TQ,3,'\ucc44\ucc0d\ud6a8\uacfc\ub294 \uc18c\ub9e4\uc0c1(\ud558\ub958)\uc5d0\uc11c \uc81c\uc870\uc5c5\uccb4(\uc0c1\ub958) \ubc29\ud5a5\uc73c\ub85c \uc815\ubcf4\uac00 \uc804\ub2ec\ub418\uba70 \uac08\uc218\ub85d \uc218\uc694 \ubcc0\ub3d9\ud3ed\uc774 \uc99d\ud3ed\ub418\ub294 \ud604\uc0c1\uc774\ubbc0\ub85c, "\ud558\ub958\ub85c \uac08\uc218\ub85d \uc2ec\ud654\ub41c\ub2e4"\ub294 \uc124\uba85\uc740 \ubc29\ud5a5\uc774 \ubc18\ub300\ub85c \ub418\uc5b4 \uc788\uc5b4 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uc0c1\ub958\ub85c \uac08\uc218\ub85d \ubcc0\ub3d9\ud3ed\uc774 \ucee4\uc9c4\ub2e4.',B.QS,B.akV,null)
B.aQg=s(["\uac1c\ubcc4 \uae30\uc5c5\uc758 \uc0dd\uc0b0\ubd80\uc11c \ub0b4\ubd80 \ud6a8\uc728\ub9cc\uc744 \uadf9\ub300\ud654\ud558\ub294 \uac83\uc774\ub2e4","\uc6d0\uc7ac\ub8cc \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \ucd5c\uc885\uc18c\ube44\uc790\uc5d0 \uc774\ub974\ub294 \uc804\uccb4 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud574 \uc804\uccb4 \uacf5\uae09\uc0ac\uc2ac\uc758 \ud6a8\uc728\uc131\uc744 \ub192\uc774\ub294 \uac83\uc774\ub2e4","\uc7ac\uace0\ub97c \ubb34\uc870\uac74 \ucd5c\ub300\ud55c \ub9ce\uc774 \ubcf4\uc720\ud558\uc5ec \ud488\uc808\uc744 \uc6d0\ucc9c\uc801\uc73c\ub85c \ubc29\uc9c0\ud558\ub294 \uac83\uc774\ub2e4","\uacf5\uae09\uc5c5\uccb4\uc640\uc758 \uac70\ub798\uad00\uacc4\ub97c \ub9e4\ubc88 \ucd5c\uc800\uac00 \uc785\ucc30\uc744 \ud1b5\ud574\uc11c\ub9cc \uacb0\uc815\ud558\ub294 \uac83\uc774\ub2e4"],t.s)
B.aTl=s(['\uacf5\uae09\uc0ac\uc2ac \uc804\uccb4\ub97c \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubcf4\uace0 \uc815\ubcf4\uc640 \ubb3c\uc790\uc758 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud568\uc73c\ub85c\uc368, \uacf5\uae09\uc0ac\uc2ac "\uc804\uccb4"\uc758 \ud6a8\uc728\uc131\uacfc \uace0\uac1d\uac00\uce58\ub97c \ub192\uc774\ub294 \uac83\uc744 \ubaa9\ud45c'],t.s)
B.b4b=s(["SCM\uc758 \ubaa9\uc801"],t.s)
B.bKm=new A.a("gen_ba_ops_scm_2","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac(SCM: Supply Chain Management)\uc758 \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aQg,1,'SCM\uc740 \uc6d0\uc7ac\ub8cc \uc870\ub2ec\ubd80\ud130 \uc0dd\uc0b0, \uc720\ud1b5, \ucd5c\uc885\uc18c\ube44\uc790\uc5d0 \uc774\ub974\ub294 \uacf5\uae09\uc0ac\uc2ac \uc804\uccb4\ub97c \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubcf4\uace0 \uc815\ubcf4\uc640 \ubb3c\uc790\uc758 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud568\uc73c\ub85c\uc368, \uac1c\ubcc4 \uae30\uc5c5 \ub2e8\uc704 \ucd5c\uc801\ud654\uac00 \uc544\ub2cc \uacf5\uae09\uc0ac\uc2ac "\uc804\uccb4"\uc758 \ud6a8\uc728\uc131\uacfc \uace0\uac1d\uac00\uce58\ub97c \ub192\uc774\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud55c\ub2e4.',B.aTl,B.b4b,null)
B.agu=s(["\uae30\uc5c5 \ub0b4\ubd80\uc5d0\uc11c \uc9c1\uc811 \uc218\ud589\ud558\ub358 \ud65c\ub3d9\uc744 \uc678\ubd80 \uc804\ubb38\uc5c5\uccb4\uc5d0 \uc704\ud0c1\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\ud575\uc2ec\uc5ed\ub7c9\uc5d0 \uc790\uc6d0\uc744 \uc9d1\uc911\ud558\uace0 \ube44\ud575\uc2ec \ud65c\ub3d9\uc758 \ube44\uc6a9\uc744 \uc808\uac10\ud558\ub294 \ub370 \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4","\uc678\ubd80\uc5c5\uccb4\uc5d0 \ub300\ud55c \uc758\uc874\ub3c4\uac00 \ub192\uc544\uc9d0\uc5d0 \ub530\ub77c \uacf5\uae09\ub9dd \ud1b5\uc81c\ub825\uc774 \uc57d\ud654\ub420 \uc704\ud5d8\uc774 \uc788\ub2e4","\uc544\uc6c3\uc18c\uc2f1\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud488\uc9c8\uc774\ub098 \uc815\ubcf4 \uc720\ucd9c\uacfc \uad00\ub828\ub41c \uc704\ud5d8\uc744 \uc218\ubc18\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aBQ=s(["\ud1b5\uc81c\ub825 \uc57d\ud654, \ud488\uc9c8\uad00\ub9ac\uc758 \uc5b4\ub824\uc6c0, \ud575\uc2ec \uae30\uc220\xb7\uc815\ubcf4\uc758 \uc720\ucd9c \uc704\ud5d8\uacfc \uac19\uc740 \ub2e8\uc810\ub3c4 \ud568\uaed8 \uc218\ubc18"],t.s)
B.aBq=s(["\uc544\uc6c3\uc18c\uc2f1\uc758 \uc7a5\ub2e8\uc810"],t.s)
B.bvq=new A.a("gen_ba_ops_scm_3","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\uc544\uc6c3\uc18c\uc2f1(outsourcing)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agu,3,'\uc544\uc6c3\uc18c\uc2f1\uc740 \ube44\uc6a9 \uc808\uac10\uacfc \ud575\uc2ec\uc5ed\ub7c9 \uc9d1\uc911\uc774\ub77c\ub294 \uc7a5\uc810\uc774 \uc788\ub294 \ubc18\uba74, \uc678\ubd80\uc5c5\uccb4\uc5d0 \ub300\ud55c \ud1b5\uc81c\ub825 \uc57d\ud654, \ud488\uc9c8\uad00\ub9ac\uc758 \uc5b4\ub824\uc6c0, \ud575\uc2ec \uae30\uc220\xb7\uc815\ubcf4\uc758 \uc720\ucd9c \uc704\ud5d8\uacfc \uac19\uc740 \ub2e8\uc810\ub3c4 \ud568\uaed8 \uc218\ubc18\ud55c\ub2e4. "\uc5b4\ub5a0\ud55c \uc704\ud5d8\ub3c4 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aBQ,B.aBq,null)
B.aBU=s(["\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\ucc3d\uace0\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud55c \ub4a4 \ucd9c\uace0\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ucc3d\uace0\uc5d0 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0 \uace7\ubc14\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \uc6b4\uc1a1\uc218\ub2e8\uc73c\ub85c \uc62e\uaca8 \uc2e3\ub294 \ubb3c\ub958\ubc29\uc2dd\uc774\ub2e4","\uc5ec\ub7ec \uacf5\uae09\uc5c5\uccb4\uc758 \uc7ac\uace0\ub97c \ud558\ub098\ub85c \ud1b5\ud569\ud558\uc5ec \ubb34\uae30\ud55c \uc800\uc7a5\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uace0\uac1d\uc774 \uc9c1\uc811 \ubb3c\ub958\ucc3d\uace0\ub97c \ubc29\ubb38\ud574 \uc0c1\ud488\uc744 \uc218\ub839\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4"],t.s)
B.baA=s(["\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\uc13c\ud130\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0, \ub3c4\ucc29 \uc989\uc2dc \ubaa9\uc801\uc9c0\ubcc4\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \ubc30\uc1a1\ucc28\ub7c9\uc73c\ub85c \uc62e\uaca8 \uc2e3\uace0 \uace7\ubc14\ub85c \ucd9c\uace0\ud558\ub294 \ubb3c\ub958\uae30\ubc95"],t.s)
B.aVA=s(["\ud06c\ub85c\uc2a4\ub3c4\ud0b9\uc758 \uac1c\ub150"],t.s)
B.bIF=new A.a("gen_ba_ops_scm_4","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\ud06c\ub85c\uc2a4\ub3c4\ud0b9(cross docking)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aBU,1,"\ud06c\ub85c\uc2a4\ub3c4\ud0b9\uc740 \uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\uc13c\ud130\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0, \ub3c4\ucc29 \uc989\uc2dc \ubaa9\uc801\uc9c0\ubcc4\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \ubc30\uc1a1\ucc28\ub7c9\uc73c\ub85c \uc62e\uaca8 \uc2e3\uace0 \uace7\ubc14\ub85c \ucd9c\uace0\ud558\ub294 \ubb3c\ub958\uae30\ubc95\uc73c\ub85c, \ubcf4\uad00\ube44\uc6a9\uacfc \ub9ac\ub4dc\ud0c0\uc784\uc744 \uc904\uc774\ub294 \ub370 \ud6a8\uacfc\uc801\uc774\ub2e4.",B.baA,B.aVA,null)
B.Z0=s(["\uc218\uc694\uc608\uce21\uc774 \uc5b4\ub835\uace0 \uc81c\ud488\uc218\uba85\uc8fc\uae30\uac00 \uc9e7\uc73c\ubbc0\ub85c \uc7ac\uace0\ube44\uc6a9\ubcf4\ub2e4 \ud488\uc808\xb7\uae30\ud68c\uc190\uc2e4 \ubc29\uc9c0\ub97c \uc911\uc2dc\ud558\ub294 \ubc18\uc751\uc801(responsive) \uacf5\uae09\uc0ac\uc2ac\uc774 \uc801\ud569\ud558\ub2e4","\uc218\uc694\uac00 \uc548\uc815\uc801\uc774\ubbc0\ub85c \ud6a8\uc728(efficient) \uacf5\uae09\uc0ac\uc2ac\uc744 \ud1b5\ud574 \ube44\uc6a9 \ucd5c\uc18c\ud654\ub9cc\uc744 \ucd94\uad6c\ud558\ub294 \uac83\uc774 \uc801\ud569\ud558\ub2e4","\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uc7ac\uace0\ub97c \uc804\ud600 \ubcf4\uc720\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \ucd5c\uc801\uc758 \uc804\ub7b5\uc774\ub2e4","\uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc740 \uc81c\ud488\uc758 \ud2b9\uc131\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud558\uac8c \uc124\uacc4\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aVF=s(["\uc218\uc694 \ubcc0\ub3d9\uc131\uc774 \ud06c\uace0 \uc218\uba85\uc8fc\uae30\uac00 \uc9e7\uc740 \ud601\uc2e0\uc801 \uc81c\ud488\uc740 \ud488\uc808\ub85c \uc778\ud55c \uae30\ud68c\uc190\uc2e4\uc774 \ud06c\ubbc0\ub85c, \ube60\ub974\uac8c \ub300\uc751\ud560 \uc218 \uc788\ub294 \ubc18\uc751\uc801 \uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc774 \uc801\ud569"],t.s)
