B.bOP=new A.a("gen_ba_mis_sec_1","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc815\ubcf4\ubcf4\uc548","\uc815\ubcf4\ubcf4\uc548\uc758 3\ub300 \uc694\uc18c\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.b8t,3,"\uc815\ubcf4\ubcf4\uc548\uc758 3\ub300 \ud575\uc2ec \uc694\uc18c\ub294 \uc778\uac00\ub41c \uc790\ub9cc \uc815\ubcf4\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uae30\ubc00\uc131, \uc815\ubcf4\uac00 \ubb34\ub2e8\uc73c\ub85c \ubcc0\uacbd\ub418\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \ubb34\uacb0\uc131, \ud544\uc694\ud560 \ub54c \uc815\ubcf4\uc2dc\uc2a4\ud15c\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uac00\uc6a9\uc131\uc774\ub2e4. \uc218\uc775\uc131\uc740 \uc815\ubcf4\ubcf4\uc548\uc758 \ubaa9\ud45c\uac00 \uc544\ub2c8\ub77c \uc7ac\ubb34\uc801 \uac1c\ub150\uc774\ub2e4.",B.aL6,B.a0U,null)
B.bg4=s(["\uc554\ud638\ud654\uc640 \ubcf5\ud638\ud654\uc5d0 \uc11c\ub85c \ub2e4\ub978 \ud0a4\ub97c \uc0ac\uc6a9\ud55c\ub2e4","\uc554\ud638\ud654\uc640 \ubcf5\ud638\ud654\uc5d0 \ub3d9\uc77c\ud55c \ud558\ub098\uc758 \ud0a4\ub97c \uc0ac\uc6a9\ud55c\ub2e4","\ud0a4\ub97c \uc804\ud600 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \uc54c\uace0\ub9ac\uc998\ub9cc\uc73c\ub85c \uc554\ud638\ud654\ud55c\ub2e4","\uacf5\uac1c\ud0a4\uc640 \uac1c\uc778\ud0a4\ub77c\ub294 \ud55c \uc30d\uc758 \ud0a4\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4"],t.s)
