B.aY4=s(["\uc804\uc18d\uace0\ubc1c\uc81c\uc758 \uc608\uc678 \u2014 \uace0\ubc1c\uc694\uccad\uad8c"],t.s)
B.bR5=new A.a("gen_trap_el_8","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uac80\ucc30\ucd1d\uc7a5\uc774 \uacf5\uc815\uc704\uc5d0 \uace0\ubc1c\uc744 \uc694\uccad\ud588\uc73c\ub098 \uacf5\uc815\uc704\uac00 \uc774\ub97c \uac70\ubd80\ud558\ub824\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aWo,0,"\uc804\uc18d\uace0\ubc1c\uc81c\uc758 \uc608\uc678\uc801 \ubcf4\uc644\uc7a5\uce58\ub85c \uac80\ucc30\ucd1d\uc7a5\xb7\uac10\uc0ac\uc6d0\uc7a5\xb7\uc911\uc18c\ubca4\ucc98\uae30\uc5c5\ubd80\uc7a5\uad00 \ub4f1\uc5d0\uac8c \uace0\ubc1c\uc694\uccad\uad8c\uc774 \uc778\uc815\ub418\uba70, \uc774\ub7ec\ud55c \uc694\uccad\uc774 \uc788\uc73c\uba74 \uacf5\uc815\uc704\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc774\uc5d0 \ub530\ub77c \uace0\ubc1c\ud558\uc5ec\uc57c \ud55c\ub2e4. \uc804\uc18d\uace0\ubc1c\uc81c\uac00 \uacf5\uc815\uc704\uc758 \ud310\ub2e8\uc744 \uc874\uc911\ud558\ub294 \uc81c\ub3c4\uc774\uc9c0\ub9cc, \uc774 \uc694\uccad\uad8c\uc73c\ub85c \uadf8 \ub0a8\uc6a9\uc744 \uacac\uc81c\ud55c\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4.",B.atI,B.aY4,null)
B.aDt=s([u.op,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub97c \ud1b5\ud574 \uc774\ub8e8\uc5b4\uc9c4 \ud569\uc758\ub294 \uac1c\ubcc4 \uc0ac\uc5c5\uc790 \uac04 \ub2f4\ud569\uacfc \ub2ec\ub9ac \uaddc\uc81c \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \uc81c\uc7ac\ubc1b\uc73c\uba74 \uac1c\ubcc4 \uad6c\uc131\uc0ac\uc5c5\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcc4\ub3c4\ub85c \uc81c\uc7ac\ubc1b\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ub2f4\ud569 \uc8fc\ub3c4\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4"],t.s)
