B.bFn=new A.a("gen_trap_ba_5","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,'\ud5c8\uce20\ubc84\uadf8\uc758 2\uc694\uc778\uc774\ub860\uc5d0\uc11c "\uc784\uae08 \uc778\uc0c1"\uc774 \ub3d9\uae30\ubd80\uc5ec\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.azj,0,"\ud5c8\uce20\ubc84\uadf8\uc758 2\uc694\uc778\uc774\ub860\uc5d0\uc11c \uc784\uae08\xb7\uadfc\ubb34\ud658\uacbd \ub4f1\uc740 \uc704\uc0dd\uc694\uc778\uc73c\ub85c \ubd84\ub958\ub418\uc5b4, \uc774\uac83\uc774 \ubd80\uc871\ud558\uba74 \ubd88\ub9cc\uc871\uc744 \uc57c\uae30\ud558\uc9c0\ub9cc \ucda9\ubd84\ud788 \ucc44\uc6cc\uc9c4\ub2e4\uace0 \ud574\uc11c \uadf8 \uc790\uccb4\ub85c \uc801\uadf9\uc801\uc778 \ub9cc\uc871(\ub3d9\uae30\ubd80\uc5ec)\uc744 \ub9cc\ub4e4\uc5b4\ub0b4\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uc131\ucde8\xb7\uc778\uc815 \ub4f1 \ub3d9\uae30\uc694\uc778\uacfc\ub294 \uc644\uc804\ud788 \ubcc4\uac1c\uc758 \ucd95\uc774\ub77c\ub294 \uc810\uc774 \uc774 \uc774\ub860\uc758 \ud575\uc2ec\uc774\ub2e4.",B.aUj,B.b7v,null)
B.ato=s(["STP(\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\uc120\uc815\xb7\ud3ec\uc9c0\uc154\ub2dd)\ub85c \ubaa9\ud45c \uace0\uac1d\uacfc \uc704\uce58\ub97c \uba3c\uc800 \uc815\ud55c \ub4a4, \uc774\ub97c \uc2e4\ud589\ud558\uae30 \uc704\ud55c \uad6c\uccb4\uc801 \uc218\ub2e8\uc73c\ub85c 4P(\uc81c\ud488\xb7\uac00\uaca9\xb7\uc720\ud1b5\xb7\ucd09\uc9c4) \uc804\ub7b5\uc744 \uc218\ub9bd\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \uc21c\uc11c\uc774\ub2e4","4P\ub97c \uba3c\uc800 \uc2e4\ud589\ud55c \ub4a4 \uadf8 \uacb0\uacfc\uc5d0 \ub530\ub77c STP\ub97c \uc0ac\ud6c4\uc801\uc73c\ub85c \uacb0\uc815\ud55c\ub2e4","STP\uc640 4P\ub294 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc774\ub860\uc774\ub2e4","\ud3ec\uc9c0\uc154\ub2dd\uc740 4P \uc911 \uac00\uaca9\uc804\ub7b5\uc758 \ud558\uc704 \uac1c\ub150\uc774\ub2e4"],t.s)
B.a0p=s(["STP\ub85c \ubaa9\ud45c \uace0\uac1d\uacfc \uc704\uce58\ub97c \uba3c\uc800 \uc815\ud55c \ub4a4, \uc774\ub97c \uc2e4\ud589\ud558\uae30 \uc704\ud55c \uad6c\uccb4\uc801 \uc218\ub2e8\uc73c\ub85c 4P \uc804\ub7b5\uc744 \uc218\ub9bd\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \uc21c\uc11c"],t.s)
B.aOh=s(["STP\uc640 4P\uc758 \uc804\ub7b5-\uc2e4\ud589 \uad00\uacc4"],t.s)
B.bEH=new A.a("gen_trap_ba_6","business_admin","\ud568\uc815 \ud53c\ud558\uae30",null,"STP \uc804\ub7b5\uacfc 4P \uc804\ub7b5\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ato,0,'STP \uc804\ub7b5\uc740 "\ub204\uad6c\ub97c, \uc5b4\ub5a4 \uc704\uce58\ub85c" \uacf5\ub7b5\ud560\uc9c0\ub97c \uc815\ud558\ub294 \uc804\ub7b5\uc801 \ubc29\ud5a5 \uc124\uc815 \ub2e8\uacc4\uc774\uace0, 4P\ub294 \uadf8 \ubc29\ud5a5\uc744 \uc2e4\ud589\uc5d0 \uc62e\uae30\ub294 \uad6c\uccb4\uc801 \uc2e4\ud589 \uc218\ub2e8\uc774\ubbc0\ub85c, \ud1b5\uc0c1 STP\ub97c \uba3c\uc800 \uc218\ub9bd\ud55c \ud6c4 \uc774\uc5d0 \ub9de\ucdb0 4P \ubbf9\uc2a4\ub97c \uc124\uacc4\ud558\ub294 \uc21c\uc11c\ub85c \uc9c4\ud589\ub41c\ub2e4.',B.a0p,B.aOh,null)
B.a46=s([u.dX,"\uc790\uc0b0\uacfc \ube44\uc6a9 \ubaa8\ub450 \uacfc\ub300\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc5d0\ub294 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\ubcf8\uc801 \uc9c0\ucd9c\uc744 \uc218\uc775\uc801 \uc9c0\ucd9c\ub85c \ucc98\ub9ac\ud574\ub3c4 \uc7ac\ubb34\uc81c\ud45c\uc5d0\ub294 \uc544\ubb34 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc790\uc0b0\uc774 \uacfc\ub300\uacc4\uc0c1\ub418\uace0 \ube44\uc6a9\uc774 \uacfc\uc18c\uacc4\uc0c1\ub418\uc5b4 \ub2f9\uae30\uc21c\uc774\uc775\uc774 \uacfc\ub300\uacc4\uc0c1\ub41c\ub2e4"],t.s)
