B.brU=new A.a("gen_trap_kh_2","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,'1910\ub144\ub300 \ubb34\ub2e8 \ud1b5\uce58\uc640 1920\ub144\ub300 \uc774\ub978\ubc14 "\ubb38\ud654 \ud1b5\uce58"\ub97c \uad6c\ubd84\ud560 \ub54c, \ubb38\ud654 \ud1b5\uce58\uae30\uc758 \uc2e4\uc0c1\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aKY,0,'1920\ub144\ub300 \uc774\ub978\ubc14 "\ubb38\ud654 \ud1b5\uce58"\ub294 3\xb71 \uc6b4\ub3d9 \uc774\ud6c4 \uba85\ubaa9\uc0c1 \ubcf4\ud1b5 \uacbd\ucc30\uc81c \uc804\ud658\xb7\uc870\uc120\uc5b4 \uc2e0\ubb38 \ubc1c\ud589 \ud5c8\uc6a9 \ub4f1\uc744 \ub0b4\uc138\uc6e0\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uacbd\ucc30\uad00\uc11c\uc640 \uacbd\ucc30 \uc778\uc6d0\uc744 \ud06c\uac8c \ub298\ub9ac\uace0 \uace0\ub4f1 \uacbd\ucc30\uc81c\ub97c \ud1b5\ud574 \uac10\uc2dc\ub97c \uc624\ud788\ub824 \uac15\ud654\ud55c \uae30\ub9cc\uc801 \ud1b5\uce58\uc600\ub2e4. \ud5cc\ubcd1 \uacbd\ucc30\uc81c\xb7\ud0dc\ud615\ub839\uc740 1910\ub144\ub300 \ubb34\ub2e8 \ud1b5\uce58, \uad6d\uac00 \ucd1d\ub3d9\uc6d0\ubc95\xb7\ud669\uad6d \uc2e0\ubbfc\ud654\ub294 1930\ub144\ub300 \uc774\ud6c4 \ubbfc\uc871 \ub9d0\uc0b4 \ud1b5\uce58\uc758 \ud2b9\uc9d5\uc774\ub77c \uc2dc\uae30\ub97c \ud5f7\uac08\ub9ac\uae30 \uc27d\ub2e4.',B.aGi,B.aX5,null)
B.ayK=s(["\uc804\uad6d\uc744 9\uc8fc\ub85c \ub098\ub204\uace0 \uc218\ub3c4\uc758 \ud3b8\uc7ac\uc131\uc744 \ubcf4\uc644\ud558\uae30 \uc704\ud574 5\uc18c\uacbd\uc744 \uc124\uce58\ud558\uc600\ub2e4","\uc804\uad6d\uc744 5\uacbd 15\ubd80 62\uc8fc\ub85c \ud3b8\uc131\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ud30c\uacac\ud558\uc600\ub2e4","5\ub3c4\uc640 \uc591\uacc4\ub85c \ub098\ub204\uc5b4 \uc77c\ubc18 \ud589\uc815\uacfc \uad70\uc0ac \ud589\uc815\uc744 \ubd84\ub9ac\ud558\uc600\ub2e4","8\ub3c4 \uc544\ub798 \ubd80\xb7\ubaa9\xb7\uad70\xb7\ud604\uc744 \ub450\uace0 \ubaa8\ub4e0 \uad70\ud604\uc5d0 \uc218\ub839\uc744 \ud30c\uacac\ud558\uc600\ub2e4"],t.s)
