B.bKX=new A.a("gen_trap_kh_6","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc11c\ud76c\uc758 \uc678\uad50 \ub2f4\ud310\uacfc \uac15\uac10\ucc2c\uc758 \uadc0\uc8fc \ub300\ucca9\uc744 \uad6c\ubd84\ud560 \ub54c, \uc11c\ud76c\uc758 \uc678\uad50 \ub2f4\ud310\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b_k,0,'\uc11c\ud76c\ub294 \uac70\ub780\uc758 1\ucc28 \uce68\uc785 \ub54c \uc18c\uc190\ub155\uacfc\uc758 \uc678\uad50 \ub2f4\ud310\uc744 \ud1b5\ud574 \ubb34\ub825 \ucda9\ub3cc \uc5c6\uc774 \uac15\ub3d9 6\uc8fc\ub97c \ud655\ubcf4\ud558\ub294 \uc678\uad50\uc801 \uc131\uacfc\ub97c \uac70\ub450\uc5c8\ub2e4. \ubc18\uba74 \uac15\uac10\ucc2c\uc758 \uadc0\uc8fc \ub300\ucca9\uc740 \uac70\ub780\uc758 3\ucc28 \uce68\uc785\uc744 \ubb34\ub825\uc73c\ub85c \uaca9\ud1f4\ud55c \uc804\ud22c\ub85c, \ub458 \ub2e4 "\uac70\ub780 \uce68\uc785 \ub300\uc751"\uc774\ub77c\ub294 \uacf5\ud1b5\uc810 \ub54c\ubb38\uc5d0 \ud5f7\uac08\ub9ac\uae30 \uc27d\uc9c0\ub9cc "\uc11c\ud76c=\uc678\uad50(\ub9d0)", "\uac15\uac10\ucc2c=\uc804\ud22c(\ubb34\ub825)"\ub85c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4.',B.bh6,B.aeQ,null)
B.a49=s([u.zN,"\uc11c\uc591\uc758 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \uc81c\ub3c4\xb7\uc0ac\uc0c1\uae4c\uc9c0 \uc801\uadf9\uc801\uc73c\ub85c \uc218\uc6a9\ud574\uc57c \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud558\uc600\ub2e4","\ub3d9\ub3c4\uc11c\uae30\ub860\uc744 \ub0b4\uc138\uc6cc \uc720\uad50 \uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\uba74\uc11c \uc11c\uc591 \uae30\uc220\ub9cc \ubd80\ubd84\uc801\uc73c\ub85c \uc218\uc6a9\ud558\uc790\uace0 \ud558\uc600\ub2e4","\uae09\uc9c4 \uac1c\ud654\ud30c\ub97c \uc911\uc2ec\uc73c\ub85c \uac11\uc2e0\uc815\ubcc0\uc744 \uc77c\uc73c\ucf1c \uadfc\ub300 \uad6d\uac00 \uc218\ub9bd\uc744 \uc2dc\ub3c4\ud558\uc600\ub2e4"],t.s)
