B.bBu=new A.a("gen_trap_kh_7","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc704\uc815\ucc99\uc0ac \uc6b4\ub3d9\uacfc \uac1c\ud654 \uc6b4\ub3d9\uc744 \uad6c\ubd84\ud560 \ub54c, \uc704\uc815\ucc99\uc0ac \uc6b4\ub3d9\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a49,0,"\uc704\uc815\ucc99\uc0ac \uc6b4\ub3d9\uc740 \uc131\ub9ac\ud559\uc801 \uc9c8\uc11c(\uc815)\ub97c \uc9c0\ud0a4\uace0 \uc11c\uc591\xb7\uc77c\ubcf8\uc758 \ubb38\ubb3c\uacfc \ud1b5\uc0c1\uc744 \uc0ac\uc545\ud55c \uac83(\uc0ac)\uc73c\ub85c \ubc30\ucc99\ud558\uc790\ub294 \ubcf4\uc218\uc801 \uc785\uc7a5\uc774\ub2e4. \ub3d9\ub3c4\uc11c\uae30\ub860(\uc628\uac74 \uac1c\ud654\ud30c)\uc740 \uc720\uad50 \uc9c8\uc11c \uc720\uc9c0 + \uc11c\uc591 \uae30\uc220 \uc218\uc6a9, \uae09\uc9c4 \uac1c\ud654\ud30c(\uac11\uc2e0\uc815\ubcc0)\ub294 \uc81c\ub3c4\xb7\uc0ac\uc0c1\uae4c\uc9c0 \uc801\uadf9 \uc218\uc6a9\ud558\uc790\ub294 \uc785\uc7a5\uc73c\ub85c, \uc704\uc815\ucc99\uc0ac\uc640 \uc2a4\ud399\ud2b8\ub7fc\uc0c1 \ubc18\ub300\ucabd\uc5d0 \uc788\uc5b4 \uc790\uc8fc \ud5f7\uac08\ub9b0\ub2e4.",B.aml,B.aEj,null)
B.Zq=s([u.P,"\uc758\uc815\ubd80 \uc11c\uc0ac\uc81c\ub97c \uc2e4\uc2dc\ud558\uc5ec 6\uc870\uc758 \uc5c5\ubb34\ub97c \uc758\uc815\ubd80\uac00 \uba3c\uc800 \uc2ec\uc758\ud558\ub3c4\ub85d \ud558\uc600\ub2e4","\uc9d1\ud604\uc804\uc744 \uc124\uce58\ud558\uc5ec \ud559\ubb38 \uc5f0\uad6c\uc640 \uc655\uc5d0 \ub300\ud55c \uc790\ubb38 \uae30\ub2a5\uc744 \ub2f4\ub2f9\ud558\uac8c \ud558\uc600\ub2e4","\ud6c8\ubbfc\uc815\uc74c\uc744 \ucc3d\uc81c\ud558\uc5ec \ubc31\uc131\ub4e4\uc774 \uc27d\uac8c \ubb38\uc790\ub97c \uc775\ud790 \uc218 \uc788\ub3c4\ub85d \ud558\uc600\ub2e4"],t.s)
