B.bNQ=new A.a("gen_trap_kh_8","korean_history","\ud568\uc815 \ud53c\ud558\uae30",null,"\uc870\uc120 \ud0dc\uc885\uacfc \uc138\uc885\uc758 \ud1b5\uce58 \uccb4\uc81c\ub97c \uad6c\ubd84\ud560 \ub54c, \ud0dc\uc885\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Zq,0,'\ud0dc\uc885\uc740 \uc655\uad8c\uc744 \uac15\ud654\ud558\uae30 \uc704\ud574 6\uc870 \uc9c1\uacc4\uc81c\ub97c \uc2e4\uc2dc\ud558\uc5ec \uc758\uc815\ubd80\uc758 \uad8c\ud55c\uc744 \ucd95\uc18c\ud558\uace0 6\uc870\uac00 \uc655\uc5d0\uac8c \uc9c1\uc811 \ubcf4\uace0\ud558\ub3c4\ub85d \ud558\uc600\ub2e4. \uc138\uc885\uc740 \uc989\uc704 \ud6c4 \uc758\uc815\ubd80 \uc11c\uc0ac\uc81c\ub85c \uc804\ud658\ud558\uc5ec \uc7ac\uc0c1\ub4e4\uc758 \uad8c\ud55c\uc744 \uc77c\ubd80 \uc778\uc815\ud558\uba74\uc11c\ub3c4, \uc778\uc0ac\xb7\uad70\uc0ac \ub4f1 \uc911\uc694 \uc0ac\uc548\uc740 \uc9c1\uc811 \ucc59\uaca8 \uc655\uad8c\uacfc \uc2e0\uad8c\uc758 \uc870\ud654\ub97c \uaf80\ud558\uc600\ub2e4(\uc9d1\ud604\uc804 \uc124\uce58\xb7\ud6c8\ubbfc\uc815\uc74c \ucc3d\uc81c\ub3c4 \uc138\uc885). "\ub204\uac00 \uc655\uad8c\uc744 \ub354 \uac15\ud654\ud588\ub294\uac00"\ub9cc \ubcf4\uba74 \ud0dc\uc885\xb7\uc138\uc885\uc774 \ud5f7\uac08\ub9ac\ubbc0\ub85c \ud1b5\uce58 \ubc29\uc2dd(\uc9c1\uacc4\uc81c vs \uc11c\uc0ac\uc81c)\uc73c\ub85c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4.',B.aLb,B.a6s,null)
B.amp=s([u.jv,"\uc774\uc2b9\ub9cc \uc815\ubd80\uc758 3\xb715 \ubd80\uc815 \uc120\uac70\uc5d0 \ubc18\ubc1c\ud558\uc5ec \uc77c\uc5b4\ub0ac\uc73c\uba70, \uc774\uc2b9\ub9cc\uc774 \ud558\uc57c\ud558\ub294 \uacb0\uacfc\ub97c \uac00\uc838\uc654\ub2e4","\uc2e0\uad70\ubd80\uc758 \ube44\uc0c1\uacc4\uc5c4 \ud655\ub300\uc5d0 \ubc18\ubc1c\ud558\uc5ec \uad11\uc8fc\uc5d0\uc11c \uc77c\uc5b4\ub0ac\uc73c\uba70, \uacc4\uc5c4\uad70\uc5d0 \uc758\ud574 \ubb34\ub825 \uc9c4\uc555\ub418\uc5c8\ub2e4","\ubc15\uc815\ud76c \uc815\ubd80\uc758 \uc720\uc2e0 \ud5cc\ubc95 \uc120\ud3ec \uc9c1\ud6c4 \uc804\uad6d\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4"],t.s)
